INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0d6071dd-fef1-4b3e-8229-c8621af65a88', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'component', 'blockquote', 'Blockquote', 'Typography', NULL, 'mdi-format-quote-open', 'components.catalog.blockquote.description', 'Typographic citation component with five visual variants, author/source attribution and locale-aware decorative quote marks.', NULL, NULL, 'origam-blockquote', NULL, NULL, 'origam', NULL, NULL, '/stories/?story=components-blockquote--design', '/docs/components/Blockquote/OrigamBlockquote.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.blockquote.a11y.cite_attr", "noteFallback": "The cite prop maps to the native cite attribute on the <blockquote>, providing the URL to assistive technologies and browser inspectors."}, {"noteKey": "components.blockquote.a11y.decorative_glyph", "noteFallback": "The decorative quote mark (<span class=\"origam-blockquote__mark\">) is aria-hidden=\"true\" — it is purely decorative and not announced by screen readers."}, {"noteKey": "components.blockquote.a11y.attribution_dash", "noteFallback": "The em-dash before the author name (<span class=\"origam-blockquote__dash\">) is also aria-hidden to avoid double reading."}, {"noteKey": "components.blockquote.a11y.source_cite", "noteFallback": "The source label is wrapped in <cite> for semantic correctness per the HTML spec."}], "roles": ["blockquote"], "keyboard": [{"key": "Tab", "actionKey": "components.blockquote.a11y.key_tab", "actionFallback": "Moves focus through interactive content inside the citation body if any."}]}, "tokens": {"excerpt": [{"type": "dimension", "value": "{font.size.lg}", "tokenPath": "blockquote.font-size", "descriptionKey": "components.blockquote.tokens.font_size", "descriptionFallback": "Body font size."}, {"type": "number", "value": "{font.lineHeight.relaxed}", "tokenPath": "blockquote.line-height", "descriptionKey": "components.blockquote.tokens.line_height", "descriptionFallback": "Body line-height."}, {"type": "color", "value": "{color.action.primary.bg}", "tokenPath": "blockquote.accent.color", "descriptionKey": "components.blockquote.tokens.accent_color", "descriptionFallback": "Default accent bar / glyph color."}, {"type": "dimension", "value": "4px", "tokenPath": "blockquote.accent.width", "descriptionKey": "components.blockquote.tokens.accent_width", "descriptionFallback": "Accent bar width."}, {"type": "dimension", "value": "{font.size.3xl}", "tokenPath": "blockquote.pull.font-size", "descriptionKey": "components.blockquote.tokens.pull_font_size", "descriptionFallback": "Font size in pull variant."}, {"type": "dimension", "value": "8rem", "tokenPath": "blockquote.quoted.glyph-size", "descriptionKey": "components.blockquote.tokens.glyph_size", "descriptionFallback": "Background glyph size in quoted variant."}], "sourceFile": "packages/ds/tokens/component/blockquote.json", "pipelineNote": "Built with Style Dictionary v4 + @tokens-studio/sd-transforms."}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"220\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"20\" width=\"660\" height=\"180\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"20\" y=\"20\" width=\"6\" height=\"180\" rx=\"2\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"50\" font-size=\"28\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" opacity=\"0.12\" font-family=\"serif\" font-weight=\"700\">\"</text>\n  <rect x=\"36\" y=\"30\" width=\"630\" height=\"100\" rx=\"3\" fill=\"