INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d3dddded-ed52-4aca-aaca-d19bb0276224', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'component', 'bracket-competitor', 'BracketCompetitor', 'Data Display', NULL, 'mdi-account-box-outline', 'components.catalog.bracket_competitor.description', 'A single competitor row inside a bracket match card, showing seed, avatar, name, advantage badge, forfeit indicator and score.', NULL, NULL, 'origam-bracket-competitor', NULL, NULL, 'origam', NULL, NULL, '/stories/?story=components-bracket--design', '/docs/components/Bracket/OrigamBracketCompetitor.html', 'bracket', '{"a11y": {"notes": [{"noteKey": "components.bracket_competitor.a11y.aria_label_note", "noteFallback": "Dynamic aria-label is computed: \"name, score N, winner\" — screen readers announce the full match context."}, {"noteKey": "components.bracket_competitor.a11y.tbd_note", "noteFallback": "When competitor is null, aria-label becomes \"To be determined\"."}, {"noteKey": "components.bracket_competitor.a11y.advantage_note", "noteFallback": "The advantage badge has its own aria-label: \"N-round head start\"."}, {"noteKey": "components.bracket_competitor.a11y.focus_note", "noteFallback": "focus-visible outline: 2px solid primary color with -2px offset when interactive=true."}], "roles": ["button"], "keyboard": [{"key": "Enter / Space", "actionKey": "components.bracket_competitor.a11y.key_activate", "actionFallback": "Emits the click event when interactive=true."}, {"key": "Tab", "actionKey": "components.bracket_competitor.a11y.key_tab", "actionFallback": "Moves focus to the next interactive element."}]}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"640\" height=\"160\