INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('86820d1c-05a1-4e6e-b3ad-12312c8d7c3e', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'component', 'breadcrumb', 'Breadcrumb', 'Navigation', NULL, 'mdi-dots-horizontal', 'components.catalog.breadcrumb.description', 'Hierarchical navigation trail rendered as a <nav> landmark with an ordered list of items and configurable dividers.', NULL, NULL, 'origam-breadcrumb', NULL, NULL, 'origam', NULL, NULL, '/stories/?story=components-breadcrumb--design', '/docs/components/Breadcrumb/OrigamBreadcrumb.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.breadcrumb.a11y.aria_label", "noteFallback": "The root <nav> receives aria-label=\"Breadcrumb\" from the useLocale translation (key: origam.breadcrumb.ariaLabel)."}, {"noteKey": "components.breadcrumb.a11y.aria_current", "noteFallback": "The last item is automatically set to aria-current=\"page\" via the isActive prop on OrigamBreadcrumbItem."}, {"noteKey": "components.breadcrumb.a11y.divider_hidden", "noteFallback": "OrigamBreadcrumbDivider is aria-hidden — the separators are purely presentational and not read by screen readers."}, {"noteKey": "components.breadcrumb.a11y.v_contrast", "noteFallback": "The v-contrast directive is applied to the root for auto contrast when a custom color is set."}, {"noteKey": "components.breadcrumb.a11y.disabled_opacity", "noteFallback": "Disabled items receive opacity-50 and pointer-events: none without the native disabled attribute (which does not apply to anchors)."}], "roles": ["navigation", "list", "listitem"], "keyboard": [{"key": "Tab", "actionKey": "components.breadcrumb.a11y.key_tab", "actionFallback": "Moves focus through each breadcrumb item link."}, {"key": "Enter", "actionKey": "components.breadcrumb.a11y.key_enter", "actionFallback": "Follows the link of the focused breadcrumb item."}]}, "tokens": {"excerpt": [{"type": "color", "value": "{color.text.primary}", "tokenPath": "breadcrumb.color", "descriptionKey": "components.breadcrumb.tokens.color", "descriptionFallback": "Container text color."}, {"type": "color", "value": "transparent", "tokenPath": "breadcrumb.background", "descriptionKey": "components.breadcrumb.tokens.background", "descriptionFallback": "Container background."}, {"type": "color", "value": "{color.action.primary.bg}", "tokenPath": "breadcrumb.item.hover-color", "descriptionKey": "components.breadcrumb.tokens.item_hover_color", "descriptionFallback": "Item color on hover."}, {"type": "color", "value": "{color.text.secondary}", "tokenPath": "breadcrumb.item.active-color", "descriptionKey": "components.breadcrumb.tokens.item_active_color", "descriptionFallback": "Current-page item color."}, {"type": "color", "value": "{color.text.secondary}", "tokenPath": "breadcrumb.divider.color", "descriptionKey": "components.breadcrumb.tokens.divider_color", "descriptionFallback": "Divider color."}, {"type": "dimension", "value": "{space.2}", "tokenPath": "breadcrumb.divider.padding-inline", "descriptionKey": "components.breadcrumb.tokens.divider_padding", "descriptionFallback": "Divider horizontal padding."}], "sourceFile": "packages/ds/tokens/component/breadcrumb.json", "pipelineNote": "Built with Style Dictionary v4 + @tokens-studio/sd-transforms."}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"100\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"10\" y=\"20\" width=\"680\" height=\"60\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"20\" y=\"30\" width=\"80\" height=\"40\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"60\" y=\"55\" font-size=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">Home</text>\n  <rect x=\"110\" y=\"40\" width=\"20\" height=\"20\" rx=\"2\" fill=\"var(--origam-color__surface---sunken, rgba(168,85,247,0.08))\"/>\n  <text x=\"120\" y=\"55\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #525252)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">/</text>\n  <rect x=\"140\" y=\"30\" width=\"120\" height=\"40\" rx=\"4\" fill=\"var(--origam-color__surface---sunken, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---subtle, rgba(168,85,247,0.25))\" stroke-width=\"1\"/>\n  <text x=\"200\" y=\"55\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #525252)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">Components</text>\n  <rect x=\"270\" y=\"40\" width=\"20\" height=\"20\" rx=\"2\" fill=\"var(--origam-color__surface---sunken, rgba(168,85,247,0.08))\"/>\n  <text x=\"280\" y=\"55\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #525252)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">/</text>\n  <rect x=\"300\" y=\"30\" width=\"120\" height=\"40\" rx=\"4\" fill=\"var(--origam-color__surface---sunken, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---subtle, rgba(168,85,247,0.25))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"360\" y=\"55\" font-size=\"10\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">Breadcrumb</text>\n  <circle cx=\"12\" cy=\"22\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"12\" y=\"26\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\