INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4fc0e751-bac9-4ab7-b74c-7aae81805a00', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'component', 'btn', 'Btn', 'Form & Input', NULL, 'mdi-gesture-tap-button', 'components.catalog.btn.description', 'test camel', NULL, NULL, 'origam-btn', NULL, NULL, 'origam', NULL, NULL, 'https://example.com', '/docs/components/Btn/OrigamBtn.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.btn.a11y.disabled_note", "noteFallback": "When disabled=true and tag is <a>, aria-disabled=\"true\" is set instead of the disabled attribute (which has no effect on anchors). Pointer events are removed via CSS."}, {"noteKey": "components.btn.a11y.focus_note", "noteFallback": "Focus-visible outline uses 2px solid currentColor with a 2px offset. The outline is only shown for keyboard navigation (not mouse click)."}, {"noteKey": "components.btn.a11y.loading_note", "noteFallback": "When loading=true, OrigamProgress is injected with role=\"progressbar\". The button is non-interactive (pointer-events: none) during loading."}, {"noteKey": "components.btn.a11y.reduced_motion_note", "noteFallback": "All transitions are disabled under prefers-reduced-motion: reduce."}, {"noteKey": "components.btn.a11y.icon_note", "noteFallback": "Icon-only buttons (icon prop) must have an aria-label describing the action — the label text is not visible."}], "roles": ["button"], "keyboard": [{"key": "Enter / Space", "actionKey": "components.btn.a11y.key_activate", "actionFallback": "Activates the button (fires click event). Native <button> behavior."}, {"key": "Tab", "actionKey": "components.btn.a11y.key_tab", "actionFallback": "Moves focus to the next interactive element.