INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('cac6de51-3dbe-4769-81f5-b82f312106f9', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'component', 'carousel-item', 'CarouselItem', 'Data Display', NULL, 'mdi-image-outline', 'components.catalog.carousel_item.description', 'A single slide inside OrigamCarousel — wraps OrigamWindowItem and OrigamImg, forwarding all image and window-item props.', NULL, NULL, 'origam-carousel-item', NULL, NULL, 'origam', NULL, NULL, '/stories/?story=components-carousel--design', '/docs/components/Carousel/OrigamCarousel.html', 'carousel', '{"a11y": {"notes": [{"noteKey": "components.carousel_item.a11y.alt_required", "noteFallback": "When src is set, always provide a meaningful alt attribute. An empty alt=\"\" is acceptable for purely decorative images."}, {"noteKey": "components.carousel_item.a11y.hidden_slides", "noteFallback": "Inactive slides are hidden from the accessibility tree by OrigamWindowItem (aria-hidden=\"true\") — only the active slide is reachable by keyboard and screen readers."}], "roles": [], "keyboard": [{"key": "Tab", "actionKey": "components.carousel_item.a11y.key_tab", "actionFallback": "Focus moves to interactive content inside the slide (links, buttons, form elements)."}]}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"20\" width=\"660\" height=\"140\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"20\" y=\"20\" width=\"660\" height=\"140\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.30))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <rect x=\"50\" y=\"40\" width=\"600\" height=\"100\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\"/>\n  <text x=\"350\" y=\"96\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-img (src, cover, srcset, alt…)</text>\n  <rect x=\"50\" y=\"110\" width=\"300\" height=\"30\" rx=\"2\" fill=\"var(--origam-color__feedback--info---bg, rgba(8,145,178,0.12))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"200\" y=\"128\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">#content slot (overlay)</text>\n  <circle cx=\"28\" cy=\"28\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"32\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"58\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"58\" y=\"52\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"58\" cy=\"118\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"58\" y=\"122\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <text x=\"350\" y=\"185\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">① root = origam-window-item; height: inherit flows from the parent Carousel</text>\n", "code": "<!-- root delegates to origam-window-item -->\n<origam-window-item class=\"origam-carousel-item\">\n  <template #default>\n    <!-- default slot: full custom content -->\n    <slot name=\"default\">\n      <!-- embedded image when no default slot is provided -->\n      <origam-img v-bind=\"imgProps\">\n        <!-- overlay content -->\n        <template #default>\n          <slot name=\"content\" />\n        </template>\n        <!-- error fallback -->\n        <template #error>\n          <slot name=\"error\" />\n        </template>\n        <!-- loading placeholder -->\n        <template #placeholder>\n          <slot name=\"placeholder\" />\n        </template>\n      </origam-img>\n    </slot>\n  </template>\n</origam-window-item>", "legend": [{"cls": ".origam-carousel-item", "num": 1, "descriptionKey": "components.carousel_item.anatomy.root", "descriptionFallback": "Root element. Delegates to OrigamWindowItem and inherits height from the parent Carousel."}, {"cls": "origam-img (embedded)", "num": 2, "descriptionKey": "components.carousel_item.anatomy.img", "descriptionFallback": "OrigamImg instance filling the slide area. Props (src, cover, alt, srcset, eager…) are forwarded automatically. Skipped when the default slot is used."}, {"cls": "#content slot", "num": 3, "descriptionKey": "components.carousel_item.anatomy.content_slot", "descriptionFallback": "Projected into OrigamImg''s default slot. Use for overlay captions, badges, or action buttons positioned over the image."}], "classes": [{"cls": "origam-carousel-item", "descriptionKey": "components.carousel_item.anatomy.root", "descriptionFallback": "Root element. display: block; height: inherit — fills the Carousel height."}], "svgDesc": "Schematic of the CarouselItem component with 3 numbered internal parts.", "svgTitle": "Anatomy of OrigamCarouselItem", "rootClass": "origam-carousel-item", "figcaption": "Anatomy of <code>&lt;origam-carousel-item&gt;</code> — 3 internal parts. The root delegates to OrigamWindowItem; the image fills the inherited height.", "svgViewBox": "0 0 700 200"}, "cssVars": [{"name": "--origam-carousel-item---display", "defaultValue": "block", "descriptionKey": "components.carousel_item.css_vars.display", "descriptionFallback": "Display mode of the root element."}, {"name": "--origam-carousel-item---height", "defaultValue": "inherit", "descriptionKey": "components.carousel_item.css_vars.height", "descriptionFallback": "Height inherited from the parent Carousel container."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.carousel_item.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component (OrigamImg or OrigamWindowItem)."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.carousel_item.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle for the carousel item."}, {"name": "id", "type": "string", "descriptionKey": "components.carousel_item.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.carousel_item.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.carousel_item.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.carousel_item.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "switch", "prop": "disabled", "labelKey": "components.carousel_item.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "switch", "prop": "cover", "labelKey": "components.carousel_item.playground.cover", "defaultValue": false, "labelFallback": "Cover"}], "defaultSlotContent": "Content"}, "previewVariants": []}', false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3dd6fbf9-57a3-4433-96d7-775010409f6a', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'component', 'chart', 'Chart', 'Data Visualization', NULL, 'mdi-chart-line', 'components.catalog.chart.description', 'Universal chart component with 29 visualization primitives (line, area, bar, column, pie, donut, scatter, radar, gauge, pyramid, funnel, honeycomb, treemap, sankey, word-cloud, heatmap, sunburst, box-plot, pictorial, candlestick, streamgraph, variwide, polar-bar, bullet, pareto, map, sparkline, spline, stepped-line). The type prop routes to the appropriate family member.', NULL, NULL, 'origam-chart', NULL, NULL, 'origam', NULL, NULL, '/stories/?story=components-chart--design', '/docs/components/Chart/OrigamChart.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.chart.a11y.reduced_motion", "noteFallback": "The animated prop respects prefers-reduced-motion: reduce — set animated=false or let the component detect the system preference."}, {"noteKey": "components.chart.a11y.color_blind", "noteFallback": "Use colorScheme to provide intent-based colours with sufficient contrast for all colour-vision deficiency profiles. Avoid relying solely on hue to distinguish series — use dashed/solid patterns or labels when possible."}, {"noteKey": "components.chart.a11y.empty_slot", "noteFallback": "The #empty slot provides a meaningful message when no data is available, ensuring screen reader users are not left with a silent chart container."}], "roles": ["img", "figure"], "keyboard": [{"key": "Tab", "actionKey": "components.chart.a11y.key_tab", "actionFallback": "Moves focus to interactive data points (when keyboard navigation is enabled)."}, {"key": "Enter / Space", "actionKey": "components.chart.a11y.key_activate", "actionFallback": "Fires point-click emit on a focused data point."}]}, "tokens": {"excerpt": [{"type": "color", "value": "{color.surface.default}", "tokenPath": "chart.background-color", "descriptionKey": "components.chart.tokens.bg", "descriptionFallback": "Chart container background."}, {"type": "dimension", "value": "{font.size.lg}", "tokenPath": "chart.title.font-size", "descriptionKey": "components.chart.tokens.title_font_size", "descriptionFallback": "Title font size."}, {"type": "color", "value": "{color.border.subtle}", "tokenPath": "chart.grid.color", "descriptionKey": "components.chart.tokens.grid_color", "descriptionFallback": "Grid line colour."}, {"type": "color", "value": "{color.surface.inverse}", "tokenPath": "chart.tooltip.background-color", "descriptionKey": "components.chart.tokens.tooltip_bg", "descriptionFallback": "Tooltip background."}, {"type": "dimension", "value": "2px", "tokenPath": "chart.path.stroke-width", "descriptionKey": "components.chart.tokens.path_stroke_width", "descriptionFallback": "Line/area stroke width."}, {"type": "duration", "value": "600ms", "tokenPath": "chart.animation.duration", "descriptionKey": "components.chart.tokens.animation_duration", "descriptionFallback": "Enter/update animation duration."}, {"type": "dimension", "value": "{radius.xs}", "tokenPath": "chart.bar.border-radius", "descriptionKey": "components.chart.tokens.bar_border_radius", "descriptionFallback": "Bar/column corner radius."}, {"type": "number", "value": "0.18", "tokenPath": "chart.radar.fill-opacity", "descriptionKey": "components.chart.tokens.radar_fill_opacity", "descriptionFallback": "Radar polygon fill opacity."}], "sourceFile": "packages/ds/tokens/component/chart.json", "pipelineNote": "Built with Style Dictionary v4 + @tokens-studio/sd-transforms."}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"220\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"20\" width=\"660\" height=\"160\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"350\" y=\"36\" font-size=\"13\" fill=\"var(--origam-color__text---primary, #1a0f3c)\" text-anchor=\"middle\" font-family=\"sans-serif\" font-weight=\"600\">Chart Title</text>\n  <line x1=\"60\" y1=\"40\" x2=\"60\" y2=\"155\" stroke=\"var(--origam-color__border---default, #e5e1f5)\" stroke-width=\"1\"/>\n  <line x1=\"60\" y1=\"155\" x2=\"660\" y2=\"155\" stroke=\"var(--origam-color__border---default, #e5e1f5)\" stroke-width=\"1\"/>\n  <polyline points=\"100,130 220,90 340,110 460,60 580,80 640,50\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"2\" fill=\"none\"/>\n  <rect x=\"220\" y=\"170\" width=\"260\" height=\"8\" rx=\"4\" fill=\"var(--origam-color__surface---overlay, rgba(124,58,237,0.08))\"/>\n  <text x=\"350\" y=\"178\" font-size=\"8\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">Legend</text>\n  <circle cx=\"28\" cy=\"28\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"32\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"56\" cy=\"40\" r=\"10\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"56\" y=\"44\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"60\" cy=\"150\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"60\" y=\"154\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"350\" cy=\"173\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"350\" y=\"177\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"400\" cy=\"80\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"400\" y=\"84\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <text x=\"350\" y=\"210\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">Routes to type-specific family member at runtime (cartesian / polar / radar / gauge / …)</text>\n", "code": "<!-- OrigamChart routes to a family member per type -->\n<origam-chart type=\"line\" :series=\"series\" :categories=\"categories\">\n  <!-- optional slot overrides -->\n  <template #tooltip=\"{ point, series, category }\">\n    <custom-tooltip :point=\"point\" :series=\"series\" />\n  </template>\n  <template #legend-item=\"{ series, visible }\">\n    <custom-legend-entry :series=\"series\" :visible=\"visible\" />\n  </template>\n  <template #empty>\n    <p>No data available.</p>\n  </template>\n</origam-chart>", "legend": [{"cls": ".origam-chart", "num": 1, "descriptionKey": "components.chart.anatomy.root", "descriptionFallback": "Root element. Delegates to the correct family component (cartesian/polar/radar/gauge/pyramid…)."}, {"cls": ".origam-chart__title", "num": 2, "descriptionKey": "components.chart.anatomy.title", "descriptionFallback": "Title and subtitle block rendered above the plotting area."}, {"cls": ".origam-chart__axis", "num": 3, "descriptionKey": "components.chart.anatomy.axis", "descriptionFallback": "X and Y axes with tick labels. Rendered by OrigamChartAxis. Hidden when showAxis=false."}, {"cls": ".origam-chart__legend", "num": 4, "descriptionKey": "components.chart.anatomy.legend", "descriptionFallback": "Legend block. Rendered by OrigamChartLegend. Position controlled by legendPosition prop."}, {"cls": ".origam-chart__plot", "num": 5, "descriptionKey": "components.chart.anatomy.plot", "descriptionFallback": "SVG plotting area where series paths, bars or slices are drawn."}], "classes": [{"cls": "origam-chart", "descriptionKey": "components.chart.anatomy.root", "descriptionFallback": "Root element wrapping the SVG plotting area."}, {"cls": "origam-chart__title", "descriptionKey": "components.chart.anatomy.title", "descriptionFallback": "Title / subtitle region."}, {"cls": "origam-chart__axis", "descriptionKey": "components.chart.anatomy.axis", "descriptionFallback": "Axis tick labels and grid lines."}, {"cls": "origam-chart__legend", "descriptionKey": "components.chart.anatomy.legend", "descriptionFallback": "Legend swatch entries."}, {"cls": "origam-chart__plot", "descriptionKey": "components.chart.anatomy.plot", "descriptionFallback": "SVG series paths, bars and point markers."}], "svgDesc": "Schematic of the Chart component with 5 numbered internal parts.", "svgTitle": "Anatomy of OrigamChart", "rootClass": "origam-chart", "figcaption": "Anatomy of <code>&lt;origam-chart&gt;</code> — 5 visible regions; the component delegates rendering to the appropriate family member based on the <code>type</code> prop.", "svgViewBox": "0 0 700 220"}, "cssVars": [{"name": "--origam-chart---background-color", "defaultValue": "{color.surface.default}", "descriptionKey": "components.chart.css_vars.bg", "descriptionFallback": "Chart container background colour."}, {"name": "--origam-chart---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.chart.css_vars.color", "descriptionFallback": "Default text colour for title, labels and legend."}, {"name": "--origam-chart---padding", "defaultValue": "{space.3}", "descriptionKey": "components.chart.css_vars.padding", "descriptionFallback": "Inner padding of the chart container."}, {"name": "--origam-chart__title---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.chart.css_vars.title_color", "descriptionFallback": "Title text colour."}, {"name": "--origam-chart__title---font-size", "defaultValue": "{font.size.lg}", "descriptionKey": "components.chart.css_vars.title_font_size", "descriptionFallback": "Title font size."}, {"name": "--origam-chart__axis---color", "defaultValue": "{color.border.default}", "descriptionKey": "components.chart.css_vars.axis_color", "descriptionFallback": "Axis line colour."}, {"name": "--origam-chart__grid---color", "defaultValue": "{color.border.subtle}", "descriptionKey": "components.chart.css_vars.grid_color", "descriptionFallback": "Grid line colour."}, {"name": "--origam-chart__tooltip---background-color", "defaultValue": "{color.surface.inverse}", "descriptionKey": "components.chart.css_vars.tooltip_bg", "descriptionFallback": "Tooltip background colour."}, {"name": "--origam-chart__path---stroke-width", "defaultValue": "2px", "descriptionKey": "components.chart.css_vars.path_stroke_width", "descriptionFallback": "Stroke width of line/area series paths."}, {"name": "--origam-chart__animation---duration", "defaultValue": "600ms", "descriptionKey": "components.chart.css_vars.animation_duration", "descriptionFallback": "Animation duration for enter/update transitions."}], "playground": {"controls": [{"kind": "select", "prop": "type", "options": [{"label": "line", "value": "line"}, {"label": "area", "value": "area"}, {"label": "bar", "value": "bar"}, {"label": "column", "value": "column"}, {"label": "pie", "value": "pie"}, {"label": "donut", "value": "donut"}, {"label": "scatter", "value": "scatter"}, {"label": "radar", "value": "radar"}, {"label": "gauge", "value": "gauge"}], "labelKey": "components.chart.playground.type", "defaultValue": "line", "labelFallback": "Chart type"}, {"kind": "switch", "prop": "showLegend", "labelKey": "components.chart.playground.show_legend", "defaultValue": true, "labelFallback": "Show legend"}, {"kind": "switch", "prop": "showGrid", "labelKey": "components.chart.playground.show_grid", "defaultValue": true, "labelFallback": "Show grid"}, {"kind": "switch", "prop": "animated", "labelKey": "components.chart.playground.animated", "defaultValue": true, "labelFallback": "Animated"}, {"kind": "switch", "prop": "stacked", "labelKey": "components.chart.playground.stacked", "defaultValue": false, "labelFallback": "Stacked"}]}}', false, NULL, NULL);
