INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3c9ed565-23e3-4bc6-a541-b20820f567eb', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'component', 'chart-heatmap', 'ChartHeatmap', 'Data Display', NULL, 'mdi-grid', 'components.catalog.chart_heatmap.description', 'Rectangular heatmap chart. Renders a grid of SVG <rect> cells coloured by value via CSS color-mix interpolation. Common uses: GitHub activity grids, correlation matrices, weekday × hour patterns.', NULL, NULL, 'origam-chart-heatmap', NULL, NULL, 'origam', NULL, NULL, '/stories/?story=components-chart-heatmap--design', '/docs/components/Chart/OrigamChartHeatmap.html', 'chart', '{"a11y": {"notes": [{"noteKey": "components.chart_heatmap.a11y.figure_role", "noteFallback": "Root has role=\"figure\" with aria-label from the title prop (falls back to \"heatmap chart\")."}, {"noteKey": "components.chart_heatmap.a11y.svg_role", "noteFallback": "The SVG carries role=\"img\" with a <title> and <desc> listing column and row counts."}, {"noteKey": "components.chart_heatmap.a11y.cell_aria", "noteFallback": "Each cell has aria-label in the format \"xCat × yCat: value\" for screen reader announcement."}, {"noteKey": "components.chart_heatmap.a11y.reduced_motion", "noteFallback": "Entry animations are disabled via @media (prefers-reduced-motion: reduce)."}], "roles": ["figure", "img", "button"], "keyboard": [{"key": "Tab", "actionKey": "components.chart_heatmap.a11y.key_tab", "actionFallback": "Moves focus through each cell (tabindex=\"0\")."}, {"key": "Enter / Space", "actionKey": "components.chart_heatmap.a11y.key_activate", "actionFallback": "Activates the focused cell, firing the point-click emit."}]}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"240\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"20\" width=\"660\" height=\"200\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"32\" y=\"28\" width=\"636\" height=\"16\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\"/>\n  <text x=\"350\" y=\"40\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">__header (title + subtitle)</text>\n  <rect x=\"70\" y=\"52\" width=\"82\" height=\"36\" rx=\"2\" fill=\"color-mix(in srgb, rgba(239,68,68,0.8) 10%, rgba(8,145,178,0.8))\"/>\n  <rect x=\"156\" y=\"52\" width=\"82\" height=\"36\" rx=\"2\" fill=\"color-mix(in srgb, rgba(239,68,68,0.8) 35%, rgba(8,145,178,0.8))\"/>\n  <rect x=\"242\" y=\"52\" width=\"82\" height=\"36\" rx=\"2\" fill=\"color-mix(in srgb, rgba(239,68,68,0.8) 60%, rgba(8,145,178,0.8))\"/>\n  <rect x=\"328\" y=\"52\" width=\"82\" height=\"36\" rx=\"2\" fill=\"color-mix(in srgb, rgba(239,68,68,0.8) 80%, rgba(8,145,178,0.8))\"/>\n  <rect x=\"414\" y=\"52\" width=\"82\" height=\"36\" rx=\"2\" fill=\"color-mix(in srgb, rgba(239,68,68,0.8) 95%, rgba(8,145,178,0.8))\"/>\n  <rect x=\"70\" y=\"92\" width=\"82\" height=\"36\" rx=\"2\" fill=\"color-mix(in srgb, rgba(239,68,68,0.8) 20%, rgba(8,145,178,0.8))\"/>\n  <rect x=\"156\" y=\"92\" width=\"82\" height=\"36\" rx=\"2\" fill=\"color-mix(in srgb, rgba(239,68,68,0.8) 55%, rgba(8,145,178,0.8))\"/>\n  <rect x=\"242\" y=\"92\" width=\"82\" height=\"36\" rx=\"2\" fill=\"color-mix(in srgb, rgba(239,68,68,0.8) 40%, rgba(8,145,178,0.8))\"/>\n  <rect x=\"328\" y=\"92\" width=\"82\" height=\"36\" rx=\"2\" fill=\"color-mix(in srgb, rgba(239,68,68,0.8) 75%, rgba(8,145,178,0.8))\"/>\n  <rect x=\"414\" y=\"92\" width=\"82\" height=\"36\" rx=\"2\" fill=\"color-mix(in srgb, rgba(239,68,68,0.8) 30%, rgba(8,145,178,0.8))\"/>\n  <text x=\"50\" y=\"74\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"end\">Mon</text>\n  <text x=\"50\" y=\"114\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"end\">Tue</text>\n  <text x=\"111\" y=\"142\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\">9h</text>\n  <text x=\"197\" y=\"142\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\">12h</text>\n  <rect x=\"70\" y=\"150\" width=\"426\" height=\"10\" rx=\"2\" fill=\"url(#origam-hm-grad)\"/>\n  <defs><linearGradient id=\"origam-hm-grad\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\"><stop offset=\"0%\" stop-color=\"rgba(8,145,178,0.8)\"/><stop offset=\"100%\" stop-color=\"rgba(239,68,68,0.8)\"/></linearGradient></defs>\n  <text x=\"70\" y=\"173\" font-size=\"7\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\">0</text>\n  <text x=\"496\" y=\"173\" font-size=\"7\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"end\">50</text>\n  <circle cx=\"28\" cy=\"28\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"32\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"78\" cy=\"60\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"78\" y=\"64\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"50\" cy=\"74\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"50\" y=\"78\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"111\" cy=\"142\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"111\" y=\"146\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"78\" cy=\"155\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"78\" y=\"159\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <circle cx=\"36\" cy=\"36\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"40\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">6</text>\n  <text x=\"350\" y=\"225\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">② cell fill = CSS color-mix(in srgb, colorRange[1] N%, colorRange[0]) — ⑤ gradient legend</text>\n", "code": "<div class=\"origam-chart-heatmap\" role=\"figure\" aria-label=\"Weekly activity\">\n  <header class=\"origam-chart-heatmap__header\">\n    <div class=\"origam-chart-heatmap__title\">Weekly activity</div>\n  </header>\n\n  <div class=\"origam-chart-heatmap__body\">\n    <svg class=\"origam-chart-heatmap__svg origam-chart__svg\" role=\"img\">\n      <title>Weekly activity</title>\n      <desc>Heatmap chart with 5 columns and 4 rows.</desc>\n\n      <defs>\n        <linearGradient id=\"origam-heatmap-legend-gradient\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\">\n          <stop offset=\"0%\" />\n          <stop offset=\"100%\" />\n        </linearGradient>\n      </defs>\n\n      <!-- cell grid -->\n      <g class=\"origam-chart__heatmap-series\">\n        <g class=\"origam-chart__heatmap-cell-group\">\n          <rect class=\"origam-chart__heatmap-cell\" tabindex=\"0\" role=\"button\" />\n          <text class=\"origam-chart__heatmap-label\">42</text>\n        </g>\n      </g>\n\n      <!-- axis labels -->\n      <g class=\"origam-chart__heatmap-x-axis\">\n        <text class=\"origam-chart__heatmap-axis-label origam-chart__heatmap-axis-label--x\">Mon</text>\n      </g>\n      <g class=\"origam-chart__heatmap-y-axis\">\n        <text class=\"origam-chart__heatmap-axis-label origam-chart__heatmap-axis-label--y\">9h</text>\n      </g>\n\n      <!-- gradient legend (showGradientLegend=true) -->\n      <g class=\"origam-chart__heatmap-gradient-legend\">\n        <rect fill=\"url(#origam-heatmap-legend-gradient)\" />\n        <text class=\"origam-chart__heatmap-legend-label\">0</text>\n        <text class=\"origam-chart__heatmap-legend-label\">50</text>\n      </g>\n    </svg>\n\n    <!-- tooltip -->\n    <origam-chart-tooltip />\n  </div>\n</div>", "legend": [{"cls": ".origam-chart-heatmap", "num": 1, "descriptionKey": "components.chart_heatmap.anatomy.root", "descriptionFallback": "Root element. CSS grid with areas: header / body. role=\"figure\" + aria-label from title."}, {"cls": ".origam-chart__heatmap-cell", "num": 2, "descriptionKey": "components.chart_heatmap.anatomy.cell", "descriptionFallback": "SVG <rect> for each data cell. Fill is CSS color-mix interpolated between colorRange endpoints. tabindex=\"0\" + role=\"button\"."}, {"cls": ".origam-chart__heatmap-axis-label--y", "num": 3, "descriptionKey": "components.chart_heatmap.anatomy.y_label", "descriptionFallback": "Y-axis row labels (left side). Hidden when showAxis=false."}, {"cls": ".origam-chart__heatmap-axis-label--x", "num": 4, "descriptionKey": "components.chart_heatmap.anatomy.x_label", "descriptionFallback": "X-axis column labels (bottom). Hidden when showAxis=false."}, {"cls": ".origam-chart__heatmap-gradient-legend", "num": 5, "descriptionKey": "components.chart_heatmap.anatomy.gradient_legend", "descriptionFallback": "Inline SVG gradient bar with min/max value labels. Visible when showGradientLegend=true and legendPosition is top or bottom."}, {"cls": ".origam-chart-heatmap__header", "num": 6, "descriptionKey": "components.chart_heatmap.anatomy.header", "descriptionFallback": "Title and subtitle block. Rendered only when title or subtitle is provided."}], "classes": [{"cls": "origam-chart-heatmap", "descriptionKey": "components.chart_heatmap.anatomy.root", "descriptionFallback": "Root element."}, {"cls": "origam-chart-heatmap__header", "descriptionKey": "components.chart_heatmap.anatomy.header", "descriptionFallback": "Title/subtitle block."}, {"cls": "origam-chart-heatmap__title", "descriptionKey": "components.chart_heatmap.anatomy.title", "descriptionFallback": "Primary title."}, {"cls": "origam-chart-heatmap__subtitle", "descriptionKey": "components.chart_heatmap.anatomy.subtitle", "descriptionFallback": "Subtitle."}, {"cls": "origam-chart-heatmap__body", "descriptionKey": "components.chart_heatmap.anatomy.body", "descriptionFallback": "Body containing the SVG."}, {"cls": "origam-chart-heatmap__svg", "descriptionKey": "components.chart_heatmap.anatomy.svg", "descriptionFallback": "SVG canvas."}, {"cls": "origam-chart__heatmap-cell-group", "descriptionKey": "components.chart_heatmap.anatomy.cell_group", "descriptionFallback": "<g> grouping one cell and its label."}, {"cls": "origam-chart__heatmap-cell", "descriptionKey": "components.chart_heatmap.anatomy.cell", "descriptionFallback": "Cell <rect>. Fill = color-mix interpolation."}, {"cls": "origam-chart__heatmap-cell--active", "descriptionKey": "components.chart_heatmap.anatomy.cell_active", "descriptionFallback": "Active modifier on hover/focus."}, {"cls": "origam-chart__heatmap-label", "descriptionKey": "components.chart_heatmap.anatomy.cell_label", "descriptionFallback": "Numeric value label centred in the cell."}, {"cls": "origam-chart__heatmap-axis-label", "descriptionKey": "components.chart_heatmap.anatomy.axis_label", "descriptionFallback": "Axis label (shared base class)."}, {"cls": "origam-chart__heatmap-axis-label--x", "descriptionKey": "components.chart_heatmap.anatomy.x_label", "descriptionFallback": "X-axis column label."}, {"cls": "origam-chart__heatmap-axis-label--y", "descriptionKey": "components.chart_heatmap.anatomy.y_label", "descriptionFallback": "Y-axis row label."}, {"cls": "origam-chart__heatmap-gradient-legend", "descriptionKey": "components.chart_heatmap.anatomy.gradient_legend", "descriptionFallback": "Inline gradient legend group."}, {"cls": "origam-chart__heatmap-legend-label", "descriptionKey": "components.chart_heatmap.anatomy.legend_label", "descriptionFallback": "Min/max value label beside the gradient bar."}, {"cls": "origam-chart-heatmap--no-animation", "descriptionKey": "components.chart_heatmap.anatomy.mod_no_animation", "descriptionFallback": "Disables entry animation."}], "svgDesc": "Schematic of the ChartHeatmap component with 6 numbered internal parts.", "svgTitle": "Anatomy of OrigamChartHeatmap", "rootClass": "origam-chart-heatmap", "figcaption": "Anatomy of <code>&lt;origam-chart-heatmap&gt;</code> — 6 internal parts. Cell colour interpolated via CSS <code>color-mix(in srgb, …)</code>.", "svgViewBox": "0 0 700 240"}, "cssVars": [{"name": "--origam-chart---gap", "defaultValue": "12px", "descriptionKey": "components.chart_heatmap.css_vars.gap", "descriptionFallback": "Gap between header and body areas."}, {"name": "--origam-chart---padding", "defaultValue": "12px", "descriptionKey": "components.chart_heatmap.css_vars.padding", "descriptionFallback": "Internal padding of the chart root."}, {"name": "--origam-chart---background-color", "defaultValue": "transparent", "descriptionKey": "components.chart_heatmap.css_vars.background_color", "descriptionFallback": "Background colour of the chart root."}, {"name": "--origam-chart---animation-duration", "defaultValue": "600ms", "descriptionKey": "components.chart_heatmap.css_vars.animation_duration", "descriptionFallback": "Entry animation duration. Driven by animationDuration prop."}, {"name": "--origam-chart__heatmap---stroke-color", "defaultValue": "var(--origam-color-surface-default, #ffffff)", "descriptionKey": "components.chart_heatmap.css_vars.stroke_color", "descriptionFallback": "Stroke colour of cell rects (creates visible gap between cells)."}, {"name": "--origam-chart__heatmap---stroke-width", "defaultValue": "0.5", "descriptionKey": "components.chart_heatmap.css_vars.stroke_width", "descriptionFallback": "Stroke width of cell rects."}, {"name": "--origam-chart__heatmap-label---font-size", "defaultValue": "0.5625rem", "descriptionKey": "components.chart_heatmap.css_vars.label_font_size", "descriptionFallback": "Font size of cell value labels."}, {"name": "--origam-chart__heatmap-label---color", "defaultValue": "#ffffff", "descriptionKey": "components.chart_heatmap.css_vars.label_color", "descriptionFallback": "Fill colour of cell value labels."}, {"name": "--origam-chart__heatmap-axis-label---font-size", "defaultValue": "0.625rem", "descriptionKey": "components.chart_heatmap.css_vars.axis_label_font_size", "descriptionFallback": "Font size of axis labels."}, {"name": "--origam-chart__title---font-size", "defaultValue": "1.125rem", "descriptionKey": "components.chart_heatmap.css_vars.title_font_size", "descriptionFallback": "Font size of the chart title."}], "playground": {"controls": [{"kind": "select", "prop": "bgColor", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.chart_heatmap.playground.bg_color", "defaultValue": "", "labelFallback": "Background color"}, {"kind": "text", "prop": "title", "labelKey": "components.chart_heatmap.playground.title", "defaultValue": "", "labelFallback": "Title"}, {"kind": "text", "prop": "subtitle", "labelKey": "components.chart_heatmap.playground.subtitle", "defaultValue": "", "labelFallback": "Subtitle"}, {"kind": "switch", "prop": "showLabel", "labelKey": "components.chart_heatmap.playground.show_label", "defaultValue": true, "labelFallback": "Show Label"}, {"kind": "switch", "prop": "showAxis", "labelKey": "components.chart_heatmap.playground.show_axis", "defaultValue": true, "labelFallback": "Show Axis"}, {"kind": "switch", "prop": "showGradientLegend", "labelKey": "components.chart_heatmap.playground.show_gradient_legend", "defaultValue": true, "labelFallback": "Show Gradient Legend"}, {"kind": "switch", "prop": "showLegend", "labelKey": "components.chart_heatmap.playground.show_legend", "defaultValue": true, "labelFallback": "Show Legend"}, {"kind": "switch", "prop": "showTooltip", "labelKey": "components.chart_heatmap.playground.show_tooltip", "defaultValue": true, "labelFallback": "Show Tooltip"}]}, "previewVariants": []}', false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('067f10bb-da2c-4f8d-b0db-de9acb616233', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'component', 'chart-honeycomb', 'ChartHoneycomb', 'Data Display', NULL, 'mdi-hexagon-multiple-outline', 'components.catalog.chart_honeycomb.description', 'Hexagonal tile-map chart. Renders a grid of SVG <polygon> hexagons positioned by (x=col, y=row) indices. Supports pointy-top and flat-top orientations, categorical and heatmap colour modes.', NULL, NULL, 'origam-chart-honeycomb', NULL, NULL, 'origam', NULL, NULL, '/stories/?story=components-chart-honeycomb--design', '/docs/components/Chart/OrigamChartHoneycomb.html', 'chart', '{"a11y": {"notes": [{"noteKey": "components.chart_honeycomb.a11y.figure_role", "noteFallback": "Root has role=\"figure\" with aria-label from the title prop (falls back to \"honeycomb chart\")."}, {"noteKey": "components.chart_honeycomb.a11y.svg_role", "noteFallback": "The SVG carries role=\"img\" with a <title> and <desc> listing the tile count."}, {"noteKey": "components.chart_honeycomb.a11y.tile_aria", "noteFallback": "Each tile has aria-label derived from its name and value (e.g. \"A: 42\")."}, {"noteKey": "components.chart_honeycomb.a11y.reduced_motion", "noteFallback": "Entry animations are disabled via @media (prefers-reduced-motion: reduce)."}], "roles": ["figure", "img", "button"], "keyboard": [{"key": "Tab", "actionKey": "components.chart_honeycomb.a11y.key_tab", "actionFallback": "Moves focus through each hex tile (tabindex=\"0\") and legend items."}, {"key": "Enter / Space", "actionKey": "components.chart_honeycomb.a11y.key_activate", "actionFallback": "Activates the focused tile, firing the point-click emit."}]}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"260\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"20\" width=\"660\" height=\"220\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"32\" y=\"28\" width=\"636\" height=\"16\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\"/>\n  <text x=\"350\" y=\"40\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">__header (title)</text>\n  <polygon points=\"140,95 165,81 190,95 190,122 165,136 140,122\" fill=\"var(--origam-color__action--primary---bg, rgba(124,58,237,0.8))\" stroke=\"var(--origam-color__surface---raised,#fff)\" stroke-width=\"2\"/>\n  <text x=\"165\" y=\"110\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" dominant-baseline=\"middle\" font-family=\"''JetBrains Mono'',monospace\">A</text>\n  <polygon points=\"193,95 218,81 243,95 243,122 218,136 193,122\" fill=\"var(--origam-color__feedback--success---bg, rgba(34,197,94,0.8))\" stroke=\"var(--origam-color__surface---raised,#fff)\" stroke-width=\"2\"/>\n  <text x=\"218\" y=\"110\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" dominant-baseline=\"middle\" font-family=\"''JetBrains Mono'',monospace\">B</text>\n  <polygon points=\"246,95 271,81 296,95 296,122 271,136 246,122\" fill=\"var(--origam-color__feedback--warning---bg, rgba(234,179,8,0.8))\" stroke=\"var(--origam-color__surface---raised,#fff)\" stroke-width=\"2\"/>\n  <text x=\"271\" y=\"110\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" dominant-baseline=\"middle\" font-family=\"''JetBrains Mono'',monospace\">C</text>\n  <polygon points=\"166,136 191,122 216,136 216,163 191,177 166,163\" fill=\"var(--origam-color__feedback--danger---bg, rgba(239,68,68,0.8))\" stroke=\"var(--origam-color__surface---raised,#fff)\" stroke-width=\"2\"/>\n  <text x=\"191\" y=\"151\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" dominant-baseline=\"middle\" font-family=\"''JetBrains Mono'',monospace\">D</text>\n  <polygon points=\"219,136 244,122 269,136 269,163 244,177 219,163\" fill=\"var(--origam-color__feedback--info---bg, rgba(8,145,178,0.8))\" stroke=\"var(--origam-color__surface---raised,#fff)\" stroke-width=\"2\"/>\n  <text x=\"244\" y=\"151\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" dominant-baseline=\"middle\" font-family=\"''JetBrains Mono'',monospace\">E</text>\n  <circle cx=\"28\" cy=\"28\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"32\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"148\" cy=\"103\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"148\" y=\"107\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"165\" cy=\"115\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"165\" y=\"119\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"165\" cy=\"132\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"165\" y=\"136\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"36\" cy=\"36\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"40\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <text x=\"350\" y=\"245\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">② tile polygon — points computed by tileSize × orientation; ③ label centred at (cx, cy)</text>\n", "code": "<div class=\"origam-chart-honeycomb\" role=\"figure\" aria-label=\"Hex tile map\">\n  <header class=\"origam-chart-honeycomb__header\">\n    <div class=\"origam-chart-honeycomb__title\">Hex tile map</div>\n  </header>\n\n  <div class=\"origam-chart-honeycomb__body\">\n    <svg class=\"origam-chart-honeycomb__svg origam-chart__svg\" role=\"img\">\n      <title>Hex tile map</title>\n      <desc>Honeycomb chart with 6 tiles.</desc>\n\n      <g class=\"origam-chart__honeycomb-series\">\n        <!-- one group per tile -->\n        <g class=\"origam-chart__honeycomb-tile-group\">\n          <!-- hex polygon (keyboard activatable) -->\n          <polygon\n            class=\"origam-chart__honeycomb-tile\"\n            points=\"…\"\n            tabindex=\"0\"\n            role=\"button\"\n            aria-label=\"A\"\n          />\n          <!-- centred label -->\n          <text class=\"origam-chart__honeycomb-label\">A</text>\n        </g>\n      </g>\n    </svg>\n\n    <!-- tooltip (showTooltip=true) -->\n    <origam-chart-tooltip />\n  </div>\n\n  <!-- legend (showLegend=true) -->\n  <origam-chart-legend />\n</div>", "legend": [{"cls": ".origam-chart-honeycomb", "num": 1, "descriptionKey": "components.chart_honeycomb.anatomy.root", "descriptionFallback": "Root element. CSS grid with areas: header / body / legend. role=\"figure\" + aria-label from title."}, {"cls": ".origam-chart__honeycomb-tile", "num": 2, "descriptionKey": "components.chart_honeycomb.anatomy.tile", "descriptionFallback": "SVG <polygon> for each tile. Points computed from tileSize, col/row index and orientation. tabindex=\"0\" + role=\"button\"."}, {"cls": ".origam-chart__honeycomb-label", "num": 3, "descriptionKey": "components.chart_honeycomb.anatomy.label", "descriptionFallback": "Text centred at the tile''s (cx, cy). Shows name or formatted value. Hidden when showLabel=false."}, {"cls": ".origam-chart__honeycomb-tile--active", "num": 4, "descriptionKey": "components.chart_honeycomb.anatomy.tile_active", "descriptionFallback": "BEM modifier applied on hover/focus — adds brightness filter."}, {"cls": ".origam-chart-honeycomb__header", "num": 5, "descriptionKey": "components.chart_honeycomb.anatomy.header", "descriptionFallback": "Title and subtitle block. Rendered only when title or subtitle is provided."}], "classes": [{"cls": "origam-chart-honeycomb", "descriptionKey": "components.chart_honeycomb.anatomy.root", "descriptionFallback": "Root element."}, {"cls": "origam-chart-honeycomb__header", "descriptionKey": "components.chart_honeycomb.anatomy.header", "descriptionFallback": "Title/subtitle block."}, {"cls": "origam-chart-honeycomb__title", "descriptionKey": "components.chart_honeycomb.anatomy.title", "descriptionFallback": "Primary title."}, {"cls": "origam-chart-honeycomb__subtitle", "descriptionKey": "components.chart_honeycomb.anatomy.subtitle", "descriptionFallback": "Subtitle."}, {"cls": "origam-chart-honeycomb__body", "descriptionKey": "components.chart_honeycomb.anatomy.body", "descriptionFallback": "Body containing the SVG."}, {"cls": "origam-chart-honeycomb__svg", "descriptionKey": "components.chart_honeycomb.anatomy.svg", "descriptionFallback": "SVG canvas — viewBox auto-computed from tile positions."}, {"cls": "origam-chart__honeycomb-tile-group", "descriptionKey": "components.chart_honeycomb.anatomy.tile_group", "descriptionFallback": "<g> grouping one tile and its label."}, {"cls": "origam-chart__honeycomb-tile", "descriptionKey": "components.chart_honeycomb.anatomy.tile", "descriptionFallback": "Hex polygon."}, {"cls": "origam-chart__honeycomb-tile--active", "descriptionKey": "components.chart_honeycomb.anatomy.tile_active", "descriptionFallback": "Active state modifier."}, {"cls": "origam-chart__honeycomb-label", "descriptionKey": "components.chart_honeycomb.anatomy.label", "descriptionFallback": "Centred tile label."}, {"cls": "origam-chart-honeycomb--pointy-top", "descriptionKey": "components.chart_honeycomb.anatomy.mod_pointy", "descriptionFallback": "Modifier for pointy-top orientation."}, {"cls": "origam-chart-honeycomb--flat-top", "descriptionKey": "components.chart_honeycomb.anatomy.mod_flat", "descriptionFallback": "Modifier for flat-top orientation."}, {"cls": "origam-chart-honeycomb--categorical", "descriptionKey": "components.chart_honeycomb.anatomy.mod_categorical", "descriptionFallback": "Modifier for categorical colour mode."}, {"cls": "origam-chart-honeycomb--heatmap", "descriptionKey": "components.chart_honeycomb.anatomy.mod_heatmap", "descriptionFallback": "Modifier for heatmap colour mode."}, {"cls": "origam-chart-honeycomb--no-animation", "descriptionKey": "components.chart_honeycomb.anatomy.mod_no_animation", "descriptionFallback": "Disables entry animation."}], "svgDesc": "Schematic of the ChartHoneycomb component with 5 numbered internal parts.", "svgTitle": "Anatomy of OrigamChartHoneycomb", "rootClass": "origam-chart-honeycomb", "figcaption": "Anatomy of <code>&lt;origam-chart-honeycomb&gt;</code> — 5 internal parts. Hexagon points computed in JavaScript from <code>tileSize</code> and <code>orientation</code>.", "svgViewBox": "0 0 700 260"}, "cssVars": [{"name": "--origam-chart---gap", "defaultValue": "12px", "descriptionKey": "components.chart_honeycomb.css_vars.gap", "descriptionFallback": "Gap between header, body and legend areas."}, {"name": "--origam-chart---padding", "defaultValue": "12px", "descriptionKey": "components.chart_honeycomb.css_vars.padding", "descriptionFallback": "Internal padding of the chart root."}, {"name": "--origam-chart---animation-duration", "defaultValue": "600ms", "descriptionKey": "components.chart_honeycomb.css_vars.animation_duration", "descriptionFallback": "Entry animation duration. Driven by animationDuration prop."}, {"name": "--origam-chart__honeycomb---stroke-color", "defaultValue": "var(--origam-color-surface-default, #ffffff)", "descriptionKey": "components.chart_honeycomb.css_vars.stroke_color", "descriptionFallback": "Stroke colour applied to each tile polygon (creates gap between tiles)."}, {"name": "--origam-chart__honeycomb---stroke-width", "defaultValue": "2", "descriptionKey": "components.chart_honeycomb.css_vars.stroke_width", "descriptionFallback": "Stroke width of tile polygons."}, {"name": "--origam-chart__honeycomb-label---font-size", "defaultValue": "0.625rem", "descriptionKey": "components.chart_honeycomb.css_vars.label_font_size", "descriptionFallback": "Font size of the centred tile label."}, {"name": "--origam-chart__honeycomb-label---font-weight", "defaultValue": "600", "descriptionKey": "components.chart_honeycomb.css_vars.label_font_weight", "descriptionFallback": "Font weight of the centred tile label."}, {"name": "--origam-chart__honeycomb-label---color", "defaultValue": "#ffffff", "descriptionKey": "components.chart_honeycomb.css_vars.label_color", "descriptionFallback": "Fill colour of the centred tile label."}, {"name": "--origam-chart__title---font-size", "defaultValue": "1.125rem", "descriptionKey": "components.chart_honeycomb.css_vars.title_font_size", "descriptionFallback": "Font size of the chart title."}], "playground": {"controls": [{"kind": "select", "prop": "bgColor", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.chart_honeycomb.playground.bg_color", "defaultValue": "", "labelFallback": "Background color"}, {"kind": "text", "prop": "title", "labelKey": "components.chart_honeycomb.playground.title", "defaultValue": "", "labelFallback": "Title"}, {"kind": "text", "prop": "subtitle", "labelKey": "components.chart_honeycomb.playground.subtitle", "defaultValue": "", "labelFallback": "Subtitle"}, {"kind": "switch", "prop": "showLabel", "labelKey": "components.chart_honeycomb.playground.show_label", "defaultValue": true, "labelFallback": "Show Label"}, {"kind": "switch", "prop": "showLegend", "labelKey": "components.chart_honeycomb.playground.show_legend", "defaultValue": true, "labelFallback": "Show Legend"}, {"kind": "switch", "prop": "showTooltip", "labelKey": "components.chart_honeycomb.playground.show_tooltip", "defaultValue": true, "labelFallback": "Show Tooltip"}, {"kind": "switch", "prop": "animated", "labelKey": "components.chart_honeycomb.playground.animated", "defaultValue": true, "labelFallback": "Animated"}]}, "previewVariants": []}', false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8999c753-00b3-4a1c-ba8e-4f3c61424902', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'component', 'chart-legend', 'ChartLegend', 'Data Display', NULL, 'mdi-format-list-bulleted-square', 'components.catalog.chart_legend.description', 'Standalone series-legend list shared by all chart families. Renders a colour swatch + series name per entry and handles click-to-toggle visibility.', NULL, NULL, 'origam-chart-legend', NULL, NULL, 'origam', NULL, NULL, '/stories/?story=components-chart-legend--design', '/docs/components/Chart/OrigamChartLegend.html', 'chart', '{"a11y": {"notes": [{"noteKey": "components.chart_legend.a11y.list_role", "noteFallback": "The root <ul> carries role=\"list\" to preserve list semantics even when CSS resets remove list markers."}, {"noteKey": "components.chart_legend.a11y.aria_pressed", "noteFallback": "Each item has aria-pressed=\"true|false\" reflecting the current visibility state, and aria-label describing the action (\"visible, click to hide\" / \"hidden, click to show\")."}, {"noteKey": "components.chart_legend.a11y.swatch_hidden", "noteFallback": "The colour swatch <span> carries aria-hidden=\"true\" — it is purely decorative."}, {"noteKey": "components.chart_legend.a11y.ssr_guard", "noteFallback": "A defensive filter removes entries missing the series ref before rendering — prevents SSR crashes when items arrive undefined."}], "roles": ["list", "button"], "keyboard": [{"key": "Tab", "actionKey": "components.chart_legend.a11y.key_tab", "actionFallback": "Moves focus through each legend entry (tabindex=\"0\")."}, {"key": "Enter / Space", "actionKey": "components.chart_legend.a11y.key_activate", "actionFallback": "Toggles the visibility of the focused series entry."}]}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"180\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"60\" width=\"660\" height=\"60\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"40\" y=\"80\" width=\"12\" height=\"12\" rx=\"3\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"58\" y=\"90\" font-size=\"10\" fill=\"var(--origam-color__text---primary, #1f2937)\" font-family=\"sans-serif\">Revenue</text>\n  <rect x=\"140\" y=\"80\" width=\"12\" height=\"12\" rx=\"3\" fill=\"var(--origam-color__feedback--danger---bg, #ef4444)\"/>\n  <text x=\"158\" y=\"90\" font-size=\"10\" fill=\"var(--origam-color__text---primary, #1f2937)\" font-family=\"sans-serif\">Costs</text>\n  <rect x=\"230\" y=\"80\" width=\"12\" height=\"12\" rx=\"3\" fill=\"var(--origam-color__feedback--success---bg, rgba(34,197,94,0.8))\"/>\n  <text x=\"248\" y=\"90\" font-size=\"10\" fill=\"var(--origam-color__text---primary, #1f2937)\" font-family=\"sans-serif\">Profit</text>\n  <rect x=\"320\" y=\"80\" width=\"12\" height=\"12\" rx=\"3\" fill=\"var(--origam-color__feedback--info---bg, rgba(8,145,178,0.8))\" opacity=\"0.4\"/>\n  <text x=\"338\" y=\"90\" font-size=\"10\" fill=\"var(--origam-color__text---primary, #1f2937)\" font-family=\"sans-serif\" text-decoration=\"line-through\" opacity=\"0.4\">Margin</text>\n  <circle cx=\"28\" cy=\"68\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"72\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"47\" cy=\"86\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"47\" y=\"90\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"66\" cy=\"86\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"66\" y=\"90\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"330\" cy=\"80\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"330\" y=\"84\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <text x=\"350\" y=\"155\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">④ --hidden modifier: opacity 0.4 + text-decoration: line-through</text>\n", "code": "<!-- root <ul>, role=\"list\" -->\n<ul class=\"origam-chart__legend origam-chart__legend--bottom\" role=\"list\">\n  <!-- one <li> per series entry -->\n  <li\n    class=\"origam-chart__legend-item\"\n    role=\"button\"\n    tabindex=\"0\"\n    aria-label=\"Revenue: visible, click to hide\"\n    aria-pressed=\"true\"\n  >\n    <!-- default slot content (replaceable via #legend-item) -->\n    <span class=\"origam-chart__legend-swatch\" aria-hidden=\"true\" />\n    <span class=\"origam-chart__legend-label\">Revenue</span>\n  </li>\n\n  <!-- hidden entry -->\n  <li\n    class=\"origam-chart__legend-item origam-chart__legend-item--hidden\"\n    role=\"button\"\n    tabindex=\"0\"\n    aria-label=\"Margin: hidden, click to show\"\n    aria-pressed=\"false\"\n  >\n    <span class=\"origam-chart__legend-swatch\" aria-hidden=\"true\" />\n    <span class=\"origam-chart__legend-label\">Margin</span>\n  </li>\n</ul>", "legend": [{"cls": ".origam-chart__legend", "num": 1, "descriptionKey": "components.chart_legend.anatomy.root", "descriptionFallback": "Root <ul> element. role=\"list\". Flex layout: row when position=top|bottom, column when left|right."}, {"cls": ".origam-chart__legend-swatch", "num": 2, "descriptionKey": "components.chart_legend.anatomy.swatch", "descriptionFallback": "<span> with background-color from the resolved series colour. aria-hidden=\"true\"."}, {"cls": ".origam-chart__legend-label", "num": 3, "descriptionKey": "components.chart_legend.anatomy.label", "descriptionFallback": "<span> with the series name text."}, {"cls": ".origam-chart__legend-item--hidden", "num": 4, "descriptionKey": "components.chart_legend.anatomy.item_hidden", "descriptionFallback": "BEM modifier when the series is hidden. opacity: 0.4 + text-decoration: line-through."}], "classes": [{"cls": "origam-chart__legend", "descriptionKey": "components.chart_legend.anatomy.root", "descriptionFallback": "Root <ul> list."}, {"cls": "origam-chart__legend--top", "descriptionKey": "components.chart_legend.anatomy.mod_top", "descriptionFallback": "Row flex-direction, justify-content: center."}, {"cls": "origam-chart__legend--bottom", "descriptionKey": "components.chart_legend.anatomy.mod_bottom", "descriptionFallback": "Row flex-direction, justify-content: center."}, {"cls": "origam-chart__legend--left", "descriptionKey": "components.chart_legend.anatomy.mod_left", "descriptionFallback": "Column flex-direction, with padding-right gap."}, {"cls": "origam-chart__legend--right", "descriptionKey": "components.chart_legend.anatomy.mod_right", "descriptionFallback": "Column flex-direction, with padding-left gap."}, {"cls": "origam-chart__legend-item", "descriptionKey": "components.chart_legend.anatomy.item", "descriptionFallback": "<li> entry — role=\"button\", tabindex=\"0\", aria-pressed."}, {"cls": "origam-chart__legend-item--hidden", "descriptionKey": "components.chart_legend.anatomy.item_hidden", "descriptionFallback": "Hidden state modifier."}, {"cls": "origam-chart__legend-swatch", "descriptionKey": "components.chart_legend.anatomy.swatch", "descriptionFallback": "Colour swatch square."}, {"cls": "origam-chart__legend-label", "descriptionKey": "components.chart_legend.anatomy.label", "descriptionFallback": "Series name label."}], "svgDesc": "Schematic of the ChartLegend component with 4 numbered internal parts.", "svgTitle": "Anatomy of OrigamChartLegend", "rootClass": "origam-chart__legend", "figcaption": "Anatomy of <code>&lt;origam-chart-legend&gt;</code> — 4 internal parts. A pure renderer: receives pre-resolved items and emits toggle events.", "svgViewBox": "0 0 700 180"}, "previewVariants": []}', false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b5576ad5-4762-4094-8a17-f376e6ac7f8d', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'component', 'chart-map', 'ChartMap', 'Data Display', NULL, 'mdi-map-outline', 'components.catalog.chart_map.description', 'World map chart with two rendering modes: choropleth (country shapes coloured by value gradient) and flight-routes (curved Bezier arcs between country centroid pairs). Built on a 1000 × 500 SVG Mercator projection.', NULL, NULL, 'origam-chart-map', NULL, NULL, 'origam', NULL, NULL, '/stories/?story=components-chart-map--design', '/docs/components/Chart/OrigamChartMap.html', 'chart', '{"a11y": {"notes": [{"noteKey": "components.chart_map.a11y.figure_role", "noteFallback": "Root has role=\"figure\" with aria-label from the title prop (falls back to \"map chart\")."}, {"noteKey": "components.chart_map.a11y.svg_role", "noteFallback": "The SVG carries role=\"img\" with a <title> and <desc> listing mode-specific counts (N countries or N routes)."}, {"noteKey": "components.chart_map.a11y.country_aria", "noteFallback": "Choropleth: each data country has aria-label \"name: value\". Non-data countries carry just the code as label."}, {"noteKey": "components.chart_map.a11y.route_aria", "noteFallback": "Flight-routes: each arc has aria-label \"FROM to TO: value\"."}, {"noteKey": "components.chart_map.a11y.reduced_motion", "noteFallback": "Entry animations are disabled via @media (prefers-reduced-motion: reduce)."}], "roles": ["figure", "img", "button"], "keyboard": [{"key": "Tab", "actionKey": "components.chart_map.a11y.key_tab", "actionFallback": "Moves focus through interactive countries (choropleth) or routes (flight-routes). Non-data countries have tabindex=\"-1\" and are skipped."}, {"key": "Enter / Space", "actionKey": "components.chart_map.a11y.key_activate", "actionFallback": "Activates the focused country or route, firing the point-click emit."}]}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"240\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"20\" width=\"660\" height=\"200\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"32\" y=\"28\" width=\"636\" height=\"16\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\"/>\n  <text x=\"350\" y=\"40\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">__header (title + subtitle)</text>\n  <rect x=\"32\" y=\"50\" width=\"636\" height=\"120\" rx=\"3\" fill=\"rgba(8,145,178,0.05)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\"/>\n  <ellipse cx=\"200\" cy=\"100\" rx=\"50\" ry=\"30\" fill=\"color-mix(in srgb,rgba(239,68,68,0.7) 80%,rgba(8,145,178,0.7))\" stroke=\"rgba(0,0,0,0.2)\" stroke-width=\"0.5\"/>\n  <ellipse cx=\"310\" cy=\"90\" rx=\"60\" ry=\"35\" fill=\"color-mix(in srgb,rgba(239,68,68,0.7) 40%,rgba(8,145,178,0.7))\" stroke=\"rgba(0,0,0,0.2)\" stroke-width=\"0.5\"/>\n  <ellipse cx=\"430\" cy=\"110\" rx=\"40\" ry=\"28\" fill=\"color-mix(in srgb,rgba(239,68,68,0.7) 65%,rgba(8,145,178,0.7))\" stroke=\"rgba(0,0,0,0.2)\" stroke-width=\"0.5\"/>\n  <ellipse cx=\"540\" cy=\"95\" rx=\"45\" ry=\"30\" fill=\"rgba(0,0,0,0.08)\" stroke=\"rgba(0,0,0,0.2)\" stroke-width=\"0.5\"/>\n  <path d=\"M 200,100 Q 255,60 310,90\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"2\" fill=\"none\" opacity=\"0.7\" stroke-linecap=\"round\"/>\n  <circle cx=\"200\" cy=\"100\" r=\"4\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <circle cx=\"310\" cy=\"90\" r=\"4\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <rect x=\"32\" y=\"178\" width=\"200\" height=\"10\" rx=\"2\" fill=\"url(#origam-map-grad-anatomy)\"/>\n  <defs><linearGradient id=\"origam-map-grad-anatomy\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\"><stop offset=\"0%\" stop-color=\"rgba(8,145,178,0.8)\"/><stop offset=\"100%\" stop-color=\"rgba(239,68,68,0.8)\"/></linearGradient></defs>\n  <text x=\"32\" y=\"200\" font-size=\"7\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\">0</text>\n  <text x=\"232\" y=\"200\" font-size=\"7\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"end\">500</text>\n  <circle cx=\"28\" cy=\"28\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"32\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"40\" cy=\"58\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"40\" y=\"62\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"200\" cy=\"110\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"200\" y=\"114\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"540\" cy=\"105\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"540\" y=\"109\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"257\" cy=\"68\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"257\" y=\"72\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <circle cx=\"200\" cy=\"100\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\" opacity=\"0.8\"/>\n  <text x=\"200\" y=\"104\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">6</text>\n  <circle cx=\"40\" cy=\"183\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"40\" y=\"187\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">7</text>\n  <text x=\"350\" y=\"225\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">③ choropleth fill = color-mix; ⑤ Bezier arc (flight-routes); ④ no-data fill = defaultCountryFill</text>\n", "code": "<div class=\"origam-chart-map\" role=\"figure\" aria-label=\"Population density\">\n  <header class=\"origam-chart-map__header\">\n    <div class=\"origam-chart-map__title\">Population density</div>\n  </header>\n\n  <div class=\"origam-chart-map__body\">\n    <svg class=\"origam-chart-map__svg origam-chart__svg\" role=\"img\" viewBox=\"0 0 1000 500\">\n      <title>Population density</title>\n      <desc>Choropleth map with 5 countries in the dataset.</desc>\n\n      <defs>\n        <linearGradient id=\"origam-map-legend-gradient\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\">\n          <stop offset=\"0%\" />\n          <stop offset=\"100%\" />\n        </linearGradient>\n      </defs>\n\n      <!-- country shapes (mode=choropleth) -->\n      <g class=\"origam-chart__map-backdrop\">\n        <!-- countries with data (choropleth fill + interactive) -->\n        <path\n          class=\"origam-chart__map-country origam-chart__map-country--has-data\"\n          tabindex=\"0\"\n          role=\"button\"\n          aria-label=\"France: 119\"\n        />\n        <!-- countries without data (defaultCountryFill) -->\n        <path class=\"origam-chart__map-country\" tabindex=\"-1\" />\n      </g>\n\n      <!-- routes (mode=flight-routes) -->\n      <g class=\"origam-chart__map-routes\">\n        <path\n          class=\"origam-chart__map-route\"\n          tabindex=\"0\"\n          role=\"button\"\n          aria-label=\"FR to US: 120\"\n        />\n        <circle class=\"origam-chart__map-node\" />\n      </g>\n\n      <!-- choropleth gradient legend (showLegend=true) -->\n      <g class=\"origam-chart__map-gradient-legend\">\n        <rect fill=\"url(#origam-map-legend-gradient)\" />\n        <text class=\"origam-chart__map-legend-label\">0</text>\n        <text class=\"origam-chart__map-legend-label\">500</text>\n      </g>\n    </svg>\n\n    <!-- tooltip -->\n    <origam-chart-tooltip />\n  </div>\n</div>", "legend": [{"cls": ".origam-chart-map", "num": 1, "descriptionKey": "components.chart_map.anatomy.root", "descriptionFallback": "Root element. CSS grid: header / body areas. role=\"figure\" + aria-label from title."}, {"cls": ".origam-chart__map-backdrop", "num": 2, "descriptionKey": "components.chart_map.anatomy.backdrop", "descriptionFallback": "<g> rendering all country <path> elements. Built from WORLD_GEOGRAPHIC_DATA projected to 1000 × 500 via Mercator."}, {"cls": ".origam-chart__map-country--has-data", "num": 3, "descriptionKey": "components.chart_map.anatomy.country_has_data", "descriptionFallback": "BEM modifier for countries with data. cursor: pointer + brightness filter on hover. tabindex=\"0\" + role=\"button\"."}, {"cls": ".origam-chart__map-country (no data)", "num": 4, "descriptionKey": "components.chart_map.anatomy.country_no_data", "descriptionFallback": "Countries absent from the dataset. Fill = defaultCountryFill. cursor: default, not focusable."}, {"cls": ".origam-chart__map-route", "num": 5, "descriptionKey": "components.chart_map.anatomy.route", "descriptionFallback": "Quadratic Bezier arc in flight-routes mode (M x1,y1 Q cx,cy x2,y2). Stroke width driven by log(value + 1) × 1.5."}, {"cls": ".origam-chart__map-node", "num": 6, "descriptionKey": "components.chart_map.anatomy.node", "descriptionFallback": "Endpoint circles on each route, deduplicated. pointer-events: none."}, {"cls": ".origam-chart__map-gradient-legend", "num": 7, "descriptionKey": "components.chart_map.anatomy.gradient_legend", "descriptionFallback": "Inline SVG gradient bar with min/max labels. Bottom-left corner of the SVG. Visible when showLegend=true and mode=choropleth."}], "classes": [{"cls": "origam-chart-map", "descriptionKey": "components.chart_map.anatomy.root", "descriptionFallback": "Root element."}, {"cls": "origam-chart-map__header", "descriptionKey": "components.chart_map.anatomy.header", "descriptionFallback": "Title/subtitle block."}, {"cls": "origam-chart-map__title", "descriptionKey": "components.chart_map.anatomy.title", "descriptionFallback": "Primary title."}, {"cls": "origam-chart-map__subtitle", "descriptionKey": "components.chart_map.anatomy.subtitle", "descriptionFallback": "Subtitle."}, {"cls": "origam-chart-map__body", "descriptionKey": "components.chart_map.anatomy.body", "descriptionFallback": "Body containing the SVG."}, {"cls": "origam-chart-map__svg", "descriptionKey": "components.chart_map.anatomy.svg", "descriptionFallback": "SVG canvas — 1000 × 500 Mercator viewBox."}, {"cls": "origam-chart__map-backdrop", "descriptionKey": "components.chart_map.anatomy.backdrop", "descriptionFallback": "<g> holding all country <path> elements."}, {"cls": "origam-chart__map-country", "descriptionKey": "components.chart_map.anatomy.country", "descriptionFallback": "Country <path>."}, {"cls": "origam-chart__map-country--has-data", "descriptionKey": "components.chart_map.anatomy.country_has_data", "descriptionFallback": "Interactive country (has a value in the dataset)."}, {"cls": "origam-chart__map-country--active", "descriptionKey": "components.chart_map.anatomy.country_active", "descriptionFallback": "Hovered/active country."}, {"cls": "origam-chart__map-routes", "descriptionKey": "components.chart_map.anatomy.routes", "descriptionFallback": "<g> holding route arcs (flight-routes mode)."}, {"cls": "origam-chart__map-route", "descriptionKey": "components.chart_map.anatomy.route", "descriptionFallback": "Route Bezier arc."}, {"cls": "origam-chart__map-route--active", "descriptionKey": "components.chart_map.anatomy.route_active", "descriptionFallback": "Hovered/active route."}, {"cls": "origam-chart__map-node", "descriptionKey": "components.chart_map.anatomy.node", "descriptionFallback": "Route endpoint circle."}, {"cls": "origam-chart__map-gradient-legend", "descriptionKey": "components.chart_map.anatomy.gradient_legend", "descriptionFallback": "Inline gradient legend group."}, {"cls": "origam-chart__map-legend-label", "descriptionKey": "components.chart_map.anatomy.legend_label", "descriptionFallback": "Min/max label beside the gradient bar."}, {"cls": "origam-chart-map--choropleth", "descriptionKey": "components.chart_map.anatomy.mod_choropleth", "descriptionFallback": "Modifier for choropleth mode."}, {"cls": "origam-chart-map--flight-routes", "descriptionKey": "components.chart_map.anatomy.mod_routes", "descriptionFallback": "Modifier for flight-routes mode."}, {"cls": "origam-chart-map--no-animation", "descriptionKey": "components.chart_map.anatomy.mod_no_animation", "descriptionFallback": "Disables entry animation."}], "svgDesc": "Schematic of the ChartMap component with 7 numbered internal parts.", "svgTitle": "Anatomy of OrigamChartMap", "rootClass": "origam-chart-map", "figcaption": "Anatomy of <code>&lt;origam-chart-map&gt;</code> — 7 internal parts. SVG canvas: 1000 × 500 Mercator projection. Two modes: choropleth gradient or flight-route Bezier arcs.", "svgViewBox": "0 0 700 240"}, "cssVars": [{"name": "--origam-chart---gap", "defaultValue": "12px", "descriptionKey": "components.chart_map.css_vars.gap", "descriptionFallback": "Gap between header and body areas."}, {"name": "--origam-chart---padding", "defaultValue": "12px", "descriptionKey": "components.chart_map.css_vars.padding", "descriptionFallback": "Internal padding of the chart root."}, {"name": "--origam-chart---background-color", "defaultValue": "transparent", "descriptionKey": "components.chart_map.css_vars.background_color", "descriptionFallback": "Background colour of the chart root."}, {"name": "--origam-chart---animation-duration", "defaultValue": "600ms", "descriptionKey": "components.chart_map.css_vars.animation_duration", "descriptionFallback": "Entry animation duration. Driven by animationDuration prop."}, {"name": "--origam-chart__map---stroke-width", "defaultValue": "1", "descriptionKey": "components.chart_map.css_vars.stroke_width", "descriptionFallback": "Stroke width of all country path outlines."}, {"name": "--origam-chart__map-legend-label---font-size", "defaultValue": "0.625rem", "descriptionKey": "components.chart_map.css_vars.legend_label_font_size", "descriptionFallback": "Font size of min/max labels on the gradient legend."}, {"name": "--origam-chart__map-legend-label---color", "defaultValue": "var(--origam-color-text-secondary, #6b7280)", "descriptionKey": "components.chart_map.css_vars.legend_label_color", "descriptionFallback": "Fill colour of gradient legend labels."}, {"name": "--origam-chart__title---font-size", "defaultValue": "1.125rem", "descriptionKey": "components.chart_map.css_vars.title_font_size", "descriptionFallback": "Font size of the chart title."}, {"name": "--origam-chart__title---font-weight", "defaultValue": "600", "descriptionKey": "components.chart_map.css_vars.title_font_weight", "descriptionFallback": "Font weight of the chart title."}], "playground": {"controls": [{"kind": "select", "prop": "bgColor", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.chart_map.playground.bg_color", "defaultValue": "", "labelFallback": "Background color"}, {"kind": "text", "prop": "title", "labelKey": "components.chart_map.playground.title", "defaultValue": "", "labelFallback": "Title"}, {"kind": "text", "prop": "subtitle", "labelKey": "components.chart_map.playground.subtitle", "defaultValue": "", "labelFallback": "Subtitle"}, {"kind": "select", "prop": "lineColor", "options": [{"label": "(default)", "value": ""}, {"label": "neutral", "value": "neutral"}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "ghost", "value": "ghost"}, {"label": "success", "value": "success"}, {"label": "warning", "value": "warning"}, {"label": "danger", "value": "danger"}, {"label": "info", "value": "info"}], "labelKey": "components.chart_map.playground.line_color", "defaultValue": "", "labelFallback": "Line Color"}, {"kind": "switch", "prop": "showLegend", "labelKey": "components.chart_map.playground.show_legend", "defaultValue": true, "labelFallback": "Show Legend"}, {"kind": "switch", "prop": "showTooltip", "labelKey": "components.chart_map.playground.show_tooltip", "defaultValue": true, "labelFallback": "Show Tooltip"}, {"kind": "switch", "prop": "animated", "labelKey": "components.chart_map.playground.animated", "defaultValue": true, "labelFallback": "Animated"}]}, "previewVariants": []}', false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('891123a1-36c9-4429-9822-3272e7f8cdb2', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'component', 'chart-pareto', 'ChartPareto', 'Data Display', NULL, 'mdi-chart-bar', 'components.catalog.chart_pareto.description', 'Pareto chart combining vertical bars sorted descending by value with a cumulative percentage line on a secondary right Y-axis. Ideal for 80/20 rule and root-cause analysis.', NULL, NULL, 'origam-chart-pareto', NULL, NULL, 'origam', NULL, NULL, '/stories/?story=components-chart-pareto--design', '/docs/components/Chart/OrigamChartPareto.html', 'chart', '{"a11y": {"notes": [{"noteKey": "components.chart_pareto.a11y.root_figure", "noteFallback": "Root div carries role=\"figure\" and aria-label from the title prop (or \"Pareto chart\" as fallback)."}, {"noteKey": "components.chart_pareto.a11y.svg_img", "noteFallback": "Inner SVG has role=\"img\" with a <title> and <desc> element summarising the data count."}, {"noteKey": "components.chart_pareto.a11y.bar_label", "noteFallback": "Each bar <rect> has aria-label describing its category, value, share (%) and cumulative (%)."}, {"noteKey": "components.chart_pareto.a11y.reduced_motion", "noteFallback": "All CSS animations are disabled under prefers-reduced-motion: reduce."}], "roles": ["figure", "img", "button"], "keyboard": [{"key": "Tab", "actionKey": "components.chart_pareto.a11y.key_tab", "actionFallback": "Moves focus between focusable bars (tabindex=\"0\" on each <rect>)."}, {"key": "Enter / Space", "actionKey": "components.chart_pareto.a11y.key_activate", "actionFallback": "Activates the focused bar (fires point-click)."}]}, "tokens": {"excerpt": [{"type": "color", "value": "{color.surface.default}", "tokenPath": "chart.background-color", "descriptionKey": "components.chart_pareto.tokens.background_color", "descriptionFallback": "Chart wrapper background."}, {"type": "color", "value": "{color.surface.inverse}", "tokenPath": "chart.tooltip.background-color", "descriptionKey": "components.chart_pareto.tokens.tooltip_bg", "descriptionFallback": "Tooltip background colour."}, {"type": "color", "value": "{color.border.default}", "tokenPath": "chart.axis.color", "descriptionKey": "components.chart_pareto.tokens.axis_color", "descriptionFallback": "Axis line and tick mark colour."}, {"type": "color", "value": "{color.border.subtle}", "tokenPath": "chart.grid.color", "descriptionKey": "components.chart_pareto.tokens.grid_color", "descriptionFallback": "Grid line stroke colour."}, {"type": "dimension", "value": "{space.3}", "tokenPath": "chart.legend.gap", "descriptionKey": "components.chart_pareto.tokens.legend_gap", "descriptionFallback": "Gap between legend items."}], "sourceFile": "packages/ds/tokens/component/chart.json", "pipelineNote": "Built with Style Dictionary v4 + @tokens-studio/sd-transforms. Outputs: CSS custom properties, SCSS variables, TypeScript types."}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"280\" fill=\"var(--origam-color__surface---sunken, #f9fafb)\" rx=\"4\"/>\n  <rect x=\"16\" y=\"16\" width=\"668\" height=\"224\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"350\" y=\"32\" font-size=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\" font-weight=\"700\">origam-chart-pareto ①</text>\n  <text x=\"350\" y=\"46\" font-size=\"8.5\" fill=\"var(--origam-color__text---secondary, #6b7280)\" text-anchor=\"middle\" font-family=\"sans-serif\">__header ②</text>\n  <rect x=\"24\" y=\"50\" width=\"660\