INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e7a5e9fe-db79-429c-be9b-730ae7672607', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'component', 'chart-polar-bar', 'ChartPolarBar', 'Data Display', NULL, 'mdi-chart-donut-variant', 'components.catalog.chart_polar_bar.description', 'Nightingale-rose (polar bar) chart. N data points are rendered as radial wedges each occupying an equal angular slice; outer radius is proportional to value. Ideal for cyclical data such as hours per day or monthly activity.', NULL, NULL, 'origam-chart-polar-bar', NULL, NULL, 'origam', NULL, NULL, '/stories/?story=components-chart-polar-bar--design', '/docs/components/Chart/OrigamChartPolarBar.html', 'chart-polar', '{"a11y": {"notes": [{"noteKey": "components.chart_polar_bar.a11y.root_figure", "noteFallback": "Root div carries role=\"figure\" and aria-label from the title prop (or \"Polar bar chart\")."}, {"noteKey": "components.chart_polar_bar.a11y.svg_img", "noteFallback": "Inner SVG has role=\"img\" with <title> and <desc> elements summarising the data."}, {"noteKey": "components.chart_polar_bar.a11y.wedge_label", "noteFallback": "Each wedge <path> has aria-label with category, value, percentage and series name."}, {"noteKey": "components.chart_polar_bar.a11y.reduced_motion", "noteFallback": "All CSS animations are disabled under prefers-reduced-motion: reduce."}], "roles": ["figure", "img", "button"], "keyboard": [{"key": "Tab", "actionKey": "components.chart_polar_bar.a11y.key_tab", "actionFallback": "Moves focus between focusable wedges (tabindex=\"0\" on each <path>)."}, {"key": "Enter / Space", "actionKey": "components.chart_polar_bar.a11y.key_activate", "actionFallback": "Activates the focused wedge (fires point-click)."}]}, "tokens": {"excerpt": [{"type": "color", "value": "{color.surface.default}", "tokenPath": "chart.background-color", "descriptionKey": "components.chart_polar_bar.tokens.background_color", "descriptionFallback": "Chart wrapper background."}, {"type": "color", "value": "{color.surface.inverse}", "tokenPath": "chart.tooltip.background-color", "descriptionKey": "components.chart_polar_bar.tokens.tooltip_bg", "descriptionFallback": "Tooltip background colour."}, {"type": "dimension", "value": "{space.3}", "tokenPath": "chart.legend.gap", "descriptionKey": "components.chart_polar_bar.tokens.legend_gap", "descriptionFallback": "Gap between legend items."}], "sourceFile": "packages/ds/tokens/component/chart.json", "pipelineNote": "Built with Style Dictionary v4 + @tokens-studio/sd-transforms. Outputs: CSS custom properties, SCSS variables, TypeScript types."}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"280\" fill=\"var(--origam-color__surface---sunken, #f9fafb)\" rx=\"4\"/>\n  <rect x=\"16\" y=\"16\" width=\"668\" height=\"228\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"350\" y=\"32\" font-size=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\" font-weight=\"700\">origam-chart-polar-bar ①</text>\n  <rect x=\"24\" y=\"40\" width=\"660\" height=\"18\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(124,58,237,0.3))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"354\" y=\"52\" font-size=\"8\" fill=\"var(--origam-color__text---secondary, #6b7280)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">__header ②</text>\n  <rect x=\"24\" y=\"64\" width=\"660\" height=\"168\" rx=\"2\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, #e5e7eb)\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"40\" y=\"78\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #9ca3af)\" font-family=\"''JetBrains Mono'',monospace\">__body ③</text>\n  <g transform=\"translate(350,148)\">\n    <path d=\"M0,-60 A60,60 0 0,1 58,-17 L29,-8 A30,30 0 0,0 0,-30 Z\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" opacity=\"0.9\"/>\n    <path d=\"M58,-17 A60,60 0 0,1 36,50 L18,25 A30,30 0 0,0 29,-8 Z\" fill=\"var(--origam-color__action--info---bg, #0ea5e9)\" opacity=\"0.9\"/>\n    <path d=\"M36,50 A60,60 0 0,1 -36,50 L-18,25 A30,30 0 0,0 18,25 Z\" fill=\"var(--origam-color__action--success---bg, #22c55e)\" opacity=\"0.9\"/>\n    <path d=\"M-36,50 A60,60 0 0,1 -58,-17 L-29,-8 A30,30 0 0,0 -18,25 Z\" fill=\"var(--origam-color__action--warning---bg, #f59e0b)\" opacity=\"0.9\"/>\n    <path d=\"M-58,-17 A60,60 0 0,1 0,-60 L0,-30 A30,30 0 0,0 -29,-8 Z\" fill=\"var(--origam-color__action--danger---bg, #ef4444)\" opacity=\"0.9\"/>\n    <circle cx=\"0\" cy=\"0\" r=\"5\" fill=\"var(--origam-color__surface---raised, #fff)\"/>\n  </g>\n  <text x=\"465\" y=\"100\" font-size=\"8\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-family=\"''JetBrains Mono'',monospace\">origam-chart__polar-bar-wedge ④</text>\n  <text x=\"465\" y=\"114\" font-size=\"8\" fill=\"var(--origam-color__text---secondary, #6b7280)\" font-family=\"''JetBrains Mono'',monospace\">--active modifier on hover</text>\n  <text x=\"465\" y=\"132\" font-size=\"8\" fill=\"var(--origam-color__text---secondary, #6b7280)\" font-family=\"''JetBrains Mono'',monospace\">__polar-bar-category-label ⑤</text>\n  <text x=\"465\" y=\"146\" font-size=\"8\" fill=\"var(--origam-color__text---secondary, #6b7280)\" font-family=\"''JetBrains Mono'',monospace\">__polar-bar-value-label ⑥</text>\n  <rect x=\"200\" y=\"248\" width=\"300\" height=\"16\" rx=\"2\" fill=\"var(--origam-color__surface---sunken, #f3f4f6)\" stroke=\"var(--origam-color__border---default, #e5e7eb)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"350\" y=\"259\" font-size=\"8\" fill=\"var(--origam-color__text---secondary, #6b7280)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-chart-legend</text>\n", "code": "<div class=\"origam-chart-polar-bar\">\n  <div class=\"origam-chart-polar-bar__header\">\n    <slot name=\"title\" />\n  </div>\n  <div class=\"origam-chart-polar-bar__body\">\n    <svg class=\"origam-chart-polar-bar__svg origam-chart__svg\" role=\"img\">\n      <title /><desc />\n      <g class=\"origam-chart__series\" :transform=\"translateCenter\">\n        <path class=\"origam-chart__polar-bar-wedge\" role=\"button\" tabindex=\"0\" />\n        <text class=\"origam-chart__polar-bar-category-label\" />\n        <text class=\"origam-chart__polar-bar-value-label\" />\n      </g>\n    </svg>\n    <origam-chart-tooltip />\n    <div class=\"origam-chart-polar-bar__empty origam-chart__empty\">\n      <slot name=\"empty\" />\n    </div>\n  </div>\n  <origam-chart-legend />\n</div>", "legend": [{"cls": ".origam-chart-polar-bar", "num": 1, "descriptionKey": "components.chart_polar_bar.anatomy.root", "descriptionFallback": "Root wrapper. CSS grid: header / body / legend rows."}, {"cls": ".origam-chart-polar-bar__header", "num": 2, "descriptionKey": "components.chart_polar_bar.anatomy.header", "descriptionFallback": "Optional title + subtitle block."}, {"cls": ".origam-chart-polar-bar__body", "num": 3, "descriptionKey": "components.chart_polar_bar.anatomy.body", "descriptionFallback": "Plot area containing the SVG and empty-state slot."}, {"cls": ".origam-chart__polar-bar-wedge", "num": 4, "descriptionKey": "components.chart_polar_bar.anatomy.wedge", "descriptionFallback": "SVG <path> arc for one data point. Keyboard-focusable (role=\"button\", tabindex=\"0\"). Gets --active modifier on hover."}, {"cls": ".origam-chart__polar-bar-category-label", "num": 5, "descriptionKey": "components.chart_polar_bar.anatomy.category_label", "descriptionFallback": "Category text anchored outside the outer radius. text-anchor driven by wedge midpoint quadrant."}, {"cls": ".origam-chart__polar-bar-value-label", "num": 6, "descriptionKey": "components.chart_polar_bar.anatomy.value_label", "descriptionFallback": "Optional numeric value label inside the wedge. Hidden when angular space is insufficient (showValueLabel flag)."}], "classes": [{"cls": "origam-chart-polar-bar", "descriptionKey": "components.chart_polar_bar.anatomy.root", "descriptionFallback": "Root grid wrapper."}, {"cls": "origam-chart-polar-bar__header", "descriptionKey": "components.chart_polar_bar.anatomy.header", "descriptionFallback": "Title/subtitle block."}, {"cls": "origam-chart-polar-bar__body", "descriptionKey": "components.chart_polar_bar.anatomy.body", "descriptionFallback": "Plot area."}, {"cls": "origam-chart-polar-bar__svg", "descriptionKey": "components.chart_polar_bar.anatomy.svg", "descriptionFallback": "Square SVG (viewBox NxN)."}, {"cls": "origam-chart__polar-bar-wedge", "descriptionKey": "components.chart_polar_bar.anatomy.wedge", "descriptionFallback": "Arc wedge <path>."}, {"cls": "origam-chart__polar-bar-wedge--active", "descriptionKey": "components.chart_polar_bar.anatomy.wedge_active", "descriptionFallback": "Added on hover / keyboard focus."}, {"cls": "origam-chart__polar-bar-category-label", "descriptionKey": "components.chart_polar_bar.anatomy.category_label", "descriptionFallback": "Outer category text."}, {"cls": "origam-chart__polar-bar-value-label", "descriptionKey": "components.chart_polar_bar.anatomy.value_label", "descriptionFallback": "Inner value text."}, {"cls": "origam-chart-polar-bar__empty", "descriptionKey": "components.chart_polar_bar.anatomy.empty", "descriptionFallback": "Empty-state overlay."}], "svgDesc": "Schematic of the ChartPolarBar component with 6 numbered internal parts.", "svgTitle": "Anatomy of OrigamChartPolarBar", "rootClass": "origam-chart-polar-bar", "figcaption": "Anatomy of <code>&lt;origam-chart-polar-bar&gt;</code> — 6 internal parts. Wedges ④ are SVG <code>&lt;path&gt;</code> elements inside a centred <code>&lt;g&gt;</code>. Category labels ⑤ and optional value labels ⑥ float outside / inside the outer radius.", "svgViewBox": "0 0 700 280"}, "cssVars": [{"name": "--origam-chart---background-color", "defaultValue": "{color.surface.default}", "descriptionKey": "components.chart_polar_bar.css_vars.background_color", "descriptionFallback": "Background colour of the chart wrapper."}, {"name": "--origam-chart---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.chart_polar_bar.css_vars.color", "descriptionFallback": "Default text colour (inherited by category labels)."}, {"name": "--origam-chart---padding", "defaultValue": "{space.3}", "descriptionKey": "components.chart_polar_bar.css_vars.padding", "descriptionFallback": "Inner padding of the root wrapper."}, {"name": "--origam-chart---gap", "defaultValue": "{space.3}", "descriptionKey": "components.chart_polar_bar.css_vars.gap", "descriptionFallback": "Grid gap between header / body / legend rows."}, {"name": "--origam-chart---animation-duration", "defaultValue": "600ms", "descriptionKey": "components.chart_polar_bar.css_vars.animation_duration", "descriptionFallback": "Wedge animation duration. Set via animationDuration prop."}, {"name": "--origam-chart__tooltip---background-color", "defaultValue": "{color.surface.inverse}", "descriptionKey": "components.chart_polar_bar.css_vars.tooltip_bg", "descriptionFallback": "Tooltip background colour."}], "playground": {"controls": [{"kind": "select", "prop": "bgColor", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.chart_polar_bar.playground.bg_color", "defaultValue": "", "labelFallback": "Background color"}, {"kind": "text", "prop": "title", "labelKey": "components.chart_polar_bar.playground.title", "defaultValue": "", "labelFallback": "Title"}, {"kind": "text", "prop": "subtitle", "labelKey": "components.chart_polar_bar.playground.subtitle", "defaultValue": "", "labelFallback": "Subtitle"}, {"kind": "switch", "prop": "showLabel", "labelKey": "components.chart_polar_bar.playground.show_label", "defaultValue": true, "labelFallback": "Show Label"}, {"kind": "switch", "prop": "showValue", "labelKey": "components.chart_polar_bar.playground.show_value", "defaultValue": false, "labelFallback": "Show Value"}, {"kind": "switch", "prop": "showLegend", "labelKey": "components.chart_polar_bar.playground.show_legend", "defaultValue": true, "labelFallback": "Show Legend"}, {"kind": "switch", "prop": "showTooltip", "labelKey": "components.chart_polar_bar.playground.show_tooltip", "defaultValue": true, "labelFallback": "Show Tooltip"}, {"kind": "switch", "prop": "animated", "labelKey": "components.chart_polar_bar.playground.animated", "defaultValue": true, "labelFallback": "Animated"}]}}', false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('465af07e-5a74-4c59-ac1b-22948d673cbc', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'component', 'checkbox', 'Checkbox', 'Form & Input', NULL, 'mdi-checkbox-marked', 'components.catalog.checkbox.description', 'Form checkbox with label, hint, validation messages, indeterminate state, and full keyboard/accessibility support. Wraps OrigamInput and OrigamCheckboxBtn.', NULL, NULL, 'origam-checkbox', NULL, NULL, 'origam', NULL, NULL, '/stories/?story=components-checkbox--design', '/docs/components/Checkbox/OrigamCheckbox.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.checkbox.a11y.aria_checked", "noteFallback": "The hidden native <input type=\"checkbox\"> carries aria-checked (including \"mixed\" for indeterminate). Screen readers announce state correctly."}, {"noteKey": "components.checkbox.a11y.aria_describedby", "noteFallback": "aria-describedby links the checkbox to the messages container (messagesId) so validation errors are announced."}, {"noteKey": "components.checkbox.a11y.disabled", "noteFallback": "When disabled=true, the native input is disabled and pointer events are removed. Screen readers announce \"dimmed\" state."}], "roles": ["checkbox"], "keyboard": [{"key": "Space", "actionKey": "components.checkbox.a11y.key_space", "actionFallback": "Toggles the checked state. Native <input type=\"checkbox\"> behaviour."}, {"key": "Tab", "actionKey": "components.checkbox.a11y.key_tab", "actionFallback": "Moves focus to the next interactive element."}]}, "tokens": {"excerpt": [{"type": "color", "value": "{color.action.primary.bg}", "tokenPath": "checkbox.input.background-color-checked", "descriptionKey": "components.checkbox.tokens.bg_checked", "descriptionFallback": "Background when checked."}, {"type": "color", "value": "{color.border.default}", "tokenPath": "checkbox.input.border-color", "descriptionKey": "components.checkbox.tokens.border_color", "descriptionFallback": "Default border colour."}, {"type": "dimension", "value": "{radius.xs}", "tokenPath": "checkbox.input.border-radius", "descriptionKey": "components.checkbox.tokens.border_radius", "descriptionFallback": "Corner radius of the box."}, {"type": "color", "value": "{color.text.onColor}", "tokenPath": "checkbox.icon.color", "descriptionKey": "components.checkbox.tokens.icon_color", "descriptionFallback": "Checkmark icon colour."}, {"type": "color", "value": "{color.text.primary}", "tokenPath": "checkbox.label.color", "descriptionKey": "components.checkbox.tokens.label_color", "descriptionFallback": "Label text colour."}, {"type": "duration", "value": "{motion.duration.medium}", "tokenPath": "checkbox.transition-duration", "descriptionKey": "components.checkbox.tokens.transition_duration", "descriptionFallback": "Check/uncheck animation duration."}], "sourceFile": "packages/ds/tokens/component/checkbox.json", "pipelineNote": "Built with Style Dictionary v4 + @tokens-studio/sd-transforms."}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"40\" width=\"660\" height=\"120\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"50\" y=\"76\" width=\"40\" height=\"40\" rx=\"4\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <polyline points=\"58,97 68,108 82,84\" stroke=\"white\" stroke-width=\"3\" fill=\"none\" stroke-linecap=\"round\"/>\n  <rect x=\"110\" y=\"86\" width=\"220\" height=\"20\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\"/>\n  <text x=\"220\" y=\"100\" font-size=\"12\" fill=\"var(--origam-color__text---primary, #1a0f3c)\" text-anchor=\"middle\" font-family=\"sans-serif\">Checkbox label</text>\n  <rect x=\"20\" y=\"130\" width=\"660\" height=\"20\" rx=\"3\" fill=\"none\"/>\n  <text x=\"360\" y=\"143\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"sans-serif\">Hint / validation messages</text>\n  <circle cx=\"28\" cy=\"48\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"52\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"70\" cy=\"70\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"70\" y=\"74\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"220\" cy=\"80\" r=\"10\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"220\" y=\"84\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"360\" cy=\"134\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"360\" y=\"138\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"68\" cy=\"96\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"68\" y=\"100\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <text x=\"350\" y=\"185\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">Checkbox wraps OrigamInput (frame) + OrigamCheckboxBtn (control)</text>\n", "code": "<origam-input class=\"origam-checkbox\">\n  <template #default=\"{ id, messagesId, isDisabled, isReadonly, isValid }\">\n    <origam-checkbox-btn\n      :id=\"id\"\n      :aria-describedby=\"messagesId\"\n      :disabled=\"isDisabled\"\n      :error=\"!isValid\"\n      :readonly=\"isReadonly\"\n    >\n      <!-- hidden native checkbox -->\n      <input type=\"checkbox\" class=\"origam-selection-control__input\" />\n      <!-- visual box + icon -->\n      <span class=\"origam-checkbox-btn__box\">\n        <origam-icon class=\"origam-checkbox-btn__icon\" />\n      </span>\n      <!-- label -->\n      <label class=\"origam-selection-control__label\" :for=\"id\" />\n    </origam-checkbox-btn>\n  </template>\n</origam-input>", "legend": [{"cls": ".origam-checkbox", "num": 1, "descriptionKey": "components.checkbox.anatomy.root", "descriptionFallback": "Root element extending OrigamInput. Holds the label, hint and messages frame."}, {"cls": ".origam-checkbox-btn", "num": 2, "descriptionKey": "components.checkbox.anatomy.btn", "descriptionFallback": "Visual checkbox control (OrigamCheckboxBtn). Contains the box and icon."}, {"cls": ".origam-selection-control__label", "num": 3, "descriptionKey": "components.checkbox.anatomy.label", "descriptionFallback": "Text label. Bound via htmlFor to the hidden native <input>."}, {"cls": ".origam-input__details", "num": 4, "descriptionKey": "components.checkbox.anatomy.details", "descriptionFallback": "Messages/hint area. Hidden when hideDetails=true."}, {"cls": ".origam-selection-control__input", "num": 5, "descriptionKey": "components.checkbox.anatomy.input", "descriptionFallback": "Hidden native <input type=\"checkbox\"> that carries the value for form submissions."}], "classes": [{"cls": "origam-checkbox", "descriptionKey": "components.checkbox.anatomy.root", "descriptionFallback": "Root element wrapping OrigamInput and OrigamCheckboxBtn."}, {"cls": "origam-checkbox-btn", "descriptionKey": "components.checkbox.anatomy.btn", "descriptionFallback": "Visual selection control (the styled square box + check icon)."}, {"cls": "origam-selection-control__label", "descriptionKey": "components.checkbox.anatomy.label", "de