{"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.color_picker_edit.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "select", "prop": "mode", "options": [{"label": "rgb", "value": "rgb"}, {"label": "rgba", "value": "rgba"}, {"label": "hsl", "value": "hsl"}, {"label": "hsla", "value": "hsla"}, {"label": "hex", "value": "hex"}, {"label": "hexa", "value": "hexa"}], "labelKey": "components.color_picker_edit.playground.mode", "defaultValue": "rgba", "labelFallback": "Mode"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.color_picker_edit.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}]}, "previewVariants": [{"label": "rgba mode", "props": {"mode": "rgba"}, "ariaLabel": "RGBA mode edit panel"}, {"label": "hex mode", "props": {"mode": "hex"}, "ariaLabel": "HEX mode edit panel"}, {"label": "disabled", "props": {"mode": "rgba", "disabled": true}, "ariaLabel": "Disabled edit panel"}]}', false, NULL, NULL);
