INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ff5d1b98-c516-4560-9dab-0c1c46abe4b9', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'component', 'contextual-menu', 'ContextualMenu', 'Navigation', NULL, 'mdi-menu', 'components.catalog.contextual_menu.description', 'Right-click context menu that opens at the cursor position. Wraps OrigamMenu with openOnContextMenu + target="cursor" + activator="cursor" preconfigured.', NULL, NULL, 'origam-contextual-menu', NULL, NULL, 'origam', NULL, NULL, '/stories/?story=components-contextualmenu--design', '/docs/components/ContextualMenu/OrigamContextualMenu.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.contextual_menu.a11y.cursor_note", "noteFallback": "The menu panel is positioned at the exact cursor coordinates of the right-click event via target=\"cursor\". This matches the native browser context menu behaviour."}, {"noteKey": "components.contextual_menu.a11y.focus_note", "noteFallback": "On open, focus moves to the first enabled menu item. On close (Escape), focus returns to the element that received the right-click."}], "roles": ["menu", "menuitem"], "keyboard": [{"key": "Escape", "actionKey": "components.contextual_menu.a11y.key_escape", "actionFallback": "Closes the context menu and returns focus to the trigger element."}, {"key": "↑ / ↓", "actionKey": "components.contextual_menu.a11y.key_navigate", "actionFallback": "Navigate between menu items."}, {"key": "Enter / Space", "actionKey": "components.contextual_menu.a11y.key_select", "actionFallback": "Activates the focused menu item."}]}, "tokens": {"excerpt": [{"type": "color", "value": "{color.surface.raised}", "tokenPath": "contextual-menu.background", "descripti