op": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.data_table.playground.color", "defaultValue": "", "labelFallback": "Color / Intent"}, {"kind": "select", "prop": "density", "options": [{"label": "(default)", "value": ""}, {"label": "default", "value": "default"}, {"label": "DENSITY.DEFAULT", "value": "DENSITY.DEFAULT"}, {"label": "compact", "value": "compact"}, {"label": "DENSITY.COMPACT", "value": "DENSITY.COMPACT"}, {"label": "DENSITY.COMFORTABLE", "value": "DENSITY.COMFORTABLE"}, {"label": "comfortable", "value": "comfortable"}], "labelKey": "components.data_table.playground.density", "defaultValue": "", "labelFallback": "Density"}, {"kind": "switch", "prop": "hideDefaultBody", "labelKey": "components.data_table.playground.hide_default_body", "defaultValue": false, "labelFallback": "Hide Default Body"}, {"kind": "switch", "prop": "hideDefaultFooter", "labelKey": "components.data_table.playground.hide_default_footer", "defaultValue": false, "labelFallback": "Hide Default Footer"}, {"kind": "switch", "prop": "hideDefaultHeader", "labelKey": "components.data_table.playground.hide_default_header", "defaultValue": false, "labelFallback": "Hide Default Header"}, {"kind": "switch", "prop": "returnObject", "labelKey": "components.data_table.playground.return_object", "defaultValue": false, "labelFallback": "Return Object"}, {"kind": "switch", "prop": "multiSort", "labelKey": "components.data_table.playground.multi_sort", "defaultValue": false, "labelFallback": "Multi Sort"}, {"kind": "switch", "prop": "mustSort", "labelKey": "components.data_table.playground.must_sort", "defaultValue": false, "labelFallback": "Must Sort"}], "defaultSlotContent": "Tab"}}', false, NULL, NULL);
