INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3f3ab1ad-3304-4d90-8c2a-6587528ba1d9', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'component', 'data-table-headers', 'DataTableHeaders', 'Data Display', NULL, 'mdi-table-row', 'components.catalog.data_table_headers.description', 'Header row container that renders all column header cells, an optional progress loader, and switches to mobile layout when the breakpoint is reached.', NULL, NULL, 'origam-data-table-headers', NULL, NULL, 'origam', NULL, NULL, '/stories/?story=components-datatable--design', '/docs/components/DataTable/OrigamDataTable.html', 'data-table', '{"a11y": {"notes": [{"noteKey": "components.data_table_headers.a11y.aria_sort", "noteFallback": "Each sortable header cell exposes <code>aria-sort</code> (\"ascending\", \"descending\", or \"none\") on the <code>&lt;th&gt;</code> element."}, {"noteKey": "components.data_table_headers.a11y.loader_note", "noteFallback": "When loading, the progress row is inserted inside a <code>&lt;thead&gt;</code> scope, giving screen readers the context that loading is related to the table header."}], "roles": ["rowgroup"], "keyboard": [{"key": "Tab", "actionKey": "components.data_table_headers.a11y.key_tab", "actionFallback": "Moves focus through sortable header cells and the select-all checkbox."}]}, "tokens": {"excerpt": [{"type": "color", "value": "{color.surface.raised}", "tokenPath": "data-table.header.background-color", "descriptionKey": "components.data_table_headers.tokens.background_color", "descriptionFallback": "Header row background colour."}, {"type": "color", "value": "{color.border.default}", "tokenPath": "data-table.header.border-bottom-color", "descriptionKey": "components.data_table_headers.tokens.border_bottom_color", "descriptionFallback": "Bottom border separating header from body rows."}, {"type": "fontWeight", "value": "{font.weight.medium}", "tokenPath": "data-table.header.font-weight", "descriptionKey": "components.data_table_headers.tokens.font_weight", "descriptionFallback": "Column title font weight."}, {"type": "dimension", "value": "{space.3}", "tokenPath": "data-table.header.padding-block", "descriptionKey": "components.data_table_headers.tokens.padding_block", "descriptionFallback": "Block (top/bottom) padding for header cells."}], "sourceFile": "packages/ds/tokens/component/data-table.json", "pipelineNote": "Built with Style Dictionary v4 + @tokens-studio/sd-transforms. Header tokens live under the data-table.header namespace."}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"560\" height=\"140\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"16\" y=\"20\" width=\"528\" height=\"44\" rx=\"0\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"16\" y=\"64\" width=\"528\" height=\"8\" rx=\"0\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.15))\" stroke=\"none\"/>\n  <rect x=\"16\" y=\"64\" width=\"200\" height=\"8\" rx=\"0\" fill=\"var(--origam-color__feedback--info---bg, rgba(8,145,178,0.5))\"/>\n  <rect x=\"30\" y=\"28\" width=\"120\" height=\"28\" rx=\"0\" fill=\"none\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.30))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"90\" y=\"46\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">th cell</text>\n  <rect x=\"158\" y=\"28\" width=\"120\" height=\"28\" rx=\"0\" fill=\"none\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.30))\"