INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5ae5f8f5-4f48-4557-abbb-00f8496fc08c', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'component', 'date-picker', 'DatePicker', 'Form & Input', NULL, 'mdi-calendar', 'components.catalog.date_picker.description', 'Calendar popup to select a single date, multiple dates or a range. Supports month and year navigation with animated view transitions.', NULL, NULL, 'origam-date-picker', NULL, NULL, 'origam', NULL, NULL, '/stories/?story=components-datepicker--design', '/docs/components/DatePicker/OrigamDatePicker.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.date_picker.a11y.grid_note", "noteFallback": "The day grid uses role=\"grid\" with role=\"gridcell\" for each day. Disabled days have aria-disabled=\"true\" and are skipped in keyboard navigation."}, {"noteKey": "components.date_picker.a11y.label_note", "noteFallback": "Each day button has an aria-label with the full date string (e.g. \"15 juin 2026\") for screen reader users."}, {"noteKey": "components.date_picker.a11y.reduced_motion_note", "noteFallback": "View-change transitions (OrigamFade) are disabled under prefers-reduced-motion: reduce."}], "roles": ["dialog", "grid", "gridcell", "button"], "keyboard": [{"key": "← / → / ↑ / ↓", "actionKey": "components.date_picker.a11y.key_navigate_days", "actionFallback": "Navigate between day cells within the grid."}, {"key": "Enter / Space", "actionKey": "components.date_picker.a11y.key_select", "actionFallback": "Select the focused day, month or year."}, {"key": "PageUp / PageDown", "actionKey": "components.date_picker.a11y.key_month_nav", "actionFallback": "Move to the previous / next month without leaving the day grid