INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('afc433b5-08db-4b9c-b17e-2a4112d0c276', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'component', 'expand-x', 'ExpandX', 'Utilities & Providers', NULL, 'mdi-arrow-expand-horizontal', 'components.catalog.transition_expand_x.description', 'JS-driven horizontal width expand/collapse transition. Animates the element width from 0 to its natural offsetWidth (enter) and back to 0 (leave). Duration 0.5s with cubic-bezier(0.4, 0, 0.2, 1).', NULL, NULL, 'origam-expand-x', NULL, NULL, 'origam', NULL, NULL, '/stories/?story=components-transition--design', '/docs/components/Transition/OrigamExpandX.html', 'transition', '{"a11y": {"notes": [{"noteKey": "components.expand_x.a11y.reduced_motion", "noteFallback": "Set disabled=true to suppress all animations for users with prefers-reduced-motion: reduce. OrigamDatePickerMonth passes this prop automatically when the media query matches."}, {"noteKey": "components.expand_x.a11y.no_role", "noteFallback": "ExpandX is transparent to the accessibility tree — it adds no ARIA roles or attributes. Only the slotted content is visible to screen readers."}, {"noteKey": "components.expand_x.a11y.overflow", "noteFallback": "During the transition, overflow: hidden is set on the element to prevent content from showing outside the animated bounds. The original overflow is restored in afterEnter / afterLeave."}], "roles": [], "keyboard": []}, "tokens": {"excerpt": [{"type": "duration", "value": "{motion.duration.slow}", "tokenPath": "transition.expand.duration", "descriptionKey": "components.expand_x.tokens.duration", "descriptionFallback": "Expand/collapse animation duration (shared with ExpandY). Slightly slower than fade/slide to account for layout reflow."}, {"type": "cubicBezier", "value": "{motion.easing.standard}", "tokenPath": "transition.expand.easing", "descriptionKey": "components.expand_x.tokens.easing", "descriptionFallback": "Easing curve for the expand animation."}, {"type": "dimension", "value": "0", "tokenPath": "transition.expand.max-height-from", "descriptionKey": "components.expand_x.tokens.from", "descriptionFallback": "Starting dimension for the expand animation (0 → offsetWidth)."}], "sourceFile": "packages/ds/tokens/component/transition.json", "pipelineNote": "Expand tokens share the \"expand\" group with ExpandY. Built with Style Dictionary v4 + @tokens-studio/sd-transforms."}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"160\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <!-- enter phase: 0 → full width -->\n  <rect x=\"40\" y=\"40\" width=\"280\" height=\"80\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"40\" y=\"40\" width=\"60\" height=\"80\" rx=\"6\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"none\"/>\n  <text x=\"180\" y=\"76\" font-size=\"10\" fill=\"var(--origam-color__text---primary, #3b1c6e)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">enter-active</text>\n  <text x=\"180\" y=\"92\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">width: 0 → offsetWidth</text>\n  <!-- arrow -->\n  <text x=\"350\" y=\"84\" font-size=\"22\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" text-anchor=\"middle\">→</text>\n  <!-- leave phase: full width → 0 -->\n  <rect x=\"380\" y=\"40\" width=\"280\" height=\"80\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\" stroke-dasharray=\"5 3\" opacity=\"0.55\"/>\n  <rect x=\"600\" y=\"40\" width=\"60\" height=\"80\" rx=\"6\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.05))\" stroke=\"none\" opacity=\"0.55\"/>\n  <text x=\"520\" y=\"76\" font-size=\"10\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\" opacity=\"0.7\">leave-active</text>\n  <text x=\"520\" y=\"92\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\" opacity=\"0.7\">width: offsetWidth → 0</text>\n  <!-- markers -->\n  <circle cx=\"48\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"48\" y=\"52.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"388\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"388\" y=\"52.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n", "code": "<!-- OrigamExpandX — JS-driven <transition> -->\n<transition\n  name=\"origam-transition--expand-x\"\n  mode=\"in-out\"\n  :css=\"!disabled\"\n  @before-enter=\"handleBeforeEnter\"\n  @enter=\"handleEnter\"\n  @after-enter=\"handleAfterEnter\"\n  @enter-cancelled=\"handleEnterCancelled\"\n  @leave=\"handleLeave\"\n  @after-leave=\"handleAfterLeave\"\n  @leave-cancelled=\"handleLeaveCancelled\"\n>\n  <slot name=\"default\" />\n</transition>", "legend": [{"cls": ".origam-transition--expand-x-enter-active", "num": 1, "descriptionKey": "components.expand_x.anatomy.enter_active", "descriptionFallback": "Enter phase. CSS class drives transition-duration (0.5s), timing (cubic-bezier(0.4,0,0.2,1)) and transition-property (width). The JS beforeEnter hook stashes the initial width; enter sets width to 0 then requestAnimationFrame restores offsetWidth."}, {"cls": ".origam-transition--expand-x-leave-active", "num": 2, "descriptionKey": "components.expand_x.anatomy.leave_active", "descriptionFallback": "Leave phase. CSS class drives transition-duration (0.5s), timing and transition-property. The JS leave hook stashes the current width and animates to 0. afterLeave restores the initial style."}], "classes": [{"cls": "origam-transition--expand-x-enter-active", "descriptionKey": "components.expand_x.anatomy.enter_active", "descriptionFallback": "Applied during enter. Sets transition-property: width, duration 0.5s."}, {"cls": "origam-transition--expand-x-leave-active", "descriptionKey": "components.expand_x.anatomy.leave_active", "descriptionFallback": "Applied during leave. Sets transition-property: width, duration 0.5s."}, {"cls": "origam-transition--expand-x-move", "descriptionKey": "components.expand_x.anatomy.move", "descriptionFallback": "Applied to elements repositioning in a group transition. Sets transition-property: transform, duration 0.5s."}], "svgDesc": "Schematic showing width expansion from 0 to natural size on enter, and collapse on leave.", "svgTitle": "Anatomy of OrigamExpandX", "rootClass": "origam-transition--expand-x", "figcaption": "Anatomy of <code>&lt;origam-expand-x&gt;</code> — wraps a single element. JS hooks read <code>offsetWidth</code> to animate width from 0 → natural size on enter ①, and back to 0 on leave ②. <code>overflow: hidden</code> is set during the transition to prevent content overflow.", "svgViewBox": "0 0 700 160"}, "cssVars": [{"name": "--origam-transition--expand-x-enter-active---transition-duration", "defaultValue": "0.5s", "descriptionKey": "components.expand_x.css_vars.enter_duration", "descriptionFallback": "Duration of the enter (expand) animation."}, {"name": "--origam-transition--expand-x-enter-active---transition-timing-function", "defaultValue": "cubic-bezier(0.4, 0, 0.2, 1)", "descriptionKey": "components.expand_x.css_vars.enter_timing", "descriptionFallback": "Easing function for the enter animation."}, {"name": "--origam-transition--expand-x-enter-active---transition-property", "defaultValue": "width", "descriptionKey": "components.expand_x.css_vars.enter_property", "descriptionFallback": "CSS property animated on enter."}, {"name": "--origam-transition--expand-x-enter-leave---transition-duration", "defaultValue": "0.5s", "descriptionKey": "components.expand_x.css_vars.leave_duration", "descriptionFallback": "Duration of the leave (collapse) animation."}, {"name": "--origam-transition--expand-x-enter-leave---transition-timing-function", "defaultValue": "cubic-bezier(0.4, 0, 0.2, 1)", "descriptionKey": "components.expand_x.css_vars.leave_timing", "descriptionFallback": "Easing function for the leave animation."}, {"name": "--origam-transition--expand-x-enter-leave---transition-property", "defaultValue": "width", "descriptionKey": "components.expand_x.css_vars.leave_property", "descriptionFallback": "CSS property animated on leave."}, {"name": "--origam-transition--expand-x-move---transition-duration", "defaultValue": "0.5s", "descriptionKey": "components.expand_x.css_vars.move_duration", "descriptionFallback": "Duration of the move animation in group transitions."}, {"name": "--origam-transition--expand-x-move---transition-property", "defaultValue": "transform", "descriptionKey": "components.expand_x.css_vars.move_property", "descriptionFallback": "CSS property animated during group moves."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.expand_x.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props."}], "playground": {"controls": [{"kind": "switch", "prop": "disabled", "labelKey": "components.expand_x.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "select", "prop": "mode", "options": [{"label": "(default)", "value": ""}, {"label": "TRANSITION_MODE.IN_OUT", "value": "TRANSITION_MODE.IN_OUT"}, {"label": "in-out", "value": "in-out"}, {"label": "TRANSITION_MODE.OUT_IN", "value": "TRANSITION_MODE.OUT_IN"}, {"label": "out-in", "value": "out-in"}, {"label": "TRANSITION_MODE.DEFAULT", "value": "TRANSITION_MODE.DEFAULT"}, {"label": "default", "value": "default"}], "labelKey": "components.expand_x.playground.mode", "defaultValue": "", "labelFallback": "Mode"}], "defaultSlotContent": "Content"}}', false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('95466e57-7a31-4ed5-bbd8-622fda0ad25a', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'component', 'expand-y', 'ExpandY', 'Utilities & Providers', NULL, 'mdi-arrow-expand-vertical', 'components.catalog.transition_expand_y.description', 'JS-driven vertical height expand/collapse transition. Animates the element height from 0 to its natural offsetHeight (enter) and back to 0 (leave). Duration 0.5s with cubic-bezier(0.4, 0, 0.2, 1). Commonly used for accordion and collapsible content.', NULL, NULL, 'origam-expand-y', NULL, NULL, 'origam', NULL, NULL, '/stories/?story=components-transition--design', '/docs/components/Transition/OrigamExpandY.html', 'transition', '{"a11y": {"notes": [{"noteKey": "components.expand_y.a11y.reduced_motion", "noteFallback": "Set disabled=true to suppress all animations for users with prefers-reduced-motion: reduce. OrigamExpansionPanel passes this automatically when the media query matches."}, {"noteKey": "components.expand_y.a11y.no_role", "noteFallback": "ExpandY is transparent to the accessibility tree — it adds no ARIA roles or attributes. Only the slotted content is visible to screen readers."}, {"noteKey": "components.expand_y.a11y.overflow", "noteFallback": "During the transition, overflow: hidden is set on the element to prevent content from showing outside the animated bounds. The original overflow is restored in afterEnter / afterLeave."}], "roles": [], "keyboard": []}, "tokens": {"excerpt": [{"type": "duration", "value": "{motion.duration.slow}", "tokenPath": "transition.expand.duration", "descriptionKey": "components.expand_y.tokens.duration", "descriptionFallback": "Expand/collapse anim