INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4f433721-96b7-4385-b348-506aaf18dbcb', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'component', 'img', 'Img', 'Data Display', NULL, 'mdi-image-outline', 'components.catalog.img.description', 'Responsive image component with lazy loading, aspect-ratio enforcement, placeholder and error slot, optional gradient overlay, srcset / sizes support, and a smooth fade-in transition on load.', NULL, NULL, 'origam-img', NULL, NULL, 'origam', NULL, NULL, '/stories/?story=components-img--design', '/docs/components/Img/OrigamImg.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.img.a11y.alt", "noteFallback": "Always provide a meaningful alt text. When alt is present, role=\"img\" and aria-label={alt} are set on the root. For decorative images, omit alt and set aria-hidden=\"true\" on the parent."}, {"noteKey": "components.img.a11y.lazy_loading", "noteFallback": "Lazy loading is handled via IntersectionObserver (not the native loading=\"lazy\" attribute) so the component loads the image only when it enters the viewport. The placeholder slot is announced by the browser as the alt text is still present on the root."}, {"noteKey": "components.img.a11y.error_slot", "noteFallback": "When the image fails to load, the #error slot is shown. The slot content should include meaningful text or an icon-with-label so users know the image did not load."}, {"noteKey": "components.img.a11y.reduced_motion", "noteFallback": "The fade-in transition respects prefers-reduced-motion. When the user prefers reduced motion, set transition=\"false\" or use --origam-img---transition-duration: 0ms."}], "roles": ["img"], "keyboard": []}, "tokens": {"excerpt": [{"type": "color", "value": "{color.surface.overlay}", "tokenPath": "img.background-color", "descriptionKey": "components.img.tokens.background_color", "descriptionFallback": "Container background while loading."}, {"type": "dimension", "value": "{radius.none}", "tokenPath": "img.border-radius", "descriptionKey": "components.img.tokens.border_radius", "descriptionFallback": "Default corner radius (0 — overridden by rounded prop)."}, {"type": "duration", "value": "{motion.duration.medium}", "tokenPath": "img.transition-duration", "descriptionKey": "components.img.tokens.transition_duration", "descriptionFallback": "Fade-in duration on load."}, {"type": "color", "value": "{color.surface.disabled}", "tokenPath": "img.placeholder.background-color", "descriptionKey": "components.img.tokens.placeholder_bg", "descriptionFallback": "Background of the placeholder slot zone."}, {"type": "color", "value": "{color.feedback.danger.bgSubtle}", "tokenPath": "img.error.background-color", "descriptionKey": "components.img.tokens.error_bg", "descriptionFallback": "Background of the error slot zone."}, {"type": "color", "value": "{color.feedback.danger.fgSubtle}", "tokenPath": "img.error.color", "descriptionKey": "components.img.tokens.error_color", "descriptionFallback": "Foreground colour of the error slot zone."}], "sourceFile": "packages/ds/tokens/component/img.json", "pipelineNote": "Built with Style Dictionary v4 + @tokens-studio/sd-transforms. Outputs: CSS custom properties, SCSS variables, TypeScript types."}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"16\" width=\"644\" height=\"168\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"48\" y=\"36\" width=\"604\" height=\"108\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"350\" y=\"80\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">__picture (absolute, object-fit: contain/cover)</text>\n  <rect x=\"200\" y=\"52\" width=\"300\" height=\"40\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"350\" y=\"76\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\">__placeholder (lazy load blur)</text>\n  <rect x=\"48\" y=\"156\" width=\"604\" height=\"20\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.15))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"350\" y=\"170\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\">#default slot (overlay content)</text>\n  <circle cx=\"36\" cy=\"24\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"28.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"56\" cy=\"44\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"56\" y=\"48\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"200\" cy=\"56\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"200\" y=\"60\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n", "code": "<!-- OrigamImg — wraps OrigamResponsive for aspect ratio -->\n<origam-responsive\n  v-intersect=\"intersect\"\n  :aria-label=\"alt\"\n  :aspect-ratio=\"aspectRatio\"\n  :role=\"alt ? ''img'' : undefined\"\n  class=\"origam-img\"\n>\n  <template #additional>\n    <!-- main image (fade-in on load) -->\n    <origam-transition :transition=\"transition\">\n      <img v-show=\"isLoaded\" class=\"origam-img__picture origam-img__picture--cover\" />\n    </origam-transition>\n\n    <!-- lazySrc placeholder (blur filter) -->\n    <origam-transition :transition=\"transition\">\n      <img v-if=\"lazySrc && !isLoaded\" class=\"origam-img__picture origam-img__picture--preload\" />\n    </origam-transition>\n\n    <!-- #placeholder slot — v-if isLoading && slots.placeholder -->\n    <div v-if=\"(isLoading || isError) && slots.placeholder\" class=\"origam-img__placeholder\">\n      <slot name=\"placeholder\" />\n    </div>\n\n    <!-- #error slot — v-if isError && slots.error -->\n    <div v-if=\"isError && slots.error\" class=\"origam-img__error\">\n      <slot name=\"error\" />\n    </div>\n\n    <!-- gradient overlay — v-if gradient -->\n    <div v-if=\"gradient\" class=\"origam-img__gradient\" />\n  </template>\n\n  <!-- #default slot — overlay content -->\n  <template #default v-if=\"hasContent\">\n    <slot name=\"default\" />\n  </template>\n</origam-responsive>", "legend": [{"cls": ".origam-img", "num": 1, "descriptionKey": "components.img.anatomy.root", "descriptionFallback": "Root element wrapping OrigamResponsive. Carries role=\"img\" when alt is present. Has --booting modifier until aspectRatio resolves."}, {"cls": ".origam-img__picture", "num": 2, "descriptionKey": "components.img.anatomy.picture", "descriptionFallback": "Native <img> element. Absolutely positioned, 100% width/height. Has --cover (object-fit: cover) or --contain (object-fit: contain) modifier. Has --preload modifier with blur filter when showing lazySrc."}, {"cls": ".origam-img__placeholder", "num": 3, "descriptionKey": "components.img.anatomy.placeholder", "descriptionFallback": "Shown during loading (or lazySrc phase) when the #placeholder slot is provided. Absolutely positioned layer behind the main image."}, {"cls": ".origam-img__error", "num": 4, "descriptionKey": "components.img.anatomy.error", "descriptionFallback": "Shown when the image fails to load and the #error slot is provided."}, {"cls": ".origam-img__gradient", "num": 5, "descriptionKey": "components.img.anatomy.gradient", "descriptionFallback": "Absolutely positioned <div> rendered when gradient prop is set. Applies background-image: linear-gradient(...)."}], "classes": [{"cls": "origam-img", "descriptionKey": "components.img.anatomy.root", "descriptionFallback": "Root element. Has --booting class until aspectRatio resolves (prevents premature paint)."}, {"cls": "origam-img--booting", "descriptionKey": "components.img.anatomy.booting", "descriptionFallback": "Disables the sizer transition during initial mount. Removed after first rAF."}, {"cls": "origam-img__picture", "descriptionKey": "components.img.anatomy.picture", "descriptionFallback": "Native <img>. Always absolutely positioned inside the responsive sizer."}, {"cls": "origam-img__picture--cover", "descriptionKey": "components.img.anatomy.picture_cover", "descriptionFallback": "object-fit: cover — image fills the container, cropped."}, {"cls": "origam-img__picture--contain", "descriptionKey": "components.img.anatomy.picture_contain", "descriptionFallback": "object-fit: contain — image fits inside the container without cropping."}, {"cls": "origam-img__picture--preload", "descriptionKey": "components.img.anatomy.picture_preload", "descriptionFallback": "Applied to the lazySrc image. Has blur filter while the full-res image loads."}, {"cls": "origam-img__placeholder", "descriptionKey": "components.img.anatomy.placeholder", "descriptionFallback": "#placeholder slot wrapper. Shown during loading."}, {"cls": "origam-img__error", "descriptionKey": "components.img.anatomy.error", "descriptionFallback": "#error slot wrapper. Shown on load failure."}, {"cls": "origam-img__gradient", "descriptionKey": "components.img.anatomy.gradient", "descriptionFallback": "Gradient overlay div. background-image set from the gradient prop."}], "svgDesc": "Schematic of the Img component with 5 numbered internal parts.", "svgTitle": "Anatomy of OrigamImg", "rootClass": "origam-img", "figcaption": "Anatomy of <code>&lt;origam-img&gt;</code> — 5 internal parts. The root ① wraps OrigamResponsive for aspect-ratio enforcement. The picture ② is absolutely positioned. Placeholder ③ and error ④ layers are conditional. The gradient ⑤ is an absolute div when the gradient prop is set.", "svgViewBox": "0 0 700 200"}, "cssVars": [{"name": "--origam-img---background-color", "defaultValue": "{color.surface.overlay}", "descriptionKey": "components.img.css_vars.background_color", "descriptionFallback": "Background colour of the image container while the image loads."}, {"name": "--origam-img---border-radius", "defaultValue": "{radius.none} (0px)", "descriptionKey": "components.img.css_vars.border_radius", "descriptionFallback": "Corner radius of the image root. Overridden by the rounded prop."}, {"name": "--origam-img---transition-duration", "defaultValue": "{motion.duration.medium}", "descriptionKey": "components.img.css_vars.transition_duration", "descriptionFallback": "Fade-in transition duration when the image loads."}, {"name": "--origam-img__picture--preload---filter", "defaultValue": "blur(4px)", "descriptionKey": "components.img.css_vars.picture_preload_filter", "descriptionFallback": "CSS filter applied to the lazySrc placeholder image."}, {"name": "--origam-img__picture--contain---object-fit", "defaultValue": "contain", "descriptionKey": "components.img.css_vars.picture_contain_object_fit", "descriptionFallback": "object-fit value for the --contain modifier."}, {"name": "--origam-img__picture--cover---object-fit", "defaultValue": "cover", "descriptionKey": "components.img.css_vars.picture_cover_object_fit", "descriptionFallback": "object-fit value for the --cover modifier."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.img.exposed.filter_props", "descriptionFallback": "Filters and forwards a subset of props."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.img.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.img.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.img.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.img.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "ComputedRef<boolean>", "descriptionKey": "components.img.exposed.is_loaded", "descriptionFallback": "True when the image has successfully loaded (state === LOADED)."}, {"name": "styleIsLoaded", "type": "Ref<boolean>", "descriptionKey": "components.img.exposed.style_is_loaded", "descriptionFallback": "True once the component style sheet has been injected. Note: distinct from isLoaded (image load state)."}], "playground": {"controls": [{"kind": "text", "prop": "src", "labelKey": "components.img.playground.src", "defaultValue": "https://picsum.photos/600/400", "labelFallback": "Source URL"}, {"kind": "text", "prop": "alt", "labelKey": "components.img.playground.alt", "defaultValue": "Landscape photo", "labelFallback": "Alt text"}, {"kind": "switch", "prop": "cover", "labelKey": "components.img.playground.cover", "defaultValue": false, "labelFallback": "Cover (vs contain)"}, {"kind": "select", "prop": "aspectRatio", "options": [{"label": "(auto)", "value": ""}, {"label": "16/9", "value": "1.7778"}, {"label": "4/3", "value": "1.3333"}, {"label": "1/1 (square)", "value": "1"}, {"label": "3/4 (portrait)", "value": "0.75"}], "labelKey": "components.img.playground.aspect_ratio", "defaultValue": "", "labelFallback": "Aspect ratio"}, {"kind": "select", "prop": "rounded", "options": [{"label": "(none)", "value": ""}, {"label": "sm", "value": "sm"}, {"label": "md", "value": "md"}, {"label": "lg", "value": "lg"}, {"label": "xl", "value": "xl"}, {"label": "pill", "value": "pill"}], "labelKey": "components.img.playground.rounded", "defaultValue": "", "labelFallback": "Rounded"}, {"kind": "select", "prop": "gradient", "options": [{"label": "(none)", "value": ""}, {"label": "to bottom (dark)", "value": "to bottom, transparent, rgba(0,0,0,0.6)"}, {"label": "to top (dark)", "value": "to top, transparent, rgba(0,0,0,0.6)"}], "labelKey": "components.img.playground.gradient", "defaultValue": "", "labelFallback": "Gradient"}]}, "previewVariants": [{"label": "contain", "props": {"alt": "Photo (contain)", "src": "https://picsum.photos/400/300", "width": 200, "aspectRatio": "4/3"}}, {"label": "cover", "props": {"alt": "Photo (cover)", "src": "https://picsum.photos/400/300", "cover": true, "width": 200, "aspectRatio": "4/3"}}, {"label": "rounded", "props": {"alt": "Rounded photo", "src": "https://picsum.photos/300/300", "cover": true, "width": 120, "rounded": "xl", "aspectRatio": 1}}]}', false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1fd41e00-b26b-4436-b939-f872016412fc', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'component', 'infinite-scroll', 'InfiniteScroll', 'Data Display', NULL, 'mdi-infinity', 'components.catalog.infinite_scroll.description', 'Sentinel-based infinite scroll that fires a load event when the user reaches the start or end of a scrollable area.', NULL, NULL, 'origam-infinite-scroll', NULL, NULL, 'origam', NULL, NULL, '/stories/?story=components-infinite-scroll--design', '/docs/components/InfiniteScroll/OrigamInfiniteScroll.html', NULL, '{"playground": {"controls": [{"kind": "select", "prop": "side", "options": [{"label": "(default)", "value": ""}, {"label": "start", "value": "start"}, {"label": "end", "value": "end"}, {"label": "both", "value": "both"}], "labelKey": "components.infinite_scroll.playground.side", "defaultValue": "", "labelFallback": "Side"}, {"kind": "select", "prop": "mode", "options": [{"label": "(default)", "value": ""}, {"label": "intersect", "value": "intersect"}, {"label": "manual", "value": "manual"}], "labelKey": "components.infinite_scroll.playground.mode", "defaultValue": "", "labelFallback": "Mode"}, {"kind": "select", "prop": "direction", "options": [{"label": "(default)", "value": ""}, {"label": "horizontal", "value": "horizontal"}, {"label": "vertical", "value": "vertical"}], "labelKey": "components.infinite_scroll.playground.direction", "defaultValue": "", "labelFallback": "Direction"}], "defaultSlotContent": "Content"}}', false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ce6c5c77-f469-4579-8970-cfc96dbbf2e0', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'component', 'infinite-scroll-intersect', 'InfiniteScrollIntersect', 'Data Display', NULL, 'mdi-arrow-collapse-down', 'components.catalog.infinite_scroll_intersect.description', 'Low-level sentinel element used by InfiniteScroll to detect when the scroll boundary enters the viewport via IntersectionObserver.', NULL, NULL, 'origam-infinite-scroll-intersect', NULL, NULL, 'origam', NULL, NULL, '/stories/?story=components-infinite-scroll--design', '/docs/components/InfiniteScroll/OrigamInfiniteScroll.html', 'infinite-scroll', '{"a11y": {"notes": [{"noteKey": "components.infinite_scroll_intersect.a11y.invisible_note", "noteFallback": "The sentinel is a non-interactive, invisible element with no ARIA role. Screen readers ignore it. Announce newly loaded content via a live region on the parent component."}], "roles": [], "keyboard": []}, "tokens": {"excerpt": [{"type": "color", "value": "{color.action.primary.bg}", "tokenPath": "infinite-scroll.loader.color", "descriptionKey": "components.infinite_scroll_intersect.tokens.loader_color", "descriptionFallback": "Color passed to the OrigamProgress spinner in the loading slot."}, {"type": "dimension", "value": "{space.3}", "tokenPath": "infinite-scroll.loader.gap", "descriptionKey": "components.infinite_scroll_intersect.tokens.loader_gap", "descriptionFallback": "Gap between loader and adjacent elements within the side zone."}, {"type": "color", "value": "{color.text.secondary}", "tokenPath": "infinite-scroll.empty.color", "descriptionKey": "components.infinite_scroll_intersect.tokens.empty_color", "descriptionFallback": "Text color for the empty-state message shown when no more items are available."}], "sourceFile": "packages/ds/tokens/component/infinite-scroll.json", "pipelineNote": "Built with Style Dictionary v4 + @tokens-studio/sd-transforms. Outputs: CSS custom properties, SCSS variables, TypeScript types."}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"160\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"40\" width=\"644\" height=\"80\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\" stroke-dasharray=\"6 3\"/>\n  <text x=\"350\" y=\"84\" font-size=\"10\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">height: 1px (invisible sentinel)</text>\n  <circle cx=\"36\" cy=\"48\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"52.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <line x1=\"46\" y1=\"44\" x2=\"88\" y2=\"28\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"92\" y=\"28\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-infinite-scroll-intersect</text>\n", "legend": [{"cls": ".origam-infinite-scroll-intersect", "num": 1, "descriptionKey": "components.infinite_scroll_intersect.anatomy.root", "descriptionFallback": "Root element. A minimal <code>&lt;div&gt;</code> containing a non-breaking space (<code>&amp;nbsp;</code>) to ensure the browser paints it. Observed by <code>useIntersectionObserver</code> and fires the <code>intersect</code> emit on visibility change."}], "svgDesc": "Schematic of the InfiniteScrollIntersect sentinel element with 1 numbered part.", "svgTitle": "Anatomy of OrigamInfiniteScrollIntersect", "rootClass": "origam-infinite-scroll-intersect", "figcaption": "Anatomy of <code>&lt;origam-infinite-scroll-intersect&gt;</code> — a single invisible sentinel <code>&lt;div&gt;</code> observed by an IntersectionObserver.", "svgViewBox": "0 0 700 160"}, "cssVars": [{"name": "--origam-infinite-scroll---loader-color", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.infinite_scroll_intersect.css_vars.loader_color", "descriptionFallback": "Color of the loading spinner in the parent InfiniteScroll loader slot."}, {"name": "--origam-infinite-scroll---loader-gap", "defaultValue": "{space.3}", "descriptionKey": "components.infinite_scroll_intersect.css_vars.loader_gap", "descriptionFallback": "Gap between the loader and adjacent elements in the side zone."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.infinite_scroll_intersect.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}], "playground": {"controls": [{"kind": "select", "prop": "side", "options": [{"label": "(default)", "value": ""}, {"label": "start", "value": "start"}, {"label": "INFINITE_SCROLL_SIDE.START", "value": "INFINITE_SCROLL_SIDE.START"}, {"label": "INFINITE_SCROLL_SIDE.END", "value": "INFINITE_SCROLL_SIDE.END"}, {"label": "end", "value": "end"}, {"label": "INFINITE_SCROLL_SIDE.BOTH", "value": "INFINITE_SCROLL_SIDE.BOTH"}, {"label": "both", "value": "both"}], "labelKey": "components.infinite_scroll_intersect.playground.side", "defaultValue": "", "labelFallback": "Side"}]}, "previewVariants": []}', false, NULL, NULL);
