INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('503bec4f-5601-4dec-878b-cee926c558e6', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'component', 'masonry', 'Masonry', 'Layout & Structure', NULL, 'mdi-view-dashboard-variant-outline', 'components.catalog.masonry.description', 'Pinterest-style masonry grid. Uses native CSS grid-template-rows: masonry when supported; falls back to a ResizeObserver bucket-fill algorithm. Container-query responsive via columnBreakpoints.', NULL, NULL, 'origam-masonry', NULL, NULL, 'origam', NULL, NULL, '/stories/?story=components-masonry--design', '/docs/components/Masonry/OrigamMasonry.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.masonry.a11y.role_note", "noteFallback": "OrigamMasonry renders with <code>role=\"list\"</code>. In the JS path, each item wrapper carries <code>role=\"listitem\"</code>. In the CSS path, direct children should carry their own semantic markup."}, {"noteKey": "components.masonry.a11y.order_note", "noteFallback": "Items are laid out in DOM order. Visual column order may differ from reading order — ensure the DOM order matches a meaningful reading sequence for keyboard and screen reader users."}, {"noteKey": "components.masonry.a11y.reduced_motion_note", "noteFallback": "Transitions are disabled under <code>prefers-reduced-motion: reduce</code> via a dedicated @media block in the SCSS."}], "roles": ["list"], "keyboard": []}, "tokens": {"excerpt": [{"type": "duration", "value": "{motion.duration.fast}", "tokenPath": "masonry.animation-duration", "descriptionKey": "components.masonry.tokens.animation_duration", "descriptionFallback": "Duration of the animated position-change transition."}, {"type": "cubicBezier", "value": "{motion.easing.standard}", "tokenPath": "masonry.animation-easing", "descriptionKey": "components.masonry.tokens.animation_easing", "descriptionFallback": "Easing of the animated position-change transition."}], "sourceFile": "packages/ds/tokens/component/masonry.json", "pipelineNote": "Built with Style Dictionary v4 + @tokens-studio/sd-transforms. The token file is minimal — most visual configuration is expressed as CSS vars injected inline by the component."}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"260\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <text x=\"24\" y=\"20\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" font-family=\"''JetBrains Mono'',monospace\">CSS path (grid-template-rows: masonry)</text>\n  <rect x=\"24\" y=\"28\" width=\"300\" height=\"200\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"36\" y=\"40\" width=\"84\" height=\"80\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.10))\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\"/>\n  <rect x=\"130\" y=\"40\" width=\"84\" height=\"120\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.10))\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\"/>\n  <rect x=\"224\" y=\"40\" width=\"84\" height=\"60\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.10))\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\"/>\n  <rect x=\"36\" y=\"132\" width=\"84\" height=\"60\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\"/>\n  <rect x=\"224\" y=\"112\" width=\"84\" height=\"100\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\"/>\n  <text x=\"376\" y=\"20\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" font-family=\"''JetBrains Mono'',monospace\">JS fallback (ResizeObserver + bucket-fill)</text>\n  <rect x=\"376\" y=\"28\" width=\"300\" height=\"200\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1.5\" stroke-dasharray=\"4 2\"/>\n  <rect x=\"388\" y=\"40\" width=\"84\" height=\"80\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.10))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\"/>\n  <text x=\"430\" y=\"84\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">__item</text>\n  <rect x=\"482\" y=\"40\" width=\"84\" height=\"120\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.10))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\"/>\n  <rect x=\"576\" y=\"40\" width=\"84\" height=\"60\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.10))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\"/>\n  <rect x=\"388\" y=\"132\" width=\"84\" height=\"60\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\"/>\n  <circle cx=\"32\" cy=\"36\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"32\" y=\"40.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"384\" cy=\"36\" r=\"10\" fill=\"var(--origam-color__border---default, rgba(168,85,247,0.5))\"/>\n  <text x=\"384\" y=\"40.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"44\" cy=\"48\" r=\"8\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"44\" y=\"52\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"396\" cy=\"48\" r=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"396\" y=\"52\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <text x=\"350\" y=\"248\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">CSS path: display: grid + masonry / JS path: position: absolute per item</text>\n", "code": "<component :is=\"tag\" role=\"list\" class=\"origam-masonry origam-masonry--css\">\n  <!-- CSS path: children rendered directly as grid items -->\n  <slot />\n</component>\n\n<!-- OR (JS fallback path) -->\n<component :is=\"tag\" role=\"list\" class=\"origam-masonry origam-masonry--js\">\n  <div\n    v-for=\"(child, idx) in childrenVNodes\"\n    :key=\"idx\"\n    class=\"origam-masonry__item\"\n    role=\"listitem\"\n    :style=\"getItemStyle(idx)\"\n  >\n    <component :is=\"{ render: () => child }\" />\n  </div>\n</component>", "legend": [{"cls": ".origam-masonry.origam-masonry--css", "num": 1, "descriptionKey": "components.masonry.anatomy.css_path", "descriptionFallback": "CSS path: <code>display: grid; grid-template-rows: masonry; align-tracks: start</code>. <code>grid-template-columns</code> set via <code>--origam-masonry---template-columns</code> CSS var. No item wrappers — children are direct grid items."}, {"cls": ".origam-masonry.origam-masonry--js", "num": 2, "descriptionKey": "components.masonry.anatomy.js_path", "descriptionFallback": "JS fallback path: <code>position: relative; display: block</code>. Container height driven by <code>--origam-masonry---container-height</code>. Items absolutely positioned."}, {"cls": "(direct child — CSS path)", "num": 3, "descriptionKey": "components.masonry.anatomy.css_child", "descriptionFallback": "In the CSS path, children are placed directly as grid items. No wrapper is injected by the component."}, {"cls": ".origam-masonry__item", "num": 4, "descriptionKey": "components.masonry.anatomy.js_item", "descriptionFallback": "In the JS fallback path, each child VNode is wrapped in a <code>div.origam-masonry__item</code> with <code>position: absolute; left/top/width</code> computed by useMasonry."}], "classes": [{"cls": "origam-masonry", "descriptionKey": "components.masonry.anatomy.root", "descriptionFallback": "Root element. role=\"list\". Box-sizing: border-box; gap driven by --origam-masonry---resolved-gap."}, {"cls": "origam-masonry--css", "descriptionKey": "components.masonry.anatomy.css_path", "descriptionFallback": "CSS path modifier. display: grid; grid-template-rows: masonry; align-tracks: start."}, {"cls": "origam-masonry--js", "descriptionKey": "components.masonry.anatomy.js_path", "descriptionFallback": "JS fallback modifier. position: relative; display: block; height from --origam-masonry---container-height."}, {"cls": "origam-masonry--animated", "descriptionKey": "components.masonry.anatomy.animated", "descriptionFallback": "Applied when animated=true. Adds CSS transitions on item position changes."}, {"cls": "origam-masonry__item", "descriptionKey": "components.masonry.anatomy.js_item", "descriptionFallback": "Absolute-positioned wrapper for each child VNode in the JS fallback path. role=\"listitem\"."}], "svgDesc": "Schematic of the Masonry component in CSS and JS fallback paths.", "svgTitle": "Anatomy of OrigamMasonry", "rootClass": "origam-masonry", "figcaption": "Anatomy of <code>&lt;origam-masonry&gt;</code> — ① CSS path (grid-template-rows: masonry, native, no wrappers), ② JS fallback path (position: relative container), ③ direct child (CSS path — no wrapper), ④ <code>.origam-masonry__item</code> (JS path — absolute wrapper added by the component).", "svgViewBox": "0 0 700 260"}, "cssVars": [{"name": "--origam-masonry---resolved-gap", "defaultValue": "var(--origam-grid---gap-md)", "descriptionKey": "components.masonry.css_vars.resolved_gap", "descriptionFallback": "Bridge variable: the serialised gap value (token or raw CSS). Consumed by the gap property AND read back by the JS algo via getComputedStyle."}, {"name": "--origam-masonry---template-columns", "defaultValue": "repeat(3, 1fr)", "descriptionKey": "components.masonry.css_vars.template_columns", "descriptionFallback": "CSS path only. Set to repeat(N, 1fr) where N = active column count."}, {"name": "--origam-masonry---container-height", "defaultValue": "auto", "descriptionKey": "components.masonry.css_vars.container_height", "descriptionFallback": "JS path only. Set to the computed total height of the bucket-fill layout."}, {"name": "--origam-masonry---animation-duration", "defaultValue": "{motion.duration.fast}", "descriptionKey": "components.masonry.css_vars.animation_duration", "descriptionFallback": "Duration of position-change transitions (animated=true)."}, {"name": "--origam-masonry---animation-easing", "defaultValue": "{motion.easing.standard}", "descriptionKey": "components.masonry.css_vars.animation_easing", "descriptionFallback": "Easing of position-change transitions."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.masonry.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child."}, {"name": "layout", "type": "Ref<{ items: Array<{ left: number; top: number; width: number }>; containerHeight: number }>", "descriptionKey": "components.masonry.exposed.layout", "descriptionFallback": "Reactive layout data computed by useMasonry. Available in both paths but only consumed by the template in the JS path."}, {"name": "relayout", "type": "() => void", "descriptionKey": "components.masonry.exposed.relayout", "descriptionFallback": "Forces an immediate re-computation of the bucket-fill layout. Useful after programmatically changing item content without changing the DOM structure."}, {"name": "useCssPath", "type": "ComputedRef<boolean>", "descriptionKey": "components.masonry.exposed.use_css_path", "descriptionFallback": "True when the CSS masonry path is active. False when the JS fallback runs."}, {"name": "gapPx", "type": "Ref<number>", "descriptionKey": "components.masonry.exposed.gap_px", "descriptionFallback": "Current gap value in pixels as resolved by getComputedStyle. Used by the JS bucket-fill algorithm."}], "playground": {"controls": [{"kind": "number", "prop": "columns", "labelKey": "components.masonry.playground.columns", "defaultValue": 3, "labelFallback": "Columns"}, {"kind": "select", "prop": "gap", "options": [{"label": "xs", "value": "xs"}, {"label": "sm", "value": "sm"}, {"label": "md", "value": "md"}, {"label": "lg", "value": "lg"}, {"label": "xl", "value": "xl"}], "labelKey": "components.masonry.playground.gap", "defaultValue": "md", "labelFallback": "Gap"}, {"kind": "switch", "prop": "animated", "labelKey": "components.masonry.playground.animated", "defaultValue": true, "labelFallback": "Animated"}, {"kind": "select", "prop": "align", "options": [{"label": "top", "value": "top"}, {"label": "center", "value": "center"}], "labelKey": "components.masonry.playground.align", "defaultValue": "top", "labelFallback": "Align"}]}, "previewVariants": []}', false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b20b6190-49bf-4ced-b466-6f15e4833545', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'component', 'media', 'Media', 'Media', NULL, 'mdi-play-circle-outline', 'components.catalog.media.description', 'Universal media controls shell (controller, scrubber, volume) consumed by OrigamAudio and OrigamVideo. Headless and media-agnostic — drives any HTMLMediaElement via state + methods refs from useMediaPlayer().', NULL, NULL, 'origam-media-controller', NULL, NULL, 'origam', NULL, NULL, '/stories/?story=components-audio--design', '/docs/components/Media/OrigamMediaController.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.media.a11y.scrubber_note", "noteFallback": "OrigamMediaScrubber sets role=\"slider\", aria-valuemin, aria-valuemax, aria-valuenow and aria-valuetext on the track element. Keyboard users can seek using ArrowLeft/ArrowRight."}, {"noteKey": "components.media.a11y.volume_note", "noteFallback": "OrigamMediaVolumeControl mute button receives an aria-label from the muteLabel / unmuteLabel props. These must be translated strings passed by the parent."}, {"noteKey": "components.media.a11y.reduced_motion", "noteFallback": "Scrubber transitions and controller fade-in are suppressed under prefers-reduced-motion: reduce."}], "roles": ["group", "progressbar", "slider"], "keyboard": [{"key": "Space / K", "actionKey": "components.media.a11y.key_play_pause", "actionFallback": "Toggle play / pause."}, {"key": "ArrowLeft / J", "actionKey": "components.media.a11y.key_seek_back", "actionFallback": "Seek backward (scrubber step or 5 s)."}, {"key": "ArrowRight / L", "actionKey": "components.media.a11y.key_seek_forward", "actionFallback": "Seek forward (scrubber step or 5 s)."}, {"key": "ArrowUp / ArrowDown", "actionKey": "components.media.a11y.key_volume", "actionFallback": "Adjust volume (vertical scrubber when focused)."}, {"key": "M", "actionKey": "components.media.a11y.key_mute", "actionFallback": "Toggle mute."}]}, "tokens": {"excerpt": [{"type": "color", "value": "{color.action.primary.bg}", "tokenPath": "media-scrubber.color", "descriptionKey": "components.media.tokens.scrubber_color", "descriptionFallback": "Fill color of the scrubber progress bar and thumb."}, {"type": "dimension", "value": "{radius.full}", "tokenPath": "media-scrubber.border-radius", "descriptionKey": "components.media.tokens.scrubber_border_radius", "descriptionFallback": "Border-radius of the track, progress and thumb (pill by default)."}], "sourceFile": "packages/ds/tokens/component/media.json", "pipelineNote": "Built with Style Dictionary v4 + @tokens-studio/sd-transforms. Outputs: CSS custom properties, SCSS variables, TypeScript types."}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"220\" fill=\"var(--origam-color__surface---sunken, #f3f4f6)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"20\" width=\"660\" height=\"180\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #1f2937)\" stroke=\"var(--origam-color__action--primary---bg, #6366f1)\" stroke-width=\"1.5\"/>\n  <rect x=\"30\" y=\"30\" width=\"640\" height=\"30\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(99,102,241,0.12))\" stroke=\"var(--origam-color__border---default, rgba(99,102,241,0.3))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"350\" y=\"50\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #9ca3af)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">#header slot</text>\n  <rect x=\"30\" y=\"68\" width=\"640\" height=\"28\" rx=\"3\" fill=\"rgba(99,102,241,0.08)\" stroke=\"var(--origam-color__border---default, rgba(99,102,241,0.3))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <rect x=\"40\" y=\"76\" width=\"500\" height=\"12\" rx=\"6\" fill=\"var(--origam-color__action--primary---bg, #6366f1)\" opacity=\"0.6\"/>\n  <rect x=\"540\" y=\"76\" width=\"120\" height=\"12\" rx=\"6\" fill=\"var(--origam-color__surface---disabled, rgba(99,102,241,0.2))\"/>\n  <text x=\"350\" y=\"90\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #9ca3af)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">#waveform / progress row</text>\n  <rect x=\"30\" y=\"104\" width=\"640\" height=\"36\" rx=\"3\" fill=\"rgba(99,102,241,0.05)\" stroke=\"var(--origam-color__border---default, rgba(99,102,241,0.25))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <rect x=\"40\" y=\"114\" width=\"80\" height=\"16\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(99,102,241,0.2))\"/>\n  <text x=\"80\" y=\"126\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #9ca3af)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">play/pause</text>\n  <rect x=\"130\" y=\"114\" width=\"120\" height=\"16\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(99,102,241,0.1))\"/>\n  <text x=\"190\" y=\"126\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #9ca3af)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">time display</text>\n  <rect x=\"490\" y=\"114\" width=\"80\" height=\"16\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(99,102,241,0.1))\"/>\n  <text x=\"530\" y=\"126\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #9ca3af)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">volume</text>\n  <rect x=\"580\" y=\"114\" width=\"40\" height=\"16\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(99,102,241,0.1))\"/>\n  <text x=\"600\" y=\"126\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #9ca3af)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">cfg</text>\n  <rect x=\"30\" y=\"148\" width=\"640\" height=\"30\" rx=\"3\" fill=\"rgba(99,102,241,0.06)\" stroke=\"var(--origam-color__border---default, rgba(99,102,241,0.25))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"350\" y=\"167\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #9ca3af)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">#footer slot</text>\n  <circle cx=\"28\" cy=\"28\" r=\"8\" fill=\"var(--origam-color__action--primary---bg, #6366f1)\"/>\n  <text x=\"28\" y=\"32\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"28\" cy=\"66\" r=\"8\" fill=\"var(--origam-color__action--primary---bg, #6366f1)\"/>\n  <text x=\"28\" y=\"70\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"28\" cy=\"102\" r=\"8\" fill=\"var(--origam-color__action--primary---bg, #6366f1)\"/>\n  <text x=\"28\" y=\"106\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"28\" cy=\"146\" r=\"8\" fill=\"var(--origam-color__action--primary---bg, #6366f1)\"/>\n  <text x=\"28\" y=\"150\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"672\" cy=\"28\" r=\"8\" fill=\"var(--origam-color__action--primary---bgHover, #818cf8)\"/>\n  <text x=\"672\" y=\"32\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <circle cx=\"672\" cy=\"102\" r=\"8\" fill=\"var(--origam-color__action--primary---bgHover, #818cf8)\"/>\n  <text x=\"672\" y=\"106\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">6</text>\n", "code": "<div class=\"origam-media-controller\">\n  <slot name=\"header\"/>\n\n  <div class=\"origam-media-controller__progress-row\">\n    <slot name=\"waveform\" :state=\"state\" :methods=\"methods\">\n      <origam-media-scrubber class=\"origam-media-controller__scrubber\" />\n    </slot>\n  </div>\n\n  <div class=\"origam-media-controller__buttons-row\">\n    <div class=\"origam-media-controller__buttons-left\">\n      <slot name=\"prepend-transport\"/>\n      <!-- previous / play-pause / next buttons -->\n      <span class=\"origam-media-controller__time\">\n        <span class=\"origam-media-controller__time-current\"/>\n        <span class=\"origam-media-controller__time-sep\">/</span>\n        <span class=\"origam-media-controller__time-total\"/>\n      </span>\n      <slot name=\"extraControlsLeft\"/>\n    </div>\n\n    <div class=\"origam-media-controller__buttons-right\">\n      <slot name=\"extraControlsRight\"/>\n      <!-- volume control + config menu -->\n      <slot name=\"append-transport\"/>\n    </div>\n  </div>\n\n  <slot name=\"footer\"/>\n</div>", "legend": [{"cls": ".origam-media-controller", "num": 1, "descriptionKey": "components.media.anatomy.root", "descriptionFallback": "Root container. When inset=true, overlays the media surface with a gradient."}, {"cls": ".origam-media-controller__progress-row", "num": 2, "descriptionKey": "components.media.anatomy.progress_row", "descriptionFallback": "Hosts the OrigamMediaScrubber timeline (or the #waveform slot override)."}, {"cls": ".origam-media-controller__buttons-row", "num": 3, "descriptionKey": "components.media.anatomy.buttons_row", "descriptionFallback": "Transport row: play/pause, previous/next, time display, volume, config menu."}, {"cls": ".origam-media-controller__time", "num": 4, "descriptionKey": "components.media.anatomy.time", "descriptionFallback": "Current time / total duration display. Children: __time-current, __time-sep, __time-total."}, {"cls": ".origam-media-controller__buttons-left", "num": 5, "descriptionKey": "components.media.anatomy.buttons_left", "descriptionFallback": "Left side of transport row. Hosts #prepend-transport slot, play/pause, previous/next, time."}, {"cls": ".origam-media-controller__buttons-right", "num": 6, "descriptionKey": "components.media.anatomy.buttons_right", "descriptionFallback": "Right side of transport row. Hosts #extraControlsRight slot, volume control, config menu."}], "classes": [{"cls": "origam-media-controller", "descriptionKey": "components.media.anatomy.root", "descriptionFallback": "Root container. Applies inset overlay mode when inset=true."}, {"cls": "origam-media-controller__progress-row", "descriptionKey": "components.media.anatomy.progress_row", "descriptionFallback": "Scrubber / waveform slot row."}, {"cls": "origam-media-controller__scrubber", "descriptionKey": "components.media.anatomy.scrubber", "descriptionFallback": "Default OrigamMediaScrubber instance injected in the progress row."}, {"cls": "origam-media-controller__buttons-row", "descriptionKey": "components.media.anatomy.buttons_row", "descriptionFallback": "Full-width transport row containing left and right button groups."}, {"cls": "origam-media-controller__buttons-left", "descriptionKey": "components.media.anatomy.buttons_left", "descriptionFallback": "Left transport group: prepend-transport slot, play/pause, prev/next, time."}, {"cls": "origam-media-controller__play-btn", "descriptionKey": "components.media.anatomy.play_btn", "descriptionFallback": "Play / pause toggle button."}, {"cls": "origam-media-controller__time", "descriptionKey": "components.media.anatomy.time", "descriptionFallback": "Time display wrapper. Contains __time-current, __time-sep, __time-total."}, {"cls": "origam-media-controller__buttons-right", "descriptionKey": "components.media.anatomy.buttons_right", "descriptionFallback": "Right transport group: extraControlsRight slot, volume, config menu, append-transport."}], "svgDesc": "Schematic of the MediaController shell with 6 numbered zones.", "svgTitle": "Anatomy of OrigamMediaController", "rootClass": "origam-media-controller", "figcaption": "Anatomy of <code>&lt;origam-media-controller&gt;</code> — 6 internal zones: header slot, progress row (scrubber), transport row (buttons), footer slot, plus prepend/append transport injection points.", "svgViewBox": "0 0 700 220"}, "cssVars": [{"name": "--origam-media-scrubber---color", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.media.css_vars.scrubber_color", "descriptionFallback": "Color of the filled progress track and thumb."}, {"name": "--origam-media-scrubber---border-radius", "defaultValue": "{radius.full}", "descriptionKey": "components.media.css_vars.scrubber_border_radius", "descriptionFallback": "Border-radius of the track and progress bar (pill shape by default)."}, {"name": "--origam-media-volume-control__scrubber---color", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.media.css_vars.volume_scrubber_color", "descriptionFallback": "Color of the volume level bar inside the tooltip."}], "playground": {"controls": [{"kind": "switch", "prop": "inset", "labelKey": "components.media.playground.inset", "defaultValue": false, "labelFallback": "Inset"}, {"kind": "switch", "prop": "visible", "labelKey": "components.media.playground.visible", "defaultValue": true, "labelFallback": "Visible"}, {"kind": "switch", "prop": "allowRemotePlayback", "labelKey": "components.media.playground.allow_remote_playback", "defaultValue": false, "labelFallback": "Allow Remote Playback"}, {"kind": "switch", "prop": "downloadable", "labelKey": "components.media.playground.downloadable", "defaultValue": false, "labelFallback": "Downloadable"}, {"kind": "switch", "prop": "showPrevious", "labelKey": "components.media.playground.show_previous", "defaultValue": false, "labelFallback": "Show Previous"}, {"kind": "switch", "prop": "showNext", "labelKey": "components.media.playground.show_next", "defaultValue": false, "labelFallback": "Show Next"}, {"kind": "switch", "prop": "showLoop", "labelKey": "components.media.playground.show_loop", "defaultValue": false, "labelFallback": "Show Loop"}, {"kind": "switch", "prop": "showShuffle", "labelKey": "components.media.playground.show_shuffle", "defaultValue": false, "labelFallback": "Show Shuffle"}]}, "previewVariants": []}', false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('57411518-86e8-460d-922a-8bfcdfc2d3c1', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'component', 'media-controller', 'MediaController', 'Media', NULL, 'mdi-play-circle-outline', 'components.catalog.media_controller.description', 'Universal media controls shell shared by OrigamAudio and OrigamVideo. Purely presentational — receives state and methods from useMediaPlayer() and emits playback intents (play, pause, seek, volume, loop, shuffle, quality, download) without owning the HTMLMediaElement.', NULL, NULL, 'origam-media-controller', NULL, NULL, 'origam', NULL, NULL, '/stories/?story=components-audio--design', '/docs/components/Media/OrigamMediaController.html', 'media', '{"a11y": {"notes": [{"noteKey": "components.media_controller.a11y.nav_label", "noteFallback": "The transport row is a <nav> element with aria-label set via the i18n key \"origam.media.transport\". This correctly marks the zone as a landmark region."}, {"noteKey": "components.media_controller.a11y.aria_pressed", "noteFallback": "Toggle buttons (shuffle, loop, cast) use aria-pressed reflecting their active state. Screen readers announce \"pressed\" or \"not pressed\" on focus."}, {"noteKey": "components.media_controller.a11y.aria_labels", "noteFallback": "All icon-only buttons carry an aria-label (play, pause, previous, next, mute, unmute, shuffle, loop-all/one/off, cast, stop-cast, settings). Labels are i18n-translated strings computed in the script, not hardcoded strings in the template."}, {"noteKey": "components.media_controller.a11y.scrubber", "noteFallback": "The inner OrigamMediaScrubber uses role=\"slider\", aria-orientation=\"horizontal\", aria-valuemin/max/now/text and aria-label. See MediaScrubber accessibility notes for the full keyboard matrix."}], "roles": ["navigation"], "keyboard": [{"key": "Tab", "actionKey": "components.media_controller.a11y.key_tab", "actionFallback": "Moves focus sequentially through all transport buttons (previous, play/pause, next, mute, volume slider, shuffle, loop, cast, cog)."}, {"key": "Enter / Space", "actionKey": "components.media_controller.a11y.key_activate", "actionFallback": "Activates the focused transport button. Native <button> behaviour via OrigamBtn."}, {"key": "ArrowLeft / ArrowRight", "actionKey": "components.media_controller.a11y.key_scrubber_h", "actionFallback": "When the scrubber is focused: seeks backward/forward by step (default 0.1 s or 5 % of duration)."}, {"key": "Home / End", "actionKey": "components.media_controller.a11y.key_scrubber_bounds", "actionFallback": "When the scrubber is focused: seeks to the start or end of the media."}]}, "tokens": {"excerpt": [{"type": "color", "value": "{color.text.primary}", "tokenPath": "media-controller.color", "descriptionKey": "components.media_controller.tokens.color", "descriptionFallback": "Default text/icon color for the controller bar."}, {"type": "color", "value": "{color.action.primary.bg}", "tokenPath": "media-controller.scrubber.color", "descriptionKey": "components.media_controller.tokens.scrubber_color", "descriptionFallback": "Override color for the inner MediaScrubber timeline bar."}], "sourceFile": "packages/ds/tokens/component/media-controller.json", "pipelineNote": "Built with Style Dictionary v4 + @tokens-studio/sd-transforms."}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"240\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"10\" width=\"660\" height=\"220\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <circle cx=\"28\" cy=\"18\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"22\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <rect x=\"40\" y=\"24\" width=\"620\" height=\"40\" rx=\"4\" fill=\"var(--origam-color__surface---sunken, #f3eeff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"350\" y=\"47\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">#header slot</text>\n  <circle cx=\"48\" cy=\"32\" r=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"48\" y=\"36\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <rect x=\"40\" y=\"74\" width=\"620\" height=\"36\" rx=\"4\" fill=\"var(--origam-color__surface---overlay, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\"/>\n  <rect x=\"60\" y=\"86\" width=\"440\" height=\"12\" rx=\"6\" fill=\"var(--origam-color__surface---overlay, rgba(124,58,237,0.15))\"/>\n  <rect x=\"60\" y=\"86\" width=\"150\" height=\"12\" rx=\"6\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <circle cx=\"48\" cy=\"82\" r=\"8\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"48\" y=\"86\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <rect x=\"40\" y=\"120\" width=\"620\" height=\"48\" rx=\"4\" fill=\"var(--origam-color__surface---sunken, #f9f5ff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\"/>\n  <rect x=\"52\" y=\"132\" width=\"260\" height=\"24\" rx=\"3\" fill=\"var(--origam-color__surface---overlay, rgba(124,58,237,0.08))\"/>\n  <text x=\"182\" y=\"147\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">prev | play | next | volume | time</text>\n  <rect x=\"340\" y=\"132\" width=\"308\" height=\"24\" rx=\"3\" fill=\"var(--origam-color__surface---overlay, rgba(124,58,237,0.08))\"/>\n  <text x=\"494\" y=\"147\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">shuffle | loop | cast | cog</text>\n  <circle cx=\"48\" cy=\"128\" r=\"8\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"48\" y=\"132\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"332\" cy=\"128\" r=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"332\" y=\"132\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <rect x=\"40\" y=\"178\" width=\"620\" height=\"38\" rx=\"4\" fill=\"var(--origam-color__surface---sunken, #f3eeff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"350\" y=\"199\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">#footer slot</text>\n  <circle cx=\"48\" cy=\"186\" r=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"48\" y=\"190\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">6</text>\n", "code": "<div class=\"origam-media-controller origam-media-controller--visible\">\n  <slot name=\"header\" />\n\n  <div class=\"origam-media-controller__progress-row\">\n    <slot name=\"waveform\" :state=\"state\" :methods=\"methods\">\n      <origam-media-scrubber class=\"origam-media-controller__scrubber\" />\n    </slot>\n  </div>\n\n  <nav class=\"origam-media-controller__buttons-row\">\n    <div class=\"origam-media-controller__buttons-left\">\n      <slot name=\"prepend-transport\" />\n      <!-- prev / play-pause / next / volume / time -->\n      <slot name=\"extraControlsLeft\" />\n    </div>\n    <div class=\"origam-media-controller__buttons-right\">\n      <slot name=\"extraControlsRight\" />\n      <!-- shuffle / loop / cast / cog-menu -->\n      <slot name=\"append-transport\" />\n    </div>\n  </nav>\n\n  <slot name=\"footer\" />\n</div>", "legend": [{"cls": ".origam-media-controller", "num": 1, "descriptionKey": "components.media_controller.anatomy.root", "descriptionFallback": "Root div. display: flex; flex-direction: column; gap: 0. When inset=true, applies .origam-media-controller--inset (position: absolute, dark gradient overlay, opacity: 0 by default). .origam-media-controller--visible toggles opacity: 1 and pointer-events: auto."}, {"cls": "#header slot", "num": 2, "descriptionKey": "components.media_controller.anatomy.header", "descriptionFallback": "Optional header region above the scrubber. OrigamAudio injects cover art + metadata strip here."}, {"cls": ".origam-media-controller__progress-row", "num": 3, "descriptionKey": "components.media_controller.anatomy.progress_row", "descriptionFallback": "Scrubber row — padding: 0 12px. Contains OrigamMediaScrubber by default; replaceable via the #waveform slot."}, {"cls": ".origam-media-controller__buttons-left", "num": 4, "descriptionKey": "components.media_controller.anatomy.buttons_left", "descriptionFallback": "Left transport group: previous, play/pause, next, volume control, time display. Flex row; gap: 2px. Buttons use variant=\"text\" density=\"compact\"."}, {"cls": ".origam-media-controller__buttons-right", "num": 5, "descriptionKey": "components.media_controller.anatomy.buttons_right", "descriptionFallback": "Right transport group: shuffle, loop, cast, config cog menu. Same sizing as the left group."}, {"cls": "#footer slot", "num": 6, "descriptionKey": "components.media_controller.anatomy.footer", "descriptionFallback": "Optional footer region below the transport row. OrigamAudio injects the playlist here."}], "classes": [{"cls": "origam-media-controller", "descriptionKey": "components.media_controller.anatomy.root", "descriptionFallback": "Root flex column."}, {"cls": "origam-media-controller--inset", "descriptionKey": "components.media_controller.anatomy.inset", "descriptionFallback": "Applied when inset=true. position: absolute; bottom/left/right: 0; dark gradient; opacity: 0; pointer-events: none."}, {"cls": "origam-media-controller--visible", "descriptionKey": "components.media_controller.anatomy.visible", "descriptionFallback": "Combined with --inset to show the overlay: opacity: 1; pointer-events: auto."}, {"cls": "origam-media-controller__progress-row", "descriptionKey": "components.media_controller.anatomy.progress_row", "descriptionFallback": "Scrubber container with inline padding."}, {"cls": "origam-media-controller__buttons-row", "descriptionKey": "components.media_controller.anatomy.buttons_row", "descriptionFallback": "Transport row. display: flex; justify-content: space-between; min-height: 36px."}, {"cls": "origam-media-controller__buttons-left", "descriptionKey": "components.media_controller.anatomy.buttons_left", "descriptionFallback": "Left button group: flex row; gap: 2px."}, {"cls": "origam-media-controller__buttons-right", "descriptionKey": "components.media_controller.anatomy.buttons_right", "descriptionFallback": "Right button group: flex row; gap: 2px."}, {"cls": "origam-media-controller__scrubber", "descriptionKey": "components.media_controller.anatomy.scrubber", "descriptionFallback": "Class applied to the inner OrigamMediaScrubber. width: 100%; overrides scrubber color tokens."}, {"cls": "origam-media-controller__time", "descriptionKey": "components.media_controller.anatomy.time", "descriptionFallback": "Time display: currentTime / duration. Inline-flex; monospace; font-variant-numeric: tabular-nums."}, {"cls": "origam-media-controller__play-btn", "descriptionKey": "components.media_controller.anatomy.play_btn", "descriptionFallback": "Class applied to the play/pause OrigamBtn for targeting in consumer styles."}], "svgDesc": "Schematic of the media controller with 6 numbered parts: root, header slot, scrubber row, buttons row (left group and right group), footer slot.", "svgTitle": "Anatomy of OrigamMediaController", "rootClass": "origam-media-controller", "figcaption": "Anatomy of <code>&lt;origam-media-controller&gt;</code> — 6 internal parts. Root flex column ①, header slot ②, scrubber row ③ (OrigamMediaScrubber), transport row with left button group ④ (prev/play/next/volume/time) and right button group ⑤ (shuffle/loop/cast/cog), footer slot ⑥.", "svgViewBox": "0 0 700 240"}, "cssVars": [{"name": "--origam-media-controller---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.media_controller.css_vars.color", "descriptionFallback": "Text and icon color for the entire controller bar. Inherits from the parent surface by default."}, {"name": "--origam-media-controller---accent-color", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.media_controller.css_vars.accent_color", "descriptionFallback": "Accent color applied to active transport buttons (loop-active, shuffle-active, cast-active). Background is a 14% tint of this color."}, {"name": "--origam-media-controller__scrubber---color", "defaultValue": "currentColor", "descriptionKey": "components.media_controller.css_vars.scrubber_color", "descriptionFallback": "Override for the inner MediaScrubber progress/thumb color. Falls through to the scrubber default when unset."}, {"name": "--origam-media-controller__time---color", "defaultValue": "inherit", "descriptionKey": "components.media_controller.css_vars.time_color", "descriptionFallback": "Color for the current time / duration display."}], "exposed": [{"name": "configMenuOpen", "type": "Ref<boolean>", "descriptionKey": "components.media_controller.exposed.config_menu_open", "descriptionFallback": "Reactive flag controlling the cog config menu open/close state. Can be read or set externally to programmatically open or close the menu."}, {"name": "resolvedLoopMode", "type": "ComputedRef<TAudioLoopMode>", "descriptionKey": "components.media_controller.exposed.resolved_loop_mode", "descriptionFallback": "The currently active loop mode computed from the internal state. Reflects the prop value unless the user cycled it via the loop button."}, {"name": "internalShuffle", "type": "Ref<boolean>", "descriptionKey": "components.media_controller.exposed.internal_shuffle", "descriptionFallback": "Internal shuffle toggle state. Mirrors the shuffle prop and updates when the button is clicked."}], "playground": {"controls": [{"kind": "switch", "prop": "inset", "labelKey": "components.media_controller.playground.inset", "defaultValue": false, "labelFallback": "Inset"}, {"kind": "switch", "prop": "visible", "labelKey": "components.media_controller.playground.visible", "defaultValue": true, "labelFallback": "Visible"}, {"kind": "switch", "prop": "allowRemotePlayback", "labelKey": "components.media_controller.playground.allow_remote_playback", "defaultValue": false, "labelFallback": "Allow Remote Playback"}, {"kind": "switch", "prop": "downloadable", "labelKey": "components.media_controller.playground.downloadable", "defaultValue": false, "labelFallback": "Downloadable"}, {"kind": "switch", "prop": "showPrevious", "labelKey": "components.media_controller.playground.show_previous", "defaultValue": false, "labelFallback": "Show Previous"}, {"kind": "switch", "prop": "showNext", "labelKey": "components.media_controller.playground.show_next", "defaultValue": false, "labelFallback": "Show Next"}, {"kind": "switch", "prop": "showLoop", "labelKey": "components.media_controller.playground.show_loop", "defaultValue": false, "labelFallback": "Show Loop"}, {"kind": "switch", "prop": "showShuffle", "labelKey": "components.media_controller.playground.show_shuffle", "defaultValue": false, "labelFallback": "Show Shuffle"}]}, "previewVariants": []}', false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a57a7a08-2f97-4715-bfbc-b3fdbe48d368', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'component', 'media-scrubber', 'MediaScrubber', 'Media', NULL, 'mdi-tune', 'components.catalog.media_scrubber.description', 'Headless media-agnostic track-and-thumb slider widget. Owns the full pointer-events drag pipeline, keyboard matrix (ARIA slider pattern), optional buffer bar, hover tooltip and both horizontal and vertical orientations. Used internally by OrigamMediaController for the timeline and the volume slider.', NULL, NULL, 'origam-media-scrubber', NULL, NULL, 'origam', NULL, NULL, '/stories/?story=components-audio--design', '/docs/components/Media/OrigamMediaController.html', 'media', '{"a11y": {"notes": [{"noteKey": "components.media_scrubber.a11y.role_slider", "noteFallback": "role=\"slider\" is set only when not disabled. When disabled, the role attribute is omitted (undefined) and tabindex becomes -1 so AT users are not invited to interact with a frozen widget."}, {"noteKey": "components.media_scrubber.a11y.aria_label_required", "noteFallback": "ariaLabel is a required prop. Always pass a translated string (e.g. \"Seek\" for the timeline, \"Volume\" for the volume slider). The label must describe the purpose of the slider, not its current value."}, {"noteKey": "components.media_scrubber.a11y.aria_value_text", "noteFallback": "Use ariaValueText for a human-readable representation of the value — e.g. \"1:23\" for a timestamp so screen readers announce \"1 minute 23 seconds\" rather than the raw float \"83.4\"."}, {"noteKey": "components.media_scrubber.a11y.reduced_motion", "noteFallback": "Under prefers-reduced-motion: reduce, both track and thumb CSS transitions are disabled (transition: none)."}, {"noteKey": "components.media_scrubber.a11y.pointer_capture", "noteFallback": "The component uses setPointerCapture() on pointerdown so drag events continue even when the pointer leaves the element boundary. This is the standard drag pattern for range inputs on touch devices."}], "roles": ["slider"], "keyboard": [{"key": "ArrowRight / ArrowUp", "actionKey": "components.media_scrubber.a11y.key_increment", "actionFallback": "Increases the value by step (or 5% of range when step=0). ArrowRight for horizontal; ArrowUp for vertical."}, {"key": "ArrowLeft / ArrowDown", "actionKey": "components.media_scrubber.a11y.key_decrement", "actionFallback": "Decreases the value by step (or 5% of range when step=0). ArrowLeft for horizontal; ArrowDown for vertical."}, {"key": "PageUp", "actionKey": "components.media_scrubber.a11y.key_page_up", "actionFallback": "Increases the value by 10% of the range (same regardless of step)."}, {"key": "PageDown", "actionKey": "components.media_scrubber.a11y.key_page_down", "actionFallback": "Decreases the value by 10% of the range."}, {"key": "Home", "actionKey": "components.media_scrubber.a11y.key_home", "actionFallback": "Sets the value to min."}, {"key": "End", "actionKey": "components.media_scrubber.a11y.key_end", "actionFallback": "Sets the value to max."}]}, "tokens": {"excerpt": [{"type": "color", "value": "{color.action.primary.bg}", "tokenPath": "media-scrubber.color", "descriptionKey": "components.media_scrubber.tokens.color", "descriptionFallback": "Primary color (progress bar + thumb fill)."}, {"type": "dimension", "value": "4px", "tokenPath": "media-scrubber.track.thickness", "descriptionKey": "components.media_scrubber.tokens.track_thickness", "descriptionFallback": "Track height at rest (horizontal) / width (vertical)."}, {"type": "dimension", "value": "6px", "tokenPath": "media-scrubber.track.thickness-active", "descriptionKey": "components.media_scrubber.tokens.track_thickness_active", "descriptionFallback": "Track height on hover / focus / scrubbing."}, {"type": "dimension", "value": "12px", "tokenPath": "media-scrubber.thumb.diameter", "descriptionKey": "components.media_scrubber.tokens.thumb_diameter", "descriptionFallback": "Circular thumb diameter."}, {"type": "color", "value": "{color.neutral.900}", "tokenPath": "media-scrubber.tooltip.background-color", "descriptionKey": "components.media_scrubber.tokens.tooltip_background_color", "descriptionFallback": "Hover tooltip background (near-black for contrast)."}, {"type": "color", "value": "{color.neutral.0}", "tokenPath": "media-scrubber.tooltip.color", "descriptionKey": "components.media_scrubber.tokens.tooltip_color", "descriptionFallback": "Hover tooltip text color (white)."}], "sourceFile": "packages/ds/tokens/component/media-scrubber.json", "pipelineNote": "Built with Style Dictionary v4 + @tokens-studio/sd-transforms."}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"160\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"30\" y=\"55\" width=\"640\" height=\"14\" rx=\"7\" fill=\"var(--origam-color__surface---overlay, rgba(124,58,237,0.15))\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\"/>\n  <rect x=\"30\" y=\"55\" width=\"220\" height=\"14\" rx=\"7\" fill=\"rgba(124,58,237,0.25)\"/>\n  <rect x=\"30\" y=\"55\" width=\"148\" height=\"14\" rx=\"7\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <circle cx=\"178\" cy=\"62\" r=\"7\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke=\"var(--origam-color__surface---raised, #fff)\" stroke-width=\"2\"/>\n  <rect x=\"130\" y=\"30\" width=\"60\" height=\"20\" rx=\"3\" fill=\"rgba(0,0,0,0.8)\"/>\n  <text x=\"160\" y=\"43\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-family=\"ui-monospace,monospace\">0:48</text>\n  <line x1=\"160\" y1=\"50\" x2=\"160\" y2=\"55\" stroke=\"rgba(0,0,0,0.5)\" stroke-width=\"1\"/>\n  <circle cx=\"38\" cy=\"55\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"38\" y=\"59\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"350\" cy=\"55\" r=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"350\" y=\"59\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"240\" cy=\"55\" r=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"240\" y=\"59\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"90\" cy=\"55\" r=\"8\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"90\" y=\"59\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"178\" cy=\"55\" r=\"8\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"178\" y=\"59\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <circle cx=\"160\" cy=\"25\" r=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"160\" y=\"29\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">6</text>\n  <text x=\"350\" y=\"115\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">① root — ② track — ③ buffer bar — ④ progress bar — ⑤ thumb — ⑥ hover tooltip</text>\n", "code": "<div\n  class=\"origam-media-scrubber origam-media-scrubber--horizontal\"\n  role=\"slider\"\n  tabindex=\"0\"\n  aria-orientation=\"horizontal\"\n  aria-valuemin=\"0\"\n  aria-valuemax=\"120\"\n  aria-valuenow=\"48\"\n  aria-valuetext=\"0:48\"\n  aria-label=\"Seek\"\n>\n  <div class=\"origam-media-scrubber__track\" aria-hidden=\"true\">\n    <div class=\"origam-media-scrubber__buffer\" aria-hidden=\"true\" />\n    <div class=\"origam-media-scrubber__progress\" aria-hidden=\"true\" />\n    <div class=\"origam-media-scrubber__thumb\" aria-hidden=\"true\" />\n  </div>\n\n  <div class=\"origam-media-scrubber__hover-tooltip\" aria-hidden=\"true\">\n    <slot name=\"tooltip\" :value=\"48\">0:48</slot>\n  </div>\n</div>", "legend": [{"cls": ".origam-media-scrubber", "num": 1, "descriptionKey": "components.media_scrubber.anatomy.root", "descriptionFallback": "Root div. role=\"slider\" (or undefined when disabled), tabindex=\"0\" (or -1 when disabled), aria-orientation, aria-valuemin/max/now/text, aria-label. Handles all pointer and keyboard events. position: relative; cursor: pointer; touch-action: none; user-select: none."}, {"cls": ".origam-media-scrubber__track", "num": 2, "descriptionKey": "components.media_scrubber.anatomy.track", "descriptionFallback": "Track bar. Background color from token --origam-media-scrubber---track-bg. Height grows from --track-thickness to --track-thickness-active on hover / focus / scrubbing. aria-hidden=\"true\"."}, {"cls": ".origam-media-scrubber__buffer", "num": 3, "descriptionKey": "components.media_scrubber.anatomy.buffer", "descriptionFallback": "Buffered portion bar. Renders from min to buffered%. Background --origam-media-scrubber---buffer-bg. Visible only when buffered prop is a finite number. aria-hidden=\"true\"."}, {"cls": ".origam-media-scrubber__progress", "num": 4, "descriptionKey": "components.media_scrubber.anatomy.progress", "descriptionFallback": "Playback progress bar. Width/height = valuePct%. Background --origam-media-scrubber---primary. aria-hidden=\"true\"."}, {"cls": ".origam-media-scrubber__thumb", "num": 5, "descriptionKey": "components.media_scrubber.anatomy.thumb", "descriptionFallback": "Circular drag handle. Position driven by valuePct% (left in horizontal, bottom in vertical). Hidden at rest when showThumbOnHoverOnly=true; revealed on :hover, :focus-visible and .origam-media-scrubber--scrubbing. aria-hidden=\"true\"."}, {"cls": ".origam-media-scrubber__hover-tooltip", "num": 6, "descriptionKey": "components.media_scrubber.anatomy.tooltip", "descriptionFallback": "Hover tooltip. position: absolute; bottom: calc(100% + 8px); left = hoverPct%. Contains the #tooltip slot or the formatted value string. Horizontal orientation only. aria-hidden=\"true\"."}], "classes": [{"cls": "origam-media-scrubber", "descriptionKey": "components.media_scrubber.anatomy.root", "descriptionFallback": "Root slider element with ARIA role and pointer/keyboard event handlers."}, {"cls": "origam-media-scrubber--horizontal", "descriptionKey": "components.media_scrubber.anatomy.horizontal", "descriptionFallback": "Applied when orientation=\"horizontal\". width: 100%; height: 14px."}, {"cls": "origam-media-scrubber--vertical", "descriptionKey": "components.media_scrubber.anatomy.vertical", "descriptionFallback": "Applied when orientation=\"vertical\". height: 100%; width: 14px; flex-direction: column."}, {"cls": "origam-media-scrubber--disabled", "descriptionKey": "components.media_scrubber.anatomy.disabled", "descriptionFallback": "Applied when disabled=true. cursor: not-allowed; opacity: 0.5."}, {"cls": "origam-media-scrubber--scrubbing", "descriptionKey": "components.media_scrubber.anatomy.scrubbing", "descriptionFallback": "Applied while a pointer drag is in progress. Prevents pointerleave from clearing the tooltip."}, {"cls": "origam-media-scrubber--thumb-on-hover", "descriptionKey": "components.media_scrubber.anatomy.thumb_on_hover", "descriptionFallback": "Applied when showThumbOnHoverOnly=true. Scales the thumb to 0 at rest."}, {"cls": "origam-media-scrubber__track", "descriptionKey": "components.media_scrubber.anatomy.track", "descriptionFallback": "Track bar — background + growing height on hover."}, {"cls": "origam-media-scrubber__buffer", "descriptionKey": "components.media_scrubber.anatomy.buffer", "descriptionFallback": "Buffered portion indicator bar."}, {"cls": "origam-media-scrubber__progress", "descriptionKey": "components.media_scrubber.anatomy.progress", "descriptionFallback": "Playback progress fill."}, {"cls": "origam-media-scrubber__thumb", "descriptionKey": "components.media_scrubber.anatomy.thumb", "descriptionFallback": "Circular drag handle (position: absolute)."}, {"cls": "origam-media-scrubber__hover-tooltip", "descriptionKey": "components.media_scrubber.anatomy.tooltip", "descriptionFallback": "Floating hover value tooltip (horizontal only)."}], "svgDesc": "Schematic of the horizontal scrubber with 5 numbered parts: root, track, buffer bar, progress bar, thumb and hover tooltip.", "svgTitle": "Anatomy of OrigamMediaScrubber", "rootClass": "origam-media-scrubber", "figcaption": "Anatomy of <code>&lt;origam-media-scrubber&gt;</code> — 6 internal parts. Root ①, track ② (full-width bg), optional buffer bar ③, progress bar ④ (fills to modelValue %), draggable thumb ⑤, and the hover tooltip ⑥ (horizontal only, conditional on showHoverTooltip).", "svgViewBox": "0 0 700 160"}, "cssVars": [{"name": "--origam-media-scrubber---color", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.media_scrubber.css_vars.color", "descriptionFallback": "Primary accent color. Drives --origam-media-scrubber---primary (progress bar + thumb fill)."}, {"name": "--origam-media-scrubber---track-background-color", "defaultValue": "rgba(255,255,255,0.3)", "descriptionKey": "components.media_scrubber.css_vars.track_background_color", "descriptionFallback": "Idle track fill. Semi-transparent by design (overlaid on the media surface)."}, {"name": "--origam-media-scrubber---buffer-background-color", "defaultValue": "rgba(255,255,255,0.4)", "descriptionKey": "components.media_scrubber.css_vars.buffer_background_color", "descriptionFallback": "Buffer bar fill. Slightly more opaque than the track."}, {"name": "--origam-media-scrubber---thumb-diameter", "defaultValue": "13px", "descriptionKey": "components.media_scrubber.css_vars.thumb_diameter", "descriptionFallback": "Diameter of the circular thumb handle."}, {"name": "--origam-media-scrubber---track-size", "defaultValue": "3px", "descriptionKey": "components.media_scrubber.css_vars.track_size", "descriptionFallback": "Track thickness at rest."}, {"name": "--origam-media-scrubber---track-size-active", "defaultValue": "5px", "descriptionKey": "components.media_scrubber.css_vars.track_size_active", "descriptionFallback": "Track thickness on hover / focus / scrubbing. Animates over 140ms."}, {"name": "--origam-media-scrubber__tooltip---background-color", "defaultValue": "rgba(0,0,0,0.85)", "descriptionKey": "components.media_scrubber.css_vars.tooltip_background_color", "descriptionFallback": "Hover tooltip background. Near-black for contrast."}, {"name": "--origam-media-scrubber__tooltip---color", "defaultValue": "#ffffff", "descriptionKey": "components.media_scrubber.css_vars.tooltip_color", "descriptionFallback": "Hover tooltip text color."}], "exposed": [{"name": "rootEl", "type": "Ref<HTMLElement | null>", "descriptionKey": "components.media_scrubber.exposed.root_el", "descriptionFallback": "Template ref to the root DOM element. Useful for measuring the track dimensions or programming pointer capture externally."}, {"name": "isScrubbing", "type": "Ref<boolean>", "descriptionKey": "components.media_scrubber.exposed.is_scrubbing", "descriptionFallback": "True while a pointer drag is captured. The parent can use this to suppress autohide logic on the controller overlay during a drag."}, {"name": "hoverValue", "type": "Ref<number | null>", "descriptionKey": "components.media_scrubber.exposed.hover_value", "descriptionFallback": "The hovered track value while the cursor is over the scrubber. null when the cursor has left. Mirrors the hover emit."}], "playground": {"controls": [{"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.media_scrubber.playground.color", "defaultValue": "", "labelFallback": "Color / Intent"}, {"kind": "select", "prop": "rounded", "options": [{"label": "(default)", "value": ""}, {"label": "ROUNDED.X_SMALL", "value": "ROUNDED.X_SMALL"}, {"label": "x-small", "value": "x-small"}, {"label": "ROUNDED.SMALL", "value": "ROUNDED.SMALL"}, {"label": "small", "value": "small"}, {"label": "default", "value": "default"}, {"label": "ROUNDED.DEFAULT", "value": "ROUNDED.DEFAULT"}, {"label": "ROUNDED.MEDIUM", "value": "ROUNDED.MEDIUM"}, {"label": "medium", "value": "medium"}, {"label": "large", "value": "large"}, {"label": "ROUNDED.LARGE", "value": "ROUNDED.LARGE"}, {"label": "x-large", "value": "x-large"}, {"label": "ROUNDED.X_LARGE", "value": "ROUNDED.X_LARGE"}, {"label": "shaped", "value": "shaped"}, {"label": "ROUNDED.SHAPED", "value": "ROUNDED.SHAPED"}, {"label": "shaped-invert", "value": "shaped-invert"}, {"label": "ROUNDED.SHAPED_INVERT", "value": "ROUNDED.SHAPED_INVERT"}], "labelKey": "components.media_scrubber.playground.rounded", "defaultValue": "", "labelFallback": "Rounded"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.media_scrubber.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "switch", "prop": "showThumbOnHoverOnly", "labelKey": "components.media_scrubber.playground.show_thumb_on_hover_only", "defaultValue": false, "labelFallback": "Show Thumb On Hover Only"}, {"kind": "switch", "prop": "showHoverTooltip", "labelKey": "components.media_scrubber.playground.show_hover_tooltip", "defaultValue": false, "labelFallback": "Show Hover Tooltip"}]}, "previewVariants": []}', false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6120fd87-39a1-42c7-8fef-bbc8f9b94a7f', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'component', 'media-volume-control', 'MediaVolumeControl', 'Media', NULL, 'mdi-volume-high', 'components.catalog.media_volume_control.description', 'Mute / unmute toggle button with a vertical volume scrubber shown in a tooltip on hover.', NULL, NULL, 'origam-media-volume-control', NULL, NULL, 'origam', NULL, NULL, '/stories/?story=components-media-volume-control--design', '/docs/components/Media/OrigamMediaVolumeControl.html', 'media', '{"a11y": {"notes": [{"noteKey": "components.media_volume_control.a11y.aria_label_note", "noteFallback": "The toggle button''s aria-label switches between muteLabel and unmuteLabel to reflect the current state."}, {"noteKey": "components.media_volume_control.a11y.scrubber_note", "noteFallback": "The scrubber exposes aria-label (volumeLabel) and aria-valuetext (formatted percentage) for screen readers."}, {"noteKey": "components.media_volume_control.a11y.reduced_motion_note", "noteFallback": "The button scale transform on :active is the only animation — it respects prefers-reduced-motion by being a short (120ms) transition."}], "roles": ["button"], "keyboard": [{"key": "Enter / Space", "actionKey": "components.media_volume_control.a11y.key_toggle", "actionFallback": "Toggles mute/unmute on the icon button."}, {"key": "Arrow Up / Arrow Down", "actionKey": "components.media_volume_control.a11y.key_scrubber", "actionFallback": "Adjusts volume via the vertical scrubber (step 0.05)."}, {"key": "Tab", "actionKey": "components.media_volume_control.a11y.key_tab", "actionFallback": "Moves focus between the toggle button and the scrubber inside the tooltip."}]}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #f8f9fa)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"30\" width=\"200\" height=\"140\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <circle cx=\"128\" cy=\"100\" r=\"30\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"128\" y=\"104\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">icon</text>\n  <rect x=\"280\" y=\"20\" width=\"80\" height=\"160\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bgHover, #a855f7)\" stroke-width=\"1.5\"/>\n  <rect x=\"306\" y=\"40\" width=\"28\" height=\"120\" rx=\"4\" fill=\"var(--origam-color__surface---disabled, #e9d5ff)\"/>\n  <rect x=\"306\" y=\"100\" width=\"28\" height=\"60\" rx=\"4\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <circle cx=\"320\" cy=\"100\" r=\"8\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <circle cx=\"36\" cy=\"38\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"42.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"152\" cy=\"38\" r=\"10\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"152\" y=\"42.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"288\" cy=\"28\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"288\" y=\"32.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"320\" cy=\"28\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"320\" y=\"32.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <line x1=\"46\" y1=\"38\" x2=\"80\" y2=\"20\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"84\" y=\"18\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-tooltip</text>\n", "code": "<!-- tooltip wraps both the activator button and the volume panel -->\n<origam-tooltip location=\"top\" content-class=\"origam-media-volume-control__tooltip\">\n  <template #activator=\"{ props: activatorProps }\">\n    <!-- mute / unmute toggle -->\n    <button\n      type=\"button\"\n      class=\"origam-media-volume-control__btn\"\n      :aria-label=\"muted ? unmuteLabel : muteLabel\"\n      @click=\"onToggleMute\"\n    >\n      <origam-icon :icon=\"volumeIcon\" aria-hidden=\"true\" />\n    </button>\n  </template>\n\n  <!-- tooltip body: vertical scrubber -->\n  <div class=\"origam-media-volume-control__wrapper\">\n    <origam-media-scrubber\n      class=\"origam-media-volume-control__scrubber\"\n      orientation=\"vertical\"\n      :model-value=\"resolvedVolume\"\n      :max=\"1\"\n      :step=\"0.05\"\n      :aria-label=\"volumeLabel\"\n      @update:model-value=\"onVolumeFromScrubber\"\n    />\n  </div>\n</origam-tooltip>", "legend": [{"cls": ".origam-media-volume-control__btn", "num": 1, "descriptionKey": "components.media_volume_control.anatomy.btn", "descriptionFallback": "Icon-only <code>&lt;button&gt;</code> that triggers mute/unmute. Styled with <code>all: unset</code> and rounded with <code>border-radius: 50%</code>."}, {"cls": ".origam-icon (within __btn)", "num": 2, "descriptionKey": "components.media_volume_control.anatomy.icon", "descriptionFallback": "Volume icon that switches between VOLUME_OFF / VOLUME_LOW / VOLUME_MEDIUM / VOLUME_HIGH based on <code>volume</code> and <code>muted</code>."}, {"cls": ".origam-media-volume-control__wrapper", "num": 3, "descriptionKey": "components.media_volume_control.anatomy.wrapper", "descriptionFallback": "Container inside the tooltip — 14 × 80 px — that hosts the vertical scrubber."}, {"cls": ".origam-media-volume-control__scrubber", "num": 4, "descriptionKey": "components.media_volume_control.anatomy.scrubber", "descriptionFallback": "<code>&lt;origam-media-scrubber&gt;</code> in vertical orientation. <code>max=1</code>, <code>step=0.05</code>. Collapses to 0 when muted."}], "classes": [{"cls": "origam-media-volume-control__btn", "descriptionKey": "components.media_volume_control.anatomy.btn", "descriptionFallback": "Icon-only toggle button. Uses all:unset and 50% border-radius."}, {"cls": "origam-media-volume-control__tooltip", "descriptionKey": "components.media_volume_control.anatomy.tooltip", "descriptionFallback": "CSS class injected via content-class on the tooltip to style its inner panel."}, {"cls": "origam-media-volume-control__wrapper", "descriptionKey": "components.media_volume_control.anatomy.wrapper", "descriptionFallback": "Fixed-size (14 × 80 px) flex container for the vertical scrubber."}, {"cls": "origam-media-volume-control__scrubber", "descriptionKey": "components.media_volume_control.anatomy.scrubber", "descriptionFallback": "OrigamMediaScrubber instance in vertical orientation."}], "svgDesc": "Schematic of the MediaVolumeControl component with 4 numbered internal parts.", "svgTitle": "Anatomy of OrigamMediaVolumeControl", "rootClass": "origam-media-volume-control__btn", "figcaption": "Anatomy of <code>&lt;origam-media-volume-control&gt;</code> — 4 internal parts: the tooltip wrapper ①, the icon-only toggle button ②, the tooltip volume wrapper ③, and the vertical scrubber ④.", "svgViewBox": "0 0 700 200"}, "cssVars": [{"name": "--origam-media-volume-control---btn-size", "defaultValue": "36px", "descriptionKey": "components.media_volume_control.css_vars.btn_size", "descriptionFallback": "Width and height of the toggle button."}, {"name": "--origam-media-volume-control---btn-border-radius", "defaultValue": "50%", "descriptionKey": "components.media_volume_control.css_vars.btn_border_radius", "descriptionFallback": "Border radius of the toggle button (full circle by default)."}, {"name": "--origam-media-volume-control---color", "defaultValue": "inherit", "descriptionKey": "components.media_volume_control.css_vars.color", "descriptionFallback": "Foreground color of the icon button."}, {"name": "--origam-media-volume-control---hover-background-color", "defaultValue": "color-mix(in srgb, currentColor 12%, transparent)", "descriptionKey": "components.media_volume_control.css_vars.hover_background_color", "descriptionFallback": "Background color on hover and focus-visible."}, {"name": "--origam-media-volume-control---icon-size", "defaultValue": "20px", "descriptionKey": "components.media_volume_control.css_vars.icon_size", "descriptionFallback": "Font-size of the volume icon inside the button."}, {"name": "--origam-media-volume-control---tooltip-background-color", "defaultValue": "rgba(28, 28, 28, 0.92)", "descriptionKey": "components.media_volume_control.css_vars.tooltip_background_color", "descriptionFallback": "Background color of the tooltip content area containing the scrubber."}], "playground": {"controls": [{"kind": "number", "prop": "volume", "labelKey": "components.media_volume_control.playground.volume", "defaultValue": 0.8, "labelFallback": "Volume (0-1)"}, {"kind": "switch", "prop": "muted", "labelKey": "components.media_volume_control.playground.muted", "defaultValue": false, "labelFallback": "Muted"}]}, "previewVariants": []}', false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d361ab1c-412f-4f0e-96b0-51602e183db7', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'component', 'menu', 'Menu', 'Overlay & Surface', NULL, 'mdi-menu', 'components.catalog.menu.description', 'Floating contextual menu anchored to an activator element. Supports nested sub-menus, keyboard navigation, items array shorthand, and full slot customisation.', NULL, NULL, 'origam-menu', NULL, NULL, 'origam', NULL, NULL, '/stories/?story=components-menu--design', '/docs/components/Menu/OrigamMenu.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.menu.a11y.activator_note", "noteFallback": "The activator element receives aria-haspopup=\"menu\" and aria-expanded=\"true/false\" bound by the overlay. The menu id is referenced via aria-owns."}, {"noteKey": "components.menu.a11y.role_note", "noteFallback": "The menu panel has role=\"menu\". Each item should carry role=\"menuitem\" (provided automatically by OrigamListItem when inside a menu)."}, {"noteKey": "components.menu.a11y.focus_note", "noteFallback": "Focus is trapped inside the menu when open. On close, focus returns to the activator element."}], "roles": ["menu"], "keyboard": [{"key": "Escape", "actionKey": "components.menu.a11y.key_close", "actionFallback": "Closes the menu and returns focus to the activator."}, {"key": "ArrowDown", "actionKey": "components.menu.a11y.key_next_item", "actionFallback": "Moves focus to the next menu item."}, {"key": "ArrowUp", "actionKey": "components.menu.a11y.key_prev_item", "actionFallback": "Moves focus to the previous menu item."}, {"key": "Enter / Space", "actionKey": "components.menu.a11y.key_select", "actionFallback": "Activates the focused menu item."}, {"key": "Tab", "actionKey": "components.menu.a11y.key_tab", "actionFallback": "Closes the menu and moves focus to the next focusable element."}]}, "tokens": {"excerpt": [{"type": "color", "value": "{color.surface.raised}", "tokenPath": "menu.background", "descriptionKey": "components.menu.tokens.background", "descriptionFallback": "Menu panel background — inherits the raised surface token."}, {"type": "dimension", "value": "{radius.md}", "tokenPath": "menu.border-radius", "descriptionKey": "components.menu.tokens.border_radius", "descriptionFallback": "Border radius of the menu panel."}, {"type": "shadow", "value": "{shadow.lg}", "tokenPath": "menu.box-shadow", "descriptionKey": "components.menu.tokens.box_shadow", "descriptionFallback": "Drop shadow applied to the floating panel."}, {"type": "duration", "value": "{motion.duration.fast}", "tokenPath": "menu.transition-duration", "descriptionKey": "components.menu.tokens.transition_duration", "descriptionFallback": "Enter/leave animation duration."}, {"type": "number", "value": "{zIndex.dropdown}", "tokenPath": "menu.z-index", "descriptionKey": "components.menu.tokens.z_index", "descriptionFallback": "Stacking order of the floating menu panel."}, {"type": "dimension", "value": "320px", "tokenPath": "menu.content.max-width", "descriptionKey": "components.menu.tokens.content_max_width", "descriptionFallback": "Maximum width of the scrollable content inner area."}], "sourceFile": "packages/ds/tokens/component/menu.json", "pipelineNote": "Built with Style Dictionary v4 + @tokens-studio/sd-transforms. Outputs: CSS custom properties, SCSS variables, TypeScript types."}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"280\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"50\" y=\"20\" width=\"120\" height=\"36\" rx=\"4\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" opacity=\"0.9\"/>\n  <text x=\"110\" y=\"42\" font-size=\"10\" fill=\"#fff\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">Activator</text>\n  <rect x=\"50\" y=\"64\" width=\"280\" height=\"180\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(124,58,237,0.3))\" stroke-width=\"1.5\"/>\n  <rect x=\"60\" y=\"74\" width=\"260\" height=\"26\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\"/>\n  <text x=\"190\" y=\"91\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-menu__title (subheader)</text>\n  <rect x=\"60\" y=\"106\" width=\"260\" height=\"36\" rx=\"3\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\"/>\n  <text x=\"190\" y=\"128\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-menu__item (list-item)</text>\n  <rect x=\"60\" y=\"148\" width=\"260\" height=\"36\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.05))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\"/>\n  <text x=\"190\" y=\"170\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-menu__item (hover)</text>\n  <rect x=\"60\" y=\"190\" width=\"260\" height=\"36\" rx=\"3\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\"/>\n  <text x=\"190\" y=\"212\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-menu__item</text>\n  <circle cx=\"46\" cy=\"24\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"46\" y=\"28\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"46\" cy=\"68\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"46\" y=\"72\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"46\" cy=\"110\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"46\" y=\"114\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"46\" cy=\"152\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"46\" y=\"156\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"46\" cy=\"194\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"46\" y=\"198\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n", "code": "<origam-overlay role=\"menu\" v-model=\"isActive\">\n  <template #activator=\"{ props }\">\n    <slot name=\"activator\" v-bind=\"{ props }\"/>\n  </template>\n\n  <template #default>\n    <div class=\"origam-menu__content\">\n      <slot name=\"default\">\n        <origam-list class=\"origam-menu__list\">\n          <origam-list-subheader v-if=\"title\" class=\"origam-menu__title\">\n            {{ title }}\n          </origam-list-subheader>\n          <origam-list-group class=\"origam-menu__items\">\n            <origam-list-item\n              v-for=\"item in items\"\n              class=\"origam-menu__item\"\n              v-bind=\"item\"\n            />\n          </origam-list-group>\n        </origam-list>\n      </slot>\n    </div>\n  </template>\n</origam-overlay>", "legend": [{"cls": "#activator slot", "num": 1, "descriptionKey": "components.menu.anatomy.activator", "descriptionFallback": "The element that triggers the menu open/close. Receives an event-binding props object from the overlay."}, {"cls": ".origam-menu__list", "num": 2, "descriptionKey": "components.menu.anatomy.list", "descriptionFallback": "OrigamList container rendered inside the overlay panel (default slot fallback)."}, {"cls": ".origam-menu__title", "num": 3, "descriptionKey": "components.menu.anatomy.title", "descriptionFallback": "Optional OrigamListSubheader injected when the title prop is set."}, {"cls": ".origam-menu__items", "num": 4, "descriptionKey": "components.menu.anatomy.items", "descriptionFallback": "OrigamListGroup container iterating over the items array."}, {"cls": ".origam-menu__item", "num": 5, "descriptionKey": "components.menu.anatomy.item", "descriptionFallback": "Each OrigamListItem rendered from the items array. When an item has children, a nested OrigamMenu is rendered instead."}], "classes": [{"cls": "origam-menu", "descriptionKey": "components.menu.anatomy.root", "descriptionFallback": "Root class applied to the overlay element (role=\"menu\")."}, {"cls": "origam-menu__list", "descriptionKey": "components.menu.anatomy.list", "descriptionFallback": "OrigamList rendered as the default items container."}, {"cls": "origam-menu__title", "descriptionKey": "components.menu.anatomy.title", "descriptionFallback": "OrigamListSubheader rendered when title prop is set."}, {"cls": "origam-menu__items", "descriptionKey": "components.menu.anatomy.items", "descriptionFallback": "OrigamListGroup iterating over the items array."}, {"cls": "origam-menu__item", "descriptionKey": "components.menu.anatomy.item", "descriptionFallback": "Each OrigamListItem rendered per item in the items array."}], "svgDesc": "Schematic of the Menu component with 5 numbered parts.", "svgTitle": "Anatomy of OrigamMenu", "rootClass": "origam-menu", "figcaption": "Anatomy of <code>&lt;origam-menu&gt;</code> — 5 parts: activator (slot), content panel, optional title subheader, and list items (rendered from the items array or default slot).", "svgViewBox": "0 0 700 280"}, "cssVars": [{"name": "--origam-menu---background", "defaultValue": "{color.surface.raised}", "descriptionKey": "components.menu.css_vars.background", "descriptionFallback": "Menu panel background color."}, {"name": "--origam-menu---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.menu.css_vars.color", "descriptionFallback": "Menu text color."}, {"name": "--origam-menu---border-radius", "defaultValue": "{radius.md}", "descriptionKey": "components.menu.css_vars.border_radius", "descriptionFallback": "Border-radius of the menu panel."}, {"name": "--origam-menu---box-shadow", "defaultValue": "{shadow.lg}", "descriptionKey": "components.menu.css_vars.box_shadow", "descriptionFallback": "Drop shadow applied to the menu panel."}, {"name": "--origam-menu---max-height", "defaultValue": "calc(100vh - 32px)", "descriptionKey": "components.menu.css_vars.max_height", "descriptionFallback": "Maximum height before the menu becomes scrollable."}, {"name": "--origam-menu---z-index", "defaultValue": "{zIndex.dropdown}", "descriptionKey": "components.menu.css_vars.z_index", "descriptionFallback": "Z-index of the menu overlay panel."}, {"name": "--origam-menu---transition-duration", "defaultValue": "{motion.duration.fast}", "descriptionKey": "components.menu.css_vars.transition_duration", "descriptionFallback": "Enter/leave transition duration."}, {"name": "--origam-menu__content---padding", "defaultValue": "{space.1}", "descriptionKey": "components.menu.css_vars.content_padding", "descriptionFallback": "Inner padding of the menu content area."}, {"name": "--origam-menu__content---max-width", "defaultValue": "320px", "descriptionKey": "components.menu.css_vars.content_max_width", "descriptionFallback": "Maximum width of the menu content area."}], "playground": {"controls": [{"kind": "select", "prop": "location", "options": [{"label": "bottom", "value": "bottom"}, {"label": "top", "value": "top"}, {"label": "left", "value": "left"}, {"label": "right", "value": "right"}, {"label": "bottom start", "value": "bottom start"}, {"label": "bottom end", "value": "bottom end"}], "labelKey": "components.menu.playground.location", "defaultValue": "bottom", "labelFallback": "Location"}, {"kind": "switch", "prop": "closeOnContentClick", "labelKey": "components.menu.playground.close_on_content_click", "defaultValue": true, "labelFallback": "Close on content click"}, {"kind": "switch", "prop": "openOnHover", "labelKey": "components.menu.playground.open_on_hover", "defaultValue": false, "labelFallback": "Open on hover"}, {"kind": "select", "prop": "rounded", "options": [{"label": "(default)", "value": ""}, {"label": "sm", "value": "sm"}, {"label": "md", "value": "md"}, {"label": "lg", "value": "lg"}, {"label": "xl", "value": "xl"}], "labelKey": "components.menu.playground.rounded", "defaultValue": "", "labelFallback": "Rounded"}, {"kind": "select", "prop": "elevation", "options": [{"label": "(default)", "value": ""}, {"label": "0", "value": "0"}, {"label": "sm", "value": "sm"}, {"label": "md", "value": "md"}, {"label": "lg", "value": "lg"}], "labelKey": "components.menu.playground.elevation", "defaultValue": "", "labelFallback": "Elevation"}]}, "previewVariants": []}', false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c9f994e4-4266-4061-85f3-158aa80581cd', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'component', 'messages', 'Messages', 'Form & Input', NULL, 'mdi-message-text-outline', 'components.catalog.messages.description', 'Accessible live region that displays a list of validation or hint messages below form fields. Supports transitions, custom slot content, and full design token customisation.', NULL, NULL, 'origam-messages', NULL, NULL, 'origam', NULL, NULL, '/stories/?story=components-messages--design', '/docs/components/Messages/OrigamMessages.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.messages.a11y.live_region", "noteFallback": "The root element carries aria-live=\"polite\" and role=\"status\". Screen readers announce new messages without interrupting the current speech flow."}, {"noteKey": "components.messages.a11y.color_note", "noteFallback": "Color alone is never the sole indicator — message text is always visible. Ensure sufficient contrast ratio (≥4.5:1) when overriding the color prop."}], "roles": ["status"], "keyboard": []}, "tokens": {"excerpt": [{"type": "color", "value": "currentColor", "tokenPath": "messages.color", "descriptionKey": "components.messages.tokens.color", "descriptionFallback": "Inherits the field context color (error=danger, hint=info)."}, {"type": "dimension", "value": "12px", "tokenPath": "messages.font-size", "descriptionKey": "components.messages.tokens.font_size", "descriptionFallback": "Fixed 12 px per design spec."}, {"type": "dimension", "value": "14px", "tokenPath": "messages.min-height", "descriptionKey": "components.messages.tokens.min_height", "descriptionFallback": "Prevents layout collapse when messages array is empty."}, {"type": "duration", "value": "{motion.duration.normal}", "tokenPath": "messages.message.transition-duration", "descriptionKey": "components.messages.tokens.message_transition", "descriptionFallback": "Slide-y transition duration for individual message rows."}], "sourceFile": "packages/ds/tokens/component/messages.json", "pipelineNote": "Built with Style Dictionary v4 + @tokens-studio/sd-transforms."}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"180\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"30\" y=\"30\" width=\"640\" height=\"120\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(124,58,237,0.3))\" stroke-width=\"1.5\"/>\n  <rect x=\"50\" y=\"52\" width=\"580\" height=\"26\" rx=\"3\" fill=\"var(--origam-color__feedback--danger---bgSubtle, rgba(239,68,68,0.06))\"/>\n  <text x=\"340\" y=\"69\" font-size=\"9\" fill=\"var(--origam-color__feedback--danger---fg, #dc2626)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-messages__message — \"This field is required\"</text>\n  <rect x=\"50\" y=\"84\" width=\"580\" height=\"26\" rx=\"3\" fill=\"var(--origam-color__feedback--danger---bgSubtle, rgba(239,68,68,0.04))\"/>\n  <text x=\"340\" y=\"101\" font-size=\"9\" fill=\"var(--origam-color__feedback--danger---fg, #dc2626)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-messages__message — \"Must be a valid email\"</text>\n  <circle cx=\"26\" cy=\"34\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"26\" y=\"38\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"26\" cy=\"56\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"26\" y=\"60\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"26\" cy=\"88\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"26\" y=\"92\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n", "code": "<div\n  class=\"origam-messages\"\n  aria-live=\"polite\"\n  role=\"status\"\n>\n  <transition-group name=\"slide-y-transition\">\n    <div\n      v-for=\"message in normalizedMessages\"\n      :key=\"message\"\n      class=\"origam-messages__message\"\n    >\n      <slot :message=\"message\">{{ message }}</slot>\n    </div>\n  </transition-group>\n</div>", "legend": [{"cls": ".origam-messages", "num": 1, "descriptionKey": "components.messages.anatomy.root", "descriptionFallback": "Root container. Has aria-live=\"polite\" and role=\"status\" for screen-reader announcements."}, {"cls": ".origam-messages__message (row 1)", "num": 2, "descriptionKey": "components.messages.anatomy.message_1", "descriptionFallback": "First message row. Enters/leaves with the slide-y transition."}, {"cls": ".origam-messages__message (row n)", "num": 3, "descriptionKey": "components.messages.anatomy.message_n", "descriptionFallback": "Subsequent message rows — one per entry in the messages array."}], "classes": [{"cls": "origam-messages", "descriptionKey": "components.messages.anatomy.root", "descriptionFallback": "Root container — aria-live=\"polite\" + role=\"status\" live region."}, {"cls": "origam-messages__message", "descriptionKey": "components.messages.anatomy.message", "descriptionFallback": "Individual message row. One per string in the messages prop."}], "svgDesc": "Schematic of the Messages component with 3 numbered parts.", "svgTitle": "Anatomy of OrigamMessages", "rootClass": "origam-messages", "figcaption": "Anatomy of <code>&lt;origam-messages&gt;</code> — 3 parts: the root live-region container, and one <code>__message</code> row per entry in the messages array.", "svgViewBox": "0 0 700 180"}, "cssVars": [{"name": "--origam-messages---color", "defaultVa