INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('16c4defc-c211-4bd6-9040-8b700d91f5d6', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'component', 'qr-code', 'QrCode', 'Data Display', NULL, 'mdi-qrcode', 'components.catalog.qr_code.description', 'SSR-safe SVG QR code renderer with configurable error correction level, quiet zone, module corner radius, optional title, and a centred icon/image overlay. Accepts any text or URL via the value prop.', NULL, NULL, 'origam-qr-code', NULL, NULL, 'origam', NULL, NULL, '/stories/?story=components-qrcode--design', '/docs/components/QrCode/OrigamQrCode.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.qr_code.a11y.role_note", "noteFallback": "The root element has role=\"img\" and aria-label. When ariaLabel is not set, it falls back to \"QR code for {value}\". This ensures screen readers announce the purpose without exposing the raw URL twice."}, {"noteKey": "components.qr_code.a11y.center_note", "noteFallback": "The center overlay (icon, image, or #center slot) is marked aria-hidden=\"true\" since it is purely decorative — the aria-label on the root already conveys the full meaning."}, {"noteKey": "components.qr_code.a11y.error_level_note", "noteFallback": "When using a logo overlay, use errorCorrectionLevel=\"H\" (30% redundancy). Lower levels may make the code unscannable when modules are occluded by the overlay."}], "roles": ["img"], "keyboard": []}, "tokens": {"excerpt": [{"type": "color", "value": "{color.text.primary}", "tokenPath": "qrcode.foreground", "descriptionKey": "components.qr_code.tokens.foreground", "descriptionFallback": "Default dark module fill color."}, {"type": "color", "value": "{color.surface.default}", "tokenPath": "qrcode.background-color", "descriptionKey": "components.qr_code.tokens.background_color", "descriptionFallback": "Default quiet-zone background."}, {"type": "dimension", "value": "120px", "tokenPath": "qrcode.size-sm", "descriptionKey": "components.qr_code.tokens.size_sm", "descriptionFallback": "Small wrapper size."}, {"type": "dimension", "value": "240px", "tokenPath": "qrcode.size-md", "descriptionKey": "components.qr_code.tokens.size_md", "descriptionFallback": "Medium (default) wrapper size."}, {"type": "dimension", "value": "480px", "tokenPath": "qrcode.size-lg", "descriptionKey": "components.qr_code.tokens.size_lg", "descriptionFallback": "Large wrapper size."}, {"type": "dimension", "value": "0", "tokenPath": "qrcode.module.corner-radius", "descriptionKey": "components.qr_code.tokens.module_corner_radius", "descriptionFallback": "Default module corner radius (square). Set via qrCodeProps.rounded."}], "sourceFile": "packages/ds/tokens/component/qrcode.json", "pipelineNote": "Built with Style Dictionary v4 + @tokens-studio/sd-transforms. Module color and corner-radius are applied at SVG generation time via resolveQrColor / resolveQrCornerRadius utilities."}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"280\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"200\" y=\"20\" width=\"300\" height=\"240\" rx=\"8\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(124,58,237,0.3))\" stroke-width=\"1.5\"/>\n  <text x=\"350\" y=\"50\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #7c3aed)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-qr-code__title</text>\n  <rect x=\"220\" y=\"58\" width=\"260\" height=\"160\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\"/>\n  <text x=\"350\" y=\"135\" font-size=\"32\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" text-anchor=\"middle\">⬛</text>\n  <text x=\"350\" y=\"160\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #9ca3af)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-qr-code__svg-host</text>\n  <circle cx=\"350\" cy=\"120\" r=\"24\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(124,58,237,0.2))\" stroke-width=\"1\"/>\n  <text x=\"350\" y=\"125\" font-size=\"14\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" text-anchor=\"middle\">◆</text>\n  <text x=\"350\" y=\"235\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #9ca3af)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-qr-code__center (icon/image/#center slot)</text>\n  <circle cx=\"196\" cy=\"24\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"196\" y=\"28\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"196\" cy=\"50\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"196\" y=\"54\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"196\" cy=\"62\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"196\" y=\"66\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"324\" cy=\"100\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"324\" y=\"104\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"196\" cy=\"232\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"196\" y=\"236\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n", "code": "<div class=\"origam-qr-code\" role=\"img\" :aria-label=\"resolvedAriaLabel\">\n  <!-- optional title above the matrix -->\n  <div v-if=\"title\" class=\"origam-qr-code__title\">{{ title }}</div>\n\n  <!-- SVG host + center overlay -->\n  <div class=\"origam-qr-code__svg-host\">\n    <!-- inline SVG generated by qrcode-generator -->\n    <!-- v-html: the SVG string is sanitized and contains only geometric elements -->\n\n    <!-- centred overlay (icon / image / #center slot) -->\n    <div class=\"origam-qr-code__center\" aria-hidden=\"true\">\n      <slot name=\"center\" :size=\"centerSize\">\n        <origam-avatar\n          v-if=\"image\"\n          class=\"origam-qr-code__center-avatar\"\n        />\n        <origam-icon\n          v-else-if=\"icon\"\n          class=\"origam-qr-code__center-icon\"\n          :icon=\"icon\"\n        />\n      </slot>\n    </div>\n  </div>\n</div>", "legend": [{"cls": ".origam-qr-code", "num": 1, "descriptionKey": "components.qr_code.anatomy.root", "descriptionFallback": "Root wrapper element. Has role=\"img\" and aria-label. Applies wrapper-level color, bgColor, rounded, border, elevation, size, padding, margin."}, {"cls": ".origam-qr-code__title", "num": 2, "descriptionKey": "components.qr_code.anatomy.title", "descriptionFallback": "Optional heading rendered above the SVG. Only present when the title prop is set."}, {"cls": ".origam-qr-code__svg-host", "num": 3, "descriptionKey": "components.qr_code.anatomy.svg_host", "descriptionFallback": "Container div that hosts the inline SVG element and the center overlay. Manages the relative positioning context."}, {"cls": "inline SVG (matrix)", "num": 4, "descriptionKey": "components.qr_code.anatomy.svg", "descriptionFallback": "The QR matrix rendered as an inline SVG by qrcode-generator. Module color and corner radius are applied here from qrCodeProps."}, {"cls": ".origam-qr-code__center", "num": 5, "descriptionKey": "components.qr_code.anatomy.center", "descriptionFallback": "Absolutely centered overlay zone. Renders the icon (origam-qr-code__center-icon), image (origam-qr-code__center-avatar), or #center slot. aria-hidden=\"true\"."}], "classes": [{"cls": "origam-qr-code", "descriptionKey": "components.qr_code.anatomy.root", "descriptionFallback": "Root wrapper with role=\"img\"."}, {"cls": "origam-qr-code__title", "descriptionKey": "components.qr_code.anatomy.title", "descriptionFallback": "Optional title heading above the matrix."}, {"cls": "origam-qr-code__svg-host", "descriptionKey": "components.qr_code.anatomy.svg_host", "descriptionFallback": "SVG + center overlay container."}, {"cls": "origam-qr-code__center", "descriptionKey": "components.qr_code.anatomy.center", "descriptionFallback": "Absolutely centered overlay for icon/image/slot. aria-hidden=\"true\"."}, {"cls": "origam-qr-code__center-icon", "descriptionKey": "components.qr_code.anatomy.center_icon", "descriptionFallback": "OrigamIcon rendered at the center when icon prop is set."}, {"cls": "origam-qr-code__center-avatar", "descriptionKey": "components.qr_code.anatomy.center_avatar", "descriptionFallback": "OrigamAvatar rendered at the center when image prop is set."}], "svgDesc": "Schematic of the QrCode component with 5 numbered parts.", "svgTitle": "Anatomy of OrigamQrCode", "rootClass": "origam-qr-code", "figcaption": "Anatomy of <code>&lt;origam-qr-code&gt;</code> — 5 parts: wrapper root, optional title, SVG host, inline SVG matrix, and the centred overlay zone (#center slot).", "svgViewBox": "0 0 700 280"}, "cssVars": [{"name": "--origam-qrcode---foreground", "defaultValue": "{color.text.primary}", "descriptionKey": "components.qr_code.css_vars.foreground", "descriptionFallback": "Default module (dark square) fill color."}, {"name": "--origam-qrcode---background-color", "defaultValue": "{color.surface.default}", "descriptionKey": "components.qr_code.css_vars.background_color", "descriptionFallback": "Default quiet-zone and SVG background color."}, {"name": "--origam-qrcode---size-sm", "defaultValue": "120px", "descriptionKey": "components.qr_code.css_vars.size_sm", "descriptionFallback": "Wrapper width/height for size=\"small\"."}, {"name": "--origam-qrcode---size-md", "defaultValue": "240px", "descriptionKey": "components.qr_code.css_vars.size_md", "descriptionFallback": "Wrapper width/height for size=\"default\" (medium)."}, {"name": "--origam-qrcode---size-lg", "defaultValue": "480px", "descriptionKey": "components.qr_code.css_vars.size_lg", "descriptionFallback": "Wrapper width/height for size=\"large\"."}, {"name": "--origam-qrcode__module---corner-radius", "defaultValue": "0", "descriptionKey": "components.qr_code.css_vars.module_corner_radius", "descriptionFallback": "Per-module corner radius in module units. 0 = square, 0.5 = circle."}, {"name": "--origam-qrcode__logo---padding", "defaultValue": "{space.2}", "descriptionKey": "components.qr_code.css_vars.logo_padding", "descriptionFallback": "Pixel padding of the opaque backdrop drawn around the logo overlay."}], "playground": {"controls": [{"kind": "text", "prop": "value", "labelKey": "components.qr_code.playground.value", "defaultValue": "https://origam.dev", "labelFallback": "URL / text"}, {"kind": "select", "prop": "errorCorrectionLevel", "options": [{"label": "L (7%)", "value": "L"}, {"label": "M (15%)", "value": "M"}, {"label": "Q (25%)", "value": "Q"}, {"label": "H (30%)", "value": "H"}], "labelKey": "components.qr_code.playground.error_correction_level", "defaultValue": "M", "labelFallback": "Error correction"}, {"kind": "select", "prop": "size", "options": [{"label": "small (120px)", "value": "small"}, {"label": "default (240px)", "value": "default"}, {"label": "large (480px)", "value": "large"}], "labelKey": "components.qr_code.playground.size", "defaultValue": "default", "labelFallback": "Size"}, {"kind": "number", "prop": "quietZone", "labelKey": "components.qr_code.playground.quiet_zone", "defaultValue": 4, "labelFallback": "Quiet zone"}, {"kind": "select", "prop": "rounded", "options": [{"label": "(none)", "value": ""}, {"label": "sm", "value": "sm"}, {"label": "md", "value": "md"}, {"label": "lg", "value": "lg"}], "labelKey": "components.qr_code.playground.rounded", "defaultValue": "", "labelFallback": "Wrapper rounded"}, {"kind": "switch", "prop": "border", "labelKey": "components.qr_code.playground.border", "defaultValue": false, "labelFallback": "Border"}]}, "previewVariants": [{"label": "default", "props": {"value": "https://origam.dev"}, "ariaLabel": "QR code for origam.dev"}, {"label": "with icon", "props": {"icon": "mdi-vuejs", "value": "https://origam.dev", "errorCorrectionLevel": "H"}, "ariaLabel": "QR code with Vue icon overlay"}, {"label": "card", "props": {"value": "https://origam.dev", "border": true, "padding": "3", "rounded": "lg", "elevation": "sm"}, "ariaLabel": "QR code as card"}]}', false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d7f78c81-47e6-492e-9bce-8cd566e0ff4c', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'component', 'radio', 'Radio', 'Form & Input', NULL, 'mdi-radiobox-marked', 'components.catalog.radio.description', 'Single-selection radio control with label, error and focus state support. Wraps OrigamRadioBtn inside OrigamInput.', NULL, NULL, 'origam-radio', NULL, NULL, 'origam', NULL, NULL, '/stories/?story=components-radio--design', '/docs/components/Radio/OrigamRadio.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.radio.a11y.disabled_note", "noteFallback": "When disabled, aria-disabled=\"true\" is set on the native input. Pointer events are suppressed via CSS."}, {"noteKey": "components.radio.a11y.label_note", "noteFallback": "The label is associated with the input via the for/id pair managed by OrigamLabel. Clicking the label activates the control."}, {"noteKey": "components.radio.a11y.group_note", "noteFallback": "RadioGroup sets aria-labelledby and aria-describedby on the group container for screen-reader announcements."}], "roles": ["radio"], "keyboard": [{"key": "Space", "actionKey": "components.radio.a11y.key_space", "actionFallback": "Selects the radio when focused."}, {"key": "Tab", "actionKey": "components.radio.a11y.key_tab", "actionFallback": "Moves focus to the next interactive element."}, {"key": "Arrow keys (in group)", "actionKey": "components.radio.a11y.key_arrows", "actionFallback": "Navigates between radio options in a RadioGroup."}]}, "tokens": {"excerpt": [{"type": "dimension", "value": "20px", "tokenPath": "radio.input.size", "descriptionKey": "components.radio.tokens.input_size", "descriptionFallback": "Diameter of the circular radio input."}, {"type": "color", "value": "{color.border.default}", "tokenPath": "radio.input.border-color", "descriptionKey": "components.radio.tokens.input_border_color", "descriptionFallback": "Border color of the unchecked radio."}, {"type": "color", "value": "{color.action.primary.bg}", "tokenPath": "radio.input.border-color-checked", "descriptionKey": "components.radio.tokens.input_border_color_checked", "descriptionFallback": "Border color when checked."}, {"type": "dimension", "value": "10px", "tokenPath": "radio.dot.size", "descriptionKey": "components.radio.tokens.dot_size", "descriptionFallback": "Diameter of the inner selection dot."}, {"type": "color", "value": "{color.action.primary.bg}", "tokenPath": "radio.dot.background-color", "descriptionKey": "components.radio.tokens.dot_background_color", "descriptionFallback": "Fill color of the selection dot when checked."}, {"type": "duration", "value": "{motion.duration.fast}", "tokenPath": "radio.input.transition-duration", "descriptionKey": "components.radio.tokens.transition_duration", "descriptionFallback": "Transition duration for border and dot animations."}], "sourceFile": "packages/ds/tokens/component/radio.json", "pipelineNote": "Built with Style Dictionary v4 + @tokens-studio/sd-transforms."}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"480\" height=\"180\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"20\" width=\"440\" height=\"140\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\" stroke-dasharray=\"6 3\"/>\n  <circle cx=\"70\" cy=\"90\" r=\"30\" fill=\"none\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"2\"/>\n  <circle cx=\"70\" cy=\"90\" r=\"12\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <rect x=\"120\" y=\"78\" width=\"200\" height=\"24\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\"/>\n  <text x=\"220\" y=\"95\" font-size=\"12\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">Label text</text>\n  <circle cx=\"28\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"32\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"50\" cy=\"68\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"50\" y=\"72\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"70\" cy=\"58\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"70\" y=\"62\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"70\" cy=\"90\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"70\" y=\"94\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"130\" cy=\"68\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"130\" y=\"72\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n", "code": "<!-- root: OrigamInput wrapper -->\n<div class=\"origam-radio origam-input\">\n  <!-- SelectionControl owns the ripple zone + native input -->\n  <origam-radio-btn class=\"origam-radio-btn\">\n    <origam-selection-control class=\"origam-selection-control\" type=\"radio\">\n      <!-- input zone with ripple -->\n      <div class=\"origam-selection-control__input\">\n        <origam-icon :icon=\"trueIcon\" />   <!-- dot when checked -->\n        <input type=\"radio\" />\n      </div>\n      <!-- label -->\n      <div class=\"origam-selection-control__label\">\n        <origam-label />\n      </div>\n    </origam-selection-control>\n  </origam-radio-btn>\n</div>", "legen