INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5e8035dd-f910-40b0-8223-81275d0c832f', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'component', 'scale-rotate', 'ScaleRotate', 'Utilities & Providers', NULL, 'mdi-rotate-3d-variant', 'components.catalog.transition_scale_rotate.description', 'CSS-driven Vue transition that combines scale(0) + rotate(−45deg) + opacity on enter, with a symmetric leave. Sub-component of the Transition family.', NULL, NULL, 'origam-scale-rotate', NULL, NULL, 'origam', NULL, NULL, '/stories/?story=components-transition--design', '/docs/components/Transition/OrigamTransition.html', 'transition', '{"a11y": {"notes": [{"noteKey": "components.scale_rotate.a11y.reduced_motion", "noteFallback": "The transition is disabled automatically when prefers-reduced-motion: reduce is detected (disabled prop becomes true via useCssTransition)."}, {"noteKey": "components.scale_rotate.a11y.no_role", "noteFallback": "The wrapper is transparent to the accessibility tree. Only the slotted child is announced by screen readers."}], "roles": [], "keyboard": []}, "tokens": {"excerpt": [{"type": "duration", "value": "{motion.duration.medium}", "tokenPath": "transition.default.duration", "descriptionKey": "components.scale_rotate.tokens.duration", "descriptionFallback": "Default enter/leave duration shared by all transition sub-components."}, {"type": "cubicBezier", "value": "{motion.easing.standard}", "tokenPath": "transition.default.easing", "descriptionKey": "components.scale_rotate.tokens.easing", "descriptionFallback": "Default easing function (cubic-bezier)."}], "sourceFile": "packages/ds/tokens/component/transition.json", "pipelineNote": "Built with Style Dictionary v4 + @tokens-studio/sd-transforms."}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"180\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"40\" y=\"40\" width=\"260\" height=\"100\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"170\" y=\"86\" font-size=\"11\" fill=\"var(--origam-color__text---primary, #3b1c6e)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">enter-active</text>\n  <text x=\"170\" y=\"102\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">scale(0) rotate(−45deg) → full</text>\n  <rect x=\"400\" y=\"40\" width=\"260\" height=\"100\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\" stroke-dasharray=\"5 3\" opacity=\"0.5\"/>\n  <text x=\"530\" y=\"86\" font-size=\"11\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">leave-active</text>\n  <text x=\"530\" y=\"102\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">full → opacity 0</text>\n  <circle cx=\"48\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"48\" y=\"52\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"408\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"408\" y=\"52\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <text x=\"350\" y=\"95\" font-size=\"22\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" text-anchor=\"middle\">→</text>\n", "code": "<!-- wraps <transition> or <transition-group> via useCssTransition -->\n<component :is=\"tag\" :name=\"name\" v-bind=\"transitionProps\">\n  <slot name=\"default\" />\n</component>\n\n<!-- CSS keyframes (global, not scoped) -->\n<!-- .origam-transition--scale-rotate-enter-from { opacity: 0; transform: scale(0) rotate(-45deg); }\n     .origam-transition--scale-rotate-enter-active,\n     .origam-transition--scale-rotate-leave-active { transition-property: transform, opacity; transition-duration: 0.3s; } -->", "legend": [{"cls": ".origam-transition--scale-rotate-enter-active", "num": 1, "descriptionKey": "components.scale_rotate.anatomy.enter", "descriptionFallback": "Enter phase. Child animates from scale(0) rotate(−45deg) opacity:0 to identity. Duration: 0.3 s, easing: cubic-bezier(0.4,0,0.2,1)."}, {"cls": ".origam-transition--scale-rotate-leave-active", "num": 2, "descriptionKey": "components.scale_rotate.anatomy.leave", "descriptionFallback": "Leave phase. Child transitions opacity and transform out over 0.3 s."}], "classes": [{"cls": "origam-transition--scale-rotate", "descriptionKey": "components.scale_rotate.anatomy.class_root", "descriptionFallback": "CSS transition class prefix applied by Vue."}, {"cls": "origam-transition--scale-rotate-enter-from", "descriptionKey": "components.scale_rotate.anatomy.class_enter_from", "descriptionFallback": "Starting state: opacity:0, transform: scale(0) rotate(−45deg)."}, {"cls": "origam-transition--scale-rotate-enter-active", "descriptionKey": "components.scale_rotate.anatomy.class_enter_active", "descriptionFallback": "Transition active state for enter (0.3 s, standard easing)."}, {"cls": "origam-transition--scale-rotate-leave-active", "descriptionKey": "components.scale_rotate.anatomy.class_leave_active", "descriptionFallback": "Transition active state for leave (0.3 s)."}, {"cls": "origam-transition--scale-rotate-move", "descriptionKey": "components.scale_rotate.anatomy.class_move", "descriptionFallback": "Move transition applied in group mode (0.5 s, transform-only)."}], "svgDesc": "Schematic of the scale-rotate transition with entering and leaving elements.", "svgTitle": "Anatomy of OrigamScaleRotate", "rootClass": "origam-transition--scale-rotate", "figcaption": "Anatomy of <code>&lt;origam-scale-rotate&gt;</code> — wraps one child element. The enter ① animates from scale(0) + rotate(−45deg) + opacity:0 to full. The leave ② transitions opacity out over 0.3 s.", "svgViewBox": "0 0 700 180"}, "cssVars": [{"name": "--origam-transition---default-duration", "defaultValue": "{motion.duration.medium}", "descriptionKey": "components.scale_rotate.css_vars.duration", "descriptionFallback": "Default transition duration for the scale-rotate animation (0.3 s hardcoded in the CSS class, token reference for override)."}, {"name": "--origam-transition---default-easing", "defaultValue": "{motion.easing.standard}", "descriptionKey": "components.scale_rotate.css_vars.easing", "descriptionFallback": "Easing function: cubic-bezier(0.4, 0, 0.2, 1)."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.scale_rotate.exposed.filter_props", "descriptionFallback": "Forwards a filtered subset of props to the underlying transition."}], "playground": {"controls": [{"kind": "select", "prop": "mode", "options": [{"label": "(none)", "value": ""}, {"label": "in-out", "value": "in-out"}, {"label": "out-in", "value": "out-in"}], "labelKey": "components.scale_rotate.playground.mode", "defaultValue": "", "labelFallback": "Mode"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.scale_rotate.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "switch", "prop": "group", "labelKey": "components.scale_rotate.playground.group", "defaultValue": false, "labelFallback": "Group mode"}]}, "previewVariants": []}', false, NULL, NULL);
