INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('04993de9-478b-44ea-b075-38ece7b8e2a9', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'component', 'skeleton', 'Skeleton', 'Feedback & Status', NULL, 'mdi-shimmer', 'components.catalog.skeleton.description', 'Loading placeholder with animated pulse shimmer. Supports text, rectangular, circular, card and list-item variants. Renders real content via the default slot when loading=false.', NULL, NULL, 'origam-skeleton', NULL, NULL, 'origam', NULL, NULL, '/stories/?story=components-skeleton--design', '/docs/components/Skeleton/OrigamSkeleton.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.skeleton.a11y.role_note", "noteFallback": "Each skeleton block has role=\"status\", aria-busy=\"true\" and aria-label=\"Loading\". This ensures screen readers announce the loading state without repeating a full description."}, {"noteKey": "components.skeleton.a11y.reduced_motion_note", "noteFallback": "The pulse animation is disabled under prefers-reduced-motion: reduce. The skeleton remains visible as a static placeholder."}, {"noteKey": "components.skeleton.a11y.content_note", "noteFallback": "When loading=false, the skeleton is replaced by real content via the default slot. Ensure the revealed content is semantically correct (headings, alt text, etc.)."}], "roles": ["status"], "keyboard": []}, "tokens": {"excerpt": [{"type": "color", "value": "{color.surface.overlay}", "tokenPath": "skeleton.background-color", "descriptionKey": "components.skeleton.tokens.background_color", "descriptionFallback": "Base placeholder background color."}, {"type": "dimension", "value": "{radius.sm}", "tokenPath": "skeleton.border-radius", "descriptionK