INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4e970f40-1b7c-4970-8be8-c62de3b52470', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'component', 'slider-field', 'SliderField', 'Form & Input', NULL, 'mdi-tune-variant', 'components.catalog.slider_field.description', 'Range slider with thumb, track and tick marks. Supports range (dual-thumb), vertical orientation, and media-scrubber variants.', NULL, NULL, 'origam-slider-field', NULL, NULL, 'origam', NULL, NULL, '/stories/?story=components-sliderfield--design', '/docs/components/SliderField/OrigamSliderField.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.slider_field.a11y.range_note", "noteFallback": "The native <input type=\"range\"> owns keyboard and pointer math. aria-valuemin, aria-valuemax, aria-valuenow and aria-orientation are managed by the browser natively."}, {"noteKey": "components.slider_field.a11y.label_note", "noteFallback": "Pair with the label prop or an aria-label attribute to identify the slider purpose for screen readers."}, {"noteKey": "components.slider_field.a11y.range_dual_note", "noteFallback": "In range (dual-thumb) mode, each thumb is a separate <input type=\"range\">. Provide distinct aria-label values for the start and end thumbs."}], "roles": ["slider"], "keyboard": [{"key": "Arrow Left / Down", "actionKey": "components.slider_field.a11y.key_decrease", "actionFallback": "Decreases the value by one step."}, {"key": "Arrow Right / Up", "actionKey": "components.slider_field.a11y.key_increase", "actionFallback": "Increases the value by one step."}, {"key": "Home", "actionKey": "components.slider_field.a11y.key_home", "actionFallback": "Jumps to the minimum value."}, {"key": "End", "acti