INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('68395372-2554-42a7-aa1c-b7da5314dac0', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'component', 'tab', 'Tab', 'Navigation', NULL, 'mdi-tab', 'components.catalog.tab.description', 'Single registered tab inside an OrigamTabs tablist — renders the label text and optional leading/trailing icons.', NULL, NULL, 'origam-tab', NULL, NULL, 'origam', NULL, NULL, '/stories/?story=components-tabs--design', '/docs/components/Tabs/OrigamTabs.html', 'tabs', '{"a11y": {"notes": [{"noteKey": "components.tab.a11y.aria_note", "noteFallback": "OrigamTab wires role=\"tab\", aria-selected, aria-controls (pointing to the matching panel id) and aria-disabled automatically — no manual ARIA needed on the consumer side."}, {"noteKey": "components.tab.a11y.disabled_note", "noteFallback": "When disabled=true the tab gets aria-disabled=\"true\" and tabindex=-1; click events are swallowed via handleClick guard."}, {"noteKey": "components.tab.a11y.focus_note", "noteFallback": "Focus-visible outline is applied via :focus-visible pseudo-class (2px solid currentColor, outline-offset: -2px). Never shown on mouse click."}, {"noteKey": "components.tab.a11y.reduced_motion_note", "noteFallback": "The indicator transform transition should be disabled under prefers-reduced-motion: reduce via the consuming theme."}], "roles": ["tab"], "keyboard": [{"key": "Enter / Space", "actionKey": "components.tab.a11y.key_activate", "actionFallback": "Activates the tab (selects it in the group)."}, {"key": "ArrowLeft / ArrowRight", "actionKey": "components.tab.a11y.key_arrows", "actionFallback": "Moves focus to the previous / next tab in the tablist (roving tabindex managed by OrigamTabs)."}, {"key": "Tab", "actionKey": "components.tab.a11y.key_tab", "actionFallback": "Moves focus outside the tablist to the next focusable element (tabpanel)."}]}, "tokens": {"excerpt": [{"type": "color", "value": "{color.text.secondary}", "tokenPath": "tabs.item.color", "descriptionKey": "components.tab.tokens.item_color", "descriptionFallback": "Resting label color."}, {"type": "dimension", "value": "{space.12}", "tokenPath": "tabs.item.height", "descriptionKey": "components.tab.tokens.item_height", "descriptionFallback": "Minimum tab height."}, {"type": "fontWeight", "value": "{font.weight.medium}", "tokenPath": "tabs.item.font-weight", "descriptionKey": "components.tab.tokens.item_font_weight", "descriptionFallback": "Resting label font weight."}, {"type": "duration", "value": "{motion.duration.fast}", "tokenPath": "tabs.item.transition-duration", "descriptionKey": "components.tab.tokens.item_transition_duration", "descriptionFallback": "Transition duration for color and background changes."}, {"type": "color", "value": "{color.action.primary.bg}", "tokenPath": "tabs.indicator.color", "descriptionKey": "components.tab.tokens.indicator_color", "descriptionFallback": "Underline indicator color for variant=\"underline\"."}, {"type": "dimension", "value": "{border.width.2}", "tokenPath": "tabs.indicator.height", "descriptionKey": "components.tab.tokens.indicator_height", "descriptionFallback": "Thickness of the underline indicator."}], "sourceFile": "packages/ds/tokens/component/tabs.json", "pipelineNote": "Built with Style Dictionary v4 + @tokens-studio/sd-transforms. Tab-level tokens live under the tabs.item and tabs.indicator keys."}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"600\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"40\" y=\"52\" width=\"520\" height=\"80\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"60\" y=\"66\" width=\"80\" height=\"52\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\"/>\n  <text x=\"100\" y=\"95\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">icon</text>\n  <rect x=\"152\" y=\"66\" width=\"256\" height=\"52\" rx=\"3\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"280\" y=\"95\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">Label / #default slot</text>\n  <rect x=\"420\" y=\"66\" width=\"80\" height=\"52\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\"/>\n  <text x=\"460\" y=\"95\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">append icon</text>\n  <rect x=\"40\" y=\"128\" width=\"520\" height=\"4\" rx=\"0\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <circle cx=\"50\" cy=\"60\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"50\" y=\"64.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"88\" cy=\"74\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"88\" y=\"78\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"280\" cy=\"74\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"280\" y=\"78\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"448\" cy=\"74\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"448\" y=\"78\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"280\" cy=\"133\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"280\" y=\"137\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <line x1=\"50\" y1=\"48\" x2=\"80\" y2=\"28\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"84\" y=\"26\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-tab</text>\n  <text x=\"300\" y=\"175\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">② prepend · ③ label · ④ append — flex row; ⑤ indicator — abs bottom</text>\n", "code": "<!-- root button: role=\"tab\", aria-selected, aria-controls, tabindex -->\n<button class=\"origam-tab\" role=\"tab\">\n  <!-- leading icon (v-if=\"icon\") -->\n  <span class=\"origam-tab__prepend\">\n    <origam-icon :icon=\"icon\" />\n  </span>\n\n  <!-- label / #default slot -->\n  <span class=\"origam-tab__label\">\n    <slot name=\"default\">{{ text }}</slot>\n  </span>\n\n  <!-- trailing icon (v-if=\"appendIcon\") -->\n  <span class=\"origam-tab__append\">\n    <origam-icon :icon=\"appendIcon\" />\n  </span>\n\n  <!-- underline indicator (v-if=\"variant === ''underline''\") -->\n  <span class=\"origam-tab__indicator\" aria-hidden=\"true\" />\n</button>", "legend": [{"cls": ".origam-tab", "num": 1, "descriptionKey": "components.tab.anatomy.root", "descriptionFallback": "Root element. Renders as <code>&lt;button&gt;</code> by default. Carries <code>role=\"tab\"</code>, <code>aria-selected</code>, <code>aria-controls</code> and managed <code>tabindex</code>."}, {"cls": ".origam-tab__prepend", "num": 2, "descriptionKey": "components.tab.anatomy.prepend", "descriptionFallback": "Leading icon area. Rendered with <code>v-if=\"icon\"</code>. Wraps an <code>&lt;OrigamIcon&gt;</code>."}, {"cls": ".origam-tab__label", "num": 3, "descriptionKey": "components.tab.anatomy.label", "descriptionFallback": "Label zone. Contains the default slot (falls back to the <code>text</code> prop)."}, {"cls": ".origam-tab__append", "num": 4, "descriptionKey": "components.tab.anatomy.append", "descriptionFallback": "Trailing icon area. Rendered with <code>v-if=\"appendIcon\"</code>."}, {"cls": ".origam-tab__indicator", "num": 5, "descriptionKey": "components.tab.anatomy.indicator", "descriptionFallback": "Absolute underline indicator. Visible only when <code>variant=\"underline\"</code>. Scales from 0 → 1 on <code>--active</code> via CSS transform."}], "classes": [{"cls": "origam-tab", "descriptionKey": "components.tab.anatomy.root", "descriptionFallback": "Root element. Carries role=\"tab\", aria-selected, aria-controls, and tabindex."}, {"cls": "origam-tab--active", "descriptionKey": "components.tab.anatomy.active", "descriptionFallback": "Applied when this tab is the selected item in the tablist."}, {"cls": "origam-tab--disabled", "descriptionKey": "components.tab.anatomy.disabled", "descriptionFallback": "Applied when disabled=true. Sets cursor: not-allowed; pointer-events: none."}, {"cls": "origam-tab--with-prepend", "descriptionKey": "components.tab.anatomy.with_prepend", "descriptionFallback": "Applied when the icon prop is set (leading icon present)."}, {"cls": "origam-tab--with-append", "descriptionKey": "components.tab.anatomy.with_append", "descriptionFallback": "Applied when the appendIcon prop is set (trailing icon present)."}, {"cls": "origam-tab__prepend", "descriptionKey": "components.tab.anatomy.prepend", "descriptionFallback": "Leading icon wrapper. Only rendered when icon prop is provided."}, {"cls": "origam-tab__label", "descriptionKey": "components.tab.anatomy.label", "descriptionFallback": "Label zone containing the default slot content or text prop."}, {"cls": "origam-tab__append", "descriptionKey": "components.tab.anatomy.append", "descriptionFallback": "Trailing icon wrapper. Only rendered when appendIcon prop is provided."}, {"cls": "origam-tab__indicator", "descriptionKey": "components.tab.anatomy.indicator", "descriptionFallback": "Bottom indicator bar. Visible only in underline variant; scales on activation."}], "svgDesc": "Schematic of the Tab component with 4 numbered internal parts.", "svgTitle": "Anatomy of OrigamTab", "rootClass": "origam-tab", "figcaption": "Anatomy of <code>&lt;origam-tab&gt;</code> — 5 internal parts. The indicator (⑤) is absolute-positioned at the block-end and scales on activation.", "svgViewBox": "0 0 600 200"}, "cssVars": [{"name": "--origam-tabs__item---color", "defaultValue": "{color.text.secondary}", "descriptionKey": "components.tab.css_vars.color", "descriptionFallback": "Tab label color in resting state."}, {"name": "--origam-tabs__item---background-color", "defaultValue": "transparent", "descriptionKey": "components.tab.css_vars.background_color", "descriptionFallback": "Tab background in resting state."}, {"name": "--origam-tabs__item---height", "defaultValue": "48px", "descriptionKey": "components.tab.css_vars.height", "descriptionFallback": "Minimum tab height."}, {"name": "--origam-tabs__item---padding-inline", "defaultValue": "16px", "descriptionKey": "components.tab.css_vars.padding_inline", "descriptionFallback": "Horizontal padding of each tab."}, {"name": "--origam-tabs__item---padding-block", "defaultValue": "0", "descriptionKey": "components.tab.css_vars.padding_block", "descriptionFallback": "Vertical padding of each tab."}, {"name": "--origam-tabs__item---gap", "defaultValue": "8px", "descriptionKey": "components.tab.css_vars.gap", "descriptionFallback": "Gap between icon and label."}, {"name": "--origam-tabs__item---font-size", "defaultValue": "0.875rem", "descriptionKey": "components.tab.css_vars.font_size", "descriptionFallback": "Tab label font size."}, {"name": "--origam-tabs__item---font-weight", "defaultValue": "500", "descriptionKey": "components.tab.css_vars.font_weight", "descriptionFallback": "Tab label font weight."}, {"name": "--origam-tabs__item---letter-spacing", "defaultValue": "0.03125em", "descriptionKey": "components.tab.css_vars.letter_spacing", "descriptionFallback": "Tab label letter spacing."}, {"name": "--origam-tabs__item---border-radius", "defaultValue": "0", "descriptionKey": "components.tab.css_vars.border_radius", "descriptionFallback": "Tab border radius. Set to radius.full for pills variant."}, {"name": "--origam-tabs__item---transition-duration", "defaultValue": "0.2s", "descriptionKey": "components.tab.css_vars.transition_duration", "descriptionFallback": "Transition duration for color, background-color, border-color and transform."}, {"name": "--origam-tabs__item--active---color", "defaultValue": "currentColor", "descriptionKey": "components.tab.css_vars.active_color", "descriptionFallback": "Tab label color when active."}, {"name": "--origam-tabs__item--active---font-weight", "defaultValue": "600", "descriptionKey": "components.tab.css_vars.active_font_weight", "descriptionFallback": "Font weight applied to the active tab."}, {"name": "--origam-tabs__indicator---color", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.tab.css_vars.indicator_color", "descriptionFallback": "Color of the underline indicator bar (variant=\"underline\")."}, {"name": "--origam-tabs__indicator---height", "defaultValue": "2px", "descriptionKey": "components.tab.css_vars.indicator_height", "descriptionFallback": "Thickness of the underline indicator bar."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.tab.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "toggle", "type": "() => void", "descriptionKey": "components.tab.exposed.toggle", "descriptionFallback": "Toggles the selected state of this tab in the group."}, {"name": "select", "type": "(value: boolean) => void", "descriptionKey": "components.tab.exposed.select", "descriptionFallback": "Programmatically selects (true) or deselects (false) this tab."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.tab.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed tab styles."}, {"name": "id", "type": "string", "descriptionKey": "components.tab.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.tab.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.tab.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.tab.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "text", "prop": "text", "labelKey": "components.tab.playground.text", "defaultValue": "Tab label", "labelFallback": "Label text"}, {"kind": "select", "prop": "icon", "options": [{"label": "(none)", "value": ""}, {"label": "mdi-home", "value": "mdi-home"}, {"label": "mdi-magnify", "value": "mdi-magnify"}, {"label": "mdi-account", "value": "mdi-account"}, {"label": "mdi-star", "value": "mdi-star"}], "labelKey": "components.tab.playground.icon", "defaultValue": "", "labelFallback": "Leading icon"}, {"kind": "select", "prop": "appendIcon", "options": [{"label": "(none)", "value": ""}, {"label": "mdi-close", "value": "mdi-close"}, {"label": "mdi-chevron-right", "value": "mdi-chevron-right"}, {"labe