INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ef08173c-3d7e-429f-a535-24125210eb23', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'component', 'textarea-field', 'TextareaField', 'Form & Input', NULL, 'mdi-text-box-outline', 'components.catalog.textarea_field.description', 'Multi-line textarea with auto-grow, manual resize, counter, and an optional rich-text (contenteditable) mode with a formatting toolbar.', NULL, NULL, 'origam-textarea-field', NULL, NULL, 'origam', NULL, NULL, '/stories/?story=components-textareafield--design', '/docs/components/TextareaField/OrigamTextareaField.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.textarea_field.a11y.label_note", "noteFallback": "The label prop generates an <origam-label> with a for= attribute pointing to the textarea id. Always use label or aria-label to identify the field."}, {"noteKey": "components.textarea_field.a11y.rich_note", "noteFallback": "In rich mode the contenteditable div has role=\"textbox\" aria-multiline=\"true\". Toolbar buttons expose aria-pressed for toggle commands (bold, italic, etc.)."}, {"noteKey": "components.textarea_field.a11y.counter_note", "noteFallback": "When counter is set, the textarea has aria-describedby pointing to the counter element. Screen readers announce the remaining character count."}], "roles": ["textbox"], "keyboard": [{"key": "Tab", "actionKey": "components.textarea_field.a11y.key_tab", "actionFallback": "Focuses the textarea."}, {"key": "Shift+Tab", "actionKey": "components.textarea_field.a11y.key_shift_tab", "actionFallback": "Moves focus to the previous interactive element."}]}, "tokens": {"excerpt": [{"type": "number", "value": "{opacity.0}", "tokenPath": "textarea-field.textarea.opacity", "descriptionKey": "components.textarea_field.tokens.textarea_opacity", "descriptionFallback": "Initial textarea opacity (revealed on mount)."}, {"type": "duration", "value": "0.15s", "tokenPath": "textarea-field.textarea.transition-duration", "descriptionKey": "components.textarea_field.tokens.textarea_transition", "descriptionFallback": "Fade-in duration."}, {"type": "color", "value": "{color.border.subtle}", "tokenPath": "textarea-field.grip.border-color", "descriptionKey": "components.textarea_field.tokens.grip_border", "descriptionFallback": "Resize grip border color."}, {"type": "color", "value": "{color.surface.sunken}", "tokenPath": "textarea-field.rich-toolbar.bg-color", "descriptionKey": "components.textarea_field.tokens.toolbar_bg", "descriptionFallback": "Rich toolbar background."}, {"type": "dimension", "value": "{radius.md}", "tokenPath": "textarea-field.rich-toolbar.border-radius", "descriptionKey": "components.textarea_field.tokens.toolbar_radius", "descriptionFallback": "Rich toolbar border radius."}], "sourceFile": "packages/ds/tokens/component/textarea-field.json", "pipelineNote": "Built with Style Dictionary v4 + @tokens-studio/sd-transforms."}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"260\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"20\" width=\"644\" height=\"220\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"48\" y=\"58\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" font-family=\"''JetBrains Mono'',monospace\">Description</text>\n  <rect x=\"48\" y=\"68\" width=\"604\" height=\"36\" rx=\"3\" fill=\"var(--origam-color__surface---sunken, #f8f5ff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\"/>\n  <text x=\"60\" y=\"91\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" font-family=\"''JetBrains Mono'',monospace\">B  I  U  code  link  ≡  1. ▼H</text>\n  <rect x=\"48\" y=\"112\" width=\"604\" height=\"88\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.03))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\"/>\n  <text x=\"60\" y=\"140\" font-size=\"10\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" font-family=\"sans-serif\">Start typing rich content here…</text>\n  <rect x=\"628\" y=\"192\" width=\"16\" height=\"8\" rx=\"2\" fill=\"var(--origam-color__border---default, rgba(168,85,247,0.5))\"/>\n  <text x=\"400\" y=\"222\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"end\" font-family=\"''JetBrains Mono'',monospace\">0 / 500</text>\n  <circle cx=\"36\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"32.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"56\" cy=\"52\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"56\" y=\"56.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"56\" cy=\"64\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"56\" y=\"68.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"56\" cy=\"108\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"56\" y=\"112.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"636\" cy=\"192\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"636\" y=\"196.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <circle cx=\"408\" cy=\"218\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"408\" y=\"222.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">6</text>\n  <line x1=\"46\" y1=\"20\" x2=\"80\" y2=\"6\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"84\" y=\"6\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-textarea-field</text>\n", "legend": [{"cls": ".origam-textarea-field", "num": 1, "descriptionKey": "components.textarea_field.anatomy.root", "descriptionFallback": "Root element. Wraps the OrigamField chrome (label, messages, prepend/append)."}, {"cls": ".origam-field__label", "num": 2, "descriptionKey": "components.textarea_field.anatomy.label", "descriptionFallback": "OrigamLabel rendered above the input surface."}, {"cls": ".origam-rich-toolbar", "num": 3, "descriptionKey": "components.textarea_field.anatomy.toolbar", "descriptionFallback": "Formatting toolbar (rich mode only). Position top/bottom driven by toolbarPosition prop."}, {"cls": ".origam-textarea-field__surface", "num": 4, "descriptionKey": "components.textarea_field.anatomy.surface", "descriptionFallback": "The editing surface. In plain mode: a native <textarea>. In rich mode: a contenteditable div."}, {"cls": ".origam-textarea-field__grip", "num": 5, "descriptionKey": "components.textarea_field.anatomy.grip", "descriptionFallback": "Manual resize grip shown when noResize=false and autoGrow=false."}, {"cls": ".origam-textarea-field__counter", "num": 6, "descriptionKey": "components.textarea_field.anatomy.counter", "descriptionFallback": "Character counter shown when counter prop is set."}], "svgDesc": "Schematic of the TextareaField component with 6 numbered internal parts.", "svgTitle": "Anatomy of OrigamTextareaField", "rootClass": "origam-textarea-field", "figcaption": "Anatomy of <code>&lt;origam-textarea-field&gt;</code> — 6 internal parts: root ①, label ②, rich toolbar ③ (rich mode only), editing surface ④, resize grip ⑤, counter ⑥.", "svgViewBox": "0 0 700 260"}, "cssVars": [{"name": "--origam-textarea-field__textarea---opacity", "defaultValue": "0", "descriptionKey": "components.textarea_field.css_vars.textarea_opacity", "descriptionFallback": "Initial opacity of the textarea (revealed on activation to 1)."}, {"name": "--origam-textarea-field__textarea---opacity-active", "defaultValue": "1", "descriptionKey": "components.textarea_field.css_vars.textarea_opacity_active", "descriptionFallback": "Active textarea opacity."}, {"name": "--origam-textarea-field__textarea---transition-duration", "defaultValue": "0.15s", "descriptionKey": "components.textarea_field.css_vars.textarea_transition_duration", "descriptionFallback": "Fade-in duration for the textarea."}, {"name": "--origam-textarea-field__grip---border-color", "defaultValue": "{color.border.subtle}", "descriptionKey": "components.textarea_field.css_vars.grip_border_color", "descriptionFallback": "Border color of the resize grip handle."}, {"name": "--origam-textarea-field__grip---opacity", "defaultValue": "{opacity.26}", "descriptionKey": "components.textarea_field.css_vars.grip_opacity", "descriptionFallback": "Resting opacity of the grip handle."}, {"name": "--origam-textarea-field__rich-toolbar---bg-color", "defaultValue": "{color.surface.sunken}", "descriptionKey": "components.textarea_field.css_vars.toolbar_bg", "descriptionFallback": "Toolbar background (tinted vs. editor surface)."}, {"name": "--origam-textarea-field__rich-toolbar---border-color", "defaultValue": "{color.border.subtle}", "descriptionKey": "components.textarea_field.css_vars.toolbar_border", "descriptionFallback": "Toolbar border color."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.textarea_field.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.textarea_field.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.textarea_field.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.textarea_field.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.textarea_field.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.textarea_field.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "text", "prop": "label", "labelKey": "components.textarea_field.playground.label", "defaultValue": "Description", "labelFallback": "Label"}, {"kind": "text", "prop": "placeholder", "labelKey": "components.textarea_field.playground.placeholder", "defaultValue": "Enter text…", "labelFallback": "Placeholder"}, {"kind": "number", "prop": "rows", "labelKey": "components.textarea_field.playground.rows", "defaultValue": 4, "labelFallback": "Rows"}, {"kind": "switch", "prop": "autoGrow", "labelKey": "components.textarea_field.playground.auto_grow", "defaultValue": false, "labelFallback": "Auto-grow"}, {"kind": "switch", "prop": "noResize", "labelKey": "components.textarea_field.playground.no_resize", "defaultValue": false, "labelFallback": "No resize"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.textarea_field.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "switch", "prop": "readonly", "labelKey": "components.textarea_field.playground.readonly", "defaultValue": false, "labelFallback": "Readonly"}]}, "previewVariants": []}', false, NULL, NULL);
