INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6b9f2030-9742-495e-93f6-d0264d8d851b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'const', 'border-radius-regex', 'BORDER_RADIUS_REGEX', 'Layout & Sizing', NULL, NULL, 'consts.catalog.border_radius_regex.description', 'Regular expression used to detect a free-form CSS border-radius string passed via the rounded prop. Accepts 1–4 values with standard CSS length units or a unit-less 0. Non-matching values fall through to the named-variant or boolean branches of useRounded.', 'export const BORDER_RADIUS_REGEX = /^(?<radius>(?: ?(?:0|(?:[0-9]+(?:\.[0-9]+)?)(?:px|pt|PC|in|cm|mm|em|rem|%|ex|ch|fr))){0,4})$/', NULL, NULL, '/^(?<radius>(?: ?(?:0|(?:[0-9]+(?:\.[0-9]+)?)(?:px|pt|PC|in|cm|mm|em|rem|%|ex|ch|fr))){0,4})$/', 'packages/ds/src/consts/Commons/rounded.const.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ad08556a-ceae-40ab-98c1-c6ad81ace027', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'const', 'border-regex', 'BORDER_REGEX', 'Layout & Sizing', NULL, NULL, 'consts.catalog.border_regex.description', 'Regular expression that parses a free-form border shorthand value into named capture groups: width, style, and color. Supports hex literals, CSS functions (rgb/hsl/rgba), CSS custom properties (var(--…)), and named keywords. The var() alternative is placed before the bare [A-Za-z]+ branch to avoid eating "var" as a keyword.', 'export const BORDER_REGEX = /^(?<width>(?: ?(?:[0-9]+)(?:px|pt|PC|in|cm|mm|em|rem|%|ex|ch|fr)?){0,4}) {0,1}(?<style>(?:(?: ?(?:none|hidden|dotted|dashed|solid|double|groove|ridge|inset|outset))+){0,4}) ?(?<color>(?: ?(?:(?:(?:#)(?:[a-f0-9]{3}|[a-f0-9]{6}))|(?:var\(--[^)]+\))|(?:(?:rgb|hsl|rgba)a?\(.*\))|(?:[A-Za-z]+))){0,4})$/', NULL, NULL, '/^(?<width>(?: ?(?:[0-9]+)(?:px|pt|PC|in|cm|mm|em|rem|%|ex|ch|fr)?){0,4}) {0,1}(?<style>(?:(?: ?(?:none|hidden|dotted|dashed|solid|double|groove|ridge|inset|outset))+){0,4}) ?(?<color>(?: ?(?:(?:(?:#)(?:[a-f0-9]{3}|[a-f0-9]{6}))|(?:var\(--[^)]+\))|(?:(?:rgb|hsl|rgba)a?\(.*\))|(?:[A-Za-z]+))){0,4})$/', 'packages/ds/src/consts/Commons/border.const.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('839df156-fed6-46ac-a76e-3b32d5197193', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'const', 'bracket-default-losers-label', 'BRACKET_DEFAULT_LOSERS_LABEL', 'Data Display', NULL, NULL, 'consts.catalog.bracket_default_losers_label.description', 'Default heading rendered above the loser-bracket tree in a double-elimination layout. Override via the losersLabel prop (e.g. to localise). Kept as a literal in withDefaults, mirrored here for consumer reference.', 'export const BRACKET_DEFAULT_LOSERS_LABEL = ''Losers bracket''', NULL, NULL, '''Losers bracket''', 'packages/ds/src/consts/Bracket/bracket.const.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
