INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c630d8ed-25fc-4b57-b026-6316f6323a55', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'const', 'built-in-patterns', 'BUILT_IN_PATTERNS', 'Form & Input', NULL, NULL, 'consts.catalog.built_in_patterns.description', 'Curated mask presets map (name → { pattern, validator }). Covers common formats: French/US/international phone, IBAN, SIRET, credit card, ISO date, FR/US date, time, and postal codes.', 'export const BUILT_IN_PATTERNS: Record<TBuiltInPattern, IMaskOptions> = {
    [BUILT_IN_PATTERN.PHONE_FR]: {
        pattern: ''## ## ## ## ##'',
        validator: null
    },
    [BUILT_IN_PATTERN.PHONE_US]: {
        pattern: ''(###) ###-####'',
        validator: null
    },
    [BUILT_IN_PATTERN.PHONE_INTERNATIONAL]: {
        pattern: ''+## ## ## ## ## ##'',
        validator: null
    },
    [BUILT_IN_PATTERN.IBAN]: {
        // IBAN max length is 34, FR is 27, EN is 22.
        // Pattern accepts up to 34 alphanumeric chars in
        // 4-char blocks. The `validator` enforces the
        // mod-97 checksum on the unmasked value.
        pattern: ''**** **** **** **** **** **** ****  **'',
        validator: PATTERN_VALIDATOR.IBAN
    },
    [BUILT_IN_PATTERN.SIRET]: {
        pattern: ''### ### ### #####'',
        validator: null
    },
    [BUILT_IN_PATTERN.CREDIT_CARD]: {
        pattern: ''#### #### #### ####'',
        validator: PATTERN_VALIDATOR.LUHN
    },
    [BUILT_IN_PATTERN.DATE_ISO]: {
        pattern: ''####-##-##'',
        validator: PATTERN_VALIDATOR.DATE_ISO
    },
    [BUILT_IN_PATTERN.DATE_FR]: {
        pattern: ''##/##/####'',
        validator: PATTERN_VALIDATOR.DATE_FR
    },
    [BUILT_IN_PATTERN.DATE_US]: {
        pattern: ''##/##/####'',
        validator: PATTERN_VALIDATOR.DATE_US
    },
    [BUILT_IN_PATTERN.TIME]: {
        pattern: ''##:##'',
        validator: null
    },
    [BUILT_IN_PATTERN.TIME_12H]: {
        pattern: ''##:## AA'',
        validator: null
    },
    [BUILT_IN_PATTERN.POSTCODE_FR]: {
        pattern: ''#####'',
        validator: null
    },
    [BUILT_IN_PATTERN.POSTCODE_US]: {
        pattern: ''#####'',
        validator: null
    }
}', NULL, NULL, NULL, 'packages/ds/src/consts/Mask/built-in-patterns.const.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
