INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a81ba0ff-1cd0-438c-87bc-a2702a7f277a', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'const', 'cielab-forward-transform', 'CIELAB_FORWARD_TRANSFORM', 'Color', NULL, NULL, 'consts.catalog.cielab_forward_transform.description', 'CIELAB forward transfer function f(t). Converts a linearised XYZ tristimulus value to the CIE L*a*b* cube-root compressed domain. Threshold determined by COLOR_DELTA (6÷29).', 'export const CIELAB_FORWARD_TRANSFORM = (t: number): number => (
    t > COLOR_DELTA ** 3
        ? Math.cbrt(t)
        : (t / (3 * COLOR_DELTA ** 2)) + 4 / 29
)', NULL, NULL, '(t: number): number => ( t > COLOR_DELTA ** 3 ? Math.cbrt(t) : (t / (3 * COLOR_DELTA ** 2)) + 4 / 29 )', 'packages/ds/src/consts/Commons/color.const.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c4115490-3bd1-4f4b-b769-388e7b758c19', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'const', 'cielab-reverse-transform', 'CIELAB_REVERSE_TRANSFORM', 'Color', NULL, NULL, 'consts.catalog.cielab_reverse_transform.description', 'CIELAB reverse transfer function f⁻¹(t). Converts a CIE L*a*b* cube-root-compressed value back to a linearised XYZ tristimulus. Threshold determined by COLOR_DELTA (6÷29).', 'export const CIELAB_REVERSE_TRANSFORM = (t: number): number => (
    t > COLOR_DELTA
        ? t ** 3
        : (3 * COLOR_DELTA ** 2) * (t - 4 / 29)
)', NULL, NULL, '(t: number): number => ( t > COLOR_DELTA ? t ** 3 : (3 * COLOR_DELTA ** 2) * (t - 4 / 29) )', 'packages/ds/src/consts/Commons/color.const.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('30f4e9ae-0500-44c5-96c7-9b315b1b509f', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'const', 'circumference', 'CIRCUMFERENCE', 'Components', NULL, NULL, 'consts.catalog.circumference.description', 'SVG circle circumference (2π × MAGIC_RADIUS) used by OrigamProgress circular mode to compute stroke-dasharray and stroke-dashoffset for the progress arc.', 'export const CIRCUMFERENCE = 2 * Math.PI * MAGIC_RADIUS', NULL, NULL, '2 * Math.PI * MAGIC_RADIUS', 'packages/ds/src/consts/Progress/progress.const.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
