INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e1567046-3cc0-44f8-8713-34c39ee677f0', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'const', 'custom-border-radius-regex', 'CUSTOM_BORDER_RADIUS_REGEX', 'Layout & Sizing', NULL, NULL, 'consts.catalog.custom_border_radius_regex.description', 'Regex that detects free-form CSS border-radius values not covered by the fixed-unit BORDER_RADIUS_REGEX whitelist: custom-property references (var(…)), CSS math functions (calc/clamp/min/max/env), and single lengths with viewport or advanced units (vw, vh, lh, …). Mirrors the convertToUnit escape hatch used by useDimension.', 'export const CUSTOM_BORDER_RADIUS_REGEX = /^(?:var|calc|clamp|min|max|env)\(.*\)$|^-?(?:0|[0-9]*\.?[0-9]+)(?:px|pt|pc|in|cm|mm|q|em|rem|ex|ch|cap|ic|lh|rlh|vw|vh|vi|vb|vmin|vmax|%)$/i', NULL, NULL, '/^(?:var|calc|clamp|min|max|env)\(.*\)$|^-?(?:0|[0-9]*\.?[0-9]+)(?:px|pt|pc|in|cm|mm|q|em|rem|ex|ch|cap|ic|lh|rlh|vw|vh|vi|vb|vmin|vmax|%)$/i', 'packages/ds/src/consts/Commons/rounded.const.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
