    grid:                 ''display: grid'',
    subgrid:              ''grid-template-columns: subgrid'',
    flexGap:              ''gap: 1px'',
    containerQueries:     ''(container-type: inline-size)'',
    has:                  ''selector(:has(*))'',
    aspectRatio:          ''aspect-ratio: 1'',
    colorMix:             ''color: color-mix(in srgb, red, blue)'',
    accentColor:          ''accent-color: red'',
    minMaxClamp:          ''width: min(10px, 20px)'',
    mathFunctions:        ''width: calc(min(10px, 20px) + max(5px, 8px))'',
    anchorPositioning:    ''anchor-name: --foo'',
    scrollDrivenAnims:    ''animation-timeline: scroll()'',
    viewTransitions:      ''view-transition-name: foo'',
    nestedSelectors:      ''selector(& > a)'',
    individualTransforms: ''translate: 1px 1px'',
    logicalProperties:    ''margin-inline: 1px'',
    backdropFilter:       ''backdrop-filter: blur(1px)'',
    fieldSizing:          ''field-sizing: content'',
    textWrapBalance:      ''text-wrap: balance'',
    contentVisibility:    ''content-visibility: auto'',
    masonry:              ''grid-template-rows: masonry''
} as const satisfies Record<string, string>', NULL, NULL, '{ grid: ''display: grid'', subgrid: ''grid-template-columns: subgrid'', flexGap: ''gap: 1px'', containerQueries: ''(container-type: inline-size)'', has: ''selector(:has(*))'', aspectRatio: ''aspect-ratio: 1'', colorMix: ''color: color-mix(in srgb, red, blue)'', accentColor: ''accent-color: red'', minMaxClamp: ''width: min(10px, 20px)'', mathFunctions: ''width: calc(min(10px, 20px) + max(5px, 8px))'', anchorPositioning: ''anchor-name: --foo'', scrollDrivenAnims: ''animation-timeline: scroll()'', viewTransitions: ''view-transition-name: foo'', nestedSelectors: ''selector(& > a)'', individualTransforms: ''translate: 1px 1px'', logicalProperties: ''margin-inline: 1px'', backdropFilter: ''backdrop-filter: blur(1px)'', fieldSizing: ''field-sizing: content'', textWrapBalance: ''text-wrap: balance'', contentVisibility: ''content-visibility: auto'', masonry: ''grid-template-rows: masonry'' } as const satisfies Record<string, string>', 'packages/ds/src/consts/CssSupport/css-support.const.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
