INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d0ce30f5-beae-4e29-af21-4908dd88e8e5', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'const', 'hover', 'HOVER', 'Internals', NULL, NULL, 'consts.catalog.hover.description', 'Handler object used internally by the v-hover directive. Exposes show() and hide() methods that add or remove the configured CSS class on the target element when hover state changes.', 'export const HOVER = {
    show (
        _e: THoverEvent,
        el: IHoverHtmlElement,
        value: IHoverOptions
    ) {
        if (!el?._hover?.enabled) {
            return
        }

        el.classList.add(value.class)
    },

    hide (el: IHoverHtmlElement | null, value: IHoverOptions) {
        if (!el?._hover?.enabled) return

        el.classList.remove(value.class)
    }
}', NULL, NULL, NULL, 'packages/ds/src/consts/Commons/hover.const.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
