INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a9722b30-52a9-4f87-9ffa-f0c9295330f1', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'const', 'list-open-strategy', 'LIST_OPEN_STRATEGY', 'Navigation & Disclosure', NULL, NULL, 'consts.catalog.list_open_strategy.description', 'Open strategy for list-style navigation (e.g. OrigamList). Uses MULTIPLE_OPEN_STRATEGY for opening and a custom select handler that closes all siblings not on the path from the selected item to the root.', 'export const LIST_OPEN_STRATEGY: TStrategyOpen = {
    open: MULTIPLE_OPEN_STRATEGY.open,
    select: ({id, value, opened, parents}) => {
        if (!value) return opened

        const path: Array<unknown> = []

        let parent = parents.get(id)

        while (parent != null) {
            path.push(parent)
            parent = parents.get(parent)
        }

        return new Set(path)
    }
}', NULL, NULL, NULL, 'packages/ds/src/consts/Commons/nested.const.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
