INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8d9ea4f9-60b2-4d88-baef-71dc5a01ae9c', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'const', 'mdi', 'MDI', 'Icons', NULL, NULL, 'consts.catalog.mdi.description', 'The Material Design Icons icon set adapter for Origam. Implements IIconSet by rendering OrigamClassIcon with the mdi CSS class. Normalises bare icon names (magnify) and already-prefixed names (mdi-magnify) to always emit mdi-{name}. Pass this constant to the icons option when installing Origam.', 'export const MDI: IIconSet = {
    // The MDI font CSS exposes each glyph as `.mdi-<name>` (e.g. `.mdi-magnify`).
    // Consumers may pass either the bare name (`magnify`) — as is the case when
    // an `mdi:` prefix has been stripped by the icon resolver — or the already-
    // prefixed form (`mdi-magnify`, as found in MDI_ALIASES below). We
    // normalise to always emit the `mdi-` class so the font renders.
    component: (props: any) => h(OrigamClassIcon, {
        ...props,
        icon: typeof props.icon === ''string'' && !props.icon.startsWith(''mdi-'')
            ? `mdi-${props.icon}`
            : props.icon,
        class: ''mdi''
    })
}', NULL, NULL, NULL, 'packages/ds/src/consts/Icon/mdi.const.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
