    checkboxOff: ''mdi-checkbox-blank-outline'',
    checkboxIndeterminate: ''mdi-minus-box'',
    delimiter: ''mdi-circle'',
    sortAsc: ''mdi-arrow-up'',
    sortDesc: ''mdi-arrow-down'',
    expand: ''mdi-chevron-down'',
