INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('197d28c7-b287-47a3-bfeb-e17a22958a0f', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'const', 'multiple-open-strategy', 'MULTIPLE_OPEN_STRATEGY', 'Navigation & Disclosure', NULL, NULL, 'consts.catalog.multiple_open_strategy.description', 'Open strategy that allows any number of nested items to be expanded simultaneously. When opening an item all its ancestors are also opened; when closing only the targeted item is removed from the opened set. Contrast with SINGLE_OPEN_STRATEGY which collapses siblings. Used by OrigamList, OrigamTreeview and any nested component.', 'export const MULTIPLE_OPEN_STRATEGY: TStrategyOpen = {
    open: ({id, value, opened, parents}) => {
        if (value) {
            let parent = parents.get(id)
            opened.add(id)

            while (parent != null && parent !== id) {
                opened.add(parent)
                parent = parents.get(parent)
            }

            return opened
        } else {
            opened.delete(id)
        }

        return opened
    },
    select: () => null
}', NULL, NULL, NULL, 'packages/ds/src/consts/Commons/nested.const.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
