INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8f5b3d82-5883-40dd-8f87-f09ecebc687c', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'const', 'ripples', 'RIPPLES', 'Interaction & Animation', NULL, NULL, 'consts.catalog.ripples.description', 'Low-level ripple controller used internally by v-ripple. Exposes show() and hide() methods that create, animate, and remove the ripple DOM elements on the target element.', 'export const RIPPLES = {

    show (
        e: TRippleEvent,
        el: IRippleHtmlElement,
        value: IRippleOptions = {}
    ) {
        if (!el?._ripple?.enabled) {
            return
        }

        const container = document.createElement(''span'')
        const animation = document.createElement(''span'')

        container.appendChild(animation)
        container.className = ''origam-ripple__container''

        if (value.class) {
            container.className += ` ${value.class}`
        }

        const {radius, scale, x, y, centerX, centerY} = calculate(e, el, value)

        const size = `${radius * 2}px`
        animation.className = ''origam-ripple__animation''
        animation.style.width = size
        animation.style.height = size

        el.appendChild(container)

        const computed = window.getComputedStyle(el)
        if (computed && computed.position === ''static'') {
            el.style.position = ''relative''
            el.dataset.previousPosition = ''static''
        }

        animation.classList.add(''origam-ripple__animation--enter'')
        animation.classList.add(''origam-ripple__animation--visible'')
        rippleTransform(animation, `translate(${x}, ${y}) scale3d(${scale},${scale},${scale})`)
        animation.dataset.activated = String(performance.now())

        setTimeout(() => {
            animation.classList.remove(''origam-ripple__animation--enter'')
            animation.classList.add(''origam-ripple__animation--in'')
            rippleTransform(animation, `translate(${centerX}, ${centerY}) scale3d(1,1,1)`)
        }, 0)
    },

    hide (el: IRippleHtmlElement | null) {
        if (!el?._ripple?.enabled) return

        const ripples = el.getElementsByClassName(''origam-ripple__animation'')

        if (ripples.length === 0) return
        const animation: IRippleElement = ripples[ripples.length - 1]

        if (animation.dataset?.isHiding) return
        else animation.dataset!.isHiding = ''true''

        const diff = performance.now() - Number(animation.dataset!.activated)
        const delay = Math.max(250 - diff, 0)

        setTimeout(() => {
            animation.classList.remove(''origam-ripple__animation--in'')
            animation.classList.add(''origam-ripple__animation--out'')

            setTimeout(() => {
                const ripples = el.getElementsByClassName(''origam-ripple__animation'')
                if (ripples.length === 1 && el.dataset.previousPosition) {
                    el.style.position = el.dataset.previousPosition
                    delete el.dataset.previousPosition
                }

                if (animation.parentNode?.parentNode === el) el.removeChild(animation.parentNode)
            }, 300)
        }, delay)
    }
}', NULL, NULL, NULL, 'packages/ds/src/consts/Commons/ripple.const.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
