INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6759d894-5804-4f0b-8733-53d2d0bd2633', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'const', 'sheet-fast-flick-threshold', 'SHEET_FAST_FLICK_THRESHOLD', 'Interaction & Gestures', NULL, NULL, 'consts.catalog.sheet_fast_flick_threshold.description', 'Velocity threshold (in pixels per millisecond) above which a swipe release on a BottomSheet is treated as a "fast flick". When exceeded, the sheet snaps one step in the direction of motion instead of snapping to the nearest position by distance. 0.5 px/ms ≈ a 200 px swipe in 400 ms.', 'export const SHEET_FAST_FLICK_THRESHOLD = 0.5', NULL, NULL, '0.5', 'packages/ds/src/consts/Sheet/sheet-swipe.const.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('424e220c-5665-45ff-98bf-a6fa56d99ba0', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'const', 'single-open-strategy', 'SINGLE_OPEN_STRATEGY', 'Overlay & Positioning', NULL, NULL, 'consts.catalog.single_open_strategy.description', 'Nested-open strategy that enforces a single-open-at-a-time policy: opening a node closes any previously open sibling, while parents of the newly opened node are kept open. The `select` hook is a no-op (returns null). Used as the default strategy for ExpansionPanel.', 'export const SINGLE_OPEN_STRATEGY: TStrategyOpen = {
    open: ({id, value, opened, parents}) => {
        if (value) {
            const newOpened = new Set<unknown>()
            newOpened.add(id)

            let parent = parents.get(id)

            while (parent != null) {
                newOpened.add(parent)
                parent = parents.get(parent)
            }

            return newOpened
        } else {
            opened.delete(id)
            return opened
        }
    },
    select: () => null
}', NULL, NULL, NULL, 'packages/ds/src/consts/Commons/nested.const.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('51ba7907-9502-4a7c-a45a-4bce0f854d7d', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'const', 'sizes-array', 'SIZES_ARRAY', 'Layout & Sizing', NULL, NULL, 'consts.catalog.sizes_array.description', 'Ordered list of the five standard size values (x-small → x-large) used by the `size` prop across components. Useful for iterating the complete size matrix in stories and validation helpers.', 'export const SIZES_ARRAY: Array<TSize> = [
    SIZES.X_SMALL,
