INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5b4e753f-358b-413b-87c6-78a4cbc1bfad', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'const', 'srgb-forward-matrix', 'SRGB_FORWARD_MATRIX', 'Color & Theming', NULL, NULL, 'consts.catalog.srgb_forward_matrix.description', 'XYZ-to-sRGB linear transformation matrix (3×3) used in the color pipeline to convert CIE XYZ tristimulus values to linear sRGB channel values before gamma expansion via SRGB_FORWARD_TRANSFORM.', 'export const SRGB_FORWARD_MATRIX = [
    [3.2406, -1.5372, -0.4986],
    [-0.9689, 1.8758, 0.0415],
    [0.0557, -0.2040, 1.0570]
]', NULL, NULL, NULL, 'packages/ds/src/consts/Commons/color.const.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5fd414be-047c-44ee-bbd0-c6599a106448', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'const', 'srgb-forward-transform', 'SRGB_FORWARD_TRANSFORM', 'Color & Theming', NULL, NULL, 'consts.catalog.srgb_forward_transform.description', 'sRGB gamma-expansion function (linear → sRGB encoded). Applies the IEC 61966-2-1 piecewise formula: values ≤ 0.0031308 are linearised as C × 12.92; values above use the power-curve branch 1.055 × C^(1/2.4) − 0.055.', 'export const SRGB_FORWARD_TRANSFORM = (C: number): number => (
    C <= 0.0031308
        ? C * 12.92
        : 1.055 * C ** (1 / 2.4) - 0.055
)', NULL, NULL, '(C: number): number => ( C <= 0.0031308 ? C * 12.92 : 1.055 * C ** (1 / 2.4) - 0.055 )', 'packages/ds/src/consts/Commons/color.const.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5d10c602-47c3-4970-882d-f3585d0972db', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'const', 'srgb-reverse-matrix', 'SRGB_REVERSE_MATRIX', 'Color & Theming', NULL, NULL, 'consts.catalog.srgb_reverse_matrix.description', 'sRGB-to-XYZ linear transformation matrix (3×3) used in the color pipeline to convert linear sRGB channel values to CIE XYZ tristimulus values. Paired with SRGB_REVERSE_TRANSFORM for the sRGB → XYZ direction.', 'export const SRGB_REVERSE_MATRIX = [
    [0.4124, 0.3576, 0.1805],
    [0.2126, 0.7152, 0.0722],
    [0.0193, 0.1192, 0.9505]
]', NULL, NULL, NULL, 'packages/ds/src/consts/Commons/color.const.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4f9c0671-cbf0-4786-90af-342bd024fa30', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'const', 'srgb-reverse-transform', 'SRGB_REVERSE_TRANSFORM', 'Color & Theming', NULL, NULL, 'consts.catalog.srgb_reverse_transform.description', 'sRGB gamma-compression function (sRGB encoded → linear). Applies the IEC 61966-2-1 piecewise decode: values ≤ 0.04045 are linearised as C / 12.92; values above use the power-curve branch ((C + 0.055) / 1.055)^2.4.', 'export const SRGB_REVERSE_TRANSFORM = (C: number): number => (
    C <= 0.04045
        ? C / 12.92
        : ((C + 0.055) / 1.055) ** 2.4
)', NULL, NULL, '(C: number): number => ( C <= 0.04045 ? C / 12.92 : ((C + 0.055) / 1.055) ** 2.4 )', 'packages/ds/src/consts/Commons/color.const.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ab5ecc5d-858b-4e9f-9929-93362cc452b6', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'const', 'supported-langs', 'SUPPORTED_LANGS', 'Code & Syntax', NULL, NULL, 'consts.catalog.supported_langs.description', 'Frozen list of language identifiers (CODE_LANG enum values) bundled with the default shiki highlighter. OrigamCode accepts only these values for its `lang` prop unless a custom highlighter is registered. Keep this list and the `langs` argument of `createHighlighter()` in lockstep.', 'export const SUPPORTED_LANGS: ReadonlyArray<CODE_LANG> = Object.freeze([
    CODE_LANG.PLAINTEXT,
    CODE_LANG.VUE,
    CODE_LANG.TS,
    CODE_LANG.JS,
    CODE_LANG.TSX,
    CODE_LANG.JSX,
    CODE_LANG.SCSS,
    CODE_LANG.CSS,
    CODE_LANG.JSON,
    CODE_LANG.BASH,
    CODE_LANG.HTML,
    CODE_LANG.XML,
    CODE_LANG.YAML,
    CODE_LANG.MD
])', NULL, NULL, 'Object.freeze([ CODE_LANG.PLAINTEXT, CODE_LANG.VUE, CODE_LANG.TS, CODE_LANG.JS, CODE_LANG.TSX, CODE_LANG.JSX, CODE_LANG.SCSS, CODE_LANG.CSS, CODE_LANG.JSON, CODE_LANG.BASH, CODE_LANG.HTML, CODE_LANG.XML, CODE_LANG.YAML, CODE_LANG.MD ])', 'packages/ds/src/consts/Code/code.const.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d1461aa7-aee8-4c84-a498-bf4b2e66f183', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'const', 'supports-eye-dropper', 'SUPPORTS_EYE_DROPPER', 'Feature Detection', NULL, NULL, 'consts.catalog.supports_eye_dropper.description', 'Boolean feature-detection flag that is `true` when the runtime is a browser AND the `EyeDropper` API is available in `window`. Evaluated once at module initialisation. Used by the color-picker components to conditionally render the eye-dropper button.', 'export const SUPPORTS_EYE_DROPPER = IN_BROWSER && ''EyeDropper'' in window', NULL, NULL, 'IN_BROWSER && ''EyeDropper'' in window', 'packages/ds/src/consts/Commons/commons.const.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
