INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5b43f804-830a-48fb-81f6-cbf8d0cf7e92', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'directive', 'click-outside', 'v-click-outside', 'Directive', NULL, 'mdi-cursor-pointer', 'directives.click_outside.description', 'Calls a handler when a click lands outside the bound element. Supports Shadow DOM via handleShadow() and an optional closeConditional guard to suppress the callback.', NULL, '// Simple handler — called on every outside click
v-click-outside="onClickOutside"

// Full options object
v-click-outside="{
  handler: onClickOutside,
  closeConditional: (e) => isOpen.value,
  include: () => [extraEl]
}"', NULL, NULL, NULL, NULL, 'directives.click_outside.note', 'The directive attaches listeners in capture phase on the document (or the nearest Shadow Root) so it intercepts clicks before any element handler can stop propagation.', NULL, NULL, NULL, '{"signatureLang": "ts", "signatureSummary": "v-click-outside=\"handler | options\""}', false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('22646d93-a34e-4079-896b-1d8f203dd95f', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'directive', 'contrast', 'v-contrast', 'Directive', NULL, 'mdi-contrast-circle', 'directives.contrast.description', 'Automatically adjusts foreground text colour to meet the WCAG AA contrast ratio (4.5:1 by default, configurable via createOrigam). Pass false to opt out on a specific element.', NULL, '// Enabled — follows createOrigam({ contrast }) global config
v-contrast

// Per-element opt-out
v-contrast="false"', NULL, NULL, NULL, NULL, 'directives.contrast.note', 'The threshold and algorithm are set globally in createOrigam({ contrast: { threshold: 4.5 } }). Individual elements can override with v-contrast="false" but cannot raise the threshold above the global value.', NULL, NULL, NULL, '{"signatureLang": "ts", "signatureSummary": "v-contrast | v-contrast=\"false\""}', false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e4dd6565-fed1-47fc-a28f-03a2631191cd', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'enum', 'bracket-match-status', 'BRACKET_MATCH_STATUS', 'Data Display', NULL, NULL, 'enums.catalog.bracket_match_status.description', 'TypeScript enum for the status of a match in a tournament bracket (pending, live, completed, forfeited).', 'export enum BRACKET_MATCH_STATUS {
    PENDING = ''pending'',
    LIVE = ''live'',
    COMPLETED = ''completed'',
    FORFEITED = ''forfeited''
}', NULL, NULL, NULL, 'packages/ds/src/enums/Bracket/bracket-match-status.enum.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b4d3815a-c911-4ac0-b13f-6c76387bf095', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'directive', 'hover', 'v-hover', 'Directive', NULL, 'mdi-cursor-default-outline', 'directives.hover.description', 'Toggles a CSS class on an element while the pointer is over it. Supports a callback mode (.callback modifier) and propagation stop (.stop modifier).', NULL, '// Toggle a CSS class on hover
v-hover="{ class: ''is-hovered'' }"

// Invoke a callback with the hover state (boolean)
v-hover.callback="onHoverChange"

// Stop pointer-event propagation on hover
v-hover.stop', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"signatureLang": "ts", "signatureSummary": "v-hover=\"{ class: ''…'' }\" | v-hover.callback=\"fn\""}', false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6750eb13-563c-4356-9e62-267b9a158199', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'directive', 'intersect', 'v-intersect', 'Directive', NULL, 'mdi-eye-outline', 'directives.intersect.description', 'Wraps the IntersectionObserver API. Fires a callback each time the element enters or leaves the viewport. Supports .once to disconnect after the first entry and .quiet to skip the initial call on mount.', NULL, '// Simple handler
v-intersect="onIntersect"

// With IntersectionObserver options
v-intersect="{ handler: onIntersect, options: { threshold: 0.5 } }"

// Fire once on enter, then auto-disconnect
v-intersect.once="onEntered"

// Skip the initial call triggered on observer setup
v-intersect.quiet="onIntersect"', NULL, NULL, NULL, NULL, 'directives.intersect.note', 'IntersectionObserver is not available in IE 11 without a polyfill. Origam does not bundle a polyfill — add one via the project if IE 11 support is required.', NULL, NULL, NULL, '{"signatureLang": "ts", "signatureSummary": "v-intersect=\"handler | options\""}', false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e408aa4d-5324-4ce8-9baf-c75bfe2af1ac', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'directive', 'ripple', 'v-ripple', 'Directive', NULL, 'mdi-target', 'directives.ripple.description', 'Applies a Material-style ripple animation emanating from the click position. Supports centered ripples, circular clipping, custom CSS classes and propagation stop.', NULL, '// Default — ripple from pointer position
v-ripple

// Disabled
v-ripple="false"

// Custom CSS class on the ripple element
v-ripple="{ class: ''my-ripple'' }"

// Always emanate from element center
v-ripple.center

// Clip to a circle
v-ripple.circle

// Stop pointer-event propagation after ripple
v-ripple.stop', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"signatureLang": "ts", "signatureSummary": "v-ripple | v-ripple=\"false\" | v-ripple.center.circle"}', false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('fd6e7015-cf65-4c44-98c4-2b35de0cebb0', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'directive', 'touch', 'v-touch', 'Directive', NULL, 'mdi-gesture-tap', 'directives.touch.description', 'Attaches touch event listeners (touchstart, touchend, touchmove) and recognises swipe gestures (left, right, up, down). All handlers are optional; only attach what you need.', NULL, 'v-touch="{
  start?:  (e) => void,   // touchstart
  end?:    (e) => void,   // touchend
  move?:   (e) => void,   // touchmove
  left?:   (e) => void,   // swipe left
  right?:  (e) => void,   // swipe right
  up?:     (e) => void,   // swipe up
  down?:   (e) => void,   // swipe down
  parent?: boolean,       // attach listeners to parentElement
  options?: AddEventListenerOptions
}"', NULL, NULL, NULL, NULL, 'directives.touch.note', 'The swipe threshold (minimum displacement and velocity) is not currently configurable per-instance. Adjust at the DS level if needed.', NULL, NULL, NULL, '{"signatureLang": "ts", "signatureSummary": "v-touch=\"{ left, right, up, down, start, end, move }\""}', false, NULL, NULL);
