INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('029da576-3f26-4b70-857d-773cc70aec6e', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-audio-emits', 'IAudioEmits', 'Events & Emits', NULL, NULL, 'interfaces.catalog.i_audio_emits.description', 'Emits surfaced by <OrigamAudio>. Event names mirror native DOM audio events one-to-one, plus v-model bindings for playbackRate, currentTrackIndex, loopMode and shuffle.', 'export interface IAudioEmits {
    (e: ''play''): void
    (e: ''pause''): void
    (e: ''ended''): void
    (e: ''timeupdate'', event: Event): void
    (e: ''volumechange'', event: Event): void
    (e: ''loadedmetadata'', event: Event): void
    (e: ''error'', payload: Event | MediaError | Error): void
    /** Two-way binding for the playback rate. The component DOES NOT
     *  set this in response to the consumer''s prop changes — only
     *  when the user picks a rate from the config menu. */
    (e: ''update:playbackRate'', rate: number): void
    /** Fired when the listener clicks the "Download" row in the
     *  config menu. Payload is the URL of the file. */
    (e: ''download'', url: string): void
    /** Fires once per waveform recomputation (typically when `src`
     *  changes). Payload is the downsampled peaks array (0..1
     *  amplitudes). Ported from `ISoundEmits[''waveform'']`. */
    (e: ''waveform'', peaks: Array<number>): void
    /** Fires when the listener clicks the "previous track" button.
     *  Always emitted alongside the in-component navigation (playlist
     *  jump if a playlist is set, otherwise the listener can implement
     *  its own previous logic). */
    (e: ''previous''): void
    /** Fires when the listener clicks the "next track" button. Same
     *  contract as `previous`. */
    (e: ''next''): void
    /** Two-way binding for the active playlist index. Fires when the
     *  user clicks a track in the list, presses prev / next, or when
     *  the player auto-advances on `ended`. */
    (e: ''update:currentTrackIndex'', index: number): void
    /** Two-way binding for the loop mode. Fires when the user cycles
     *  the loop button (`none` → `all` → `one` → `none`). */
    (e: ''update:loopMode'', mode: TAudioLoopMode): void
    /** Two-way binding for the shuffle flag. Fires when the user
     *  toggles the shuffle button. */
    (e: ''update:shuffle'', shuffle: boolean): void
    /** Fires whenever the active track changes (manual click, prev /
     *  next, auto-advance). Payload is the new track descriptor. */
    (e: ''track-change'', track: IAudioTrack, index: number): void
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Audio/audio-player.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a06f5ce5-7a05-4fec-af68-37a1b2a9b9b9', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-audio-player-emits', 'IAudioPlayerEmits', 'Events & Emits', NULL, NULL, 'interfaces.catalog.i_audio_player_emits.description', 'Emit signatures recommended for audio host components using useAudioPlayer. Extends the media-agnostic IMediaPlayerEmits baseline — the composable itself does not emit; this interface is for the host SFC defineEmits contract.', 'export interface IAudioPlayerEmits extends IMediaPlayerEmits {}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Audio/audio-player.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c2f810d5-56bf-4d88-8fc7-5ea276a5e068', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-audio-player-methods', 'IAudioPlayerMethods', 'Component Props', NULL, NULL, 'interfaces.catalog.i_audio_player_methods.description', 'Imperative methods returned by useAudioPlayer (Audio namespace). Extends the media-agnostic IMediaPlayerMethods baseline. Kept as a distinct symbol so audio-specific commands can be added without churn on consumer types.', 'export interface IAudioPlayerMethods extends IMediaPlayerMethods {}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Audio/audio-player.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a59be36c-7978-47e8-bc15-a4933c7419a2', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-audio-player-state', 'IAudioPlayerState', 'Component Props', NULL, NULL, 'interfaces.catalog.i_audio_player_state.description', 'Reactive state surface returned by useAudioPlayer (Audio namespace). Extends the media-agnostic IMediaPlayerState baseline. Future audio-specific extensions (waveform analysis, frequency bins) have a home here without breaking existing imports.', 'export interface IAudioPlayerState extends IMediaPlayerState {}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Audio/audio-player.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f01debe9-0b51-4d4b-b9e0-8a67999a79c2', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-audio-props', 'IAudioProps', 'Component Props', NULL, NULL, 'interfaces.catalog.i_audio_props.description', 'Full props contract for <OrigamAudio> — composes useAudioPlayer with OrigamMediaController to paint an opinionated audio card (cover + title/artist + transport bar). Exposes variant, cover, playlist, loop mode, shuffle, waveform, playback rates and the full design surface.', 'export interface IAudioProps
    extends ICommonsComponentProps,
        ITagProps,
        IRoundedProps,
        IBorderProps,
        IDimensionProps,
        IMarginProps,
        IPaddingProps,
        IElevationProps,
        IPositionProps,
        IColorProps,
        IBgColorProps,
        ITypographyProps {
    /**
     * Visual variant of the audio surface.
     *
     * - `''expanded''` — full Stemtracks studio strip: 96 px cover,
     *                  title / artist / album header, waveform mini
     *                  scrubber above the transport row.
     * - `''compact''`  — slim transport-only dock: 48 px cover, inline
     *                  metadata, no waveform, transport row only.
     *
     * Legacy `''normal''` / `''minimal''` alias values remain accepted for
     * backward compatibility and resolve to `''expanded''` / `''compact''`.
     *
     * @default ''expanded''
     */
    variant?: TAudioVariant
    /**
     * Side of the surface where the album cover is painted. The
     * controller column sits on the opposite side. Swap to keep the
     * cover next to the page edge (e.g. against a left sidebar).
     *
     * @default ''left''
     */
    coverPosition?: TCoverPosition
    /**
     * Media URL — either a single string for `<audio src>`, an
     * `IAudioSource` object (`{ src, type }`), or an array of sources
     * for codec fallback. The browser walks the array top-down and
     * picks the first source whose `type` it can decode.
     */
    src: string | IAudioSource | Array<IAudioSource>
    /**
     * Optional captions / chapters tracks attached to the `<audio>`.
     * Reuses the video track shape (kind / src / srclang / label /
     * default) so consumers learn the API once.
     *
     * @default []
     */
    tracks?: Array<IVideoTrack>
    /**
     * Optional title shown above the controls (e.g. `"Podcast Episode 42"`).
     */
    title?: string
    /**
     * Optional artist / author shown next to the title.
     */
    artist?: string
    /**
     * Optional album name shown below the artist (ported from
     * `ISoundMetadata.album`). Renders only when set.
     */
    album?: string
    /**
     * Optional cover image shown next to the title. Accepts a URL
     * string or an `ISrcObject` for srcset / lazy-src support.
     */
    cover?: string | ISrcObject
    /**
     * Display the computed waveform above the controls. Pass `true`
     * to force the computation (when supported); pass `''auto''` to
     * activate it only when the browser supports `OfflineAudioContext`.
     * SSR + jsdom fall through to `false`.
     *
     * The decoder lives in `useWaveform` — fetch + decode through
     * `OfflineAudioContext` + downsample channel 0 to 200 peaks.
     *
     * @default false
     */
    waveform?: boolean | ''auto''
    /**
     * Stroke colour for the *played* portion of the waveform bars.
     * Default `''currentColor''` so the waveform inherits the
     * typographic theme. Override via the prop OR via
     * `--origam-audio__waveform---color-played` directly on the wrapper.
     *
     * @default ''currentColor''
     */
    waveformColor?: string
    /**
     * Starts playback as soon as `loadedmetadata` fires. Most
     * browsers require `muted=true` alongside `autoplay`; the
     * component forces `muted=true` when the consumer asks for
     * autoplay without an explicit `muted` value.
     *
     * **Accessibility:** `autoplay` is suppressed when the user has
     * requested reduced motion.
     *
     * @default false
     */
    autoplay?: boolean
    /**
     * Starts the player muted.
     *
     * @default false
     */
    muted?: boolean
    /**
     * Legacy loop flag. When `true` is mapped to `loopMode=''one''` at
     * runtime so a v0.x consumer keeps the "loop this track forever"
     * behaviour without source change. Prefer `loopMode` for new code.
     *
     * @deprecated Use `loopMode` instead.
     * @default false
     */
    loop?: boolean
    /**
     * Tri-state loop strategy when a playlist is active. Cycled by the
     * loop button in the transport row:
     *   - `''none''` → no loop, playback stops after the last track
     *   - `''all''`  → loop the playlist, wrap from last to first
     *   - `''one''`  → loop the current track on its own `ended`
     *
     * For a single-track usage (`src` only, no `playlist`), `''one''`
     * keeps the legacy `loop` behaviour and `''all''` is equivalent to
     * `''one''` (there''s no next track to wrap to).
     *
     * @default ''none''
     */
    loopMode?: TAudioLoopMode
    /**
     * Shuffle the playlist order when navigating with prev / next or
     * auto-advancing on track end. The shuffled order is computed
     * deterministically (Fisher-Yates seeded by playlist length) so
     * consumers can re-render predictably; opt out of stability by
     * controlling the playlist array externally.
     *
     * Has no visible effect when no `playlist` is provided.
     *
     * @default false
     */
    shuffle?: boolean
    /**
     * Optional list of tracks to play sequentially. When set, the
     * `prev` / `next` transport buttons navigate the list instead of
     * skipping 10 s, the cover / metadata strip switches to the active
     * track, and a clickable list renders below the transport.
     *
     * Mutually informative with the top-level `src` prop: if `src`
     * AND `playlist` are both set, `playlist` wins and `src` is
     * ignored. The active track is `playlist[currentTrackIndex]`.
     */
    playlist?: Array<IAudioTrack>
    /**
     * Index of the currently-active track in the `playlist`. Supports
     * `v-model:currentTrackIndex` for two-way binding (parent stays the
     * source of truth for which track is playing).
     *
     * @default 0
     */
    currentTrackIndex?: number
    /**
     * Buffering hint. `''metadata''` (default) loads just enough to
     * compute the duration; `''none''` defers everything until the
     * user presses play; `''auto''` lets the browser pre-buffer.
     *
     * @default ''metadata''
     */
    preload?: ''none'' | ''metadata'' | ''auto''
    /**
     * Mirrors the native `crossorigin` attribute. Required when the
     * media is served from a CORS-enabled origin and the consumer
     * needs WebAudio access to the decoded samples.
     */
    crossorigin?: string
    /**
     * Which control surface to render. `''custom''` paints the
     * `<OrigamMediaController>` shell; `''native''` exposes the
     * browser''s built-in `controls` attribute on the `<audio>`.
     *
     * @default ''custom''
     */
    controls?: TAudioControls
    /**
     * Available playback rates exposed via the config menu.
     *
     * @default [0.5, 0.75, 1, 1.25, 1.5, 2]
     */
    playbackRates?: ReadonlyArray<number>
    /**
     * Initial playback rate. The runtime value is exposed via the
     * `update:playbackRate` emit.
     *
     * @default 1
     */
    playbackRate?: number
    /**
     * Enable the cast / AirPlay button (Remote Playback API). The
     * button only renders when this flag is true AND at least one
     * cast-capable device is detected.
     *
     * @default false
     */
    allowRemotePlayback?: boolean
    /**
     * Adds a "Download" row to the cog menu that lets the listener
     * download the currently-playing audio file.
     *
     * @default false
     */
    downloadable?: boolean
    /**
     * Override the downloaded file name. Defaults to the trailing
     * segment of the source URL.
     */
    downloadFilename?: string
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Audio/audio-player.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0c7a3bbf-f4b1-4f9e-95f4-51313a739184', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-audio-scoped-slot-bindings', 'IAudioScopedSlotBindings', 'Slots', NULL, NULL, 'interfaces.catalog.i_audio_scoped_slot_bindings.description', 'Bindings handed to the #controls scoped slot of <OrigamAudio>. State is exposed as plain unwrapped values (snapshot at render time) — Vue reactive re-invokes the slot on every meaningful change.', 'export interface IAudioScopedSlotBindings {
    playing: boolean
    paused: boolean
    currentTime: number
    duration: number
    buffered: number
    volume: number
    muted: boolean
    playbackRate: number
    loading: boolean
    error: MediaError | Error | null
    methods: IAudioPlayerMethods
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Audio/audio-player.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('00d3f0ed-7cc6-4d1b-9730-ce431cc3638d', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-audio-slots', 'IAudioSlots', 'Slots', NULL, NULL, 'interfaces.catalog.i_audio_slots.description', 'Slot signatures for <OrigamAudio>. Provides override points for the metadata strip, cover image, title, waveform canvas, transport controls, loading overlay and error overlay.', 'export interface IAudioSlots {
    /** Override the entire title/artist/cover strip. */
    metadata?: () => any
    /** Override the cover image / placeholder. */
    cover?: () => any
    /** Override the title rendering. */
    title?: () => any
    /** Override the default waveform `<canvas>` painter. Receives the
     *  current peaks array + the playhead context so the consumer can
     *  paint via SVG / WebGL / a custom canvas pass. Ported from
     *  `ISoundSlots.waveform`. */
    waveform?: (bindings: { peaks: Array<number>; currentTime: number; duration: number }) => any
    /** Override the entire controls (replaces the default
     *  `<OrigamMediaController>`). */
    controls?: (bindings: IAudioScopedSlotBindings) => any
    /** Overlay rendered while the media is loading. */
    loading?: () => any
    /** Overlay rendered when an error occurred. */
    error?: (bindings: { error: MediaError | Error }) => any
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Audio/audio-player.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b56e6292-fa13-46ad-baa2-66c489da0905', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-audio-source', 'IAudioSource', 'Component Props', NULL, NULL, 'interfaces.catalog.i_audio_source.description', 'A single <source> entry when the consumer passes multiple audio URLs (typically one mp3 + one ogg so the browser picks whichever codec it can decode). Mirrors IVideoSource minus video-specific fields.', 'export interface IAudioSource {
    /** Absolute or root-relative URL to the audio file. */
    src: string
    /**
     * MIME type — `"audio/mpeg"`, `"audio/ogg"`, `"audio/wav"`,
     * `"application/vnd.apple.mpegurl"` for HLS, etc. Optional but
     * recommended: it lets the browser skip sources it can''t decode
     * without a network round-trip.
     */
    type?: string
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Audio/audio-player.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ebed19c6-21de-4463-a8bc-eab24249e006', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-audio-track', 'IAudioTrack', 'Component Props', NULL, NULL, 'interfaces.catalog.i_audio_track.description', 'Descriptor for a single track in an <OrigamAudio> playlist. The src field is mandatory; title, artist, album and cover are optional metadata surfaced on the player chrome when the track becomes active.', 'export interface IAudioTrack {
    /** Absolute or root-relative audio URL (or an array for codec
     *  fallback / a single `{ src, type }` descriptor). */
    src: string | IAudioSource | Array<IAudioSource>
    /** Display title for this track. Falls back to the root `title`
     *  prop when omitted. */
    title?: string
    /** Display artist. Falls back to the root `artist` prop. */
    artist?: string
    /** Display album. Falls back to the root `album` prop. */
    album?: string
    /** Cover image URL. Falls back to the root `cover` prop. */
    cover?: string
    /** Optional pre-known duration in seconds (shown in the playlist
     *  list before the audio is loaded). Once metadata loads the
     *  runtime duration overrides this value for the active track. */
    duration?: number
    /** Optional stable identifier — used as the `<li>` key in the
     *  playlist list. Defaults to the array index when omitted. */
