INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5c3e5e3f-2a10-456b-8e6e-f66f33d691e4', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-blockquote-props', 'IBlockquoteProps', 'Component Props', NULL, NULL, 'interfaces.catalog.i_blockquote_props.description', 'Full props contract for <OrigamBlockquote> — typographic citation component built on <blockquote>. Exposes five visual variants, author/source attribution, locale-aware decorative quote marks, horizontal alignment, and the full design surface (color, border, spacing, elevation, rounded).', 'export interface IBlockquoteProps extends ICommonsComponentProps, ITagProps, IColorProps, IBgColorProps, IRoundedProps, IElevationProps, IBorderProps, IPaddingProps, IMarginProps, ITypographyProps {
    /**
     * Visual variant. See `TBlockquoteVariant` for the per-variant
     * typographic contract.
     *
     * @default ''default''
     */
    variant?: TBlockquoteVariant
    /**
     * Author of the citation. Rendered after the body as `— Author`.
     * When `source` is also set, the two are joined with a comma.
     * Can be overridden via the `#author` slot for custom rendering
     * (e.g. wrap in a link to a bio page).
     */
    author?: string
    /**
     * Source of the citation (book, publication, URL label, …).
     * Rendered after `author` as `, Source`. Can be overridden via
     * the `#source` slot. When `cite` is also set on the prop, the
     * source label is wrapped in a `<cite>` element pointing at the
     * URL.
     */
    source?: string
    /**
     * URL the citation references. Maps 1:1 to the HTML `cite`
     * attribute on the rendered `<blockquote>` (or `<q>`). Pass a
     * fully-qualified URL — the browser exposes it to assistive tech
     * and to user-agent inspectors but does not render it visually.
     */
    cite?: string
    /**
     * Locale hint that determines which decorative quote glyphs render
     * for `variant="quoted"`. See `TBlockquoteLang`.
     *
     * @default ''auto''
     */
    lang?: TBlockquoteLang
    /**
     * Horizontal alignment of the citation body and attribution. The
     * `pull` variant forces `''center''` when this prop is left empty;
     * other variants default to `''left''`.
     *
     * @default ''left''
     */
    align?: TBlockquoteAlign
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Blockquote/blockquote.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
