	/** Minimum non-outlier value (lower whisker tip). */
	min: number
	/** First quartile (25th percentile). */
	q1: number
	/** Median (50th percentile). */
	median: number
	/** Third quartile (75th percentile). */
	q3: number
	/** Maximum non-outlier value (upper whisker tip). */
	max: number
	/** IQR = Q3 − Q1. */
	iqr: number
	/** Values outside the 1.5·IQR fences. */
	outliers: Array<number>
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-box-plot.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('726f09df-f2d2-4900-8db2-6646975d7987', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-bracket-competitor', 'IBracketCompetitor', 'Data & Models', NULL, NULL, 'interfaces.catalog.i_bracket_competitor.description', 'A single competitor or team in a bracket match — intentionally generic (no sport/e-sport-specific distinction). Consumers can stash any extra payload under metadata.', 'export interface IBracketCompetitor {
    /** Stable identifier — used to detect the winner via `winnerId`. */
    id: string | number
    /** Display name (team name, player tag, …). */
    name: string
    /**
     * Optional seed number (`1` = top seed). When `showSeed` is enabled
     * on `OrigamBracket`, the seed is rendered before the name.
     */
    seed?: number
    /**
     * Optional avatar URL (team logo, country flag, player portrait).
     * Rendered as a small `<img>` left of the name.
     */
    avatar?: string
    /** Free-form payload — never read by the component. */
    metadata?: Record<string, unknown>
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Bracket/bracket-competitor.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('01e9abbe-d9d5-41bd-82d4-6faac6b67350', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-bracket-competitor-props', 'IBracketCompetitorProps', 'Component Props', NULL, NULL, 'interfaces.catalog.i_bracket_competitor_props.description', 'Props for <OrigamBracketCompetitor> — a single competitor row. Carries the full cross-cutting surface (color, bgColor, rounded, elevation, border, density, dimension, padding, margin) so a standalone row behaves like any other origam component.', 'export interface IBracketCompetitorProps extends ICommonsComponentProps, ITagProps, IColorProps, IBgColorProps, IHoverProps, IActiveProps, IRoundedProps, IElevationProps, IBorderProps, IDensityProps, IDimensionProps, IPaddingProps, IMarginProps, ITypographyProps {
    /**
     * The competitor payload. `null` renders a "TBD" placeholder — used
     * when the match''s participant is not yet determined (winner of an
     * earlier round, byes, …).
     */
    competitor: IBracketCompetitor | null
    /** Optional score — accepts string for non-numeric markers. */
    score?: number | string
    /**
     * Whether to apply the `--winner` modifier class (bolder text,
     * intent-tinted background).
     *
     * @default false
     */
    isWinner?: boolean
    /**
     * Mirror the player-is-loser state. Used to lighten the row when
     * the match is completed and the consumer wants to de-emphasize
     * the losing side.
     *
     * @default false
     */
    isLoser?: boolean
    /**
     * Toggle the score column.
     *
     * @default true
     */
    showScore?: boolean
    /**
     * Toggle the seed prefix.
     *
     * @default false
     */
    showSeed?: boolean
    /**
     * Whether the row advertises interactivity (hover state, cursor).
     *
     * @default true
     */
    interactive?: boolean
    /**
     * Head-start carried into the match by this competitor, in rounds /
     * sets. When set (`> 0`), a `+N` badge is rendered next to the name
     * — used for the Winner Bracket champion''s Grand Final advantage.
     */
    advantageRounds?: number
    /**
     * Marks this competitor as the one that FORFEITED the match — the
     * name is struck through and a "forfeit" tag is shown.
     */
    forfeit?: boolean
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Bracket/bracket-competitor-component.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f1585c4e-3aa9-4d2b-9b10-06c654dbc744', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-bracket-match', 'IBracketMatch', 'Data & Models', NULL, NULL, 'interfaces.catalog.i_bracket_match.description', 'A single match between two competitors. competitorA/B are nullable so the bracket can render "TBD" placeholders. scoreA/B accept string for non-numeric markers. nextMatchId lets OrigamBracket draw connectors automatically.', 'export interface IBracketMatch {
    /** Stable identifier — required for connector linking. */
    id: string | number
    /** Left-side / top-side competitor. `null` = TBD or bye. */
    competitorA: IBracketCompetitor | null
    /** Right-side / bottom-side competitor. `null` = TBD or bye. */
    competitorB: IBracketCompetitor | null
    /** Score of `competitorA`. Accepts `string` for non-numeric markers. */
    scoreA?: number | string
    /** Score of `competitorB`. Accepts `string` for non-numeric markers. */
    scoreB?: number | string
    /**
     * Identifier of the declared winner. Falls back to `null` /
     * `undefined` when the match is not yet completed. Used by the
     * component to apply the `--winner` modifier class on the
     * relevant competitor row.
     */
    winnerId?: string | number | null
    /**
     * Optional lifecycle marker. Drives the visual `--status-{value}`
     * modifier on the match card (e.g. live pulse, completed grey out).
     */
    status?: TBracketMatchStatus
    /**
     * Optional id of the downstream match this one feeds into. Used
     * by the connector layout to draw a path. If omitted, positional
     * mapping is used.
     */
    nextMatchId?: string | number
    /**
     * Optional head-start for one competitor — the Winner Bracket
     * champion''s one-round advantage in a double-elimination Grand
     * Final. Rendered as a `+N` badge on the favoured competitor row.
     */
    advantage?: IBracketMatchAdvantage
    /** ISO date string — informative only, displayed when present. */
    scheduledAt?: string
    /** Free-form payload — never read by the component. */
    metadata?: Record<string, unknown>
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Bracket/bracket-match.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('457da475-d524-49b9-be30-cf962121404b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-bracket-match-advantage', 'IBracketMatchAdvantage', 'Data & Models', NULL, NULL, 'interfaces.catalog.i_bracket_match_advantage.description', 'Head-start carried into a match by one competitor — the classic double-elimination Grand Final advantage, where the Winner Bracket champion starts already up by one round/set.', 'export interface IBracketMatchAdvantage {
    /** Id of the competitor that starts ahead. */
    competitorId: string | number
    /**
     * Size of the head start, in rounds / sets.
     *
     * @default 1
