INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2d0fc8d0-f3de-4d6d-bb20-756d9437e2e3', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-bracket-props', 'IBracketProps', 'Component Props', NULL, NULL, 'interfaces.catalog.i_bracket_props.description', 'Props for <OrigamBracket> — a tournament tree renderer supporting single-elimination, double-elimination and round-robin layouts. Purely presentational: accepts immutable rounds and emits interaction events.', 'export interface IBracketProps extends ICommonsComponentProps, ITagProps, IDensityProps, IRoundedProps, IColorProps, IBgColorProps, IBorderProps, IDimensionProps, IElevationProps, IMarginProps, IPaddingProps, ITypographyProps {
    /**
     * Required. Pre-ordered list of rounds. For single-elimination,
     * the rounds are laid out from earliest (e.g. round-of-16) to
     * final. For double-elimination, segregate by `IBracketRound.side`
     * (`''winner''`, `''loser''`, `''grand-final''`).
     */
    rounds: IBracketRound[]
    /**
     * Tournament shape. Single-elimination is the default.
     * Round-robin renders a NxN matrix instead of a tree.
     *
     * @default ''single-elimination''
     */
    variant?: TBracketVariant
    /**
     * Layout axis. Horizontal stacks rounds as columns (the classic
     * tournament tree look). Vertical stacks rounds as rows — useful
     * for narrow viewports. Ignored when `variant === ''round-robin''`
     * (the matrix layout has its own grid axis).
     *
     * @default ''horizontal''
     */
    direction?: ''horizontal'' | ''vertical''
    /**
     * Toggle round headers (`<h3>Quarter-finals</h3>`).
     *
     * @default true
     */
    showRoundTitles?: boolean
    /**
     * Toggle the score column on each competitor row.
     *
     * @default true
     */
    showScores?: boolean
    /**
     * Toggle the seed prefix on competitor names (e.g. `1. Team Liquid`).
     *
     * @default false
     */
    showSeed?: boolean
    /**
     * Whether match cards should be interactive (cursor, hover state,
     * keyboard focus). When `false`, click handlers still fire but the
     * cards do not advertise affordance.
     *
     * @default true
     */
    interactive?: boolean
    /**
     * Heading shown above the winner-bracket tree in a
     * double-elimination layout. Pre-translate before passing — the
     * component never calls `useT`.
     *
     * @default ''Winners bracket''
     */
    winnersLabel?: string
    /**
     * Heading shown above the loser-bracket tree in a
     * double-elimination layout.
     *
     * @default ''Losers bracket''
     */
    losersLabel?: string
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Bracket/bracket.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
