INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e01f0370-78d2-4958-b2d9-63269c9acc2b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-base-slots', 'IChartBaseSlots', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_base_slots.description', 'Slot signatures shared across every per-type chart component. Covers tooltip body replacement, legend entry replacement, title block replacement and empty state.', 'export interface IChartBaseSlots {
    /**
     * Replace the default tooltip body.
     * Sub-chart interfaces extend this with a narrower binding signature;
     * the parameter is typed `any` here so those overrides satisfy the
     * TypeScript function-parameter assignability check (TS2430).
     */
    tooltip?: (bindings: any) => any
    /** Replace one legend entry. */
    ''legend-item''?: (bindings: { series: IChartSeries, index: number, visible: boolean }) => any
    /** Replace the title block (title + subtitle). */
    title?: () => any
    /** Render when `series` is empty / every series is hidden. */
    empty?: () => any
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-base.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
