    (e: ''click:remove'', value: { file: File, index: number }): void
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/FileField/file-field-list-item.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('11564eb4-fcc4-42d7-8785-f7a1d701014b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-annotation', 'IChartAnnotation', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_annotation.description', 'A single overlay annotation drawn on top of a cartesian chart SVG surface. Supports four kinds: arrow, label, circle and bracket. Positioned in data coordinates and projected to pixel space by the chart X/Y scales.', 'export interface IChartAnnotation {
    /** Annotation kind. */
    kind: ''arrow'' | ''label'' | ''circle'' | ''bracket''
    /** Source / anchor data coordinate on the X axis (category string or numeric index). */
    x: number | string
    /** Source / anchor data coordinate on the Y axis. */
    y: number
    /**
     * End-point X coordinate in data space.
     * Required for `''arrow''` (head position) and `''bracket''` (right edge).
     */
    x2?: number | string
    /**
     * End-point Y coordinate in data space.
     * Optional for `''bracket''` — when omitted the bracket stays
     * horizontal (`y2 === y`).
     */
    y2?: number
    /** Text content rendered alongside the annotation. */
    text?: string
    /** Stroke / fill colour — accepts a `TIntent` name or any CSS colour string. */
    color?: TIntent | string
    /** Stroke width in SVG units. Default `1.5`. */
    width?: number
    /** Circle radius in SVG units. Applies to the `''circle''` kind only. Default `12`. */
    radius?: number
    /**
     * Horizontal offset of the text label relative to its anchor
     * point, in SVG units. Positive values push the label right.
     * Default `0`.
     */
    dx?: number
    /**
     * Vertical offset of the text label relative to its anchor
     * point, in SVG units. Positive values push the label down.
     * Default `-14`.
     */
    dy?: number
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-annotation.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('676e6b75-1bed-4511-8dd3-7a6611709ee2', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-annotation-geo', 'IChartAnnotationGeo', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_annotation_geo.description', 'Resolved SVG geometry for one chart annotation. Produced by computeAnnotationGeometry in chart.composable.ts and consumed directly by OrigamChartCartesian for rendering. Fields are gated per kind.', 'export interface IChartAnnotationGeo {
    kind: IChartAnnotation[''kind'']
    /** Resolved CSS colour string. */
    stroke: string
    strokeWidth: number
    /** Anchor pixel coordinate (tail of arrow / anchor of label / centre of circle / left edge of bracket). */
    ax: number
    ay: number
    /** End pixel coordinate (head of arrow / right edge of bracket). Equals `(ax, ay)` when unused. */
    bx: number
    by: number
    /** Arrowhead polygon `points` attribute — populated for `kind === ''arrow''`. */
    arrowPoints?: string
    /** Text content to display alongside the annotation. */
    text?: string
    /** Resolved horizontal text offset in SVG units. */
    dx: number
    /** Resolved vertical text offset in SVG units. */
    dy: number
    /** Circle radius in SVG units — populated for `kind === ''circle''`. */
    radius: number
    /** Callout rounded-rect geometry — populated for `kind === ''label''`. */
    callout?: { x: number, y: number, width: number, height: number }
    /** Bottom-centre of the callout box where the leader line terminates — populated for `kind === ''label''`. */
    leaderEnd?: { x: number, y: number }
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-annotation.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f829c679-0bec-4700-90fb-083ad3bef8a6', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-axis-props', 'IChartAxisProps', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_axis_props.description', 'Props for OrigamChartAxis — the cartesian-only axes, grid and tick-labels block. Expects pre-computed tick arrays and plot corners from useChart and paints them. No data coupling.', 'export interface IChartAxisProps {
    /**
     * Pixel coordinates of the plotting area''s four corners.
     * Comes verbatim from `useChart().plot.value`.
     */
    plot: {
        x0: number
        y0: number
        x1: number
        y1: number
        cx: number
        cy: number
    }
    /** Tick descriptors for X + Y (primary left axis). Comes from `useChart().ticks.value`. */
    ticks: {
        x: Array<IChartTick>
        y: Array<IChartTick>
    }
    /**
     * Tick descriptors for the secondary right Y axis.
     * When provided, a second vertical axis is rendered on the
     * right edge of the plot area. Comes from
     * `useChart().secondaryTicks.value`.
     */
    secondaryYTicks?: Array<IChartTick>
    /**
     * Render the four-corner axis frame + tick labels. When `false`,
     * the component renders nothing (mirrors the legacy `showAxis`
     * prop on `<OrigamChart>`).
     */
    showAxis?: boolean
    /**
     * Render horizontal grid lines under the plot. When `false`,
     * no grid is drawn (mirrors the legacy `showGrid` prop).
     */
    showGrid?: boolean
    /**
     * Formatter applied to X-axis tick labels. Defaults to
     * `String(value)`.
     */
    xAxisFormat?: (value: string | number) => string
    /**
     * Formatter applied to Y-axis tick labels. Defaults to
     * `String(value)`.
     */
    yAxisFormat?: (value: number) => string
    /**
     * Formatter applied to the secondary (right) Y-axis tick labels.
     * Falls back to `yAxisFormat`, then `String(value)`.
     */
    secondaryYAxisFormat?: (value: number) => string
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-axis.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('398cb51d-b57d-4959-86ad-21af2d26b2c0', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-base-emits', 'IChartBaseEmits', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_base_emits.description', 'Emit signatures shared across every per-type chart component (ChartBar, ChartLine, ChartPie, …). Covers data-point click, legend-entry click and legend visibility toggle.', 'export interface IChartBaseEmits {
    /** Mouse / keyboard activation on a data point. */
    (e: ''point-click'', point: IChartPoint, originalEvent: MouseEvent | KeyboardEvent): void
    /** Click on a legend entry — pair with `series-toggle` for state. */
    (e: ''legend-click'', series: IChartSeries, index: number): void
    /** Resulting visibility flip after a legend click. */
    (e: ''series-toggle'', series: IChartSeries, visible: boolean): void
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-base.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3bf81d8e-1bb1-4d5e-a69c-fac35ab88b53', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-base-props', 'IChartBaseProps', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_base_props.description', 'Props shared across every origam chart type — extends ICommonsComponentProps, IDimensionProps, IMarginProps, IPaddingProps, IRoundedProps, IElevationProps and IBgColorProps. Covers series data, legend, tooltip, animation, color scheme and aspect ratio.', 'export interface IChartBaseProps
    extends ICommonsComponentProps,
        IDimensionProps,
        IMarginProps,
        IPaddingProps,
        IRoundedProps,
        IElevationProps,
        IBgColorProps,
        Pick<ITypographyProps, ''fontSize'' | ''fontWeight''> {
    /** Data series — one or more. Empty array renders the `#empty` slot. */
    series: Array<IChartSeries>
    /**
     * X axis labels (for line/area/bar/column/radar). Length should
     * match the longest series; missing entries fall back to the
     * numeric index. Ignored for pie / donut / scatter.
     */
    categories?: Array<string>
    /** Optional title rendered above the plotting area. */
    title?: string
    /** Optional subtitle rendered below the title. */
    subtitle?: string
    /** Toggle the legend block. Default `true`. */
    showLegend?: boolean
    /** Anchor of the legend block. Default `''bottom''`. */
    legendPosition?: TChartLegendPosition
    /** Toggle the hover tooltip. Default `true`. */
    showTooltip?: boolean
    /**
     * Animate paths / bars / slices on first paint and on data
     * changes. Respects `prefers-reduced-motion`. Default `true`.
     */
    animated?: boolean
    /** Animation duration in ms. Default `600`. */
    animationDuration?: number
    /**
     * Palette used when a series does not pin its own `color`.
     * Pass intent strings (cycled in order) or raw CSS colours.
     * Default cycles through the 8 origam intents.
     */
    colorScheme?: Array<TIntent | string>
    /**
     * CSS `aspect-ratio` shortcut (`''16/9''`, `''4/3''`, `''1/1''`…). When
     * set, overrides `height` and lets the chart breathe with the
     * container width.
     */
    aspectRatio?: string
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-base.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8b245f8d-66b7-4e2d-a5cf-58178cfc5bef', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-box-plot-box', 'IChartBoxPlotBox', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_box_plot_box.description', 'Internal box descriptor produced by the OrigamChartBoxPlot geometry engine for each category slot. All coordinates are in SVG-space pixels. Consumed directly by the SVG renderer and exposed through the #tooltip slot.', 'export interface IChartBoxPlotBox {
	/** Category index (position in the data array). */
	index: number
	/** Category label. */
	category: string
	/** Resolved five-number summary (already coerced to SVG Y coords). */
	stats: {
		min: number
		q1: number
		median: number
		q3: number
		max: number
	}
	/** Raw numeric five-number summary (data-space values). */
	rawStats: {
		min: number
		q1: number
		median: number
		q3: number
		max: number
	}
	/** IQR in data space. */
	iqr: number
	/** SVG Y coordinate for Q3 (top of box rect). */
	svgQ3: number
	/** SVG Y coordinate for Q1 (bottom of box rect). */
	svgQ1: number
	/** SVG Y coordinate for the median line. */
	svgMedian: number
	/** SVG Y coordinate for the upper whisker tip. */
	svgMax: number
	/** SVG Y coordinate for the lower whisker tip. */
	svgMin: number
	/** Pre-computed box rectangle height (|svgQ1 − svgQ3|) — avoids template-level Math.abs(). */
	boxHeight: number
	/** SVG X centre of the slot. */
	cx: number
	/** Half-width of the box rectangle. */
	halfBoxW: number
	/** Half-width of the whisker cap segment. */
	halfCapW: number
	/** Resolved CSS colour string. */
	color: string
	/** SVG Y coordinates + raw values of each outlier. */
	outliers: Array<{ svgY: number, value: number }>
	/** Whether this box is currently visible (legend toggle). */
	visible: boolean
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-box-plot.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ef28e33b-db31-4024-8f4a-b08729d7b04d', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-box-plot-datum', 'IChartBoxPlotDatum', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_box_plot_datum.description', 'Pre-aggregated datum for OrigamChartBoxPlot — the consumer supplies all five-number-summary values (min, q1, median, q3, max) and optional outlier array directly. Use IChartBoxPlotRawDatum when raw samples should be aggregated by the component.', 'export interface IChartBoxPlotDatum {
	/** Category label shown on the X axis. */
	category: string
	/** Minimum (lower fence or true min when no outliers). */
	min: number
	/** First quartile — Q1 (25th percentile). */
	q1: number
	/** Median — Q2 (50th percentile). */
	median: number
	/** Third quartile — Q3 (75th percentile). */
	q3: number
	/** Maximum (upper fence or true max when no outliers). */
	max: number
	/** Values lying outside the 1.5·IQR whisker fences. */
	outliers?: Array<number>
	/**
	 * Override colour for this datum. Intent token or raw CSS colour.
	 * When absent the category index cycles through `colorScheme`.
	 */
	color?: TIntent | string
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-box-plot.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3a056ba1-cef5-4bd4-a6df-7846e5f6497d', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-box-plot-props', 'IChartBoxPlotProps', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_box_plot_props.description', 'Props for OrigamChartBoxPlot — extends IChartBaseProps with box-plot-specific controls: category order, box width, whisker cap width, outlier visibility, axis/grid visibility, Y-axis range overrides and axis label formatters.', 'export interface IChartBoxPlotProps extends IChartBaseProps {
	/**
	 * Explicit category order. When absent the order is inferred from
	 * the first occurrence of each category in `series[0].data`.
	 */
	categories?: Array<string>
	/**
	 * Box width as a fraction of the per-category slot width.
	 * Range [0, 1]. Default `0.6`.
	 */
	boxWidth?: number
	/**
	 * Whisker cap width as a fraction of the per-category slot width.
	 * Range [0, 1]. Default `0.4`.
	 */
	whiskerCapWidth?: number
	/** Render outlier dots beyond the whisker fences. Default `true`. */
	showOutliers?: boolean
	/** Render X and Y axes. Default `true`. */
	showAxis?: boolean
	/** Render horizontal grid lines. Default `true`. */
	showGrid?: boolean
	/**
	 * Override the auto-computed Y-axis minimum.
	 * When absent the component uses `min(data) − 10 %` padding.
	 */
	yMin?: number
	/**
	 * Override the auto-computed Y-axis maximum.
	 * When absent the component uses `max(data) + 10 %` padding.
	 */
	yMax?: number
	/**
	 * Formatter applied to X-axis category labels.
	 * Default: identity (category string returned as-is).
	 */
	xAxisFormat?: (value: string | number) => string
	/**
	 * Formatter applied to Y-axis tick values.
	 * Default: `String(value)`.
	 */
	yAxisFormat?: (value: number) => string
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-box-plot.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('574f311f-11fc-4e4b-ac22-192f6a6c14d5', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-box-plot-raw-datum', 'IChartBoxPlotRawDatum', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_box_plot_raw_datum.description', 'Raw-samples datum for OrigamChartBoxPlot — the component derives the five-number summary via Tukey''s method (linear interpolation) and detects outliers at the 1.5·IQR fence automatically. Use IChartBoxPlotDatum when the aggregation has already been done.', 'export interface IChartBoxPlotRawDatum {
	/** Category label shown on the X axis. */
	category: string
	/**
	 * Array of individual observations. Must contain at least 4 values
	 * for meaningful quartile computation. Fewer values are handled
	 * gracefully: all map to the same min/q1/median/q3/max.
	 */
	samples: Array<number>
	/**
	 * Override colour for this datum. Intent token or raw CSS colour.
	 * When absent the category index cycles through `colorScheme`.
	 */
	color?: TIntent | string
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-box-plot.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
