	/**
	 * Override the default tooltip card.
	 * Receives `point` (carries `x` = category, `y` = median),
	 * `series`, `category`, and the extended `box` descriptor.
	 */
	tooltip?: (bindings: {
		point: IChartPoint
		series: IChartSeries
		category: string | number
		box: IChartBoxPlotBox
	}) => any
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-box-plot.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d8c7ea88-7289-4999-820a-73253ceab907', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-bullet-bullet', 'IChartBulletBullet', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_bullet_bullet.description', 'Pre-computed geometry descriptor for a single bullet in a bullet chart. Produced by the bullet layout engine inside OrigamChartBullet — contains resolved colours, slot coordinates, and the maximum axis value.', 'export interface IChartBulletBullet {
    /** Position of this bullet in the original series array. */
    index: number
    /** Category label (from `categories[index]` or `series[index].name`). */
    category: string
    /** Raw datum ({value, target, ranges}). */
    datum: IChartBulletDatum
    /** Whether this bullet is currently visible (legend toggle). */
    visible: boolean
    /** Resolved fill colour for the actual-value bar. */
    barFill: string
    /** Resolved stroke colour for the target tick. */
    targetStroke: string
    /** Resolved fills for each range band, parallel to datum.ranges. */
    rangeFills: Array<string>
    /** SVG x of the bullet slot origin (horizontal: left edge; vertical: top edge). */
    slotX: number
    /** SVG y of the bullet slot origin. */
    slotY: number
    /** Total slot width (horizontal: plot width; vertical: slot column width). */
    slotW: number
    /** Total slot height (horizontal: slot row height; vertical: plot height). */
    slotH: number
    /** Maximum axis value = max(ranges[-1].to, target, value). */
    maxRange: number
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-bullet.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('61865ad1-1e15-463e-b411-31561298801a', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-bullet-datum', 'IChartBulletDatum', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_bullet_datum.description', 'Bullet data payload for a single series entry in a bullet chart. Combines the actual value, the target / goal value, and the qualitative range bands that form the background.', 'export interface IChartBulletDatum {
    /** Actual (measured) value. Drives the solid foreground bar. */
    value: number
    /** Target / goal value. Rendered as a thin cross-tick. */
    target: number
    /**
     * Qualitative range bands rendered behind the bars.
     * At least one band is required; three is the Stephen Few
     * recommendation (poor / acceptable / good).
     */
    ranges: Array<IChartBulletRange>
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-bullet.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('96903039-7a6e-402f-bb0c-41a8d0cda27a', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-bullet-props', 'IChartBulletProps', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_bullet_props.description', 'Props for <OrigamChartBullet> — the bullet / KPI chart family. Each series entry renders one bullet combining range bands, an actual-value bar, and a target marker tick (Stephen Few design).', 'export interface IChartBulletProps extends IChartBaseProps {
    /**
     * Category labels — one per series entry. Rendered beside each
     * bullet. Falls back to `series[i].name` when omitted.
     */
    categories?: Array<string>
    /**
     * Fill colour for the actual-value bar. Accepts a TIntent token or
     * a raw CSS colour. Default `''primary''`.
     */
    barColor?: TIntent | string
    /**
     * Stroke colour for the target marker tick. Default `''danger''`.
     */
    targetColor?: TIntent | string
    /**
     * Fallback palette used when `range.color` is omitted. Cycled in
     * array order across bands. Default `[''danger'', ''warning'', ''success'']`.
     */
    rangeColors?: Array<TIntent | string>
    /**
     * Layout direction. `''horizontal''` renders bullets as rows (label
     * left, bar extending right). `''vertical''` renders bullets as
     * columns (label below, bar extending upward). Default
     * `''horizontal''`.
     */
    orientation?: TChartBulletOrientation
    /**
     * Thickness of the actual-value bar as a fraction of the slot
     * height (horizontal) or slot width (vertical). Range [0, 1].
     * Default `0.45`.
     */
    barThickness?: number
    /**
     * Show the quantitative axis. Default `true`.
     */
    showAxis?: boolean
    /**
     * X-axis tick formatter — applied to axis tick labels.
     */
    xAxisFormat?: (value: string | number) => string
    /**
     * Y-axis tick formatter — applied to axis tick labels (vertical
     * orientation).
     */
    yAxisFormat?: (value: number) => string
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-bullet.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
