}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-drilldown.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('80dce086-7c52-4ef6-8e5d-28c252253f44', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-drilldown-props', 'IChartDrilldownProps', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_drilldown_props.description', 'Chart-level prop that wires up the drilldown feature on <OrigamChartCartesian> or <OrigamChartPolar>. Supplies the bank of sub-datasets and an optional Back button label for the breadcrumb navigation.', 'export interface IChartDrilldownProps {
    /**
