INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5ad1dfbe-79e0-4ff8-9183-b22b9feafbd3', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-pareto-props', 'IChartParetoProps', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_pareto_props.description', 'Props for <OrigamChartPareto> — combines vertical columns sorted descending by value with a cumulative percentage line on a secondary right Y-axis. Typical uses: quality control, root-cause analysis, 80/20 rule. Extends IChartBaseProps.', 'export interface IChartParetoProps extends IChartBaseProps {
    /**
     * Colour of all columns. Accepts a `TIntent` token or any raw CSS
     * colour string. Default `''primary''`.
     */
    barColor?: TIntent | string
    /**
     * Colour of the cumulative percentage line. Accepts a `TIntent` token
     * or any raw CSS colour string. Default `''danger''`.
     */
    lineColor?: TIntent | string
    /**
     * Gap in SVG pixels between adjacent columns. Default `4`.
     */
    barGap?: number
    /**
     * Whether to render the cumulative percentage line. Default `true`.
     */
    showLine?: boolean
    /**
     * Whether to show a value label above each column. Default `false`.
     */
    showLabel?: boolean
    /**
     * Render X (category) and Y (value + percentage) axes. Default `true`.
     */
    showAxis?: boolean
    /**
     * Render horizontal grid lines aligned with Y-axis ticks. Default `true`.
     */
    showGrid?: boolean
    /**
     * Formatter applied to X-axis category tick labels.
     * When omitted the category string is shown as-is.
     */
    xAxisFormat?: (value: string | number) => string
    /**
     * Formatter applied to the left Y-axis (value) tick labels.
     * When omitted the raw number is used.
     */
    yAxisFormat?: (value: number) => string
    /**
     * Formatter applied to the right Y-axis (cumulative %) tick labels.
     * Default formats as rounded integer percentage, e.g. `"80%"`.
     */
    cumulativeFormat?: (value: number) => string
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-pareto.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5426a079-75c0-482c-9f5e-41ccea27397b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-pareto-slots', 'IChartParetoSlots', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_pareto_slots.description', 'Slot signatures exposed by <OrigamChartPareto>. Extends IChartBaseSlots with a rich tooltip slot that exposes the full bar descriptor including share and cumulative percentage.', 'export interface IChartParetoSlots extends IChartBaseSlots {
    /**
     * Custom tooltip content.
     * Receives the full bar descriptor so consumers can show share + cumulative.
     */
    tooltip?: (bindings: {
        point: IChartPoint
        category: string
        value: number
        formattedValue: string
        share: number
        cumulative: number
        color: string
    }) => any
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-pareto.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7e314e19-0015-42cb-b1b6-d33d5dc55c3f', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-path', 'IChartPath', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_path.description', 'Output of useChart() — one path descriptor per series (or per data point for bar/column/scatter/pie). The component renders each entry inside a <g> according to kind.', 'export interface IChartPath {
    seriesIndex: number
    /**
     * SVG element kind to emit. `path` for line/area/pie/donut/
     * radar, `rect` for bar/column, `circle` for scatter +
     * line/area markers.
     */
    kind: ''path'' | ''rect'' | ''circle'' | ''polygon''
    /** Pre-computed `d` attribute for `kind === ''path'' | ''polygon''`. */
    d?: string
    /** Geometry for `kind === ''rect''`. */
    rect?: { x: number, y: number, width: number, height: number }
    /** Geometry for `kind === ''circle''`. */
    circle?: { cx: number, cy: number, r: number }
    /** Resolved CSS colour string. */
    color: string
    /** Original series reference (for tooltip / legend). */
    series: IChartSeries
    /** Optional data index when the path represents a single point. */
    dataIndex?: number
    /** Length of the path (used by stroke-dashoffset animation). */
    pathLength?: number
    /**
     * Sub-kind for `kind === ''path''`. Area charts emit two paths per
     * series — the filled area down to the baseline (`variant: ''fill''`)
     * and the overlaid stroke (`variant: ''stroke''`). The component reads
     * the variant to decide whether to paint `fill` or `stroke`.
     */
    variant?: ''fill'' | ''stroke''
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b692ce67-cd01-42d6-b508-9e56c1be7af3', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-pictorial-column', 'IChartPictorialColumn', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_pictorial_column.description', 'One column descriptor produced by the pictorial geometry engine. Holds pre-computed positions for background and filled icon grids, enabling the <OrigamChartPictorial> template to render each isotype column.', 'export interface IChartPictorialColumn {
    /** Series index (0-based). */
    seriesIndex: number
    /** Data index within the series. */
    dataIndex: number
    /** Category label (from `categories[dataIndex]` or fallback). */
    category: string
    /** Raw numeric value from `series[seriesIndex].data[dataIndex]`. */
    value: number
    /** Pre-formatted value string. */
    formatted: string
    /** Total icon slots in this column (background capacity). */
    totalSlots: number
    /** Number of filled icon slots. */
    filledSlots: number
    /** Resolved fill CSS colour string. */
    color: string
    /** X translation for the column group (SVG coordinate). */
    x: number
    /** Y translation for the column group (SVG coordinate). */
    y: number
    /** Computed icon size in SVG pixels. */
    iconSize: number
    /** Whether this column is currently visible (legend toggle). */
    visible: boolean
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-pictorial.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b0f0b8be-2cad-42cb-b964-ffb99743b7c7', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-pictorial-props', 'IChartPictorialProps', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_pictorial_props.description', 'Props for <OrigamChartPictorial> — the pictorial / isotype family. Each data value is represented as a column of repeated SVG icons; filled icons count = Math.round(value / iconsPerUnit). Extends IChartBaseProps with icon appearance, direction, and rendering mode.', 'export interface IChartPictorialProps extends IChartBaseProps {
    /**
     * SVG `<path d="…">` string for the icon drawn in each slot.
     * Must fit a `viewBox="0 0 24 24"` coordinate system.
     * Default: person silhouette.
     */
    icon?: string
    /**
     * Colour applied to all filled icons. Accepts a `TIntent` name or
     * any raw CSS colour string. When omitted, colours cycle through
     * `colorScheme` by series index (first series → first colour, etc.).
     */
    iconColor?: TIntent | string
    /**
     * Colour painted on "background" icon slots that are not yet filled.
     * Default `''rgba(0,0,0,0.1)''`.
     */
    emptyIconColor?: string
    /**
     * How many data units one icon represents.
     * E.g. `iconsPerUnit=10` → a value of 65 renders 7 filled icons
     * (rounded). Default `1`.
     */
    iconsPerUnit?: number
    /**
     * Stacking direction.
     * - `''vertical''` — icons stacked bottom-to-top (traditional column).
     * - `''horizontal''` — icons stacked left-to-right.
     * Default `''vertical''`.
     */
    direction?: TChartPictorialDirection
    /**
     * Rendering mode.
     * - `''stack''` — classic isotype: rows of small repeated icons (default).
     * - `''fill''` — one large icon per category, clip-masked from the bottom
     *   up to the fill ratio, like a thermometer / glass fill effect.
     *   The unfilled portion shows the icon silhouette as a faint "shadow".
     */
    mode?: TChartPictorialMode
    /**
     * Display the raw value label above (vertical) or to the right
     * (horizontal) of each column. Default `true`.
     */
    showLabel?: boolean
    /**
     * Display the X-axis category labels. Default `true`.
     */
    showAxis?: boolean
    /**
     * X-axis / category label formatter. Identity by default.
     */
    xAxisFormat?: (value: string | number) => string
    /**
     * Y-axis / value formatter. `String(value)` by default.
     */
    yAxisFormat?: (value: number) => string
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-pictorial.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4ccd0a92-0070-4e28-9646-9127e2bb5b3a', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-checkbox-btn-props', 'ICheckboxBtnProps', 'Form & Input', NULL, NULL, 'interfaces.catalog.i_checkbox_btn_props.description', 'Props for <OrigamCheckboxBtn>. Extends ISelectionControlProps with indeterminate state support — the third visual state between checked and unchecked.', 'export interface ICheckboxBtnProps extends ICommonsComponentProps, ISelectionControlProps {
    indeterminate?: boolean
    indeterminateIcon?: TIcon
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Checkbox/checkbox-btn.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8ae8d8cf-885c-4391-852d-cabcc18b6ccf', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-plot-band', 'IChartPlotBand', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_plot_band.description', 'A coloured rectangular zone drawn behind (or above) chart data, spanning a numeric range along either the X or Y axis. Applicable to cartesian-family charts only — not for polar, radar or gauge.', 'export interface IChartPlotBand {
    /**
     * Axis the band spans. `''y''` shades a horizontal stripe;
     * `''x''` shades a vertical stripe. Default `''y''`.
     */
    axis?: ''x'' | ''y''
    /** Lower bound in axis units. String when `axis=''x''` and categories are strings. */
    from: number | string
    /** Upper bound in axis units. */
    to: number | string
    /**
     * Fill colour. Accepts a `TIntent` token name or any CSS colour string.
     * Default resolves to the `warning` intent bg token.
     */
    color?: TIntent | string
    /** Fill opacity in the 0..1 range. Default `0.15`. */
    opacity?: number
    /** Optional label rendered centred inside the band. */
    label?: string
    /** Label fill colour. Accepts a `TIntent` token or CSS colour. Default `''currentColor''`. */
    labelColor?: TIntent | string
    /**
     * Z-order relative to chart data.
     * - `''below''` (default) — drawn behind series paths / bars / points.
     * - `''above''` — drawn on top of data.
     */
    layer?: ''below'' | ''above''
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-plot-band.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('fb46de2f-2499-4d38-849a-c48f0dbde125', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-plot-line', 'IChartPlotLine', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_plot_line.description', 'A single threshold line drawn at a fixed axis value, either horizontally (Y-axis) or vertically (X-axis). Applicable to cartesian-family charts only — not for polar, radar or gauge.', 'export interface IChartPlotLine {
    /**
     * Axis the line is perpendicular to. `''y''` draws a horizontal
     * line at a Y value; `''x''` draws a vertical line at an X value.
     * Default `''y''`.
     */
    axis?: ''x'' | ''y''
    /** Position on the axis in axis units. String when `axis=''x''` and categories are strings. */
    value: number | string
    /**
     * Stroke colour. Accepts a `TIntent` token name or any CSS colour string.
     * Default resolves to the `danger` intent bg token.
     */
    color?: TIntent | string
    /** Stroke width in SVG user units. Default `1.5`. */
    width?: number
    /** Dash pattern of the line. Default `''dashed''`. */
    dash?: ''solid'' | ''dashed'' | ''dotted''
    /** Optional label placed at the end of the line. */
    label?: string
    /**
     * Horizontal alignment of the label for Y-axis lines.
     * `''right''` (default) places the label at the right edge;
     * `''left''` at the left edge.
     */
    labelAlign?: ''left'' | ''right''
    /**
     * Z-order relative to chart data.
     * - `''below''` — drawn behind series.
     * - `''above''` (default) — drawn on top of data so the line remains visible.
     */
    layer?: ''below'' | ''above''
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-plot-line.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('52b2f2ef-5d3d-4199-9fb8-5330aa7d45be', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-point', 'IChartPoint', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_point.description', 'Hover / click payload bubbled by <OrigamChart> whenever a data point is interacted with. Fields are denormalised — the consumer does not need to re-look-up the series or resolve the colour from the palette.', 'export interface IChartPoint {
    /** Index of the series in `props.series`. */
    seriesIndex: number
    /** Series name (mirrors `IChartSeries.name`). */
    seriesName: string
    /** Index of the data point inside the series. */
    dataIndex: number
    /** X coordinate (number or category string). */
    x: number | string
    /** Y value. */
    y: number
    /** Resolved CSS colour string (intent → token → CSS or raw). */
    color: string
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-point.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d6c46dd0-328d-415e-87f6-103911bfc624', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-polar-bar-props', 'IChartPolarBarProps', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_polar_bar_props.description', 'Props for <OrigamChartPolarBar> — the polar bar (nightingale-rose) family. A single series of N data points is rendered as N wedge-shaped arcs arranged radially. Commonly used for cyclical data (hours per day, monthly activity). Extends IChartBaseProps.', 'export interface IChartPolarBarProps extends IChartBaseProps {
    /**
     * Fraction of the total radius reserved as a centre hole.
     * `0` = no hole (wedges meet at the centre point).
     * `1` = zero-thickness ring.
     * Default `0.1`.
     */
    innerRadius?: number
    /**
     * Start angle in radians for the first wedge.
     * `0` = 3 o''clock (standard mathematical).
     * `-Math.PI / 2` = 12 o''clock (conventional chart orientation).
     * Default `0`.
     */
    startAngle?: number
    /**
     * Angular gap between consecutive wedges in radians.
     * `0` = no gap (wedges are flush).
     * Default `0.02`.
     */
    gap?: number
    /**
     * Override the auto-computed maximum value used to scale wedge radii.
     * When omitted, `max(series[0].data)` is used.
     */
    maxValue?: number
    /**
     * Render the category label outside the outer radius of each wedge.
     * Default `true`.
     */
    showLabel?: boolean
    /**
     * Render the numeric value label inside the wedge when there is
     * sufficient angular room. Default `false`.
     */
    showValue?: boolean
    /**
     * Formatter applied to the tooltip X label (category name / index).
     */
    xAxisFormat?: (value: string | number) => string
    /**
     * Formatter applied to the tooltip Y value and the in-wedge value label.
     */
    yAxisFormat?: (value: number) => string
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-polar-bar.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9ba84b8b-41c8-4fe4-ba0f-ab9ba87e389f', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-polar-bar-slots', 'IChartPolarBarSlots', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_polar_bar_slots.description', 'Slot signatures exposed by <OrigamChartPolarBar>. Extends IChartBaseSlots with an enriched tooltip slot that also receives the pre-computed percentage string for the hovered wedge.', 'export interface IChartPolarBarSlots extends IChartBaseSlots {
    /**
     * Replace the default tooltip body. Receives the standard bindings
     * plus the pre-computed percentage string for this wedge.
     */
    tooltip?: (bindings: {
        point: IChartPoint
        category: string | number
        percentage: string
    }) => any
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-polar-bar.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
