    /** SVG `text-anchor` for the category label. */
    labelAnchor: ''start'' | ''middle'' | ''end''
    /** Percentage of total as a formatted string (e.g. `"23.4%"`). */
    percentage: string
    /** Whether the wedge is wide enough to host a value label inside. */
    showValueLabel: boolean
    /** X coordinate of the in-wedge value label. */
    valueLabelX: number
    /** Y coordinate of the in-wedge value label. */
    valueLabelY: number
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-polar-bar.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('174a875b-e569-4919-8387-f84996bdf98f', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-polar-emits', 'IChartPolarEmits', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_polar_emits.description', 'Emits surfaced by <OrigamChartPolar>. Extends IChartBaseEmits with drilldown events — fired when the user navigates into a sub-dataset or navigates back one level.', 'export interface IChartPolarEmits extends IChartBaseEmits {
    /** Fired when the user drills into a sub-dataset. */
    (e: ''drill'', link: IChartDrilldownLink, point: IChartPoint): void
    /** Fired when the user navigates back one drilldown level. */
    (e: ''drill-up''): void
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-polar.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('07ae3876-5e15-4362-b5d9-06c0a679a73b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-polar-props', 'IChartPolarProps', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_polar_props.description', 'Props for <OrigamChartPolar> — handles pie and donut visualisations. No axes, no grid, no tick labels. Extends IChartBaseProps with polar-specific options including donut hole size, drilldown configuration, and axis formatters.', 'export interface IChartPolarProps extends IChartBaseProps {
    /** Polar visualisation primitive. Default `''pie''`. */
    type?: TChartPolarKind
    /**
     * Inner-radius proportion for `''donut''`. `0` collapses to a
     * pie, `1` to a zero-thickness ring. Ignored when
     * `type=''pie''`. Default `0.6`.
     */
    donutHoleSize?: number
    /** Toggle the hover tooltip. Default `true`. */
    showTooltip?: boolean
    /**
     * Formatter applied to the tooltip X label. Pie tooltips
     * show the category name + value.
     */
    xAxisFormat?: (value: string | number) => string
    /** Formatter applied to the tooltip Y value. */
    yAxisFormat?: (value: number) => string
    /**
     * Drilldown configuration. When provided, data points that carry
     * an `IChartDrilldownLink` in their object-form entry trigger a
     * chart-level navigation instead of (or alongside) `point-click`.
     * A breadcrumb `<nav>` appears above the chart when depth > 1.
     */
    drilldown?: IChartDrilldownProps
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-polar.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0e398ed7-b168-4ec0-acde-c83de9c1e28f', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-props', 'IChartProps', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_props.description', 'Props accepted by <OrigamChart> — the universal chart component supporting eight visualisation primitives (line, area, bar, column, scatter, pie, donut, radar, gauge). The type prop selects the path generator inside useChart. Extends ICommonsComponentProps, IDimensionProps, IMarginProps, IPaddingProps, IRoundedProps, IElevationProps, IBgColorProps.', 'export interface IChartProps
    extends ICommonsComponentProps,
        IDimensionProps,
        IMarginProps,
        IPaddingProps,
        IRoundedProps,
        IElevationProps,
        IBgColorProps {
    /** Visualisation primitive. Default `''line''`. */
    type?: TChartType
    /** Data series — one or more. Empty array renders the `#empty` slot. */
    series: Array<IChartSeries>
    /**
     * X axis labels (for line/area/bar/column/radar). Length should
     * match the longest series; missing entries fall back to the
     * numeric index.
     */
    categories?: Array<string>
    /** Optional title rendered above the plotting area. */
    title?: string
    /** Optional subtitle rendered below the title. */
    subtitle?: string
    /** Toggle the legend block. Default `true`. */
    showLegend?: boolean
    /** Anchor of the legend block. Default `''bottom''`. */
    legendPosition?: TChartLegendPosition
    /** Toggle the hover tooltip. Default `true`. */
    showTooltip?: boolean
    /**
     * Render grid lines behind the plot. Ignored for pie/donut/radar.
     * Default `true`.
     */
    showGrid?: boolean
    /** Render X / Y axes + tick labels. Ignored for pie/donut. Default `true`. */
    showAxis?: boolean
    /**
     * Animate paths / bars / slices on first paint and on data
     * changes. Respects `prefers-reduced-motion`. Default `true`.
     */
    animated?: boolean
    /** Animation duration in ms. Default `600`. */
    animationDuration?: number
    /** Stack series on `bar` / `column`. Default `false`. */
    stacked?: boolean
    /**
     * Stacking mode applied when `stacked=true`.
     *
     * - `''normal''`  — raw absolute values (default, matches pre-v2
     *                 `stacked=true` behaviour).
     * - `''percent''` — every stack is normalised to 100 %; Y-axis
     *                 fixed at `0 → 100`, tick labels use `${v}%`.
     */
    stacking?: TChartStacking
    /**
     * Inner-radius proportion for `donut`. `0` collapses to a pie,
     * `1` to a ring of zero thickness. Default `0.6` when
     * `type === ''donut''`, ignored otherwise.
     */
    donutHoleSize?: number
    /**
     * Palette used when a series does not pin its own `color`.
     * Pass intent strings (cycled in order) or raw CSS colours.
     * Default cycles through the 8 origam intents.
     */
    colorScheme?: Array<TIntent | string>
    /** Formatter applied to X-axis tick labels. */
    xAxisFormat?: (value: string | number) => string
    /** Formatter applied to Y-axis tick labels. */
    yAxisFormat?: (value: number) => string
    /**
     * CSS `aspect-ratio` shortcut (`''16/9''`, `''4/3''`, `''1/1''`…). When
     * set, overrides `height` and lets the chart breathe with the
     * container width.
     */
    aspectRatio?: string
    /**
     * Smoothing strategy for line/area. Default `''none''` —
     * Cartesian segments between points. `''curve''` uses cubic
     * Bezier with Catmull-Rom tangents.
     */
    smoothing?: TChartSmoothing
    /**
     * Override the auto-computed Y min. Useful when the data
     * starts well above zero and you want the visual baseline.
     */
    yMin?: number
    /** Override the auto-computed Y max. */
    yMax?: number
    /**
     * Lower bound of the gauge range. Ignored unless `type=''gauge''`.
     * Default `0`.
     */
    gaugeMin?: number
    /**
     * Upper bound of the gauge range. Ignored unless `type=''gauge''`.
     * Default `100`.
     */
    gaugeMax?: number
    /**
     * Optional unit appended to the gauge centre label
     * (e.g. `''%''`, `'' km/h''`). Ignored unless `type=''gauge''`.
     */
    gaugeUnit?: string
    /**
     * Coloured rectangular zones drawn behind (or above) the chart
     * data. Forwarded to `<OrigamChartCartesian>` only — ignored for
     * polar / radar / gauge families.
     */
    plotBands?: Array<IChartPlotBand>
    /**
     * Threshold lines drawn at a fixed axis value. Forwarded to
     * `<OrigamChartCartesian>` only — ignored for polar / radar / gauge.
     */
    plotLines?: Array<IChartPlotLine>
    /**
     * Overlay annotations drawn on top of the series layer. Forwarded to
     * `<OrigamChartCartesian>` only — ignored for polar / radar / gauge /
     * other non-cartesian families. Annotations are positioned in data
     * coordinates. Four kinds: `''arrow''`, `''label''`, `''circle''`, `''bracket''`.
     */
    annotations?: Array<IChartAnnotation>
    /**
     * Drilldown configuration forwarded to `<OrigamChartCartesian>` and
     * `<OrigamChartPolar>`. Ignored by other families (radar, gauge, …).
     */
    drilldown?: IChartDrilldownProps
    /**
     * Secondary (right-hand) Y axis configuration. Forwarded to
     * `<OrigamChartCartesian>` only — ignored for other families.
     * When absent the engine ignores `series.yAxis === 1` assignments.
     */
    secondaryYAxis?: IChartSecondaryYAxis
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1a7f74d7-66ab-4c5f-a804-5dfcd8ecbae0', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-pyramid-props', 'IChartPyramidProps', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_pyramid_props.description', 'Props for <OrigamChartPyramid> — the pyramid / funnel family. A single series of N data points is rendered as N horizontal trapezoids stacked vertically. type="funnel" = widest at top (conversion funnel); type="pyramid" = widest at bottom. Extends IChartBaseProps.', 'export interface IChartPyramidProps extends IChartBaseProps {
    /**
     * Rendering mode. `''funnel''` = widest at top; `''pyramid''` =
     * widest at bottom. Default `''funnel''`.
     */
    type?: TChartPyramidKind
    /**
     * Gap between consecutive trapezoid slices, in SVG pixels.
     * Default `4`.
     */
    sliceGap?: number
    /**
     * Whether to render the category name + value inside each slice
     * when the slice is large enough, or beside it when it is not.
     * `''inside''` — label always inside the trapezoid.
     * `''outside''` — label always beside the trapezoid.
     * `''auto''`  — inside when the slice height ≥ 28px, outside
     *              otherwise. Default `''auto''`.
     */
    labelPlacement?: ''inside'' | ''outside'' | ''auto''
    /**
     * X-axis / value formatter applied to the per-slice value label.
     * When omitted the raw number is displayed.
     */
    xAxisFormat?: (value: string | number) => string
    /**
     * Y-axis formatter — alias kept for API symmetry with other
     * families. Same as `xAxisFormat` for this geometry.
     */
    yAxisFormat?: (value: number) => string
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-pyramid.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b21e186a-b9a8-4af5-b24c-45f2be97b509', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-pyramid-slice', 'IChartPyramidSlice', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_pyramid_slice.description', 'Single slice descriptor produced by the pyramid geometry engine. Exposes the pre-computed SVG <path d="…"> for the trapezoid, the label anchor position, and all data needed to render accessibility text and tooltip content.', 'export interface IChartPyramidSlice {
    /** Slice index in the original data array. */
    index: number
    /** SVG `<path d="…">` for the trapezoid. */
    d: string
    /** Resolved CSS colour string. */
    color: string
    /** Category label (from `categories[index]` or fallback). */
    category: string
    /** Raw numeric value from `series.data[index]`. */
    value: number
    /** Pre-formatted value string. */
    formatted: string
    /** Whether this slice is currently visible (legend toggle). */
    visible: boolean
    /**
     * Label anchor — centre of the trapezoid face for `inside`
     * placement; right-edge midpoint + offset for `outside`.
     */
    labelX: number
    labelY: number
    /** SVG `text-anchor` attribute matching `labelX` placement. */
    labelAnchor: ''middle'' | ''start''
    /** Y of the leader-line target (band right edge midpoint). */
    leaderX: number
    /** `true` when the band is wide enough to host the label inside. */
    labelFitsInside: boolean
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-pyramid.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('38023c37-4654-4d56-a911-26cdf9495f6c', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-range-selector', 'IChartRangeSelector', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_range_selector.description', 'Configuration for the optional band-style range-selector toolbar rendered above <OrigamChartCartesian>. When enabled, displays a set of buttons that let the user select a visible time window over the full dataset.', 'export interface IChartRangeSelector {
    /** Show the range-selector toolbar. Default `false`. */
    enabled?: boolean
    /**
     * Buttons to display. Defaults to a standard set when omitted:
     * `1w / 1m / 3m / 6m / 1y / all`.
     */
    buttons?: Array<IChartRangeSelectorButton>
    /** Zero-based index of the initially selected button. */
    selected?: number
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-range-selector.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2f5f3ff1-b066-4626-9ec2-be3e88a3f96d', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-range-selector-button', 'IChartRangeSelectorButton', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_range_selector_button.description', 'A single button in the range-selector toolbar. Exactly one of count or fraction must be provided: count = number of categories from the right edge to show; fraction = fraction of the full category range to show (0..1).', 'export interface IChartRangeSelectorButton {
    /** Short label rendered on the button. E.g. `"1w"`, `"1m"`, `"all"`. */
    label: string
    /**
     * Number of categories from the trailing edge of the data to
     * include in the visible window. Ignored when `fraction` is set.
     */
    count?: number
    /**
     * Fraction of the total category count to show (0 exclusive, 1 inclusive).
     * `fraction: 1` is equivalent to "all". Ignored when `count` is set.
     */
    fraction?: number
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-range-selector.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0c1688e2-570a-42d6-ad18-446e676212f1', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-sankey-datum', 'IChartSankeyDatum', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_sankey_datum.description', 'A single flow datum in the Sankey series. from and to are node name strings — nodes are inferred automatically from the full set of unique names. value must be >= 0. An optional color override accepts a TIntent token or raw CSS colour.', 'export interface IChartSankeyDatum {
    /** Source node name. */
    from: string
    /** Target node name. */
    to: string
    /** Flow magnitude. Must be ≥ 0. */
    value: number
    /**
     * Optional per-link colour override. Accepts a design-system intent
     * token (`TIntent`) or any raw CSS colour string. When absent the
     * source node''s colour is used.
     */
    color?: TIntent | string
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-sankey.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e98a9c60-48ee-4952-b671-5d3208402be8', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-sankey-link', 'IChartSankeyLink', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_sankey_link.description', 'Internal link descriptor for each IChartSankeyDatum after Sankey layout. Carries the rendered SVG cubic Bezier path d attribute, visual metadata and resolved colour. Produced by the Sankey layout engine — not intended for direct consumer use.', 'export interface IChartSankeyLink {
    /** Index in the original data array. */
    index: number
    /** Source node name. */
    from: string
    /** Target node name. */
    to: string
    /** Raw numeric flow value. */
    value: number
    /** Pre-formatted value string. */
    formatted: string
    /** Rendered SVG cubic Bezier path string. */
    d: string
    /** Resolved CSS stroke colour string (defaults to source node color). */
    color: string
    /** Stroke width in SVG user units. */
    strokeWidth: number
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-sankey.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6eed5b7b-f29b-4ea8-a2f1-0a2d3a9d8897', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-sankey-node', 'IChartSankeyNode', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_sankey_node.description', 'Internal node descriptor produced by the Sankey layout engine. All coordinates are in SVG-user-unit space. Nodes are inferred from the union of all from and to strings in IChartSankeyDatum; column is assigned by topological depth (Kahn''s algorithm).', 'export interface IChartSankeyNode {
    /** Unique node name (inferred from `from` / `to` values). */
    name: string
    /** Column index (0-based topological depth). */
    column: number
    /** Total flow value (max of incoming and outgoing sums). */
    value: number
    /** Pre-formatted value string. */
    formatted: string
    /** Resolved CSS colour string. */
    color: string
    /** SVG x coordinate of the node rect''s left edge. */
    x: number
    /** SVG y coordinate of the node rect''s top edge. */
    y: number
    /** Node rect height in SVG user units, proportional to value. */
    height: number
    /** Accumulated outgoing y offset (used during link placement). */
    outgoingOffset: number
    /** Accumulated incoming y offset (used during link placement). */
    incomingOffset: number
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-sankey.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9ba99866-7489-4aac-956c-ccc522d1b7b8', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-sankey-props', 'IChartSankeyProps', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_sankey_props.description', 'Props for <OrigamChartSankey>. The component consumes series[0] only — each item in series[0].data must conform to IChartSankeyDatum ({ from, to, value }). Nodes are inferred automatically; columns are assigned by topological depth. Extends IChartBaseProps.', 'export interface IChartSankeyProps extends IChartBaseProps {
    /**
     * Width of each node rectangle in SVG pixels. Default `16`.
     */
    nodeWidth?: number
    /**
     * Minimum vertical gap between sibling nodes within the same column,
     * in SVG pixels. Default `8`.
     */
    nodePadding?: number
    /**
     * Opacity of the flow ribbons (links). Range [0, 1]. Default `0.4`.
     */
    linkOpacity?: number
    /**
     * Whether to render node labels. Left-column nodes are right-aligned
     * outside their rect; right-column nodes are left-aligned outside.
     * Default `true`.
     */
    showLabel?: boolean
    /**
     * X-axis / value formatter applied to node labels and tooltip values.
     * When omitted the raw number is displayed.
     */
    xAxisFormat?: (value: number | string) => string
    /**
     * Y-axis formatter — alias kept for API symmetry with other
     * families. Same as `xAxisFormat` for this geometry.
     */
    yAxisFormat?: (value: number) => string
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-sankey.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
