     */
    ''node-label''?: (bindings: {
        name: string
        value: number
        formatted: string
        color: string
        column: number
    }) => any
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-sankey.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e694181d-4704-4e26-a6e8-289af4efd8a4', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-scales', 'IChartScales', 'Data Visualisation', NULL, NULL, 'interfaces.catalog.i_chart_scales.description', 'Pair of pixel-mapping functions produced by useChart from the data range and viewBox size. Pure functions — safe to call from computed refs. x maps a value or category index to an SVG horizontal coordinate; y maps a numeric value to an SVG vertical coordinate.', 'export interface IChartScales {
    x: (value: number | string, dataIndex?: number, categoryCount?: number) => number
    y: (value: number) => number
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c176f601-0ab2-4a03-94e0-c0326e83d7c0', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-secondary-y-axis', 'IChartSecondaryYAxis', 'Data Visualisation', NULL, NULL, 'interfaces.catalog.i_chart_secondary_y_axis.description', 'Configuration object for the secondary (right-hand) Y axis on a cartesian chart. When passed to secondaryYAxis on OrigamChartCartesian, series with yAxis: 1 are projected against this scale. Omit to use the primary left axis only.', 'export interface IChartSecondaryYAxis {
    /** Force the minimum value of the secondary Y scale. Auto-computed when absent. */
    min?: number
    /** Force the maximum value of the secondary Y scale. Auto-computed when absent. */
    max?: number
    /** Formatter applied to the right-axis tick labels. */
    format?: (value: number) => string
    /** Optional axis title rendered alongside the right axis. */
    title?: string
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-axis.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('939bab84-0869-4152-b9ce-9ebe3ecc69a4', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-series', 'IChartSeries', 'Data Visualisation', NULL, NULL, 'interfaces.catalog.i_chart_series.description', 'A single data series rendered by OrigamChart. The data field accepts either a flat number array (values aligned to categories by index) or an object array of IChartSeriesPoint for explicit x/y coordinates — required for scatter and sparse data.', 'export interface IChartSeries {
    /** Display name in the legend + screen-reader description. */
    name: string

    /**
     * Series data. Numbers are aligned to `categories[index]`.
     * Objects carry their own X coordinate (numeric or category
     * string), useful for scatter and irregular sampling.
     */
    data: Array<number> | Array<IChartSeriesPoint>

    /**
     * Intent token (`primary`, `success`, …) or raw CSS colour
     * (`#ff0080`, `rgb(…)`). When absent, the chart pulls the
     * next colour from `colorScheme` cycling by series index.
     */
    color?: TIntent | string

    /**
     * Whether the series is currently visible. Driven from the
     * legend click (`legend-click` → `series-toggle`). Default
     * `true`.
     */
    visible?: boolean

    /**
     * Override the chart-level `type` for this series only.
     * Enables mix charts (a `column` chart with a `line`
     * overlay on top).
     */
    type?: TChartType

    /**
     * Which Y axis this series is mapped to.
     * `0` (default) = left primary axis, `1` = right secondary axis.
     * Only meaningful for cartesian chart families (line, area, bar,
     * column, scatter, spline, stepped-line). Ignored for pie, donut,
     * radar, and gauge.
     */
    yAxis?: 0 | 1
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-series.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('51420870-ceff-4002-ba43-425cd31e6145', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-series-point', 'IChartSeriesPoint', 'Data Visualisation', NULL, NULL, 'interfaces.catalog.i_chart_series_point.description', 'Object form of a single data point inside IChartSeries.data. Required for scatter charts where the X axis is not a simple categories[index]. The optional z field turns the point into a bubble by scaling its dot radius.', 'export interface IChartSeriesPoint {
    /** X coordinate (numeric for scatter, string for categorical). */
    x: number | string
    /** Y value mapped to the vertical scale. */
    y: number
    /** Optional friendly label (overrides `x` in tooltips). */
    name?: string
    /**
     * Third dimension for `scatter` — turns the chart into a
     * bubble plot where the dot RADIUS scales with `z`. Useful
     * when each (x, y) coordinate carries an associated magnitude
     * (sample size, population, score, …). When absent the point
     * keeps the default fixed radius.
     */
    z?: number
    /**
     * Drilldown reference. When present and the chart has a matching
     * `IChartDrilldownDataset`, clicking this point replaces the chart
     * view with the sub-dataset.
     */
    drilldown?: IChartDrilldownLink
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-series.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('63872785-1acd-4388-835a-ac4aabd2f075', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-slots', 'IChartSlots', 'Data Visualisation', NULL, NULL, 'interfaces.catalog.i_chart_slots.description', 'Slot signatures for the universal OrigamChart component. Replace the default tooltip card, a legend entry, the title block, or the empty state without losing the rest of the chart chrome.', 'export interface IChartSlots {
    /** Replace the default tooltip body. */
    tooltip?: (bindings: { point: IChartPoint, series: IChartSeries, category: string | number }) => any
    /** Replace one legend entry. */
    ''legend-item''?: (bindings: { series: IChartSeries, index: number, visible: boolean }) => any
    /** Replace the title block (title + subtitle). */
    title?: () => any
    /** Render when `series` is empty / every series is hidden. */
    empty?: () => any
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('bed8725d-8cfd-4192-b62f-954663f0e250', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-sparkline-emits', 'IChartSparklineEmits', 'Data Visualisation', NULL, NULL, 'interfaces.catalog.i_chart_sparkline_emits.description', 'Emits surfaced by OrigamChartSparkline. Single event — point-click — fired on mouse click or keyboard activation on a data point, providing the IChartPoint payload and the originating DOM event.', 'export interface IChartSparklineEmits {
    /** Mouse / keyboard activation on a data point. */
    (e: ''point-click'', point: IChartPoint, originalEvent: MouseEvent | KeyboardEvent): void
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-sparkline.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('87a886ee-e382-4a88-87a9-26a183a64707', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-sparkline-kind', 'IChartSparklineKind', 'Data Visualisation', NULL, NULL, 'interfaces.catalog.i_chart_sparkline_kind.description', 'Internal marker descriptor for a highlighted circle rendered on the sparkline SVG. Used by the min / max / last indicator rendering logic inside OrigamChartSparkline.', 'export interface IChartSparklineKind {
    /** SVG cx coordinate. */
    cx: number
    /** SVG cy coordinate. */
    cy: number
    /** Circle radius in SVG pixels. */
    r: number
    /** Resolved CSS fill colour. */
    fill: string
    /** Role of this marker (min / max / last). */
    role: ''min'' | ''max'' | ''last''
    /** Data index this marker corresponds to. */
    dataIndex: number
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-sparkline.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('32219b9d-87cb-40f5-a4ad-b03fdfea1355', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-sparkline-props', 'IChartSparklineProps', 'Data Visualisation', NULL, NULL, 'interfaces.catalog.i_chart_sparkline_props.description', 'Props for OrigamChartSparkline — the tiny inline-chart family. Sparklines are compact data visualisations for embedding in table cells, KPI cards and dashboards. They have no axes, no legend, no grid by default. Extends IChartBaseProps omitting series, showLegend, legendPosition and colorScheme.', 'export interface IChartSparklineProps extends Omit<IChartBaseProps, ''series'' | ''showLegend'' | ''legendPosition'' | ''colorScheme''> {
    /** Single data series. Data must be `Array<number>`. */
    series: Array<IChartSeries>

    /**
     * Rendering mode.
     * `''line''` — polyline connecting data points.
     * `''area''` — line with a translucent fill below.
     * `''column''` — vertical bars.
     * `''bar''` — horizontal bars.
     * Default `''line''`.
     */
    type?: TChartSparklineKind

    /**
     * Stroke / fill intent or raw CSS colour.
     * Default `''primary''`.
     */
    color?: TIntent | string

    /**
     * Stroke width for line and area modes (SVG pixels).
     * Default `1.5`.
     */
    lineWidth?: number

    /**
     * Render a filled circle marker at every data point.
     * Only meaningful for `''line''` and `''area''` modes.
     * Default `false`.
     */
    showMarkers?: boolean

    /**
     * Highlight the minimum value point in red.
     * Default `false`.
     */
    showMin?: boolean

    /**
     * Highlight the maximum value point in green.
     * Default `false`.
     */
    showMax?: boolean

    /**
     * Highlight the last data point in the primary colour.
     * Default `true`.
     */
    showLast?: boolean

    /**
     * Radius of highlighted marker circles (SVG pixels).
     * Default `2.5`.
     */
    markerSize?: number

    /**
     * CSS width of the sparkline container.
     * Accepts a number (px) or a CSS string (`''100%''`, `''8rem''`).
     * Default `120`.
     */
    width?: number | string

    /**
     * CSS height of the sparkline container.
     * Accepts a number (px) or a CSS string (`''100%''`, `''2rem''`).
     * Default `30`.
     */
    height?: number | string
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-sparkline.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a25cb6bf-5836-4095-9e69-d68726568e8b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-streamgraph-props', 'IChartStreamgraphProps', 'Data Visualisation', NULL, NULL, 'interfaces.catalog.i_chart_streamgraph_props.description', 'Props for OrigamChartStreamgraph. Multiple series are rendered as continuous flowing ribbons stacked over time on the X axis. The baseline offset algorithm is controlled by offsetMode: wiggle (canonical streamgraph), silhouette, expand, or zero.', 'export interface IChartStreamgraphProps extends IChartBaseProps {
    /**
     * Baseline offset algorithm. Default `''wiggle''`.
     */
    offsetMode?: TChartStreamgraphOffset
    /**
     * Path interpolation. `''curve''` applies Catmull-Rom smoothing
     * on each ribbon''s top and bottom polylines. `''none''` uses
     * straight linear segments. Default `''curve''`.
     */
    smoothing?: ''none'' | ''curve''
    /**
     * Toggle the X / Y axis guides. Default `true`.
     */
    showAxis?: boolean
    /**
     * Toggle background grid lines. Default `false`.
     */
    showGrid?: boolean
    /**
     * Formatter applied to each X-axis category label.
     */
    xAxisFormat?: (value: string | number) => string
    /**
     * Formatter applied to Y-axis tick labels.
     */
    yAxisFormat?: (value: number) => string
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-streamgraph.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('021fe623-46a3-4d07-924d-fc721c386d25', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-streamgraph-ribbon', 'IChartStreamgraphRibbon', 'Data Visualisation', NULL, NULL, 'interfaces.catalog.i_chart_streamgraph_ribbon.description', 'Pre-computed ribbon descriptor produced by the streamgraph geometry engine for a single series at a single render pass. Contains the resolved SVG path, colour and raw values for tooltip display.', 'export interface IChartStreamgraphRibbon {
    /** Series index in the original `series` array. */
    seriesIndex: number
    /** Display name from `series[i].name`. */
    name: string
    /** Resolved CSS colour for this ribbon. */
    color: string
    /** SVG `<path d="…">` — top forward + bottom reverse, closed. */
    d: string
    /** Whether this ribbon is currently toggled visible. */
    visible: boolean
    /** Raw data values at each X position for tooltip display. */
    values: Array<number>
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-streamgraph.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('56250d64-4544-497e-a9a4-f6522c03d384', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-streamgraph-slots', 'IChartStreamgraphSlots', 'Data Visualisation', NULL, NULL, 'interfaces.catalog.i_chart_streamgraph_slots.description', 'Slot signatures exposed by OrigamChartStreamgraph. Extends IChartBaseSlots with a custom tooltip slot that receives all visible series values at the hovered X position for multi-series breakdown rendering.', 'export interface IChartStreamgraphSlots extends IChartBaseSlots {
    /**
     * Custom tooltip body. Receives every visible series value at
     * the hovered X position so consumers can render a multi-series
     * breakdown row.
     */
    tooltip?: (bindings: {
        point: IChartPoint | null
        series: IChartSeries | null
        category: string | number
        allPoints: Array<{ series: IChartSeries; value: number; color: string }>
    }) => any
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-streamgraph.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f92c7047-1fad-4291-a7a4-8c34ca10537e', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-sunburst-datum', 'IChartSunburstDatum', 'Data Visualisation', NULL, NULL, 'interfaces.catalog.i_chart_sunburst_datum.description', 'A single datum node in the sunburst tree. Internal nodes may omit value — it will be auto-computed as the sum of direct children. The children array forms the next ring outward in the chart.', 'export interface IChartSunburstDatum {
    /** Display name for the node. */
    name: string
    /**
     * Numeric value. Optional for internal nodes: if absent the value
     * equals the sum of direct children.
     */
    value?: number
    /** Override colour for this specific node. */
    color?: TIntent | string
    /** Child nodes — forms the next ring outward. */
    children?: Array<IChartSunburstDatum>
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-sunburst.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3365a55d-e26f-4e9c-a2a7-28f258ed7c95', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-sunburst-node', 'IChartSunburstNode', 'Data Visualisation', NULL, NULL, 'interfaces.catalog.i_chart_sunburst_node.description', 'Fully-resolved node produced by the sunburst geometry engine. Every field is definite — defaults and inherited values have been applied. Contains SVG arc coordinates, resolved colour and the label rendering mode decision.', 'export interface IChartSunburstNode {
    /** Unique path key (`"Root > Branch > Leaf"`). */
    id: string
    /** Display name (copy of `datum.name`). */
    name: string
    /** Resolved numeric value (sum of children when absent in datum). */
    value: number
    /** Tree depth; roots are 0. */
    depth: number
    /** Index within the root-level array (used for colour inheritance). */
    rootIndex: number
    /** Arc start angle in radians [0, 2π). */
    startAngle: number
    /** Arc end angle in radians (0, 2π]. */
    endAngle: number
    /** Inner ring radius for this node (SVG units). */
    innerR: number
    /** Outer ring radius for this node (SVG units). */
    outerR: number
    /** Pre-computed SVG `<path d="…">` for the arc segment. */
    d: string
    /** Resolved CSS colour string (intent var or raw). */
    color: string
    /** Whether this node is currently visible (legend toggle on root). */
    visible: boolean
    /** Full ancestor path string `"Root > Branch > Leaf"`. */
    path: string
    /** How the label for this node should be rendered. */
    labelMode: TChartSunburstLabelMode
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-sunburst.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('62bba3cd-d26c-4b6a-a387-9c5024f3d634', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-sunburst-props', 'IChartSunburstProps', 'Data Visualisation', NULL, NULL, 'interfaces.catalog.i_chart_sunburst_props.description', 'Props for OrigamChartSunburst — the hierarchical ring chart. Extends IChartBaseProps (omitting categories). Series data must be Array<IChartSunburstDatum> carrying a nested tree. Controls inner-radius hole size, ring padding, arc label rendering and value formatting.', 'export interface IChartSunburstProps extends Omit<IChartBaseProps, ''categories''> {
    /**
     * Proportion of the overall radius reserved for the centre hole.
     * `0` = full pie (no hole). `0.4` = deep donut.
     * Default `0.15`.
     */
    innerRadius?: number
    /**
     * Radial gap between consecutive rings in SVG pixels.
     * Default `1`.
     */
    ringPadding?: number
