    /** Tile display label. */
    name: string
    /** Numeric magnitude — drives tile area. Must be ≥ 0. */
    value: number
    /**
     * Optional per-tile colour override. Accepts a design-system intent
     * token (`TIntent`) or any raw CSS colour string.
     */
    color?: TIntent | string
    /**
     * Reserved for future nested / drilldown support. Currently unused;
     * v1 renders a flat single-level treemap only.
     */
    children?: Array<IChartTreemapDatum>
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-treemap.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ab2d6a88-32b5-4ed3-a6a2-fd0c9b826238', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-treemap-props', 'IChartTreemapProps', 'Data Visualisation', NULL, NULL, 'interfaces.catalog.i_chart_treemap_props.description', 'Props for OrigamChartTreemap. Consumes series[0] only — each item in series[0].data becomes one tile sized proportionally to its value. v1 renders a flat single-level treemap; nested children are accepted for forward compatibility but not rendered. Extends IChartBaseProps.', 'export interface IChartTreemapProps extends IChartBaseProps {
    /**
     * Layout algorithm.
     * - `''squarified''` — minimises tile aspect ratio (default).
     * - `''slice-dice''` — alternates horizontal / vertical slicing.
     * Default `''squarified''`.
     */
    algorithm?: TChartTreemapAlgorithm
    /**
     * Whether to render the `name` + `value` text inside each tile when
     * the tile is at least 60 × 24 SVG-px. Default `true`.
     */
    showLabel?: boolean
    /**
     * Formatter applied to the numeric value in tile labels and
     * the tooltip. When absent the raw number is stringified.
     */
    yAxisFormat?: (value: number) => string
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-treemap.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('661992cf-d529-4a6c-9b2d-87a8e30adbd1', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-treemap-slots', 'IChartTreemapSlots', 'Data Visualisation', NULL, NULL, 'interfaces.catalog.i_chart_treemap_slots.description', 'Slot signatures exposed by OrigamChartTreemap. Extends IChartBaseSlots with a tile-label slot that replaces the inline name + value text inside each tile, receiving the full tile descriptor for complete customisation.', 'export interface IChartTreemapSlots extends IChartBaseSlots {
