INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('cab9ebaa-e237-4312-b80a-eb4e12b0d809', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-treemap-tile', 'IChartTreemapTile', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_treemap_tile.description', 'Internal tile descriptor produced by the treemap layout engine. All coordinates are in SVG-user-unit space (the fixed 600 × 400 viewport). Consumed by the template to render a single <rect> + optional inline label.', 'export interface IChartTreemapTile {
    /** Index in the original sorted data array. */
    index: number
    /** Unique key derived from the datum name — used in `v-for :key`. */
    key: string
    /** Display label. */
    name: string
    /** Raw numeric value. */
    value: number
    /** Pre-formatted value string (after applying `yAxisFormat` if present). */
    formatted: string
    /** Resolved CSS colour string. */
    color: string
    /** SVG x coordinate of the tile''s top-left corner. */
    x: number
    /** SVG y coordinate of the tile''s top-left corner. */
    y: number
    /** Tile width in SVG user units. */
    width: number
    /** Tile height in SVG user units. */
    height: number
    /** Whether the tile is currently visible (legend toggle). */
    visible: boolean
    /**
     * `true` when the tile is large enough to show the `name + value`
     * label inline (min 60 × 24 SVG px).
     */
    labelFits: boolean
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-treemap.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('99f3f9c5-ceff-4c60-a7dc-f64ba69930ec', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-variwide-column', 'IChartVariwideColumn', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_variwide_column.description', 'Pre-computed column descriptor produced by the variwide geometry engine. Consumed by the template to render a single <rect> with variable width encoding a secondary metric.', 'export interface IChartVariwideColumn {
    /** Index in the original data array. */
    index: number
    /** Category label from the datum. */
