}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-variwide.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e2adc3ff-1999-4f11-b61d-9382dcd3caad', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-variwide-datum', 'IChartVariwideDatum', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_variwide_datum.description', 'A single datum in the variwide series. Encodes two dimensions simultaneously: value → bar height (primary metric, maps to Y axis) and width → bar width (secondary metric, proportional share of plot width).', 'export interface IChartVariwideDatum {
    /** Category label shown on the X axis tick and in the tooltip. */
    category: string
    /**
     * Primary value — drives the bar HEIGHT via the Y scale.
     * e.g. GDP in trillions, revenue in M€, response time in ms.
     */
    value: number
    /**
     * Secondary value — drives the bar WIDTH proportionally
     * (`barPixels = plotWidth * width / Σwidths`).
     * e.g. population in M, number of requests, market share %.
     */
    width: number
    /**
     * Optional per-datum colour override. Accepts a `TIntent` token
     * or any raw CSS colour string. When omitted the chart cycles
     * through `colorScheme`.
     */
    color?: TIntent | string
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-variwide.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5ec801b3-9121-4b69-8a80-ba98d40e1fe8', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-chart-variwide-props', 'IChartVariwideProps', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_variwide_props.description', 'Props for <OrigamChartVariwide>. A variwide chart encodes two metrics per category: height for the primary value (Y axis) and width for the secondary value (proportional share of the plot width). Typical uses: GDP × population, revenue × market share, response time × request count.', 'export interface IChartVariwideProps extends IChartBaseProps {
    /**
     * Gap in SVG pixels between adjacent columns.
     * Default `2`.
     */
    barGap?: number
    /**
     * Show the value label above each column. Default `true`.
     */
    showLabel?: boolean
    /**
     * Render X (category) and Y (value) axes. Default `true`.
     */
    showAxis?: boolean
    /**
     * Render horizontal grid lines aligned with Y-axis ticks.
     * Default `true`.
     */
    showGrid?: boolean
    /**
     * Formatter applied to X-axis category tick labels.
     * When omitted the category string is shown as-is.
     */
    xAxisFormat?: (value: string | number) => string
    /**
     * Formatter applied to Y-axis value tick labels and to the
     * primary-value display in tooltip and above-bar label.
     * When omitted the raw number is used.
     */
    yAxisFormat?: (value: number) => string
    /**
     * Override the auto-computed Y minimum.
     * Useful when the data starts well above zero.
     */
    yMin?: number
    /**
     * Override the auto-computed Y maximum.
     */
    yMax?: number
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-variwide.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
