INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6e7ffea3-28a3-44a1-bbce-9830056923e9', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-clipboard-emits', 'IClipboardEmits', 'Action & Command', NULL, NULL, 'interfaces.catalog.i_clipboard_emits.description', 'Emits for <OrigamClipboard>. Two events: copy (success, carries the payload string) and error (failure, carries the thrown Error when the clipboard API is denied or unavailable).', 'export interface IClipboardEmits {
    /** Fired after a successful write. Carries the payload string. */
    (e: ''copy'', value: string): void
    /** Fired after a failed write (clipboard API denied, no permission, …). */
    (e: ''error'', err: Error): void
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Clipboard/clipboard.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a50e9713-2b25-4bd9-972b-3fa7465928b6', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-clipboard-props', 'IClipboardProps', 'Action & Command', NULL, NULL, 'interfaces.catalog.i_clipboard_props.description', 'Props for <OrigamClipboard> — a chrome-less copy-to-clipboard wrapper. Owns the copy pipeline (navigator.clipboard.writeText + execCommand fallback) and the auto-resetting copied flag. The built-in trigger is a single button; consumers can pass a #default scoped slot for full control.', 'export interface IClipboardProps extends ICommonsComponentProps, ITagProps, IColorProps, IBgColorProps, IBorderProps, IRoundedProps, IMarginProps, IPaddingProps, ITypographyProps {
    /**
     * Text payload written to the clipboard on `copy()`. Required.
     * Re-read each time the trigger fires, so a parent that mutates
     * the value between mounts still copies the up-to-date string.
     */
    value: string
    /**
     * Duration (ms) the `copied` flag stays true after a successful
     * write. The state auto-resets after this window — there is no
     * need to clear it from the consumer side.
     *
     * @default 2000
     */
    feedbackDuration?: number
    /**
     * Label rendered inside the built-in feedback overlay (and the
     * auto-rendered button label when no slot is provided). Consumers
     * wrap with `t()` if they need full i18n.
     *
     * @default ''Copied!''
     */
    feedbackText?: string
    /**
     * Alias for `feedbackText`. Takes precedence when both are passed.
     * Provided for callers who prefer the "success" framing in their
     * codebase.
     */
    successText?: string
    /**
     * Disables the copy action. The default trigger becomes
     * non-interactive (`disabled` attribute) and `copy()` becomes a
     * no-op. The scoped slot still receives the `copy` function so
     * consumers can decide what to render — but it will short-circuit.
     *
     * @default false
     */
    disabled?: boolean
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Clipboard/clipboard.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('efb90e81-2325-42bf-a399-dfc98aa28111', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-clipboard-scoped-slot-bindings', 'IClipboardScopedSlotBindings', 'Action & Command', NULL, NULL, 'interfaces.catalog.i_clipboard_scoped_slot_bindings.description', 'Bindings exposed via the #default scoped slot of <OrigamClipboard>. Consumers use these to wire any custom trigger (button, icon, span, widget) to the copy pipeline without re-implementing the timing/feedback logic.', 'export interface IClipboardScopedSlotBindings {
    /** Triggers the copy pipeline. Promise resolves true on success. */
    copy: () => Promise<boolean>
    /** True for `feedbackDuration` ms after a successful copy. */
    copied: boolean
    /** Set when the last copy attempt threw, null otherwise. */
    error: Error | null
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Clipboard/clipboard.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('81aa1d15-b359-40f2-8fe7-472f1027937b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-clipboard-slots', 'IClipboardSlots', 'Action & Command', NULL, NULL, 'interfaces.catalog.i_clipboard_slots.description', 'Slot signatures for <OrigamClipboard>. The default slot receives copy/copied/error bindings for a fully custom trigger. The feedback slot replaces the success indicator shown after a successful copy.', 'export interface IClipboardSlots {
    /**
     * Custom trigger. Scoped — receives `{ copy, copied, error }`.
     * When omitted, the component renders a default icon button with
     * `mdi:mdi-content-copy`.
     */
    default?: (bindings: IClipboardScopedSlotBindings) => any
    /**
     * Custom feedback marker rendered when `showFeedback` is true and
     * `copied` is true. Scoped — receives the boolean for symmetry
     * with the default slot.
     */
    feedback?: (bindings: { copied: boolean }) => any
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Clipboard/clipboard.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('17fc7147-7d3f-4843-8c1e-4149727969f4', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-code-props', 'ICodeProps', 'Data Display', NULL, NULL, 'interfaces.catalog.i_code_props.description', 'Props for OrigamCode — a shiki-powered code block with line numbers, line highlighting, copy button, compact pill mode and theme awareness.', 'export interface ICodeProps extends ICommonsComponentProps, ITagProps, IBorderProps, IRoundedProps, IElevationProps, IPaddingProps, IMarginProps, IDimensionProps, IColorProps, IBgColorProps, ITypographyProps {
    /**
     * The code to highlight. When omitted, the default slot is used as the
     * source — useful for multi-line snippets that are nicer to read in
     * the template than as a JS string literal. When both are provided,
     * the prop wins.
     */
    code?: string
    /**
     * Language grammar to apply. One of the values in `SUPPORTED_LANGS`.
     * Unknown values fall back to `plaintext` (with a one-shot console
     * warning).
     */
    lang?: TCodeLang
    /**
     * Show a left gutter with line numbers. Pure CSS — uses a CSS counter
     * incremented per `.origam-code__row`, no JS layout work.
     */
    lineNumbers?: boolean
    /**
     * Lines to highlight. Accepts either a pre-computed array of 1-based
     * line numbers (`[2, 5, 6, 7]`) or a comma/range string (`''2,5-7''`)
     * that the component parses via `parseHighlightLines()`. `null` /
     * empty disables the feature.
     */
    highlightLines?: number[] | string | null
    /**
     * Show the copy-to-clipboard button in the top-right corner. Defaults
     * to `true` — most code blocks benefit from it.
     */
    copyable?: boolean
    /**
     * Auto-format the code before highlighting. Reserved for v3 — prettier
     * is intentionally NOT bundled at runtime to keep the tarball small.
     * Currently a no-op; passing `true` warns once in dev and pre-formats
     * via a best-effort whitespace trim only.
     */
    format?: boolean
    /**
     * Wrap long lines instead of scrolling horizontally. Off by default so
     * the visual column matches the source file.
     */
    wrap?: boolean
    /**
     * Optional filename rendered in the header bar (e.g. `''App.vue''`).
     * When provided AND `copyable` is true, the header also hosts the copy
     * button; otherwise the copy button is absolutely positioned in the
     * top-right corner of the code surface.
     */
    filename?: string
    /**
     * Render the block as a single-line **pill** instead of a multi-line
     * surface — ideal for a copyable install command (`npm install origam`).
     * In compact mode the header, filename and line-numbers are suppressed,
     * vertical padding shrinks to one line, the surface keeps its themed
     * tokens, and the copy control collapses to a small icon button anchored
     * inline at the end of the row (not a floating text "Copy"). The `<figure>
     * <pre><code>` semantics are preserved.
     */
    compact?: boolean
    /**
     * Decorative prompt prefix rendered BEFORE the code (e.g. `''$''` for a
     * shell command). Purely visual: it is NOT part of the highlighted code
     * and is NEVER included in the clipboard copy (only `code` is copied).
     * Most useful paired with `compact` for an install-command pill.
     */
