INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('477880d6-1762-4623-bc3d-1de97ac9d2e0', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-command', 'ICommand', 'Navigation', NULL, NULL, 'interfaces.catalog.i_command.description', 'A single command/action exposed by OrigamCommandPalette — holds the stable id, label, optional description, icon, keyboard shortcut hint, group, extra search keywords and the perform handler.', 'export interface ICommand {
    /**
     * Stable identifier. Used as the v-for key, the ARIA
     * `aria-activedescendant` target and as the dedup key in the
     * registry — registering twice with the same `id` overwrites
     * the previous entry instead of duplicating it.
     */
    id: string
    /** Visible primary label. Drives the default fuzzy-match input. */
    label: string
    /** Secondary line shown under the label (optional). */
    description?: string
    /** Optional prepend icon. */
    icon?: TIcon
    /**
     * Keyboard shortcut hint rendered through `<OrigamKbd>` next to
     * the action. Display-only — it does NOT bind a global listener.
     * (To bind a shortcut globally, use the `hotkey` prop on the
     * palette OR the `useHotkey` composable on the call site.)
     */
    kbd?: ReadonlyArray<string>
    /**
     * Group label (e.g. "Navigation", "Settings"). Commands sharing
     * the same group render under the same subheader. Commands
     * without a group fall back to a default bucket rendered first.
     */
    group?: string
    /**
     * Extra search terms that should match the command (e.g.
     * `[''preferences'', ''config'']` for a "Settings" entry).
     */
    keywords?: ReadonlyArray<string>
    /**
     * Handler invoked when the command is selected. May be async — the
     * palette awaits the returned promise before closing (when
     * `closeOnSelect` is `true`).
     */
    perform: () => void | Promise<void>
    /** Disabled commands stay visible but cannot be selected. */
    disabled?: boolean
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/CommandPalette/command.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9ce7a12b-dc08-41fe-9295-605a9a3eecc9', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-command-palette-emits', 'ICommandPaletteEmits', 'Navigation', NULL, NULL, 'interfaces.catalog.i_command_palette_emits.description', 'Emits fired by OrigamCommandPalette — open/close state, selected command, and search query text.', 'export interface ICommandPaletteEmits {
    (e: ''update:modelValue'', value: boolean): void
