INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8a0d077f-bf22-4235-9eac-882f7da3f9b6', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-command-palette-props', 'ICommandPaletteProps', 'Navigation', NULL, NULL, 'interfaces.catalog.i_command_palette_props.description', 'Props for OrigamCommandPalette — a global ⌘K command palette that fuzzy-searches registered commands, supports custom hotkeys, grouping, async loading and slot customisation.', 'export interface ICommandPaletteProps extends ICommonsComponentProps, ITypographyProps {
    /** v-model — whether the palette is open. */
    modelValue?: boolean
    /**
     * Global hotkey(s) that toggle the palette open. Defaults to
     * `[[''meta'', ''k''], [''ctrl'', ''k'']]` (⌘K / Ctrl+K). Pass `null`
     * to disable the global listener entirely.
     */
    hotkey?: TCommandPaletteHotkey | null
    /**
     * Static command list. When omitted, the palette renders commands
     * registered via the `useCommand()` global registry instead.
     */
    commands?: ReadonlyArray<ICommand>
    /** Placeholder of the search input (already-translated string). */
    placeholder?: string
    /** Empty-state message when no command matches the query. */
    emptyText?: string
    /** Max height of the result list. Number → px. */
    maxHeight?: number | string
    /** Width of the palette dialog. Number → px. */
    width?: number | string
    /** Display a loader inside the result list (use during async fetches). */
    loading?: boolean
    /** Close the palette automatically when a command is selected. */
    closeOnSelect?: boolean
    /** Close when the user presses Escape. */
    closeOnEscape?: boolean
    /** Close when the user clicks the backdrop. */
    closeOnBackdrop?: boolean
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/CommandPalette/command-palette.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4addd62f-8fff-44f2-844f-65c11183036f', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-command-palette-slot-props', 'ICommandPaletteSlotProps', 'Navigation', NULL, NULL, 'interfaces.catalog.i_command_palette_slot_props.description', 'Scoped slot data injected into the #item slot of OrigamCommandPalette — provides the ICommand data and a boolean indicating whether the row is currently highlighted.', 'export interface ICommandPaletteSlotProps {
