    global?: Record<string, unknown>
    [key: string]: Record<string, unknown> | undefined
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/DefaultProvider/default-provider.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c21bc924-b25a-43f6-9a2c-e2568585ca5d', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-default-provider-props', 'IDefaultProviderProps', 'Theme & Defaults', NULL, NULL, 'interfaces.catalog.i_default_provider_props.description', 'Props for OrigamDefaultsProvider — a structurally transparent wrapper that injects per-component prop defaults into a subtree. Supports disabled pass-through, reset/root scoping and fully scoped isolation.', 'export interface IDefaultProviderProps extends ICommonsComponentProps {
    /** Map of defaults keyed by `global` or component name. */
    defaults?: IDefault
    /**
     * When `true`, parent defaults are passed through unchanged — useful to
     * temporarily disable an outer DefaultsProvider without unmounting it.
     */
    disabled?: boolean
    /**
     * When set, parent defaults are NOT inherited; the subtree starts from
     * this provider''s defaults only. The value is opaque (string/number) but
     * can be used to track resets in DevTools.
     */
    reset?: string | number
    /**
     * Marks the provider as a root scope. Equivalent to `reset` in behaviour
     * (no parent inheritance) but communicates a different intent (this is
     * the top of a defaults tree, not a mid-tree override).
     */
    root?: string | number
    /**
     * When `true`, parent defaults are not merged in — the subtree only
     * sees this provider''s defaults. Same as `reset` but expressed
     * declaratively without needing a discriminator value.
     */
    scoped?: boolean
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/DefaultProvider/default-provider.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('472f0287-634d-42f2-8155-5fd2a58d3451', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-default-provider-slots', 'IDefaultProviderSlots', 'Theme & Defaults', NULL, NULL, 'interfaces.catalog.i_default_provider_slots.description', 'Slot contract for OrigamDefaultsProvider. The component renders no visible chrome — its only slot is default, which carries the subtree that inherits the injected defaults.', 'export interface IDefaultProviderSlots {
