INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('560762d9-dbe7-4cef-9526-22ca5d7a34a3', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-drawer-props', 'IDrawerProps', 'Layout', NULL, NULL, 'interfaces.catalog.i_drawer_props.description', 'Props for OrigamDrawer — the side navigation panel. Covers permanent, temporary, rail and expand-on-hover modes, layout reservation (push), viewport positioning (clipped), resize/route watchers and all visual surface props.', 'export interface IDrawerProps extends ITagProps, ICommonsComponentProps, IBorderProps, IElevationProps, ILayoutItemProps, IRoundedProps, IColorProps, IBgColorProps, IDensityProps, IPaddingProps, IMarginProps, ITransitionComponentProps, IScrimProps, IActiveProps, IHoverProps {
    disableResizeWatcher?: boolean
    disableRouteWatcher?: boolean
    expandOnHover?: boolean
    floating?: boolean
    modelValue?: boolean
    permanent?: boolean | null
    rail?: boolean | null
    railWidth?: number | string
    temporary?: boolean
    touchless?: boolean
    width?: number | string
    sticky?: boolean
    /**
     * Whether the drawer reserves space in the layout grid (PUSHES the
     * adjacent toolbar / main / footer / etc.) or overlays them.
     *
     *   • `true`  → drawer registers with the layout''s reserved-space
     *               system. Toolbar / main / footer adjacent to the
     *               drawer offset themselves accordingly.
     *   • `false` → drawer paints over the surrounding content (no
     *               reservation, no offset).
     *   • `null` (default) → derived from `permanent`: permanent
     *               drawers push by default, temporary drawers don''t.
     *
     * Declared as `boolean | null` (NOT `boolean | undefined`) because
     * Vue''s prop coercion turns absent boolean attributes into `false`,
     * which would silently disable the push heuristic. `null` survives
     * coercion and lets the runtime fall back to the permanent-derived
     * default.
     */
    push?: boolean | null
    /**
     * Whether the drawer slots BELOW any top-anchored layout item
     * (typically the AppBar) instead of extending the full height of
     * the layout.
     *
     *   • `true`  → drawer''s effective layout order is bumped after
     *               top items, so the drawer''s top edge starts where
     *               the AppBar''s bottom edge ends.
     *   • `false` → drawer keeps order 0, extending full height and
     *               pushing the AppBar to its right (or claiming the
     *               full left lane regardless of top items).
     *   • `null` (default) → resolved from the HTML declaration order.
     *               AppBar before Drawer → drawer below.
     *               Drawer before AppBar → drawer full-height.
     */
    clipped?: boolean | null
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Drawer/drawer.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('46748bc6-2ec8-43af-b84e-7674d59c2ff8', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-elevation-props', 'IElevationProps', 'Visual Style', NULL, NULL, 'interfaces.catalog.i_elevation_props.description', 'Elevation contract — adds a shadow rung to a component via the design-token-mapped `elevation` prop, consumed by useElevation() which emits a `box-shadow: var(--origam-shadow-…)` utility class or inline style.', 'export interface IElevationProps {
