}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Commons/elevation.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('682183b4-24f1-4ef8-a5a7-e40515fff366', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-empty-state-props', 'IEmptyStateProps', 'Feedback & Status', NULL, NULL, 'interfaces.catalog.i_empty_state_props.description', 'Props for OrigamEmptyState — the placeholder shown when a list, table or collection has nothing to display. Five built-in visual presets (no-data, no-results, error, offline, locked) bundle icon and intent; both can be overridden.', 'export interface IEmptyStateProps extends ICommonsComponentProps, ITagProps, ITypographyProps {
    /**
     * Visual preset. Bundles a default icon and intent — see
     * `EMPTY_STATE_PRESET_CONFIG`. The preset is the starting point;
     * `icon` and `iconColor` win when both are passed.
     *
     * @default ''no-data''
     */
    preset?: TEmptyStatePreset
    /**
     * Primary heading. Rendered as a `<h2>`-equivalent element with
     * the chosen `size`. Override entirely via the `#title` slot when
     * richer markup is needed (a link, an icon-prefix, …).
     */
    title?: string
    /**
     * Optional sub-heading rendered below the title. Multiple lines
     * supported; the SCSS layer clamps the readable width via the
     * `--origam-empty-state---max-width` token.
     */
    description?: string
    /**
     * Override the preset icon. Accepts the same `TIcon` shape as
     * `<OrigamIcon>`: a MDI / iconify string, an array of SVG path
     * tuples, or a Vue `Component`. Use the `#icon` slot for full
     * SVG / `<img>` illustrations.
     */
    icon?: TIcon
    /**
     * Override the preset''s icon color (the semantic intent that maps
     * to `--origam-color__action--{intent}---bg` /
     * `--origam-color__feedback--{intent}---bg`).
     */
    iconColor?: TIntent
    /**
     * Vertical density. Drives icon size, title / description font
     * sizes, padding and gap.
     *
     * @default ''md''
     */
    size?: TEmptyStateSize
    /**
     * Horizontal alignment of the icon / title / description / actions
     * stack.
     *
     * @default ''center''
     */
    align?: TEmptyStateAlign
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/EmptyState/empty-state.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d59a2a14-6bde-49db-aa6b-e93e4d0e726f', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-group-item', 'IGroupItem', 'Data & State', NULL, NULL, 'interfaces.catalog.i_group_item.description', 'Internal registration record for a single item inside a group — carries the numeric id assigned by the group provider, a reactive value ref and a reactive disabled ref.', 'export interface IGroupItem {
    id: number
