INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('91b53910-09aa-4875-97f0-4b767bbe0856', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-empty-state-slots', 'IEmptyStateSlots', 'Feedback & Status', NULL, NULL, 'interfaces.catalog.i_empty_state_slots.description', 'Slot contract for OrigamEmptyState. All slots are optional. The default slot replaces the entire built-in layout; targeted slots (icon, title, description, actions) swap individual pieces.', 'export interface IEmptyStateSlots {
    /**
     * Replaces the entire built-in layout (icon + title + description
     * + actions). Use this for a fully bespoke layout — e.g. a hero
     * empty page with a custom illustration and a multi-column CTA
     * grid.
     */
    default?: () => any
    /**
     * Replaces the default `<OrigamIcon>` rendering. Use for SVG /
     * `<img>` illustrations. Mark the surface `aria-hidden="true"`
     * when it is purely decorative.
     */
    icon?: () => any
    /**
     * Replaces the rendered title element. Slot wins over the `title`
     * prop when both are provided.
     */
    title?: () => any
    /**
     * Replaces the rendered description element. Slot wins over the
     * `description` prop when both are provided.
     */
    description?: () => any
    /**
     * Actions row rendered below the description (or the title when
     * `description` is absent). Typically holds 1–2 buttons (Create,
     * Retry, Switch to offline mode, Sign in).
     */
    actions?: () => any
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/EmptyState/empty-state.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('40599400-34c7-4fa6-8ed9-938993ae4000', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-event', 'IEvent', 'Calendar', NULL, NULL, 'interfaces.catalog.i_event.description', 'Public event data shape consumed by OrigamCalendar and useCalendar. Supports single-day, multi-day, all-day and recurring events (RRULE subset: FREQ/INTERVAL/COUNT/UNTIL/BYDAY). start/end accept ISO-8601 strings, Date objects or epoch numbers.', 'export interface IEvent {
    /** Stable identifier — used as `:key` and for click-target wiring. */
    id: string | number
    /** Displayed title — also read by the default `aria-label`. */
    title: string
    /** Optional long-form description — surfaced in the agenda view. */
    description?: string
    /** Start instant. ISO-8601 strings and `Date` instances both work. */
    start: string | Date
    /**
     * End instant. Omitted when `allDay=true` (the calendar treats the
     * event as a single-day block) or for "point-in-time" events with
     * no measurable duration.
     */
    end?: string | Date
    /**
     * `true` to render the event in the all-day band above the time
     * grid (week / day views). Has no effect in month view.
     */
    allDay?: boolean
    /**
     * Free-form category string — used as the lookup key for
     * `categoryColors`. Useful when multiple events share a colour
     * (e.g. "meeting", "focus", "personal").
     */
    category?: string
    /**
     * Direct colour override. Wins over `category` when both are set.
     * Accepts a `TIntent` (matches the design-token rail) or any CSS
     * colour string.
     */
    color?: TIntent | string
    /**
     * RRULE subset string. The calendar expands the recurrence to
     * the visible range at render time; the original event is **not**
     * mutated.
     */
    rrule?: string
    /** Free-form metadata — passed through to the `event-click` payload. */
    metadata?: Record<string, unknown>
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Calendar/event.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('db095bcd-be67-4933-add7-3938a7ff6850', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-expansion-panel-content-props', 'IExpansionPanelContentProps', 'Disclosure', NULL, NULL, 'interfaces.catalog.i_expansion_panel_content_props.description', 'Props for the collapsible body of OrigamExpansionPanel. Controls the rendered content, lazy mounting, loader state and all visual surface properties (color, border, padding, rounded …).', 'export interface IExpansionPanelContentProps extends IColorProps, IBgColorProps, ITagProps, ICommonsComponentProps, IDensityProps, IRoundedProps, IBorderProps, IPaddingProps, IMarginProps, ILazyProps, ILoaderProps {
