INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2490af34-0b27-4ad5-bc69-84d63d3fc738', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-number-field-slots', 'INumberFieldSlots', 'NumberField', NULL, NULL, '', '', 'export interface INumberFieldSlots extends IFieldSlots, Omit<IInputSlots, ''default''> {
    field?: (data: { id: string, isDisabled: boolean, isDirty: boolean, isValid: boolean | undefined, isReadonly: boolean }) => any
    increment?: (data: { canIncrease: boolean, onControlClick: () => void, onUpControlMousedown: () => void, onControlMouseup: () => void }) => any
    decrement?: (data: { canDecrease: boolean, onControlClick: () => void, onDownControlMousedown: () => void, onControlMouseup: () => void }) => any
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/NumberField/number-field.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('592b046d-5add-41d3-838c-683b63ec9805', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-number-format-props', 'INumberFormatProps', 'NumberFormat', NULL, NULL, '', 'Props for `<OrigamNumberFormat>` — pure-display i18n number renderer
powered by `Intl.NumberFormat` (zero external dep).

The component owns NO state: it transforms `value` through the
resolved `Intl` instance and emits the result into a `<tag>` element
(default `<span>`). Consumers who want to override the rendering
granularly use the scoped `#default` slot which exposes
`{ formatted, parts, value }`.', 'export interface INumberFormatProps extends ICommonsComponentProps, ITagProps {
    /**
     * Number to render. Strings are parsed via `Number()` — callers can
     * pass a stringified BigInt-like to preserve precision before
     * coercion (the actual formatting still goes through `Number`, so
     * values beyond `Number.MAX_SAFE_INTEGER` may lose accuracy).
     */
    value: number | string
    /**
     * High-level format dialect — see `TNumberFormatFormat`.
     *
     * @default ''decimal''
     */
    format?: TNumberFormatFormat
    /**
     * BCP-47 locale tag (or array, for fallback chains). The literal
     * string `''auto''` triggers the runtime resolution chain (`<html
     * lang>` → `navigator.language` → `''en-US''`).
     *
     * @default ''auto''
     */
    locale?: TNumberFormatLocale
    /**
     * ISO 4217 currency code. Required when `format === ''currency''`; we
     * fall back to `''USD''` rather than throwing so storybook controls
     * remain forgiving.
     *
     * @default ''USD'' (only when format === ''currency'')
     */
    currency?: string
    /**
     * Currency-symbol rendering — `''symbol''` (`$`), `''narrowSymbol''`
     * (`$` instead of `US$`), `''code''` (`USD`) or `''name''`
     * (`US dollar`).
     *
     * @default ''symbol''
     */
    currencyDisplay?: TNumberFormatCurrencyDisplay
    /**
     * Sanctioned unit identifier (e.g. `''kilometer-per-hour''`,
     * `''celsius''`, `''liter''`). Required when `format === ''unit''`. The
     * full ECMAScript-sanctioned list is exposed under
     * `Intl.supportedValuesOf(''unit'')` at runtime.
     */
    unit?: string
    /**
     * Unit-label rendering — `''short''` (`km/h`), `''long''`
     * (`kilometers per hour`) or `''narrow''` (`kph`).
     *
     * @default ''short''
     */
    unitDisplay?: TNumberFormatUnitDisplay
    /**
     * Raw `notation` override. Auto-set to `''compact''` when `format ===
     * ''compact''`, to `''scientific''` / `''engineering''` for the matching
     * formats. Explicit values still win — useful for `format:
     * ''decimal''` with `notation: ''scientific''`.
     */
    notation?: TNumberFormatNotation
    /**
     * Compact-notation rendering — `''short''` (`1M`) or `''long''`
     * (`1 million`). Only honoured when `notation === ''compact''`.
     *
     * @default ''short''
     */
    compactDisplay?: TNumberFormatCompactDisplay
    /** Minimum digits after the decimal point. */
    minimumFractionDigits?: number
    /** Maximum digits after the decimal point. */
    maximumFractionDigits?: number
    /** Minimum significant digits (mutually exclusive with fraction digits). */
    minimumSignificantDigits?: number
    /** Maximum significant digits (mutually exclusive with fraction digits). */
    maximumSignificantDigits?: number
    /**
     * Thousands-separator behaviour. `true` / `''auto''` keep the locale
     * default, `false` removes them, `''always''` forces them on, `''min2''`
     * only renders them when the integer part has at least 2 groups.
     *
     * @default true
     */
    useGrouping?: TNumberFormatUseGrouping
    /**
     * Sign-display strategy. `''auto''` (default — only negatives),
     * `''always''`, `''except-zero''`, `''negative''`, `''never''`.
     *
     * @default ''auto''
     */
    signDisplay?: TNumberFormatSignDisplay
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/NumberFormat/number-format.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8ec453d0-ca04-4646-9d69-22907e04498a', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-number-format-scoped-slot-bindings', 'INumberFormatScopedSlotBindings', 'NumberFormat', NULL, NULL, '', 'Bindings exposed by the scoped `#default` slot. Consumers use these
to highlight specific parts of the formatted output (currency symbol,
decimal separator, …) without re-running `Intl.NumberFormat`
themselves.', 'export interface INumberFormatScopedSlotBindings {
    /** The locale-formatted string, ready to render. */
    formatted: string
    /** The structured parts (`Intl.NumberFormatPart[]`). */
    parts: Intl.NumberFormatPart[]
    /** The numeric value after string-to-number coercion. */
    value: number
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/NumberFormat/number-format.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4be8369e-5c82-4522-802e-7634f6be5c69', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-number-format-slots', 'INumberFormatSlots', 'NumberFormat', NULL, NULL, '', 'Slot signatures for `<OrigamNumberFormat>`.', 'export interface INumberFormatSlots {
    /**
     * Custom render override. Scoped — receives the resolved value plus
     * the structured parts so consumers can paint individual segments.
     */
    default?: (bindings: INumberFormatScopedSlotBindings) => any
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/NumberFormat/number-format.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c8461628-ebaf-46b2-9757-7a0c54f3c118', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-options', 'IOptions', 'Data & State', NULL, NULL, 'interfaces.catalog.i_options.description', 'Generic label/value pair shape used across Select, RadioGroup, ChipGroup, BtnToggle and any component that needs a typed option list. The value is `T | undefined` so consumers can model an explicit "no value" row.', 'export interface IOptions<T> {
    label: string
    value: T | undefined
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Commons/options.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3fddb935-269c-4c39-9679-433c7a1982a8', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-origam-nuxt-module-options', 'IOrigamNuxtModuleOptions', 'Nuxt', NULL, NULL, '', 'Options passed by a consumer in `nuxt.config.ts` under the `origam` key.

All fields are optional — the module applies sensible defaults (see
`DEFAULTS` in `src/nuxt/module.ts`). Themes are installed as runtime OBJECTS
(ADR-004): the module passes the `themes` array straight through to the
runtime config and on to `createOrigam` in the plugins, which inject each as
a name×mode scoped `--origam-*` block. The theme-invariant `primitive` +
`utilities` sheets are still loaded as CSS. Two orthogonal axes are resolved
SSR-side to avoid FOUC: the brand `theme` (cookie) and the color `mode`
(cookie + `Sec-CH-Prefers-Color-Scheme` hint).

ADR-004 (Implemented): the DS ships exactly ONE neutral identity (the origam
baseline). Brand themes live in the consuming app (e.g. the marketing
package) and are passed here as `IOrigamTheme[]` objects authored in
semantic JSON — the DS no longer resolves preset names or ships brand
token sheets.', 'export interface IOrigamNuxtModuleOptions {
    /**
     * Themes to install, as `IOrigamTheme` objects (one per brand×mode). The
     * objects are passed verbatim to `createOrigam`, which injects each as a
     * scoped CSS-var block — no pre-generated per-theme CSS file is loaded.
     * When omitted, `createOrigam` installs the DS built-in baseline (neutral identity).
     */
    themes?: IOrigamTheme[]

    /**
     * Theme (brand) applied when no cookie is set. Use `''auto''` to render no
     * `data-theme` attribute (the default brand).
     *
     * @default ''auto''
     */
    defaultTheme?: string

    /**
     * Color modes supported by the loaded token sheets. Used to validate the
     * resolved mode before applying it.
     *
     * @default [''light'', ''dark'']
     */
    modes?: string[]

    /**
     * Color mode applied when no cookie is set and no usable
     * `Sec-CH-Prefers-Color-Scheme` hint is sent. Use `''auto''` to let the
     * server fall back to the client hint (or `''light''` if absent).
     *
     * @default ''auto''
     */
    defaultMode?: string

    /**
     * Cookie name used to persist the user''s chosen theme (brand) across
     * sessions.
     *
     * @default ''origam-theme''
     */
    cookieName?: string

    /**
     * Cookie name used to persist the user''s chosen color mode across
     * sessions.
     *
     * @default ''origam-mode''
     */
    modeCookieName?: string

    /**
     * Cookie `max-age` in seconds (shared by the theme and mode cookies).
     *
     * @default 31_536_000 (1 year)
     */
    cookieMaxAge?: number

    /**
     * Register components and composables as Nuxt auto-imports. Disable if
     * you want to opt-out and import everything explicitly (or namespace
     * the imports to avoid conflicts with another design system).
     *
     * @default true
     */
    autoImport?: boolean

    /**
     * Inject the generated utility classes stylesheet (`origam-utilities.css`).
     * Keep it on unless the consumer ships their own utility layer.
     *
     * @default true
     */
    includeUtilities?: boolean

    /**
     * Prefix applied to auto-imported components. Origam ships components
     * already prefixed `Origam*` so the default is an empty prefix — set
     * this to override if you need a custom namespace.
     *
     * @default ''Origam''
     */
    prefix?: string
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Nuxt/nuxt-module.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5dfeebb7-62c6-4134-b672-fcd2c36c8702', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-origam-nuxt-runtime-config', 'IOrigamNuxtRuntimeConfig', 'Nuxt', NULL, NULL, '', 'Shape of the public runtime config exposed by the module on
`useRuntimeConfig().public.origam`. The plugins read this at boot to install
the theme objects, resolve the active theme/mode, and configure the cookies.', 'export interface IOrigamNuxtRuntimeConfig {
    /**
     * Installed `IOrigamTheme` objects, in install order. The plugins pass
     * these straight to `createOrigam` (no preset-name resolution — ADR-004).
     * A switcher derives its brand list from `useInstalledThemes()` rather than
     * from this payload.
     */
    themes: IOrigamTheme[]
    defaultTheme: string
    modes: string[]
    defaultMode: string
    cookieName: string
    modeCookieName: string
    cookieMaxAge: number
