INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('856f6ec7-b48c-4427-be9c-41c673d2f3b3', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-origam-options', 'IOrigamOptions', 'Plugin & Configuration', NULL, NULL, 'interfaces.catalog.i_origam_options.description', 'Root configuration bag passed to `createOrigam()`. Covers component aliases, icon adapter, display breakpoints, SSR, navigation, date adapter, locale/RTL, a11y contrast guard and runtime theme injection.', 'export interface IOrigamOptions {
    aliases?: any
    blueprint?: IBlueprint
    components?: any
    directives?: any
    icons?: TIconOptions
    display?: IDisplayOptions
    ssr?: TSSROptions
    goTo?: IGoToOptions
    date?: IDateOptions
    locale?: ILocaleOptions & IRtlOptions
    /**
     * Runtime text-contrast guard. `true` (default) enables the WCAG check
     * that auto-corrects illegible text colours and warns; `false` disables
     * it. Pass an object to tune the threshold.
     */
    contrast?: boolean | IContrastOptions
    /**
     * Optional runtime theme. When supplied, `createOrigam` resolves it to a
     * block of `--origam-*` CSS variables and injects it into `<head>` at
     * install time (browser only — SSR-safe no-op on the server). Accepts a
     * pre-resolved var map and/or a DTCG-shaped token tree; see `IOrigamTheme`.
     */
    theme?: IOrigamTheme

    /**
     * Optional list of runtime themes installed together (the consumer install
     * path — see ADR-003). Each object is injected as its own name×mode scoped
     * `--origam-*` block via the same machinery as `theme`. The distinct brand
     * names are exposed through `useInstalledThemes()` so a switcher can derive
     * its list from the install rather than a hard-coded const.
     *
     * `theme` (singular) and `themes` (plural) may both be supplied; all are
     * injected. SSR-safe (injection is a no-op without `document`).
     */
    themes?: IOrigamTheme[]
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Commons/commons.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
