INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6eaf0bc1-8e30-41dc-8bcb-3da13b734469', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-parallax-layer-props', 'IParallaxLayerProps', 'Parallax', NULL, NULL, '', '', 'export interface IParallaxLayerProps extends ICommonsComponentProps, ITagProps {
    /**
     * Parallax speed multiplier for this layer.
     *  - `0`   → fixed (no movement, sticks to host)
     *  - `0.5` → half the scroll speed (background — far)
     *  - `1`   → moves with the scroll (neutral)
     *  - `>1`  → faster than the scroll (foreground — near)
     *
     * Negative values reverse the direction.
     */
    speed?: number

    /**
     * Static X-axis offset (px) applied on top of the parallax translation.
     * Useful to nudge a layer without changing its speed.
     */
    offsetX?: number

    /**
     * Static Y-axis offset (px) applied on top of the parallax translation.
     */
    offsetY?: number

    /**
     * Optional `z-index` override. By default layers stack in document order.
     */
    zIndex?: number
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Parallax/parallax-layer.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('58a16a62-6504-4b70-a957-9290daf0f8b0', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-parallax-layer-provide', 'IParallaxLayerProvide', 'Parallax', NULL, NULL, '', 'Provide context exposed by the enriched OrigamParallax to its
`<OrigamParallaxLayer>` children. Distinct from the legacy
`IParallaxProvide` consumed by `<OrigamParallaxElement>` (kept
separate to avoid coupling the two APIs).', 'export interface IParallaxLayerProvide {
    direction: Ref<TParallaxDirection>
    easing: Ref<TParallaxEasing | string>
    disabled: Ref<boolean>
    /**
     * Live scroll progress, normalised to `[0, 1]`. `0` = host just entered
     * the viewport, `1` = host just left.
     */
    progress: Ref<number>
    /**
     * Live mouse-ratio for `direction="both"` on `event="move"` —
     * `{ x: 0..1, y: 0..1 }`. Falls back to `{ x: 0.5, y: 0.5 }` when no
     * mouse data is available.
     */
    mouseRatio: Ref<{ x: number, y: number }>
    /**
     * Whether the runtime is using the CSS scroll-driven path (true) or the
     * JS rAF fallback (false). Layers may opt out of the JS work when the
     * CSS path is active.
     */
    cssScrollDriven: Ref<boolean>
    /**
     * Whether `prefers-reduced-motion: reduce` is honoured — layers MUST
     * stay at offset 0 when this is true.
     */
    reducedMotion: Ref<boolean>
    /**
     * Register / unregister a layer with the parent. The parent reads the
     * registry to compute and apply per-layer transforms each frame.
     */
    register: (layer: IParallaxLayerRegistry) => void
    unregister: (id: symbol) => void
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Parallax/parallax.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2d3ff19e-968d-4216-866e-adfb266158ce', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-parallax-layer-registry', 'IParallaxLayerRegistry', 'Motion & Parallax', NULL, NULL, 'interfaces.catalog.i_parallax_layer_registry.description', 'Internal layer descriptor registered into the parent OrigamParallax via provide/inject. The parent reads speed, offsetX and offsetY to compute the per-frame transform, then applies it to the shared target HTMLElement.', 'export interface IParallaxLayerRegistry {
    /**
     * Internal layer descriptor as registered into the parent OrigamParallax
     * via `provide` / `inject`. The parent reads `speed`, `offsetX`,
     * `offsetY` to compute the per-frame transform, then applies it via the
     * shared `target` HTMLElement.
     */
    id: symbol
    speed: number
    offsetX: number
    offsetY: number
    target: HTMLElement
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Parallax/parallax-layer.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
