INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9fdf3a03-997b-4535-8d74-deb2dfdd62fc', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-parallax-props', 'IParallaxProps', 'Motion & Parallax', NULL, NULL, 'interfaces.catalog.i_parallax_props.description', 'Full props contract for <OrigamParallax>. Extends common component, color, spacing, border, dimension and audio contracts, plus parallax-specific controls for easing, speed, direction, event type and threshold.', 'export interface IParallaxProps extends ICommonsComponentProps, ITagProps, IColorProps, IBgColorProps, IPaddingProps, IMarginProps, IBorderProps, IRoundedProps, IElevationProps, IDimensionProps, IAudioProps, IUseAudioProps {
    /**
     * @deprecated Use `duration` instead. `animationDuration` is kept as a
     * silent alias for backwards-compat and will be removed in v3.0.0.
     * When both are passed, `animationDuration` wins so existing consumers
     * relying on the old prop name keep their behaviour, but a one-shot
     * console warning is emitted at runtime to flag the migration.
     */
    animationDuration?: number
    /**
     * Easing curve. Accepts either:
     *  - a TParallaxEasing keyword (`''linear'' | ''ease-out'' | ''spring''`),
     *    routed through the scroll-driven multi-layer code path,
     *  - or any raw CSS timing-function string (legacy mouse / scroll
     *    transition path, e.g. `''cubic-bezier(...)''`).
     *
     * The keyword form is preferred for new code; the raw string form is
     * kept for backwards compatibility with v2.x.
     */
    easing?: TParallaxEasing | string
    perspective?: number
    event?: TParallaxEvent
    active?: boolean
    duration?: number

    // Phase 4 — multi-layer parallax.

    /**
     * Direction of the parallax effect.
     *  - `''vertical''` (default) → translateY based on vertical scroll progress.
     *  - `''horizontal''`         → translateX based on vertical scroll progress.
     *  - `''both''`               → translate on both axes; on `event="move"`
     *                            this maps to a 2D mouse ratio.
     */
    direction?: TParallaxDirection

    /**
     * Global parallax speed multiplier when no `<OrigamParallaxLayer>` is
     * provided (single-layer mode). Equivalent to wrapping the slot in a
     * single layer with this speed. Default `0.5`.
     */
    speed?: number

    /**
     * Force the parallax effect OFF (translate stays at 0 regardless of
     * scroll / events). Distinct from `active` which only freezes the
     * mouse-driven mode. Useful for SSR, snapshot tests, or `prefers-
     * reduced-motion` integrations.
     */
    disabled?: boolean

    /**
     * Proportion (0 → 1) of the host that must enter the viewport before
     * the parallax effect activates. `0` (default) starts the effect the
     * moment the host''s top edge crosses the bottom of the viewport;
     * `0.3` waits until 30% of the host is visible.
     */
    threshold?: number
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Parallax/parallax.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('38b62bad-c929-43a4-a960-892ccba3da7f', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-parallax-provide', 'IParallaxProvide', 'Motion & Parallax', NULL, NULL, 'interfaces.catalog.i_parallax_provide.description', 'Provide context exposed by OrigamParallax to its OrigamParallaxElement children via Vue inject. Carries reactive refs for audio data, pointer event position, movement state, easing and container shape.', 'export interface IParallaxProvide {
