    (e: ''click:control'', event: MouseEvent): void
    (e: ''mousedown:control'', event: MouseEvent): void
    /** Fires when the computed strength level changes (v-model:strength). */
    (e: ''update:strength'', value: TPasswordStrengthLevel): void
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/PasswordField/password-field.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('cdf33d29-04a7-4826-a48e-baa8a0ead944', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-password-field-props', 'IPasswordFieldProps', 'Form & Input', NULL, NULL, 'interfaces.catalog.i_password_field_props.description', 'Props contract for <OrigamPasswordField>. Extends ITextFieldProps with show/hide toggle icons, strength bar, configurable requirements checklist and a minimal mode that strips all adornments.', 'export interface IPasswordFieldProps extends ITextFieldProps {
    /** Icon shown when the password is HIDDEN (toggle reveals). */
    onIcon?: TIcon
    /** Icon shown when the password is VISIBLE (toggle hides). */
    offIcon?: TIcon
    /** Native maxlength attribute mirrored into the requirements popup. */
    maxlength?: number
    /**
     * Master switch for the strength-requirements popup. When false, the
     * field behaves exactly like a TextField with type="password".
     */
    requirements?: boolean
    /**
     * Keep the requirements popup open even when the field is not focused.
     * Useful for forms that want the requirements always visible.
     */
    persistentRequirements?: boolean
    /** Minimum password length (default 8) — drives the `minLength` rule. */
    minLength?: number
    /** Require at least one lowercase letter. */
    needTiny?: boolean
    /** Require at least one uppercase letter. */
    needUppercase?: boolean
    /** Require at least one digit. */
    needNumber?: boolean
    /** Require at least one non-alphanumeric character. */
    needSpecial?: boolean
    /** Forwarded to the internal `<OrigamMenu>` (location, delays, etc.). */
    menuProps?: IMenuProps
    /** Reserved — toggle the requirements menu programmatically. */
    menu?: boolean
    /**
     * Renders a 4-segment strength bar under the input. Each segment fills
     * as the password gets stronger (weak → fair → good → strong) using
     * `--origam-password-field__strength---bg-{level}` semantic tokens.
     */
    strengthBar?: boolean
    /**
     * Inline requirements checklist (the modern, layout-aware API).
     * Pass an array of `IPasswordRequirement` predicates to render a
     * checklist under the input. When `requirements === true` and
     * `requirementRules` is undefined, the component falls back to
     * `DEFAULT_PASSWORD_REQUIREMENTS` (≥8 chars, ≥1 uppercase, ≥1
     * number, ≥1 special).
     *
     * Distinct from `rules` (inherited from `IValidationProps`) which
     * is the form-level validation rule array — those still flow through
     * to the underlying `<origam-input>`.
     */
    requirementRules?: IPasswordRequirement[]
    /**
     * Layout for the requirements checklist:
     *   - `list` (default) — vertical `<ul>` of `<li>` rows
     *   - `tiles` — wrap of `<OrigamChip>` pills
     */
    requirementsLayout?: ''list'' | ''tiles''
    /**
     * Strip every decoration (toggle eye, strength bar, requirements
     * checklist). Useful for confirm-password sub-fields where the
     * adornments would only add noise.
     */
    minimal?: boolean
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/PasswordField/password-field.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f7fcfaea-2912-4830-8f8a-09a268ac29bc', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-password-field-slots', 'IPasswordFieldSlots', 'Form & Input', NULL, NULL, 'interfaces.catalog.i_password_field_slots.description', 'Slots contract for <OrigamPasswordField>. Extends IFieldSlots and IInputSlots (minus default) with an info slot for the requirements popup body, a counter slot and a field slot to replace the native input.', 'export interface IPasswordFieldSlots extends IFieldSlots, Omit<IInputSlots, ''default''> {
