INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('05dcbe00-83d6-4458-a34a-42d245ec5d28', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-qr-code-logo', 'IQrCodeLogo', 'Data Display', NULL, NULL, 'interfaces.catalog.i_qr_code_logo.description', 'Optional logo overlay rendered at the centre of an OrigamQrCode. The overlay is painted on top of the matrix — error-correction compensates for covered modules up to the configured level.', 'export interface IQrCodeLogo {
    /**
     * Logo source. Any URL accepted by `<image href>` works — SVG, PNG,
     * data-URI, …. The SVG fragment loads the asset asynchronously; if
     * it fails the QR remains valid (only the overlay disappears).
     */
    src: string
    /**
     * Logo width as a proportion of the QR width (0..1).
     *
     * @default 0.2
     */
    size?: number
    /**
     * Pixel padding of the (opaque) backdrop drawn around the logo.
     * Keeps the modules immediately adjacent to the logo readable —
     * without padding, the scanner sees a soft-edged blob and fails.
     *
     * @default 6
     */
    padding?: number
    /**
     * Backdrop colour painted under the logo (and within the padding
     * box). Defaults to the QR background; pass a different value to
     * paint a coloured halo (e.g. brand colour for a logotype that
     * already includes its own white box).
     *
     * @default — falls back to the QR `background` prop.
     */
    background?: string
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/QrCode/qr-code-logo.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('efb40cd4-e3a4-4684-b757-3065be6e076f', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-qr-code-options', 'IQrCodeOptions', 'Data Display', NULL, NULL, 'interfaces.catalog.i_qr_code_options.description', 'Per-matrix overrides applied inside the SVG (modules + quiet zone) independently of the wrapper-level props. Pass via the qrCodeProps prop on <OrigamQrCode>.', 'export interface IQrCodeOptions extends IRoundedProps, IBgColorProps, IColorProps {}', NULL, NULL, NULL, 'packages/ds/src/interfaces/QrCode/qr-code.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b5d36afa-0a16-4c80-b2af-c4a0fb9d94c8', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-qr-code-props', 'IQrCodeProps', 'Data Display', NULL, NULL, 'interfaces.catalog.i_qr_code_props.description', 'Full props contract for <OrigamQrCode> — SSR-safe SVG QR code renderer. Extends all common DS surface contracts plus QR-specific controls for value, error correction level, quiet zone, overlays and accessibility.', 'export interface IQrCodeProps
    extends ICommonsComponentProps,
        ITagProps,
        IColorProps,
        IBgColorProps,
        IRoundedProps,
        IBorderProps,
        IElevationProps,
        ISizeProps,
        IPaddingProps,
        IMarginProps {
    /**
     * Text or URL encoded into the QR matrix. UTF-8 is supported via
     * the underlying `qrcode-generator` Byte mode.
     */
    value: string
    /**
     * Optional heading rendered above the QR matrix inside the
     * wrapper. Useful when the QR is presented alongside meta
     * (campaign name, recipient, …) — no manual extra markup needed.
     */
    title?: string
    /**
     * Per-matrix overrides — see `IQrCodeOptions`. When omitted, the
     * SVG inherits the wrapper-level `color` / `bgColor` / and
     * defaults to square modules.
     */
    qrCodeProps?: IQrCodeOptions
    /**
     * Reed-Solomon redundancy level. Higher levels reserve more matrix
     * cells for correction codewords (and therefore tolerate more
     * damage / overlay). See `TQrCodeErrorCorrectionLevel` for the
     * tradeoff matrix.
     *
     * @default ''M''
     */
    errorCorrectionLevel?: TQrCodeErrorCorrectionLevel
    /**
     * Number of modules reserved as quiet-zone padding around the
     * matrix. The ISO spec mandates ≥4 — anything smaller risks
     * scanner failures, anything larger is purely aesthetic.
     *
     * @default 4
     */
    quietZone?: number
    /**
     * Optional centred icon overlay — rendered via `<OrigamIcon>` on
     * top of the matrix. Coexists with `image`; the `#center` slot
     * overrides both when provided.
     */
    icon?: TIcon
    /**
     * Optional centred image overlay. Accepts a raw URL (string) or
     * the standard `ISrcObject` shape (src / srcset / lazySrc /
     * aspectRatio / alt). Rendered as an `<OrigamAvatar>` overlay.
     */
    image?: string | ISrcObject
    /**
     * Accessible label used as `aria-label`. When omitted, the
     * component falls back to `"QR code for {value}"`.
     */
    ariaLabel?: string
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/QrCode/qr-code.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3987792a-d7da-4b5d-bc82-6495af4277cb', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-qr-code-slots', 'IQrCodeSlots', 'Data Display', NULL, NULL, 'interfaces.catalog.i_qr_code_slots.description', 'Slots contract for <OrigamQrCode>. The center slot replaces the default icon/image overlay. When provided, both icon and image props are ignored.', 'export interface IQrCodeSlots {
