INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b2224a2a-8a40-4a64-9fdc-5a2df97d6206', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-sheet-emits', 'ISheetEmits', 'Overlay & Feedback', NULL, NULL, 'interfaces.catalog.i_sheet_emits.description', 'Emit signature for <OrigamSheet>. Two events drive the v-model surface: update:snap fires whenever a gesture or programmatic snapTo() call settles on a new snap-point id, and update:open fires on the closed/non-closed boundary so the parent stays in sync when the user dismisses via swipe-down.', 'export interface ISheetEmits {
    (e: ''update:snap'', id: TSheetSnapId): void

    (e: ''update:open'', value: boolean): void
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Sheet/sheet-emits.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b8c9b4b0-7b97-4221-a354-b7f2bf330db6', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-sheet-props', 'ISheetProps', 'Component Props', NULL, NULL, 'interfaces.catalog.i_sheet_props.description', 'Full props contract for <OrigamSheet> — a bottom/side sheet with optional swipe-to-expand gesture, discrete snap-points, and the full design surface (color, border, spacing, elevation, position).', 'export interface ISheetProps extends ITagProps, ICommonsComponentProps, IPaddingProps, IMarginProps, IColorProps, IBgColorProps, IBorderProps, IRoundedProps, IElevationProps, IDimensionProps, ILocationProps, IPositionProps, IActiveProps, IHoverProps {
    /**
     * Edge the sheet is anchored to. Drives the bottom-swipe gesture
     * (only `''bottom''` activates the touch-drag handle today; the other
     * sides reserve the prop for future "side-sheet" patterns).
     *
     * Defaults to `undefined` so existing consumers (Picker, Dialog,
     * ColorPickerField, PasswordField) keep their pre-Phase-3 layout.
     */
    side?: TDirectionBoth

    /**
     * Enable the mobile-style swipe-to-expand / swipe-to-dismiss
     * gesture. When true (and `side === ''bottom''`), the component
     * renders a drag handle and binds `useSheetSwipe`.
     *
     * False by default — every existing consumer of `OrigamSheet`
     * (notably `OrigamDialog`) inherits a no-op gesture layer.
     */
    swipeable?: boolean

    /**
     * Discrete snap-points the sheet can settle on between drags. The
     * height value is either a number (interpreted as px) or a CSS
     * length string (`''120px''`, `''50vh''`, `''90%''`).
     *
     * Defaults to closed/peek/half/full at 0 / 120px / 50vh / 90vh.
     */
    snapPoints?: ReadonlyArray<TSheetSnapPoint>

    /** Initial snap id when the sheet mounts. Defaults to `''half''`. */
    defaultSnap?: TSheetSnapId

    /**
     * v-model:open binding — `false` ⇄ `closed` snap, anything truthy
     * keeps the last non-closed snap (or `defaultSnap` on first mount).
     */
    open?: boolean

    /**
     * Disables the swipe gesture. The sheet stays at `defaultSnap` and
     * pointer events on the handle no-op.
     */
    disabled?: boolean

    /**
     * Persistent sheets cannot be swiped past `closed` — a fast
     * downward flick instead snaps to the next non-zero point (`peek`
     * by default). Mirrors `OrigamDialog`''s `persistent` semantics.
     */
    persistent?: boolean
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Sheet/sheet.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('04d2698c-5d6e-427d-82a5-60321e74aee1', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-sheet-swipe-options', 'ISheetSwipeOptions', 'Composable Options', NULL, NULL, 'interfaces.catalog.i_sheet_swipe_options.description', 'Options bag passed to useSheetSwipe() — the bottom-sheet drag gesture composable. Wires reactive refs for the sheet element, the drag handle, snap-points, and behavioural flags.', 'export interface ISheetSwipeOptions {
    /** The sheet root element — used to read its current rendered height. */
    el: Ref<HTMLElement | null | undefined>
    /** The drag-handle element — pointer events bind to this only. */
    handle: Ref<HTMLElement | null | undefined>
    /** Ordered list of snap points (any order; the composable sorts). */
    snapPoints?: Ref<ReadonlyArray<TSheetSnapPoint>>
    /** Initial snap id; defaults to `''half''`. */
    defaultSnap?: Ref<TSheetSnapId>
    /** When true, ignore pointer events entirely. */
    disabled?: Ref<boolean | undefined>
    /** When true, dragging past `closed` snaps back instead of dismissing. */
    persistent?: Ref<boolean | undefined>
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Sheet/sheet-swipe-options.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
