    snapTo: (id: TSheetSnapId) => void
    /** Convenience — alias for `snapTo(''closed'')`. */
    dismiss: () => void
    /** Resolved height (in px) of the active snap point. */
    currentSnapHeight: Ref<number>
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Sheet/sheet-swipe-return.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
