    /** Bold first line. Useful for short labels (e.g. "Saved"). */
    title?: string
    /** Body text under the title (or sole line when `title` absent). */
    message?: string
    /**
     * Semantic intent driving icon defaults, `role=status|alert`, and
     * surface coloring. Defaults to `info`.
     */
    intent?: TIntent
    /**
     * Auto-dismiss timeout in milliseconds. Overrides the stack-level
     * `defaultDuration`. Pass `0` to make the item sticky (no auto
     * dismiss — user has to dismiss it manually or programmatically).
     */
    duration?: number
    /**
     * Prepend icon override. Defaults to the per-intent icon
     * (`mdiCheckCircle` for success, `mdiAlertCircle` for danger, …).
     */
    icon?: TIcon
    /** Optional action buttons rendered in the snackbar footer. */
    actions?: ReadonlyArray<ISnackbarGroupItemAction>
    /** Whether to show the close (`X`) button. Default `true`. */
    dismissible?: boolean
    /** Callback fired once the item leaves the stack. */
    onDismiss?: () => void
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Snackbar/snackbar-group-item.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('54276ca7-2932-42d6-9e5d-b56835cd3965', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-snackbar-group-props', 'ISnackbarGroupProps', 'Component Props', NULL, NULL, 'interfaces.catalog.i_snackbar_group_props.description', 'Props contract for <OrigamSnackbarGroup> — a multi-toast container that orchestrates a queue of OrigamSnackbar instances driven through the useSnackbarGroup({ id }) composable.', 'export interface ISnackbarGroupProps extends ICommonsComponentProps, ITagProps {
    /**
     * Identifier of the stack this container renders. Pair with
     * `useSnackbarGroup({ id })` to spawn items into the same stack.
     * Multiple stacks can coexist (e.g. a global one + a per-region
     * one) — each one is keyed independently.
     *
     * @default ''default''
     */
    id?: string
    /**
     * Anchor location on the viewport. Drives both the absolute
     * positioning (top/bottom + left/right/center pinning) and the
     * `direction` default.
     *
     * @default ''bottom-right''
     */
    location?: TSnackbarGroupLocation
    /**
     * Maximum number of items rendered concurrently. When `notify()`
     * pushes a new item past `max`, the oldest item in the stack is
     * evicted FIFO (its `onDismiss` callback still fires).
     *
     * @default 5
     */
    max?: number
    /**
     * Default auto-dismiss timeout (ms) applied to items that do not
     * supply their own `duration`. Pass `0` to make all items sticky
     * by default.
     *
     * @default 5000
     */
    defaultDuration?: number
    /**
     * Gap between stacked items (CSS dimension — `''12px''`, `''1rem''`,
     * `8`, …).
     *
     * @default ''12px''
     */
    spacing?: string | number
    /**
     * Stacking order. When unset, defaults to `''top-down''` for
     * `top-*` locations and `''bottom-up''` for `bottom-*` locations
     * — matching the natural reading direction of fresh items.
     */
    direction?: TSnackbarGroupDirection
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Snackbar/snackbar-group.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('30acf78b-181d-4f45-86d6-3c19e893fad5', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-snackbar-item-props', 'ISnackbarItemProps', 'Component Props', NULL, NULL, 'interfaces.catalog.i_snackbar_item_props.description', 'Props contract for <OrigamSnackbarItem> — the pure visual layer of a single toast notification. Owns intent theming, icon/title/message layout, action buttons, dismiss button, and ARIA semantics.', 'export interface ISnackbarItemProps extends ICommonsComponentProps, ITypographyProps {
    /**
     * Semantic intent — drives icon defaults and surface colouring via
     * `--origam-color__feedback--{intent}---*` tokens.
     *
     * @default ''info''
     */
    intent?: TIntent

    /**
     * Optional title rendered as a bold first line.
     * Useful for short labels (e.g. "Saved", "Error").
     */
    title?: string

    /**
     * Body text rendered under the title (or as the sole line when
     * `title` is absent). Can be omitted when content is provided
     * via the `default` slot.
     */
    message?: string

    /**
     * Prepend icon override. When omitted, defaults to the per-intent
     * icon (`mdiCheckCircle` for success, `mdiAlertCircle` for danger,
     * etc.). Pass `false` to suppress the icon entirely.
     */
    icon?: TIcon | false

    /**
     * Action buttons rendered inline after the text block.
     * Each action fires `handler()` and dismisses the item by default
     * unless `keepOpen: true`.
     */
    actions?: ReadonlyArray<ISnackbarGroupItemAction>

    /**
     * Whether to render the close (✕) dismiss button.
     *
     * @default true
     */
    dismissible?: boolean

    /**
     * Accessible label for the dismiss button.
     *
     * @default ''Dismiss notification''
     */
    dismissLabel?: string

    /**
     * ARIA role for the item element. Inferred from `intent` when not
     * set explicitly: `warning` / `danger` → `''alert''`, others → `''status''`.
     */
    role?: ''status'' | ''alert''

    /**
     * ARIA live region politeness. Inferred from `intent` when not set
     * explicitly: `warning` / `danger` → `''assertive''`, others → `''polite''`.
     */
    ariaLive?: ''polite'' | ''assertive''

    /**
     * `data-cy` attribute injected on the root item element, forwarded
     * from the parent stack/snackbar so each toast is addressable in e2e
     * tests.
     */
    dataCy?: string
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Snackbar/snackbar-item.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
