INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2c4d238e-4225-4dc9-b22f-8ecaa76c9217', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-text-mask-props', 'ITextMaskProps', 'Data Display', NULL, NULL, 'interfaces.catalog.i_text_mask_props.description', 'Props for <OrigamTextMask> — a typographic "window" component that paints text as a transparent fill over an animated background (background-clip: text). Accepts gradient objects, raw CSS gradient strings, preset names or image URLs.', 'export interface ITextMaskProps extends ICommonsComponentProps, ITagProps, ITypographyProps {
    /**
     * Text to mask. Ignored when the `default` slot is provided.
     *
     * Rich markup (e.g. multi-line headlines, inline `<span>` overrides)
     * should go through the slot instead.
     */
    text?: string
    /**
     * Background painted behind the text glyphs. REQUIRED.
     *
     * Accepts:
     *   - A structured {@link IGradient} object — resolved via
     *     `resolveGradient()` and emitted as a `linear|radial|conic-gradient`
     *     CSS function call. Stops can reference intents (`primary`,
     *     `success`, …) — the resolver swaps them for token-driven CSS
     *     variables, so the gradient re-tints automatically when the
     *     theme changes.
     *   - A raw CSS gradient string (`linear-gradient(...)`, …) — emitted
     *     verbatim.
     *   - A preset name (`gradient-sunset`, etc.) — resolves to the
     *     matching `--origam-gradient---{slug}` CSS variable.
     *   - Any other string — used as a raw `background-image` value
     *     (typical: `url(/hero.jpg)` for an image, `url(data:...)` for an
     *     inline asset).
     */
    background: string | IGradient
    /**
     * Animate the background. Combined with `animationType` to pick a
     * keyframe set.
     *
     * @default false
     */
    animated?: boolean
    /**
     * Duration of one animation cycle. Accepts any CSS `<time>` value
     * (`''3s''`, `''750ms''`, …). Forwarded to `animation-duration`.
     *
     * @default ''3s''
     */
    animationDuration?: string
    /**
     * Animation strategy. See {@link TTextMaskAnimation}.
     *
     * @default ''pan''
     */
    animationType?: TTextMaskAnimation
    /**
     * `text-align` of the masked content.
     *
     * @default ''left''
     */
    align?: TBlockquoteAlign
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/TextMask/text-mask.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
