INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4bc5adaa-a5c9-4984-99b4-0294db90fa7a', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-use-chart-gauge-options', 'IUseChartGaugeOptions', 'Composable Options', NULL, NULL, 'interfaces.catalog.i_use_chart_gauge_options.description', 'Strict options consumed by useChartGauge. All getters are thunks so the composable can be reactively driven by props, a store, or computed sources without re-instantiation.', 'export interface IUseChartGaugeOptions {
    /** Current value (un-clamped — the engine clamps to [min..max]). */
    value: () => number
    /** Lower bound of the gauge range. */
    min: () => number
    /** Upper bound of the gauge range. */
    max: () => number
    /** SVG viewBox width. */
    width: () => number
    /** SVG viewBox height. */
    height: () => number
    /** SVG inner padding (frees room for endpoint labels). */
    padding: () => { top: number, right: number, bottom: number, left: number }
    /** Optional override for the arc thickness. */
    thickness?: () => number
    /** Optional override for the arc start angle (radians). */
    startAngle?: () => number
    /** Optional override for the arc end angle (radians). */
    endAngle?: () => number
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart-gauge.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d2bbd5e1-efa8-459c-b19e-7126d1a535ea', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-use-chart-options', 'IUseChartOptions', 'Composable Options', NULL, NULL, 'interfaces.catalog.i_use_chart_options.description', 'Strict, defaulted options consumed by useChart. All fields are getter thunks so the composable remains reactive without owning the prop reference. Drives path computation for all eight chart primitives.', 'export interface IUseChartOptions {
    type: () => TChartType
    series: () => Array<IChartSeries>
    categories: () => Array<string>
    stacked: () => boolean
    /**
     * Stacking mode when `stacked()` is `true`. Optional — defaults
     * to `''normal''` so callers that don''t expose the prop yet are
     * unaffected.
     */
    stacking?: () => TChartStacking
    donutHoleSize: () => number
    colorScheme: () => Array<TIntent | string>
    smoothing: () => TChartSmoothing
    yMin: () => number | undefined
    yMax: () => number | undefined
    width: () => number
    height: () => number
    padding: () => { top: number, right: number, bottom: number, left: number }
    /**
     * Per-label hidden set. Used by the single-pie / donut path to
     * skip slices whose category label was toggled OFF in the
     * legend. Cartesian / radar / gauge / multi-pie use `series.visible`
     * for the same purpose; this option exists for the pie/donut
     * "category as slice" mode where there''s no per-slice series to
     * attach visibility to. Optional — defaults to an empty Set.
     */
    hiddenLabels?: () => Set<string>
    /**
     * Secondary (right-hand) Y axis configuration. Optional — when
     * absent the engine ignores `series.yAxis === 1` assignments and
     * plots everything against the primary left axis.
     */
    secondaryYAxis?: () => IChartSecondaryYAxis | undefined
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Chart/chart.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3703b3fa-059a-48da-bb2b-c80d8e3f3313', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-use-clipboard-options', 'IUseClipboardOptions', 'Composable Options', NULL, NULL, 'interfaces.catalog.i_use_clipboard_options.description', 'Options accepted by useClipboard. Controls the duration the `copied` flag stays true after a successful write.', 'export interface IUseClipboardOptions {
    /**
