}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Clipboard/clipboard.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7c476b5c-1ae0-487c-bf53-9c46b07677d7', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-use-code-return', 'IUseCodeReturn', 'Composable Returns', NULL, NULL, 'interfaces.catalog.i_use_code_return.description', 'Public surface of the useCode composable. Lazily instantiates a shiki highlighter on first call and reuses it across every OrigamCode instance for the lifetime of the page.', 'export interface IUseCodeReturn {
    /**
     * Render `code` to a pre-tokenised HTML string. Resolves once the
     * underlying shiki highlighter has loaded the requested language /
     * theme (lazy; ~200 ms cold, instant on subsequent calls).
     */
    highlight (code: string, lang: TCodeLang): Promise<string>
    /**
     * Force the highlighter to load. Useful for stories / tests that want
     * to warm the cache before mounting consumers.
     */
    prime (): Promise<void>
    /**
     * Whether the singleton highlighter is ready. `false` on first paint,
     * flips to `true` once the dynamic import finishes.
     */
    isReady (): boolean
    /**
     * Wipe the LRU cache. Test-only — production code never needs this.
     */
    resetCacheForTesting (): void
