INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('74b2306b-87a4-4cf6-9f76-d59faec601fd', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-use-inline-edit-options', 'IUseInlineEditOptions', 'Composable Options', NULL, NULL, 'interfaces.catalog.i_use_inline_edit_options.description', 'Options accepted by useInlineEdit. Controls validation rules, trim behaviour, and lifecycle callbacks for the edit-in-place state machine.', 'export interface IUseInlineEditOptions {
    /**
     * Array of validation rules — evaluated in order before `validate`.
     * First failure blocks the commit and surfaces the error message.
     */
    rules?: Array<TInlineEditRule>
    /** Sync or async validator — see `TInlineEditValidator`. */
    validate?: TInlineEditValidator
    /**
     * Strip surrounding whitespace before running the validator and
     * emitting the new value.
     *
     * @default true
     */
    trim?: boolean
    /**
     * Called when the draft is committed. Use this when the composable
     * is consumed outside the SFC''s emit pipeline (e.g. inside a
     * unit-test harness or a wrapper composable).
     */
    onConfirm?: (value: string) => void
    /** Called when the draft is discarded. */
    onCancel?: () => void
    /** Called when a validator returns an error message. */
    onError?: (message: string) => void
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/InlineEdit/inline-edit.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
