    /** @deprecated Use COMPACT  */ MINIMAL = ''minimal''
}', NULL, NULL, NULL, 'packages/ds/src/types/Audio/audio-variant.type.ts', NULL, NULL, NULL, NULL, NULL, NULL, '{"typeKind": "type"}', false, NULL, NULL);
