INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3c72001c-e816-48bd-8978-9ecac0e88c8d', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-video-player-methods', 'IVideoPlayerMethods', 'Composable Returns', NULL, NULL, 'interfaces.catalog.i_video_player_methods.description', 'Imperative methods returned by useVideoPlayer. Extends the media-shared baseline IMediaPlayerMethods with video-specific commands: toggleFullscreen, togglePip, and related enter/exit variants.', 'export interface IVideoPlayerMethods extends IMediaPlayerMethods {
    /** Enter fullscreen (or noop if already in). */
    enterFullscreen: () => Promise<void>
    /** Exit fullscreen (or noop if not in). */
    exitFullscreen: () => Promise<void>
    /** Convenience: enter or exit based on current state. */
    toggleFullscreen: () => Promise<void>
    /** Enter picture-in-picture (or noop if unsupported). */
    requestPip: () => Promise<void>
    /** Exit picture-in-picture (or noop if not in). */
    exitPip: () => Promise<void>
    /** Convenience: enter or exit PIP based on current state. */
    togglePip: () => Promise<void>
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Video/video.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9a037365-7130-4f93-902e-238554ef2ec2', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-video-player-state', 'IVideoPlayerState', 'Composable Returns', NULL, NULL, 'interfaces.catalog.i_video_player_state.description', 'Reactive state surface returned by useVideoPlayer. Extends the media-shared IMediaPlayerState baseline with video-specific reactive refs: fullscreen and pip.', 'export interface IVideoPlayerState extends IMediaPlayerState {
    /** True when the element (or wrapper) is in fullscreen. */
    fullscreen: Ref<boolean>
    /** True when the video is in picture-in-picture. */
    pip: Ref<boolean>
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Video/video.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('993e5565-b0af-4939-ab10-39a177e4b32e', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-video-props', 'IVideoProps', 'Component Props', NULL, NULL, 'interfaces.catalog.i_video_props.description', 'Props for OrigamVideo. Extends the standard DS visual interfaces (color, dimension, rounded, border, margin, padding, elevation) with media-specific controls: src, poster, tracks, autoplay, loop, aspect-ratio, fullscreen, PIP, skip, quality switching, and download.', 'export interface IVideoProps extends ICommonsComponentProps, IColorProps, IBgColorProps, IDimensionProps, IRoundedProps, IBorderProps, IMarginProps, IPaddingProps, IElevationProps, ITypographyProps {
    /**
     * Media URL — either a single string for `<video src>`, or an array
     * of `<source>` descriptors when multiple formats are provided. The
     * browser walks the list top-down and picks the first source whose
     * `type` it can decode; pass the most preferred codec first.
     */
    src: string | Array<IVideoSource>
    /**
     * Image rendered before playback starts. Maps to the native
     * `poster` attribute when the `#poster` slot is not used.
     */
    poster?: string
    /**
     * Captions / subtitles / chapter tracks attached to the player.
     * Empty array (the default) renders no `<track>` element.
     *
     * @default []
     */
    tracks?: Array<IVideoTrack>
    /**
     * Starts playback as soon as `loadedmetadata` fires. Browsers
     * usually require `muted` to be true alongside `autoplay`; the
     * component forces `muted=true` when the user passes `autoplay`
     * without an explicit `muted` value.
     *
     * **Accessibility:** `autoplay` is suppressed when the user has
     * requested reduced motion (`prefers-reduced-motion: reduce`).
     *
     * @default false
     */
    autoplay?: boolean
    /**
     * Starts the player muted. Setting `muted=true` together with
     * `autoplay=true` is required for most browsers to allow
     * unattended playback.
     *
     * @default false
     */
    muted?: boolean
    /**
     * Loops playback. The player restarts at `0` when `ended` fires.
     *
     * @default false
     */
    loop?: boolean
    /**
     * Which control surface to render. `''custom''` paints the in-house
     * toolbar; `''native''` exposes the browser''s built-in `controls`
     * attribute; `''none''` renders neither so the consumer can drive
     * playback through the `#controls` slot or programmatically.
     *
     * @default ''custom''
     */
    controls?: TVideoControls
    /**
     * Mirrors the native `playsinline` attribute. Required on iOS to
     * keep the player inside the page (otherwise iOS hijacks the
     * playback into the system video viewer). Defaults to `true`
     * because that''s the in-page UX we want 99 % of the time.
     *
     * @default true
     */
    playsInline?: boolean
    /**
     * Buffering hint. `''metadata''` (default) loads just enough to
     * compute the duration; `''none''` defers everything until the user
     * presses play; `''auto''` lets the browser pre-buffer as much as it
     * wants.
     *
     * @default ''metadata''
     */
    preload?: ''none'' | ''metadata'' | ''auto''
    /**
     * CSS `aspect-ratio` value applied to the wrapper. Accepts the
     * presets (`''16/9''`, `''4/3''`, `''1/1''`, `''21/9''`, `''9/16''`) or any
     * raw value (`''2 / 1''`, `''1.85''`, …). The wrapper enforces the
     * ratio via `aspect-ratio` so the player never re-flows the page
     * after metadata loads.
     *
     * @default ''16/9''
     */
    aspectRatio?: string
    /**
     * Mirrors the native `crossorigin` attribute. Required when the
     * media or its tracks are served from a CORS-enabled origin and
     * the consumer needs canvas / WebAudio access to the decoded
     * frames. Affects how cookies are sent on the request.
     */
    crossorigin?: ''anonymous'' | ''use-credentials''
    /**
     * Disables the picture-in-picture button (and the matching
     * keyboard shortcut). Useful for content where PIP would defeat
     * the experience (e.g. a synced multi-player layout).
     *
     * @default false
     */
    disablePictureInPicture?: boolean
    /**
     * Seconds skipped by the ±skip buttons and by the double-tap
     * gesture on touch devices. Pass `0` to hide the skip buttons.
     *
     * @default 30
     */
    skipSeconds?: number
    /**
     * Show the centered ±skip buttons + play/pause overlay on hover
     * (and always while paused). When `false`, only the bottom
     * toolbar handles play/pause.
     *
     * @default true
     */
    showCenterControls?: boolean
    /**
     * Available playback rates exposed via the config menu.
     *
     * @default [0.25, 0.5, 0.75, 1, 1.25, 1.5, 1.75, 2]
     */
    playbackRates?: ReadonlyArray<number>
    /**
     * Initial playback rate. The runtime value is exposed via the
     * `update:playbackRate` emit and the `playbackRate` scoped-slot
     * binding.
     *
     * @default 1
     */
    playbackRate?: number
    /**
     * Layout mode for the bottom toolbar :
     *   - `true` — controls overlaid on the video bottom edge,
     *     auto-hide while playing once the cursor leaves.
     *   - `false` — controls always painted, no auto-hide.
     *
     * @default true
     */
    inset?: boolean
    /**
     * Enable the cast / AirPlay button (Remote Playback API). The
     * button only renders when the browser exposes the API AND at
     * least one cast-capable device is detected. No 3rd-party plugin.
     *
     * @default true
     */
    allowRemotePlayback?: boolean
    /**
     * Enable double-tap gestures on touch devices: tap-tap on the
     * left half = skip backward by `skipSeconds`, on the right half =
     * skip forward.
     *
     * @default true
     */
    doubleTapToSkip?: boolean
    /**
     * Adds a "Download" row to the settings (cog) menu that lets the
     * viewer download the currently-playing video file. The browser''s
     * standard download dialog opens — no analytics, no XHR, no server
     * call. Works on every modern browser (uses the native `download`
     * attribute on a hidden `<a>` element).
     *
     * Set to `false` (default) to hide the row, e.g. for licensed
     * content that must stay streamed.
     *
     * @default false
     */
    downloadable?: boolean
    /**
     * Override the downloaded file name. Defaults to the trailing
     * segment of the source URL. Useful when the URL is opaque
     * (e.g. signed-S3 with a hash basename) and you want the file
     * to land in the user''s Downloads folder with a clean name.
     */
    downloadFilename?: string
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Video/video.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('da64cbb7-f158-4290-9858-b9c3f8042b9a', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-video-scoped-slot-bindings', 'IVideoScopedSlotBindings', 'Component Slots', NULL, NULL, 'interfaces.catalog.i_video_scoped_slot_bindings.description', 'Bindings passed to the #controls scoped slot of OrigamVideo. The default toolbar is built on top of the exact same surface, so a consumer who replaces the slot has access to the full state machine without re-implementing event listeners.', 'export interface IVideoScopedSlotBindings {
    /** True while the `<video>` is decoding frames and producing audio. */
    playing: boolean
    /** True when playback is paused (or has not started yet). */
    paused: boolean
    /** Current playhead position in seconds. */
    currentTime: number
    /** Total duration in seconds. `NaN` until metadata is loaded. */
    duration: number
    /** End of the buffered range in seconds (= last byte the browser can play without stalling). */
    buffered: number
    /** Volume between 0 and 1 — independent from `muted`. */
    volume: number
    /** True when the output is muted. Independent from `volume`. */
    muted: boolean
    /** True when the element (or wrapper) is in fullscreen. */
    fullscreen: boolean
    /** True when the video is in picture-in-picture. */
    pip: boolean
    /** True between `loadstart` and `loadedmetadata` — used by the loader overlay. */
    loading: boolean
    /** Set to the most recent media error (if any), else null. */
    error: MediaError | Error | null
    /** Current playback rate (1 = normal). Mirrors the `update:playbackRate` v-model. */
    playbackRate: number
    /** True when at least one Remote Playback target is available on the network. */
    remoteAvailable: boolean
    /** Connection lifecycle from the Remote Playback API:
     *  `''disconnected'' | ''connecting'' | ''connected''`. */
    remoteState: ''disconnected'' | ''connecting'' | ''connected''
    /** Imperative actions — wired to the underlying `<video>` element. */
    methods: IVideoPlayerMethods
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Video/video.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4bd4ad71-ec69-4141-8aa1-59e3edcb80e1', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-video-slots', 'IVideoSlots', 'Component Slots', NULL, NULL, 'interfaces.catalog.i_video_slots.description', 'Slot signatures for OrigamVideo. Four slots let consumers replace the entire controls toolbar, the poster overlay, the loading overlay, and the error overlay.', 'export interface IVideoSlots {
    /**
     * Full toolbar replacement. Receives the runtime state + the
     * imperative methods. When omitted, the component renders its
     * built-in toolbar (play/pause + scrubber + time + volume +
     * captions + PIP + fullscreen).
     */
    controls?: (bindings: IVideoScopedSlotBindings) => any
    /**
     * Overlay rendered while playback has not yet started
     * (`currentTime === 0 && paused`). When omitted, the component
     * paints the `poster` image as a `background-image` on the
     * `<video>` element via the native attribute.
     */
    poster?: () => any
    /** Overlay rendered while the media is loading. */
    loading?: () => any
    /** Overlay rendered when an error occurred. */
    error?: (bindings: { error: MediaError | Error }) => any
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Video/video.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('afea6b49-c206-4eb5-abd1-6b7413c36faf', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-video-source', 'IVideoSource', 'Data Shapes', NULL, NULL, 'interfaces.catalog.i_video_source.description', 'A single <source> entry when the consumer passes multiple media URLs to OrigamVideo (typically one mp4 + one webm so the browser picks whichever codec it can decode). Supports optional quality labelling for the in-player quality switcher.', 'export interface IVideoSource {
    /** Absolute or root-relative URL to the media file. */
    src: string
    /**
     * MIME type — `"video/mp4"`, `"video/webm"`, `"application/vnd.apple.mpegurl"`
     * for HLS, etc. Optional but recommended: it lets the browser skip
     * sources it can''t decode without a network round-trip.
     */
    type?: string
    /**
     * Quality identifier used to group multiple sources of the same
     * content at different resolutions / bitrates (e.g. `"1080p"`,
     * `"720p"`, `"480p"`, `"4K"`, `"auto"`).
     *
     * When ≥ 2 sources expose distinct `quality` values, OrigamVideo
     * shows a "Quality" entry in the settings (cog) menu and lets the
     * user swap between them. The currently-playing source is then
     * matched on `quality` rather than on codec.
     */
    quality?: string
    /**
     * Optional human-readable label override for the quality switcher
     * menu. Defaults to the `quality` value when not provided. Use
     * this for cases like `quality: "auto"` rendered as `"Auto (720p)"`.
     */
    label?: string
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Video/video-track.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7da2ca3b-1975-4e52-b3e9-b042987f53b1', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-video-track', 'IVideoTrack', 'Data Shapes', NULL, NULL, 'interfaces.catalog.i_video_track.description', 'A single <track> declaration attached to the <video> element. Mirrors the HTML attributes of the native element 1:1 so consumers do not have to learn a new shape. The component renders one <track> per item.', 'export interface IVideoTrack {
    /**
     * `kind` of the track. `''captions''` is the default — used by the
     * built-in captions switcher. `''subtitles''` is treated the same way
     * for switching purposes; `''descriptions''` and `''chapters''` are
     * declared but not surfaced in the default toolbar (consumers
     * needing those expose their own `#controls` slot).
     */
    kind: TVideoTrackKind
    /**
     * URL of the WebVTT file. Same-origin or CORS-enabled, otherwise
     * the browser silently rejects the track.
     */
    src: string
    /**
     * BCP-47 language tag — `''en''`, `''fr''`, `''pt-BR''`, … Drives the
     * language label shown in the captions switcher and is exposed to
     * assistive technology via the underlying `<track srclang>`.
     */
    srclang: string
    /**
     * Human-readable label shown in the switcher (`"English"`,
     * `"Français"`, …). Defaults to the uppercased `srclang` when
     * omitted.
     */
    label?: string
    /**
     * Marks this track as the one to enable on load. At most one track
     * per kind should be flagged — if multiple are passed, the first
     * one wins.
     */
    default?: boolean
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Video/video-track.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('56a45efd-af30-4ed9-a54c-9ac53cf72108', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-virtual-props', 'IVirtualProps', 'Performance', NULL, NULL, 'interfaces.catalog.i_virtual_props.description', 'Props for virtualised list components — controls item height, the visible viewport height, and the animated scroll behaviour (duration and easing).', 'export interface IVirtualProps {
    itemHeight?: number | string
    height?: number | string
    /**
     * Animation duration (ms) applied to imperative scroll calls
     * (e.g. `scrollToIndex`). Set to `0` to jump instantly.
     * Default: 300.
     */
    scrollDuration?: number
    /**
     * Easing function name forwarded to `useGoTo` (`easeInOutCubic`,
     * `easeOutQuart`, …). Default: ''easeInOutCubic''.
     */
    scrollEasing?: string
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Commons/virtual.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('36def7f4-13dc-4294-8985-331d74e98360', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-virtual-scroll-item-emits', 'IVirtualScrollItemEmits', 'Component Emits', NULL, NULL, 'interfaces.catalog.i_virtual_scroll_item_emits.description', 'Emits fired by OrigamVirtualScrollItem. The resize-observed height is forwarded to the parent virtual scroller so it can update its intrinsic-size cache.', 'export interface IVirtualScrollItemEmits {
