INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ee6c09b6-22c7-46df-8a6f-1f45cf0b1a4f', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-virtual-scroll-item-props', 'IVirtualScrollItemProps', 'Component Props', NULL, NULL, 'interfaces.catalog.i_virtual_scroll_item_props.description', 'Props for OrigamVirtualScrollItem. Extends ICommonsComponentProps with a single renderless flag to strip the wrapper element when the consumer manages its own DOM node.', 'export interface IVirtualScrollItemProps extends ICommonsComponentProps {
    renderless?: boolean
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/VirtualScroll/virtual-scroll-item.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('487f3b2f-7ba8-4142-9e1c-164c7e199747', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-virtual-scroll-props', 'IVirtualScrollProps', 'Component Props', NULL, NULL, 'interfaces.catalog.i_virtual_scroll_props.description', 'Props for OrigamVirtualScroll. Extends ICommonsComponentProps, IDimensionProps, and IVirtualProps with an items array and a renderless flag for custom DOM rendering.', 'export interface IVirtualScrollProps extends ICommonsComponentProps, IDimensionProps, IVirtualProps {
    items?: Array<any>
    renderless?: boolean
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/VirtualScroll/virtual-scroll.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a314f5e0-5b9f-45b7-9591-46dab4520e18', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'interface', 'i-watermark-props', 'IWatermarkProps', 'Component Props', NULL, NULL, 'interfaces.catalog.i_watermark_props.description', 'Props for OrigamWatermark — a repeating diagonal overlay used to mark a sub-tree as CONFIDENTIAL / DRAFT / personalised by recipient. The component renders an absolutely-positioned layer over its #default slot using a SVG data-URL as background-image.', 'export interface IWatermarkProps extends ICommonsComponentProps, ITagProps {
    /**
     * Text glyph repeated across the tile. Required unless `image` is
     * passed. UTF-8 is supported (emoji, accents, …) and the SVG
     * `<text>` element renders with the browser''s font stack, so the
     * rendered glyph inherits anti-aliasing from the platform.
     */
    text?: string
    /**
     * URL / data-URL of an image used as the repeated glyph. Wins over
     * `text` when both are passed. Pair with a transparent PNG or SVG
     * for the cleanest result on dark surfaces.
     */
    image?: string
    /**
     * Opacity of the rendered glyph, between `0` and `1`. The value is
     * applied at the SVG level (not as a CSS `opacity` on the layer)
     * so the wrapped content stays at full opacity beneath.
     *
     * @default 0.1
     */
    opacity?: number
    /**
     * Rotation in degrees applied to each tile. Negative values rotate
     * counter-clockwise — `-30` produces the classic top-left to
     * bottom-right diagonal common to confidential-document watermarks.
     *
     * @default -30
     */
    angle?: number
    /**
     * Distance (in CSS pixels) between two adjacent tiles, measured
     * along both axes. Drives the density of the watermark: smaller
     * `gap` = tighter pattern.
     *
     * @default 120
     */
    gap?: number
    /**
     * Font size (in CSS pixels) of the text glyph. Ignored when the
     * `image` prop is used.
     *
     * @default 16
     */
    fontSize?: number
    /**
     * CSS `font-family` of the text glyph. `''inherit''` resolves to the
     * SVG element''s own default (Helvetica / Arial sans-serif on most
     * platforms) since the SVG is loaded as a data-URL — it cannot
     * inherit from the surrounding document.
     *
     * @default ''inherit''
     */
    fontFamily?: string
    /**
     * Colour of the text glyph. Any CSS colour string. `''currentColor''`
     * does NOT work here because the SVG is loaded as a data-URL and
     * therefore detached from the document''s cascade — pass an explicit
     * colour for non-default values.
     *
     * @default ''currentColor''
     */
    color?: string
    /**
     * CSS `font-weight` of the text glyph. Accepts the standard CSS
     * values (`100`–`900`, `''normal''`, `''bold''`, …).
     *
     * @default 400
     */
    fontWeight?: number | string
    /**
     * `z-index` of the overlay layer. Use a value above the wrapped
     * content but below any floating UI you want to keep clickable
     * (menus, tooltips, modals). Defaults to `1` so the watermark sits
     * just above the slot.
     *
     * @default 1
     */
    zIndex?: number
    /**
     * Installs a `MutationObserver` that re-injects the layer when it
     * is removed from the DOM or when its inline style hides it (e.g.
     * `display: none`, `opacity: 0`). The observer is scoped to the
     * component''s own DOM subtree and is disconnected on unmount.
     *
     * This is a **dissuasive** measure, not a security feature — a
     * user with DevTools can always disable JS or block the script.
     *
     * @default false
     */
    antiTamper?: boolean
    /**
     * Whether the overlay intercepts pointer events. `''none''` (the
     * default) lets clicks pass through to the wrapped content;
     * `''auto''` blocks interaction (useful when the watermark itself is
     * meant to be selectable for copy-paste, e.g. a public licence
     * notice).
     *
     * @default ''none''
     */
    pointerEvents?: ''none'' | ''auto''
}', NULL, NULL, NULL, 'packages/ds/src/interfaces/Watermark/watermark.interface.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
