INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0b5795ae-8e60-4fd8-9cbf-e0f25cebda13', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'type', 'empty-state-preset', 'TEmptyStatePreset', 'Interaction & State', NULL, NULL, 'types.catalog.empty_state_preset.description', 'Visual presets for <OrigamEmptyState>. Each preset bundles a default icon and intent so consumers do not need to wire those by hand for the common cases.', '/**
 * Visual presets for `<OrigamEmptyState>`. Each preset bundles a
 * default icon + intent mapping so consumers do not need to wire those
 * by hand for the 95% case. The icon and intent can still be
 * overridden via the matching props when a one-off variation is needed.
 *
 * - `no-data`     — generic "nothing to show yet" (empty collection).
 * - `no-results`  — search or filter returned nothing.
 * - `error`       — an operation failed; retry CTA is typical.
 * - `offline`     — connectivity issue; offline-mode CTA is typical.
 * - `locked`      — feature is gated (auth, plan, permissions).
 */
export type TEmptyStatePreset =
    | ''no-data''
    | ''no-results''
    | ''error''
    | ''offline''
    | ''locked''

// Runtime enum mirror (for iteration in stories / switch blocks):
export enum EMPTY_STATE_PRESET {
    NO_DATA    = ''no-data'',
    NO_RESULTS = ''no-results'',
    ERROR      = ''error'',
    OFFLINE    = ''offline'',
    LOCKED     = ''locked'',
}', NULL, NULL, NULL, 'packages/ds/src/types/EmptyState/empty-state-preset.type.ts', NULL, NULL, NULL, NULL, NULL, NULL, '{"typeKind": "type"}', false, NULL, NULL);
