INSERT INTO public.doc_directive_arg (id, created_at, updated_at, entry_id, name, type, required, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('467566f0-bf26-4ee6-9d41-cb8482cc0d5b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '5b43f804-830a-48fb-81f6-cbf8d0cf7e92', 'closeConditional', '(e: Event) => boolean', false, 'directives.click_outside.arg_close_conditional', 'Optional guard. The handler fires only when this function returns true. Useful to suppress callbacks while a panel is already closed.', 1, false, NULL, NULL);
INSERT INTO public.doc_directive_arg (id, created_at, updated_at, entry_id, name, type, required, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0b0945d3-db7d-444b-877d-032c332d8ce7', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '5b43f804-830a-48fb-81f6-cbf8d0cf7e92', 'include', '() => HTMLElement[]', false, 'directives.click_outside.arg_include', 'Returns a list of elements that should be treated as part of the component. Clicks on these elements do not trigger the handler.', 2, false, NULL, NULL);
INSERT INTO public.doc_directive_arg (id, created_at, updated_at, entry_id, name, type, required, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ab173420-02ce-422a-adf3-8f315cf170fb', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '22646d93-a34e-4079-896b-1d8f203dd95f', 'value', 'boolean | undefined', false, 'directives.contrast.arg_value', 'Omit or set to true to enable auto-contrast. Pass false to disable contrast enforcement for this element only.', 0, false, NULL, NULL);
INSERT INTO public.doc_directive_arg (id, created_at, updated_at, entry_id, name, type, required, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1ed623d4-0f03-41d7-98d9-84fde773818c', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'b4d3815a-c911-4ac0-b13f-6c76387bf095', 'value', 'boolean | { class: string }', false, 'directives.hover.arg_value', 'Pass false to disable the directive. Pass { class } to specify the CSS class added while the pointer is over the element.', 0, false, NULL, NULL);
INSERT INTO public.doc_directive_arg (id, created_at, updated_at, entry_id, name, type, required, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('cc10136f-2fa3-4528-98da-b185d22dc917', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '6750eb13-563c-4356-9e62-267b9a158199', 'handler', '(isIntersecting: boolean, entries: IntersectionObserverEntry[], observer: IntersectionObserver) => void', true, 'directives.intersect.arg_handler', 'Callback called on each intersection change. Receives the boolean convenience flag, the raw entries array, and the observer instance.', 0, false, NULL, NULL);
INSERT INTO public.doc_directive_arg (id, created_at, updated_at, entry_id, name, type, required, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('613f1dff-fd06-4f7d-aa32-399661e3cc6e', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '6750eb13-563c-4356-9e62-267b9a158199', 'options', 'IntersectionObserverInit', false, 'directives.intersect.arg_options', 'Standard IntersectionObserver constructor options (root, rootMargin, threshold). Only available in the object form of the binding.', 1, false, NULL, NULL);
INSERT INTO public.doc_directive_arg (id, created_at, updated_at, entry_id, name, type, required, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4e6b9227-1118-49d2-97ae-67c48489c624', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'e408aa4d-5324-4ce8-9baf-c75bfe2af1ac', 'value', 'boolean | { class?: string; center?: boolean; circle?: boolean }', false, 'directives.ripple.arg_value', 'Pass false to disable. Pass an object to set a custom class on the ripple element or to override center/circle via the value (equivalent to using modifiers).', 0, false, NULL, NULL);
INSERT INTO public.doc_directive_arg (id, created_at, updated_at, entry_id, name, type, required, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('befbbed8-a4e0-4432-a214-5ac8603dedbd', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'fd6e7015-cf65-4c44-98c4-2b35de0cebb0', 'start / end / move', '(e: { originalEvent: TouchEvent } & ITouchData) => void', false, 'directives.touch.arg_lifecycle', 'Raw touch lifecycle handlers. The event is augmented with ITouchData (coordinates, delta, velocity, direction).', 0, false, NULL, NULL);
INSERT INTO public.doc_directive_arg (id, created_at, updated_at, entry_id, name, type, required, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6f0c0ae5-2fed-4b06-8001-f834d900bf71', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'fd6e7015-cf65-4c44-98c4-2b35de0cebb0', 'left / right / up / down', '(e: ITouchData) => void', false, 'directives.touch.arg_swipe', 'Swipe direction handlers. Fired when the touchend velocity and displacement exceed the detection threshold.', 1, false, NULL, NULL);
INSERT INTO public.doc_directive_arg (id, created_at, updated_at, entry_id, name, type, required, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('74b920b9-6a2d-438b-8121-a3e5e3bb93fd', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'fd6e7015-cf65-4c44-98c4-2b35de0cebb0', 'parent', 'boolean', false, 'directives.touch.arg_parent', 'When true, listeners are attached to the parentElement instead of the element itself. Useful for scrollable containers where the element may be smaller than the gesture area.', 2, false, NULL, NULL);
INSERT INTO public.doc_directive_arg (id, created_at, updated_at, entry_id, name, type, required, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('115220c1-388e-492f-b19f-6bdab930cb7f', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'fd6e7015-cf65-4c44-98c4-2b35de0cebb0', 'options', 'AddEventListenerOptions', false, 'directives.touch.arg_options', 'Options forwarded to addEventListener (e.g. { passive: true } to improve scroll performance).', 3, false, NULL, NULL);


