INSERT INTO public.doc_directive_modifier (id, created_at, updated_at, entry_id, name, type, required, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5136d818-41ee-4d93-b22d-e1618b5ed173', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'b4d3815a-c911-4ac0-b13f-6c76387bf095', 'callback', NULL, false, 'directives.hover.modifier_callback', 'When present, the directive value is treated as a function (isHovered: boolean) => void instead of a class object.', 0, false, NULL, NULL);
INSERT INTO public.doc_directive_modifier (id, created_at, updated_at, entry_id, name, type, required, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a39c8163-9017-4893-91b1-1b37de0312a1', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'b4d3815a-c911-4ac0-b13f-6c76387bf095', 'stop', NULL, false, 'directives.hover.modifier_stop', 'Calls stopPropagation() on the underlying pointer events, preventing parent hover handlers from triggering.', 1, false, NULL, NULL);
INSERT INTO public.doc_directive_modifier (id, created_at, updated_at, entry_id, name, type, required, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('28488737-7a83-406d-9630-d4c985638552', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '6750eb13-563c-4356-9e62-267b9a158199', 'once', NULL, false, 'directives.intersect.modifier_once', 'Disconnects the observer after the element enters the viewport for the first time. Useful for one-shot animations.', 0, false, NULL, NULL);
INSERT INTO public.doc_directive_modifier (id, created_at, updated_at, entry_id, name, type, required, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7466e472-05cc-4174-9100-b05d871d76ea', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '6750eb13-563c-4356-9e62-267b9a158199', 'quiet', NULL, false, 'directives.intersect.modifier_quiet', 'Suppresses the first callback call that IntersectionObserver fires synchronously on setup, so the handler only fires on real scroll-triggered intersections.', 1, false, NULL, NULL);
INSERT INTO public.doc_directive_modifier (id, created_at, updated_at, entry_id, name, type, required, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('12133247-bfad-4adb-9db6-5f74c53c6939', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'e408aa4d-5324-4ce8-9baf-c75bfe2af1ac', 'center', NULL, false, 'directives.ripple.modifier_center', 'The ripple always starts from the geometric center of the element instead of the actual click position. Typically used for icon buttons.', 0, false, NULL, NULL);
INSERT INTO public.doc_directive_modifier (id, created_at, updated_at, entry_id, name, type, required, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5aaf9b26-d742-44fb-967b-dd0711772ce4', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'e408aa4d-5324-4ce8-9baf-c75bfe2af1ac', 'circle', NULL, false, 'directives.ripple.modifier_circle', 'Clips the ripple container to a perfect circle. Combine with .center for round icon buttons.', 1, false, NULL, NULL);
INSERT INTO public.doc_directive_modifier (id, created_at, updated_at, entry_id, name, type, required, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('92b0497d-24da-4e67-a2a6-9126719090c9', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'e408aa4d-5324-4ce8-9baf-c75bfe2af1ac', 'stop', NULL, false, 'directives.ripple.modifier_stop', 'Calls stopPropagation() on the pointer event after spawning the ripple, preventing parent click handlers from firing.', 2, false, NULL, NULL);


