INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('7c41a99c-7e0f-4e69-b49a-865159c33312', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '3c406961-aaca-4991-86eb-c620d0848503', 'components.alert.examples.intents.title', 'Intent colors', '<template>
  <div style="display: flex; flex-direction: column; gap: 0.5rem;">
    <origam-alert color="success" title="Success" text="Operation completed successfully." prepend-icon="mdi-check-circle" />
    <origam-alert color="danger"  title="Error"   text="Something went wrong." prepend-icon="mdi-alert-circle" />
    <origam-alert color="warning" title="Warning" text="Please review your settings." prepend-icon="mdi-alert" />
    <origam-alert color="info"    title="Info"    text="A new update is available." prepend-icon="mdi-information" />
  </div>
</template>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('2128d078-e91d-4ff6-a98d-5166f51b4bd9', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '3c406961-aaca-4991-86eb-c620d0848503', 'components.alert.examples.closable.title', 'Closable alert', '<template>
  <origam-alert
    v-model="visible"
    color="primary"
    closable
    title="Dismissable"
    text="Click the close button to hide this alert."
  />
</template>

<script setup lang="ts">
import { ref } from ''vue''
const visible = ref(true)
</script>', 'vue', 1, false, NULL);
