INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('04bac9c3-d621-44d0-81a7-46bef71c58e4', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '57969984-e607-4946-9eb3-b38cb15389cc', 'components.app_bar.examples.basic.title', 'Basic app bar', '<template>
