INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('f03b4daf-21e8-4ceb-a7ce-23bad933efeb', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '57969984-e607-4946-9eb3-b38cb15389cc', 'components.app_bar.examples.scroll.title', 'Scroll behaviours', '<template>
  <!-- Hide on scroll down, show on scroll up -->
  <origam-app-bar scroll-behavior="hide" :scroll-threshold="200">
    My App
  </origam-app-bar>

  <!-- Elevate when scrolled away from top -->
  <origam-app-bar scroll-behavior="elevate">
    My App
  </origam-app-bar>

  <!-- Activate surface when scrolled (transparent → painted) -->
  <origam-app-bar
    scroll-behavior="active"
    :active="{ bgColor: ''surface'' }"
  >
    My App
  </origam-app-bar>
</template>', 'vue', 1, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('01d33ff1-cb42-485a-92e7-86949b608dac', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '03a86cd8-29b5-4310-baa5-d1a3335d635c', 'components.audio.examples.basic.title', 'Basic player', '<template>
