INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('348ad98e-aec5-4032-bd8d-3c2fb998ff63', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '03a86cd8-29b5-4310-baa5-d1a3335d635c', 'components.audio.examples.playlist.title', 'Playlist with loop', '<template>
  <origam-audio
    :playlist="tracks"
    loop-mode="all"
    :shuffle="true"
    waveform
    v-model:current-track-index="activeTrack"
    @track-change="onTrackChange"
  />
</template>
<script setup lang="ts">
import { ref } from ''vue''
const activeTrack = ref(0)
const tracks = [
  { src: ''/audio/track1.mp3'', title: ''Track One'', artist: ''Origam'', cover: ''/covers/1.jpg'' },
  { src: ''/audio/track2.mp3'', title: ''Track Two'', artist: ''Origam'', cover: ''/covers/2.jpg'' }
]
const onTrackChange = (track, index) => console.log(''Now playing'', track.title)
</script>', 'vue', 1, false, NULL);
