INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('2e5296d1-8e32-4e65-8d45-038e1ca68d6c', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '1ca6f7ab-ca5d-4486-b864-57fcc0faf667', 'components.calendar.examples.basic.title', 'Basic calendar', '<template>
  <origam-calendar
    v-model:view="view"
    v-model:current-date="currentDate"
    :events="events"
    @event-click="onEventClick"
    @date-click="onDateClick"
  />
</template>
<script setup lang="ts">
import { ref } from ''vue''
const view = ref(''month'')
const currentDate = ref(new Date())
const events = [
  { id: 1, title: ''Team Meeting'', start: new Date(2026, 5, 16, 10), end: new Date(2026, 5, 16, 11), category: ''work'' },
  { id: 2, title: ''Lunch'', start: new Date(2026, 5, 18, 12), end: new Date(2026, 5, 18, 13), category: ''personal'' }
]
const onEventClick = (event, domEvent) => console.log(''clicked'', event.title)
const onDateClick = (date) => console.log(''date clicked'', date)
</script>', 'vue', 0, false, NULL);
