INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('7c6d4319-868b-44c0-9cb0-0c781401f74b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '3c9ed565-23e3-4bc6-a541-b20820f567eb', 'components.chart_heatmap.examples.basic.title', 'Basic heatmap', '<template>
