INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('57238836-7a31-440f-a0df-608f90a83a62', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '8999c753-00b3-4a1c-ba8e-4f3c61424902', 'components.chart_legend.examples.basic.title', 'Standalone legend', '<template>
  <origam-chart-legend
    :items="items"
    position="bottom"
    @series-toggle="onToggle"
  />
</template>

<script setup lang="ts">
import { ref } from ''vue''

const items = ref([
  { series: { name: ''Revenue'', data: [], visible: true }, index: 0, color: ''#7c3aed'', visible: true },
  { series: { name: ''Costs'',   data: [], visible: true }, index: 1, color: ''#ef4444'', visible: true }
])

const onToggle = (series, nextVisible) => {
  const entry = items.value.find((e) => e.series.name === series.name)
  if (entry) {
    entry.visible = nextVisible
    entry.series.visible = nextVisible
  }
}
</script>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('6038ceba-95e7-4c3c-aea3-26518dc8120b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '8999c753-00b3-4a1c-ba8e-4f3c61424902', 'components.chart_legend.examples.custom_item.title', 'Custom legend entry', '<template>
  <origam-chart-legend :items="items">
    <template #legend-item="{ series, index, visible }">
      <span
        :style="{ opacity: visible ? 1 : 0.4, display: ''flex'', alignItems: ''center'', gap: ''6px'' }"
      >
        <span
          style="display:inline-block;width:16px;height:4px;border-radius:2px"
          :style="{ backgroundColor: items[index]?.color }"
        />
        {{ series.name }}
        <em v-if="!visible">(hidden)</em>
      </span>
    </template>
  </origam-chart-legend>
</template>', 'vue', 1, false, NULL);
