INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('1d3fd2e8-056d-4ec2-80f8-3beac612e427', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '6c7d4fc8-4575-481c-b2cd-b9e8e7c43e1b', 'components.client_only.examples.placeholder.title', 'Layout-preserving placeholder', '<template>
  <!-- Reserve the same block dimensions on SSR to avoid layout shift -->
  <origam-client-only
    placeholder-tag="div"
    placeholder-class="chart-skeleton"
  >
    <origam-chart type="area" :series="series" height="300" />
  </origam-client-only>
</template>

<style scoped>
.chart-skeleton {
  height: 300px;
  background: var(--origam-color__surface---raised);
  border-radius: var(--origam-radius---md);
}
</style>', 'vue', 1, false, NULL);
