INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('11d46e38-25af-48a9-ae4b-4bb4694658f9', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'bae28be3-ff6b-438e-8689-fcb23c0edbb7', 'components.clipboard.examples.custom_trigger.title', 'Custom trigger via slot', '<template>
  <origam-clipboard :value="code" @copy="toast(''Copied!'')">
    <template #default="{ copy, copied }">
      <origam-btn
        :color="copied ? ''success'' : ''primary''"
        :prepend-icon="copied ? ''mdi-check'' : ''mdi-content-copy''"
        :text="copied ? ''Copied!'' : ''Copy code''"
        variant="tonal"
        @click="copy"
      />
    </template>
  </origam-clipboard>
</template>', 'vue', 1, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('bf6790b1-2745-44fd-a8e5-97d440003ad2', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'bae28be3-ff6b-438e-8689-fcb23c0edbb7', 'components.clipboard.examples.inline_code.title', 'Inline inside OrigamCode', '<template>
