INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('d87c0e32-55b4-4b9d-a09f-50e64d01f41b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '7403d04c-dd98-4a00-9c00-444c09982412', 'components.command_palette.examples.async.title', 'Async commands', '<template>
  <origam-command-palette
    v-model="open"
    :commands="results"
    :loading="fetching"
    @query="search"
  />
</template>

<script setup lang="ts">
  import { ref } from ''vue''
  const open = ref(false)
  const results = ref([])
  const fetching = ref(false)
  async function search(q: string) {
    fetching.value = true
    results.value = await fetchCommands(q)
    fetching.value = false
  }
</script>', 'vue', 1, false, NULL);
