INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('abe57a8e-77b0-4446-ba92-796b526a3d57', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '9ba44b4c-970b-4501-b01c-7b104be54404', 'components.data_table.examples.server.title', 'Server-side sorting & pagination', '<template>
  <origam-data-table
    :headers="headers"
    :items="serverItems"
    :loading="loading"
    :items-per-page="pageSize"
    :page="currentPage"
    @update:options="onOptionsChange"
  />
</template>

<script setup lang="ts">
  import { ref } from ''vue''
  const serverItems = ref([])
  const loading = ref(false)
  const currentPage = ref(1)
  const pageSize = ref(10)

  async function onOptionsChange(opts) {
    loading.value = true
    serverItems.value = await fetchPage(opts)
    loading.value = false
  }
</script>', 'vue', 2, false, NULL);
