INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('e9ca9219-24aa-4423-b630-b89b9b95f7a5', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '23912b58-89c2-44b7-822c-6715950f3cbf', 'components.form.examples.server_errors.title', 'Server-side errors', '<template>
  <origam-form
    :error-messages="serverErrors"
    @submit.prevent="handleSubmit"
  >
    <origam-text-field v-model="username" label="Username" />
    <template #actions="{ submit }">
      <origam-btn text="Login" @click="submit" />
    </template>
  </origam-form>
</template>

<script setup lang="ts">
import { ref } from ''vue''
const username = ref('''')
const serverErrors = ref([])
const handleSubmit = async () => {
  const res = await login(username.value)
  if (!res.ok) serverErrors.value = [res.message]
}
</script>', 'vue', 1, false, NULL);
