INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('9b32632b-7a9d-4be2-af4b-8f8da1e6c5f3', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '1fd41e00-b26b-4436-b939-f872016412fc', 'components.infinite_scroll.examples.basic.title', 'Automatic infinite scroll', '<script setup lang="ts">
import { ref } from ''vue''

const items = ref(Array.from({ length: 20 }, (_, i) => `Item ${i + 1}`))

async function onLoad({ done }: { done: (s: ''ok'' | ''empty'' | ''error'') => void }) {
  const nextPage = await fetchNextPage()
  if (nextPage.length) {
    items.value.push(...nextPage)
    done(''ok'')
  } else {
    done(''empty'')
  }
}
</script>
<template>
  <origam-infinite-scroll height="400" @load="onLoad">
    <div v-for="item in items" :key="item">{{ item }}</div>
  </origam-infinite-scroll>
</template>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('8ee1556a-48f4-47a1-9ea0-f625e72ae431', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '1fd41e00-b26b-4436-b939-f872016412fc', 'components.infinite_scroll.examples.manual.title', 'Manual load mode', '<template>
  <origam-infinite-scroll mode="manual" height="300" @load="onLoad">
    <div v-for="item in items" :key="item">{{ item }}</div>
  </origam-infinite-scroll>
</template>', 'vue', 1, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('4de48204-5c38-4076-9f56-74c42a5afade', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'ce6c5c77-f469-4579-8970-cfc96dbbf2e0', 'components.infinite_scroll_intersect.examples.basic.title', 'Manual sentinel usage', '<template>
  <!-- Prefer <origam-infinite-scroll> for the common use-case.
       Use this low-level sentinel only when you need custom scroll logic. -->
  <div ref="scrollRoot" style="overflow: auto; height: 400px;">
    <div v-for="item in items" :key="item.id">{{ item.label }}</div>

    <origam-infinite-scroll-intersect
      side="bottom"
      :root-ref="scrollRoot"
      margin="0px 0px 200px 0px"
      @intersect="onIntersect"
    />
  </div>
</template>

<script setup lang="ts">
import { ref } from ''vue''

const scrollRoot = ref<HTMLElement>()
const items = ref([{ id: 1, label: ''Item 1'' }])

function onIntersect({ side, isIntersecting }: { side: string; isIntersecting: boolean }) {
  if (isIntersecting) loadMore()
}

function loadMore() {
  // fetch next page
}
</script>', 'vue', 0, false, NULL);
