INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('4bd59256-93d1-416f-b6cc-3c44537f2043', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '749afa9e-b507-48a5-bf6c-21271929120b', 'components.inline_edit.examples.async.title', 'Async validation', '<script setup lang="ts">
import { ref } from ''vue''
const slug = ref(''my-project'')

async function checkSlug(value: string): Promise<true | string> {
