INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('542797c3-a208-4239-89cf-d7cae806d7d0', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '8f1fa75a-7540-4eb3-ab44-37c43710839e', 'components.parallax_layer.examples.scroll.title', 'Scroll-driven multi-layer', '<template>
  <origam-parallax event="scroll" :height="500">
    <!-- far background — slow -->
    <origam-parallax-layer :speed="0.2">
      <img src="/sky.jpg" alt="Sky" style="width: 100%; height: 130%;" />
    </origam-parallax-layer>
    <!-- mid layer -->
    <origam-parallax-layer :speed="0.5" :offset-y="-20">
      <img src="/mountains.png" alt="Mountains" style="width: 100%;" />
    </origam-parallax-layer>
    <!-- foreground — faster than scroll -->
    <origam-parallax-layer :speed="1.5" :z-index="2">
      <h2>Hero title</h2>
    </origam-parallax-layer>
  </origam-parallax>
</template>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('ac77a2fe-7ee3-491f-b6b9-ea68c1121553', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '8f1fa75a-7540-4eb3-ab44-37c43710839e', 'components.parallax_layer.examples.css_path.title', 'CSS scroll-driven (progressive enhancement)', '<template>
  <!-- When animation-timeline: scroll() is supported, ParallaxLayer uses CSS
