INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('62223d58-f16a-4593-ad02-cfd5f3c4f9e6', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '50267bd9-5e96-412c-ae81-0b18139b79de', 'components.password_field.examples.tiles.title', 'Tiles layout', '<template>
