INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('61145ab9-94cf-4d4b-9ce5-57f2f33ff887', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'bafa23f2-c194-4b92-81c5-700db1dc166a', 'components.treeview.examples.basic.title', 'Basic file tree', '<script setup lang="ts">
