</template>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('dbb08bba-3861-498b-bd5a-98f553c4c6b0', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'bafa23f2-c194-4b92-81c5-700db1dc166a', 'components.treeview.examples.selection.title', 'Single selection', '<script setup lang="ts">
import { ref } from ''vue''
import type { ITreeviewNode } from ''origam''

const selected = ref<string>()
const items: ITreeviewNode[] = [
  { id: ''a'', label: ''Node A'' },
  { id: ''b'', label: ''Node B'', children: [
    { id: ''b1'', label: ''Node B1'' }
  ] }
]
</script>
<template>
  <origam-treeview
    v-model="selected"
    :items="items"
    select-mode="single"
  />
  <p>Selected: {{ selected }}</p>
</template>', 'vue', 1, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('d3074944-ba5a-4593-a379-901a627c26c4', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '46679f55-87bd-43f2-950e-6e93ae42e281', 'components.treeview_node.examples.basic.title', 'Standalone node (inside a treeview)', '<template>
