INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('c42f5ee9-5d93-4d02-a7f7-9914f18d8d2a', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '64f43b9d-c41e-419b-8592-337aecb337cc', '', 'Click-triggered overlay', '<script setup lang="ts">
import { ref } from ''vue''
import { useActivator } from ''origam''

const isActive = ref(false)
const isTop = ref(true)

const { activatorRef, activatorEvents, contentEvents } = useActivator(
  { openOnClick: true },
  { isActive, isTop }
)
</script>

<template>
  <button v-bind="activatorEvents" ref="activatorRef">Open</button>
  <div v-if="isActive" v-bind="contentEvents">Overlay content</div>
</template>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('fb93d8bf-f17d-4db0-baa5-99b9f63781ce', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '64f43b9d-c41e-419b-8592-337aecb337cc', '', 'Hover-triggered tooltip', '<script setup lang="ts">
import { ref } from ''vue''
import { useActivator } from ''origam''

const isActive = ref(false)
const isTop = ref(true)

const { activatorRef, activatorEvents, contentEvents } = useActivator(
  { openOnHover: true, openDelay: 300, closeDelay: 100 },
  { isActive, isTop }
)
</script>

<template>
  <span v-bind="activatorEvents" ref="activatorRef">Hover me</span>
  <div v-if="isActive" v-bind="contentEvents" role="tooltip">Tooltip</div>
</template>', 'vue', 1, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('3f2bf770-2f19-4bd0-9349-4cf9a704f91f', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '7a11802d-9786-4adb-a342-6ffdf9d3a8d9', '', 'Toggle button with v-model', '<script setup lang="ts">
import { useActive } from ''origam''

const props = defineProps<{ modelValue?: boolean }>()
const emit = defineEmits([''update:modelValue''])

const { isActive, activeClasses, onActive } = useActive(props, ''modelValue'')
</script>

<template>
  <button
    :class="[''my-btn'', activeClasses]"
    :aria-pressed="isActive"
    @click="onActive"
  >
    {{ isActive ? ''On'' : ''Off'' }}
  </button>
</template>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('94a1d4a2-c44f-4305-800d-31c268869447', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '7a11802d-9786-4adb-a342-6ffdf9d3a8d9', '', 'Forced active with style override', '<!-- Always active, success surface override -->
<origam-btn :active="{ enabled: true, bgColor: ''success'' }">
  Always selected
</origam-btn>', 'vue', 1, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('6ba0f1a6-4f99-412c-9cd2-d1a667734305', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '91a6bf47-da70-4191-90c6-a851fe513c72', '', 'Component with prepend/append icons', '<script setup lang="ts">
import { useAdjacent } from ''origam''

const props = defineProps<{
  prependIcon?: string
  appendIcon?: string
  prependAvatar?: string
  appendAvatar?: string
}>()

const {
  hasPrepend,
  hasAppend,
  onClickPrepend,
  onClickAppend
} = useAdjacent(props)
</script>

<template>
  <div class="my-component">
    <span v-if="hasPrepend" @click="onClickPrepend"><!-- prepend --></span>
    <slot />
    <span v-if="hasAppend" @click="onClickAppend"><!-- append --></span>
  </div>
</template>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('f8abf6c0-081e-4e2c-851b-97b7df138117', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '91a6bf47-da70-4191-90c6-a851fe513c72', '', 'Status-aware prepend icon override', '<script setup lang="ts">
import { computed } from ''vue''
import { useAdjacent } from ''origam''

const props = defineProps<{ status?: ''success'' | ''error''; prependIcon?: string }>()

const statusIcon = computed(() =>
  props.status === ''success'' ? ''mdi-check-circle'' :
  props.status === ''error''   ? ''mdi-alert-circle'' :
  undefined
)

const { hasPrepend, onClickPrepend } = useAdjacent(props, statusIcon)
</script>', 'vue', 1, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('5fb38589-7c92-47ad-93bf-539e12255340', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '2e5cd49a-cb4a-4ef0-ac53-bd071c9e278d', '', '16:9 video placeholder', '<script setup lang="ts">
