INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('80936156-519d-454d-b922-d43e230682ee', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '2e5cd49a-cb4a-4ef0-ac53-bd071c9e278d', '', 'Hardcoded square', '<script setup lang="ts">
