INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('25909d1f-38c3-4114-a38f-3226267acab2', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '5fb99ab4-60be-436d-bf84-d8ca40472305', '', 'Basic audio player with frequency visualiser', '<script setup lang="ts">
import { useAudio } from ''origam''

const props = defineProps<{ audio?: string; playAudio?: boolean }>()

const { audioRef, isPlaying, audioData, onPlay, onStop } = useAudio(props)
</script>

<template>
  <audio ref="audioRef" :src="audio" />
  <button @click="isPlaying ? onStop() : onPlay()">
    {{ isPlaying ? ''Pause'' : ''Play'' }}
  </button>
  <canvas v-if="audioData" />
</template>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('b184c05f-9c77-4188-8b32-5e196cd0134d', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '40bdc8fb-4914-4107-999f-03b23f0b34fd', '', 'Minimal headless audio player', '<script setup lang="ts">
import { useAudioPlayer } from ''origam''

const { audioRef, state, methods } = useAudioPlayer({ autoplay: false })
</script>

<template>
  <audio ref="audioRef" src="/track.mp3" />
  <button @click="methods.toggle()">
    {{ state.playing.value ? ''Pause'' : ''Play'' }}
  </button>
  <span>{{ state.currentTime.value.toFixed(1) }} / {{ state.duration.value.toFixed(1) }}s</span>
</template>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('3bb22b6f-4313-488f-9330-35f9bbc05a40', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '40bdc8fb-4914-4107-999f-03b23f0b34fd', '', 'Using OrigamAudio (recommended)', '<template>
