INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('99099207-b6ef-4547-aab9-9e7a26e1b251', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '25889cc4-16cd-4452-82bf-cd3c4bbc58a0', '', 'Usage with props object', '<script setup lang="ts">
