INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('ff00a69e-e375-48d0-b575-2f8ef1dcfc56', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'ed26f58b-3514-4fb6-890e-7393114695dd', '', 'Common border patterns', '<!-- Boolean: thin border (utility class origam--border-thin) -->
<origam-card border />

<!-- Named width keyword -->
<origam-card border="thick" />

<!-- Direction subset -->
<origam-card border="top" />

<!-- Custom color override -->
<origam-card border border-color="var(--origam-color__action--primary---bg)" />', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('cedb21a4-415d-4f67-90ee-b2548d1d7153', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'b7cd987d-51ee-44c4-9ba8-b882456dcfac', '', 'Month grid driven from props', '<script setup lang="ts">
import { computed, ref } from ''vue''
import { useCalendar } from ''origam''
import type { IEvent } from ''origam''

const events = ref<IEvent[]>([])
const currentDate = ref(new Date())
const view = ref<''month'' | ''week'' | ''day'' | ''agenda''>(''month'')

const { visibleDateRange, buildMonthGrid, expandedEvents, navigate } = useCalendar(
  {
    events: () => events.value,
    view: () => view.value,
    currentDate: () => currentDate.value,
    firstDayOfWeek: () => 1,
    slotDuration: () => 30,
    dayStartHour: () => 8,
    dayEndHour: () => 20,
  },
  (v) => { view.value = v },
  (d) => { currentDate.value = d }
)

const weeks = computed(() => buildMonthGrid(currentDate.value))
</script>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('590bd77e-4da1-435c-a929-4c6e616b08fe', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '89545269-c44c-4368-bbcf-609db7a344ae', '', 'Using getPadding in a custom cell renderer', '<script setup lang="ts">
import { useCell } from ''origam''
import type { IInternalDataTableHeader } from ''origam''

defineProps<{ column: IInternalDataTableHeader }>()

const { getPadding } = useCell()
</script>

<template>
  <td :style="{ padding: getPadding(column) }">
    <slot />
  </td>
</template>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('9cc3bd3a-0332-4718-b495-4e4af98f74e2', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '89b1262b-658a-438f-911f-20080950a593', '', 'Line chart driven from props', '<script setup lang="ts">
import { computed } from ''vue''
import { useChart } from ''origam''
import type { IChartSeries } from ''origam''

const props = defineProps<{
  series: IChartSeries[]
  categories: string[]
  width: number
  height: number
}>()

const { viewBox, scales, ticks, paths, legend, hover, onPointHover } = useChart({
  type: () => ''line'',
  series: () => props.series,
  categories: () => props.categories,
  stacked: () => false,
  donutHoleSize: () => 0.6,
  colorScheme: () => [],
  smoothing: () => ''none'',
  yMin: () => undefined,
  yMax: () => undefined,
  width: () => props.width,
  height: () => props.height,
  padding: () => ({ top: 20, right: 20, bottom: 40, left: 50 }),
})
</script>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('5d4647d6-b26d-4124-80ff-c221083cadb8', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'a00adb4c-b546-4b85-b215-6e2df2e90d98', '', 'Speedometer gauge at 65%', '<script setup lang="ts">
