INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('89900735-04ed-40c6-9181-9074c4ebbd2b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'a00adb4c-b546-4b85-b215-6e2df2e90d98', '', 'Custom arc sweep (half-circle)', '<script setup lang="ts">
