INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('e024a0b3-2273-47de-923a-bdf8eef84442', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '47f371d1-009f-41cd-81e2-3c3c5ec2de2d', '', 'Basic scroll-wheel zoom', '<script setup lang="ts">
import { useChartZoom } from ''origam''

const categories = [''Jan'', ''Feb'', ''Mar'', ''Apr'', ''May'', ''Jun'']

const {
  zoomStart,
  zoomEnd,
  isZoomed,
  zoomReset,
  zoomBy,
  panBy,
  WHEEL_ZOOM_STEP
} = useChartZoom({ dataLength: () => categories.length })

function onWheel(event: WheelEvent) {
  event.preventDefault()
  const delta = event.deltaY > 0 ? WHEEL_ZOOM_STEP : -WHEEL_ZOOM_STEP
  zoomBy(delta, 0.5)
}
</script>

<template>
  <div @wheel.prevent="onWheel">
    <span>Showing {{ zoomStart }} – {{ zoomEnd }}</span>
    <button v-if="isZoomed" @click="zoomReset">Reset zoom</button>
  </div>
</template>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('8c940c77-a97f-4801-9c42-ed2bfd14348c', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '47f371d1-009f-41cd-81e2-3c3c5ec2de2d', '', 'Programmatic pan', '<script setup lang="ts">
import { useChartZoom } from ''origam''

const { panBy, zoomTo } = useChartZoom({ dataLength: () => 12 })

// Zoom in on months 2–5 then pan right by 1
zoomTo(2, 5)
panBy(1) // now shows [3, 6]
</script>', 'vue', 1, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('97ab7740-3af9-4e6d-9548-fbed32dc324d', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'cbebd0b8-17f7-4246-8b58-665a028ac73a', '', 'Copy with automatic feedback', '<script setup lang="ts">
import { useClipboard } from ''origam''

const { copy, copied, error } = useClipboard({ feedbackDuration: 2000 })
</script>

<template>
  <button @click="copy(''Hello, world!'')">
    {{ copied ? ''Copied!'' : ''Copy'' }}
  </button>
  <p v-if="error">Failed: {{ error.message }}</p>
</template>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('7b942145-a236-42d7-8f3c-f8f401b3b6d0', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'cbebd0b8-17f7-4246-8b58-665a028ac73a', '', 'Check API support before copying', '<script setup lang="ts">
import { useClipboard } from ''origam''

const { copy, isSupported } = useClipboard()

async function handleCopy() {
  if (!isSupported.value) {
    console.warn(''Clipboard API not available — using fallback'')
  }
  const ok = await copy(''npm install origam'')
  if (!ok) console.error(''Copy failed'')
}
</script>', 'vue', 1, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('224df7df-6a35-4243-9944-989224bd7535', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'a2b66d1a-4da7-497d-baa0-6ffe7a676796', '', 'Highlight a snippet on mount', '<script setup lang="ts">
import { ref, onMounted } from ''vue''
import { useCode } from ''origam''

const { highlight } = useCode()
const html = ref('''')

onMounted(async () => {
  html.value = await highlight(''const x = 42'', ''typescript'')
})
</script>

<template>
  <pre><code v-html="html" /></pre>
</template>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('5765aefb-5efc-4dfe-a272-39d2233c19a4', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'a2b66d1a-4da7-497d-baa0-6ffe7a676796', '', 'Prime the highlighter eagerly', '<script setup lang="ts">
import { useCode } from ''origam''

const { prime, isReady } = useCode()

// Load shiki as soon as the component mounts so the first
// highlight() call is instant.
prime()
</script>', 'vue', 1, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('2fd94a86-a0d9-4a27-889a-1fbc7c1e3bad', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '944a393a-abe7-469a-b261-1965876f11f7', '', 'Basic intent color', '<script setup lang="ts">
