INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('b83279f0-b9d0-4c1d-b712-9af2246420a0', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '944a393a-abe7-469a-b261-1965876f11f7', '', 'Gradient foreground (background-clip: text)', '<script setup lang="ts">
import { computed } from ''vue''
import { useColor } from ''origam''

