INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('0d4632e7-0e08-4317-8d51-564cd6b221fb', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '63da2f09-e5bf-4c85-b763-f5e4b20e8b65', '', 'State-aware surface component', '<script setup lang="ts">
import { useColorEffect, useHover, useActive } from ''origam''

const props = defineProps<{
  color?: string
  bgColor?: string
}>()

const { isHover, onMouseenter, onMouseleave } = useHover(props)
const { isActive, onActive } = useActive(props)
const { colorClasses, colorStyles } = useColorEffect(props, isHover, isActive)
</script>

<template>
  <button
    :class="colorClasses"
    :style="colorStyles"
    @mouseenter="onMouseenter"
    @mouseleave="onMouseleave"
    @click="onActive"
  >
    Hover and click me
  </button>
</template>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('8c0ae92d-6bb2-431b-9ac3-19e7b2cff379', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '45a503d5-7a03-453d-b068-8a78cac44d9d', '', 'Register a command from a feature component', '<script setup lang="ts">
import { useCommand } from ''origam''

const { register } = useCommand()

// Auto-unregistered when the component unmounts
register({
  id: ''new-document'',
  label: ''New document'',
  icon: ''mdi-file-plus'',
  shortcut: ''Ctrl+N'',
  action: () => createDocument()
})
</script>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('dad586ba-836c-4acd-a1f1-54dd47826174', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '45a503d5-7a03-453d-b068-8a78cac44d9d', '', 'Open and close the palette programmatically', '<script setup lang="ts">
import { useCommand } from ''origam''

const { open, close, isOpen } = useCommand()
</script>

<template>
  <button @click="open">Open palette</button>
  <origam-command-palette :model-value="isOpen" @update:model-value="isOpen.value = $event" />
</template>', 'vue', 1, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('e909aec9-bdec-4dd9-8525-4ff166e400a7', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'b47cbce3-e0a2-40d9-b377-a8b58bf1d494', '', 'Branch on container query support', '<script setup lang="ts">
import { useCssSupport } from ''origam''

const { css } = useCssSupport()
</script>

<template>
  <ClientOnly>
    <div v-if="css.containerQueries" class="layout--cq">
      Container-query layout
    </div>
    <div v-else class="layout--js">
      JS ResizeObserver fallback
    </div>
  </ClientOnly>
</template>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('bd5ad550-8387-45f8-a45e-9c4b8033c2e8', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'b47cbce3-e0a2-40d9-b377-a8b58bf1d494', '', 'Free-form query with supportsAny', '<script setup lang="ts">
import { useCssSupport } from ''origam''

const { supportsAny, supports } = useCssSupport()

const hasSubgrid = supportsAny(''display: subgrid'', ''grid-template-rows: subgrid'')
const hasHas = supports(''selector(:has(*))'')
</script>', 'vue', 1, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('48589cf1-acf5-485e-ba3d-25965c297184', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'b47cbce3-e0a2-40d9-b377-a8b58bf1d494', '', 'Hydration-safe markup gate (useCssSupportClient)', '<script setup lang="ts">
import { useCssSupportClient } from ''origam''

// Starts false (SSR-safe), flips to real value on mount
const supportsContainer = useCssSupportClient(''containerQueries'')
</script>

<template>
  <div v-if="supportsContainer">CSS path</div>
  <div v-else>JS fallback path</div>
</template>', 'vue', 2, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('85004e12-3de5-4690-afde-c82c901332b6', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '5b90c089-ef2d-4851-9851-43aebe0b488b', '', 'Format today''s date', '<script setup lang="ts">
import { useDate } from ''origam''

const adapter = useDate()
const today = adapter.date()
const formatted = adapter.format(today, ''fullDate'')
</script>

