</template>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('5658210b-564c-4c42-8f9d-288ecea7550f', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '5b90c089-ef2d-4851-9851-43aebe0b488b', '', 'Compute the week array for the current month', '<script setup lang="ts">
import { ref, computed } from ''vue''
import { useDate } from ''origam''

const adapter = useDate()
const month = ref(adapter.date())

const weeks = computed(() => adapter.getWeekArray(month.value))
</script>', 'vue', 1, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('8ff9e649-d874-43b8-80dd-e650209e010c', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '4952c992-f32d-4f61-85a4-a1603926d70d', '', 'Render a month grid', '<script setup lang="ts">
