  date: new Date(),
  firstDayOfWeek: 1,
  weeksInMonth: ''dynamic'',
  showAdjacentMonths: true,
  weekdays: [0, 1, 2, 3, 4, 5, 6]
})

const { daysInMonth, weeksInMonth } = useDatePickerCalendar(props)
</script>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('c2e09630-ed80-4476-98f1-52d09ebb01ba', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '9845f0d8-8e47-4417-ba53-937df474236a', '', 'Opt in to defaults resolution in a component', '<script setup lang="ts">
import { useDefaults } from ''origam''
import type { IBtnProps } from ''origam''

