</script>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('3a0449b8-1098-4c60-8395-3c83a1c4f050', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '9845f0d8-8e47-4417-ba53-937df474236a', '', 'Provide defaults for a subtree', '<template>
  <!-- All OrigamBtn inside will default to color="primary" size="lg" -->
  <origam-defaults-provider :defaults="{ ''origam-btn'': { color: ''primary'', size: ''lg'' } }">
    <slot />
  </origam-defaults-provider>
</template>', 'vue', 1, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('848305e5-98b6-4842-8aaf-ba83df513e20', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '2e27fa8e-0a3d-4a22-ac39-7af628d849c8', '', 'Tooltip with open/close delay', '<script setup lang="ts">
import { ref } from ''vue''
import { useDelay } from ''origam''

const isOpen = ref(false)

const { runOpenDelay, runCloseDelay } = useDelay(
  { openDelay: 300, closeDelay: 100 },
  (value) => { isOpen.value = value }
)
</script>

<template>
  <span
    @mouseenter="runOpenDelay"
    @mouseleave="runCloseDelay"
  >
    Hover me
  </span>
  <div v-if="isOpen">Tooltip content</div>
</template>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('5d4e7602-d0fd-4fe1-802d-303760278007', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '2e27fa8e-0a3d-4a22-ac39-7af628d849c8', '', 'Await the delay promise', '<script setup lang="ts">
import { useDelay } from ''origam''

const { runOpenDelay } = useDelay({ openDelay: 500 })

async function onHover() {
  // Wait 500 ms before doing something
  await runOpenDelay()
  console.log(''Delay elapsed'')
}
</script>', 'vue', 1, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('506f1897-05d6-48aa-a18d-84ea8ae222c3', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '2cd2b2f7-ff08-421e-a4f9-f23b1f496e89', '', 'Density variants', '<origam-btn density="compact">Compact</origam-btn>
