INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('f685af09-3c80-4571-aee0-455374334a01', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '52372682-c102-4b97-8a75-da91fbad4691', '', 'Basic usage', '<script setup lang="ts">
