INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('7b0dfa60-4121-4e32-be7b-72df8acc6b40', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '7a821c82-dae6-4bf0-a503-dca570ff7920', '', 'Conditional rendering by breakpoint', '<script setup lang="ts">
