INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('77078899-5a73-4f7c-bfa9-18b6badcbc18', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '7a821c82-dae6-4bf0-a503-dca570ff7920', '', 'Custom mobileBreakpoint per component', '<script setup lang="ts">
