INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('62f19297-c504-403e-b2eb-cc3989cefdfb', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'b1cc7734-1eb9-4a37-8fd1-595f37da76f4', '', 'Horizontal panel resizer', '<script setup lang="ts">
