INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('cf0faac2-a534-41c2-bbf9-a512a52f2066', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '68a4c524-57ad-403a-ba26-73941154799b', '', 'Card elevation variants', '<!-- Origam rung (preferred) -->
