INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('97a1439a-7131-4c5b-9b1b-94b5b9c820e8', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '1a4efccf-60dc-4135-9cbd-ddd994a751bf', '', 'Custom expand cell using useExpanded', '<script setup lang="ts">
