INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('d7956808-7df0-4586-a6ae-97f68f5b8f20', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '1a4efccf-60dc-4135-9cbd-ddd994a751bf', '', 'DataTable with expandable rows', '<template>
