INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('206d4ac5-998c-4246-85ef-03712c3c3773', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '1d966010-c0f9-4c82-a784-c5f38a34188d', '', 'Search over a name list', '<script setup lang="ts">
import { ref } from ''vue''
import { useFilter } from ''origam''
import type { IInternalItem } from ''origam''

interface User extends IInternalItem {
  value: string
  raw: { name: string; email: string }
}

const users = ref<User[]>([
  { value: ''1'', raw: { name: ''Alice'', email: ''alice@example.com'' } },
  { value: ''2'', raw: { name: ''Bob'',   email: ''bob@example.com'' } },
])
const search = ref('''')

const { filteredItems } = useFilter(
  { filterKeys: [''name'', ''email''], filterMode: ''intersection'', noFilter: false },
  users,
  search
)
</script>

<template>
  <origam-text-field v-model="search" placeholder="Search..." />
  <origam-list>
    <origam-list-item v-for="u in filteredItems" :key="u.value" :title="u.raw.name" />
  </origam-list>
</template>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('a39f1f09-11ec-4fdc-b0da-9e99f2e1e3d8', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '4b7ae932-e29f-454e-b20f-7d100419052c', '', 'Input field with focus styling', '<script setup lang="ts">
import { useFocus } from ''origam''

const props = defineProps<{ focused?: boolean }>()
const emit = defineEmits<{ (e: ''update:focused'', value: boolean): void }>()

const { isFocused, focusClasses, onFocus, onBlur } = useFocus(props)
</script>

<template>
  <div :class="[''my-field'', focusClasses]">
    <input @focus="onFocus" @blur="onBlur" />
  </div>
</template>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('d31f9c4c-fc12-457b-a5b2-419d3ccc221a', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '4b7ae932-e29f-454e-b20f-7d100419052c', '', 'Programmatic focus via v-model:focused', '<template>
