INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('2d1842cd-cf84-4afb-ae59-42bc56e646dd', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '7e25cf85-df31-48af-b8b9-ac1c44654ff2', '', 'Form with programmatic validation', '<script setup lang="ts">
import { ref, useTemplateRef } from ''vue''

const form = useTemplateRef(''form'')
const isValid = ref<boolean | null>(null)

async function submit () {
  const { valid } = await form.value?.validate()
  if (valid) console.log(''Submit!'')
}
</script>

<template>
  <origam-form ref="form" v-model="isValid" @submit.prevent="submit">
    <origam-text-field
      name="email"
      label="Email"
      :rules="[v => !!v || ''Required'']"
    />
    <origam-btn type="submit" :disabled="isValid === false">Send</origam-btn>
  </origam-form>
</template>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('8fd9af2a-57e5-479b-b549-88094747d422', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '7e25cf85-df31-48af-b8b9-ac1c44654ff2', '', 'Fast-fail form', '<template>
