    <origam-text-field name="username" label="Username" :rules="usernameRules" />
    <origam-text-field name="password" label="Password" type="password" :rules="passwordRules" />
    <origam-btn type="submit">Login</origam-btn>
  </origam-form>
</template>', 'vue', 1, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('75aed56a-d8ba-4808-bd16-2804cbee16ac', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '0e04b752-48d9-4321-994f-061a53ca17a6', '', 'Scroll to an anchor element', '<script setup lang="ts">
