INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('fe186ef1-9706-452a-906a-7ff853e5db6c', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '3253e92e-d809-4e84-8274-498a3b3b132d', '', 'Defining a group provider component', '<script setup lang="ts">
