INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('dedb8b70-55bc-4f00-8823-d3926a8d209d', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '91176919-ca83-4d6f-adea-6dcc5061120c', '', 'Creating headers in a DataTable parent', '<script setup lang="ts">
