INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('a90d2a32-4260-49e6-94c0-1bac69ed47ca', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '91176919-ca83-4d6f-adea-6dcc5061120c', '', 'Consuming headers in a child component', '<script setup lang="ts">
