INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('3e3ae5a9-74f7-443e-81f7-2b2e5acbeaff', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '10e22e11-2d9c-41f6-9be6-9101c4eba63b', '', 'Press-and-hold stepper', '<script setup lang="ts">
import { ref } from ''vue''
import { useHold } from ''origam''

const count = ref(0)

const { holdStart, holdStop } = useHold({
  toggleUpDown: (increment) => {
    count.value += increment ? 1 : -1
  }
})
</script>

<template>
  <div>
    <button
      @mousedown="holdStart(''down'')"
      @mouseup="holdStop"
      @mouseleave="holdStop"
    >−</button>
    <span>{{ count }}</span>
    <button
      @mousedown="holdStart(''up'')"
      @mouseup="holdStop"
      @mouseleave="holdStop"
    >+</button>
  </div>
</template>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('3c27d40d-ef50-4b80-a129-a53e18f55b47', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'c40d1c3c-f013-4d23-b2a7-b41dde6edf9b', '', 'Simple modifier hotkey', '<script setup lang="ts">
