INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('f7a85881-0b46-4cbd-8cfd-bc62f5a5dc9a', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'c40d1c3c-f013-4d23-b2a7-b41dde6edf9b', '', 'Key sequence (vim-style)', '<script setup lang="ts">
