INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('6989c70a-1f07-463f-85c1-d64202d2bc96', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'c40d1c3c-f013-4d23-b2a7-b41dde6edf9b', '', 'Reactive hotkey (toggleable)', '<script setup lang="ts">
