INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('44968210-e533-4465-af56-f4757219df0b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '1ff790fd-d77b-4fd6-ad37-b324b43076c0', '', 'Component with hover color effect', '<script setup lang="ts">
import { useHover, useColorEffect } from ''origam''

const props = defineProps<{
  color?: string
  bgColor?: string
}>()

const { isHover, hoverClasses, onMouseenter, onMouseleave } = useHover(props)
const { colorStyles } = useColorEffect(props, isHover)
</script>

<template>
  <div
    :class="hoverClasses"
    :style="colorStyles"
    @mouseenter="onMouseenter"
    @mouseleave="onMouseleave"
  >
    Hover me
  </div>
</template>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('719c4616-c42e-4fc7-b7e7-405302bcfb4d', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '1ff790fd-d77b-4fd6-ad37-b324b43076c0', '', 'Forced hover (story / test)', '<!-- Always rendered in hover state — useful for stories -->
