<!-- Style override on hover -->
<origam-btn :hover="{ bgColor: ''success'' }">Hover = success</origam-btn>', 'vue', 1, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('bede6125-7923-408d-b04e-2c306662989b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'ce6495be-19b2-4e70-acbf-a901040737cc', '', 'Guard a client-only component', '<script setup lang="ts">
import { useHydration } from ''origam''

const isMounted = useHydration()
</script>

