  <div v-else class="skeleton" aria-hidden="true" />
</template>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('1969b40e-ea29-42d8-bcc1-f44bb143de8d', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'ce6495be-19b2-4e70-acbf-a901040737cc', '', 'Deferred computation until hydrated', '<script setup lang="ts">
