INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('1f749799-0314-4d1d-8b75-1e9192cc1d31', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '4422940c-05ad-435f-8173-2baa6b8f2bbb', '', 'Register icons when creating the Origam plugin', 'import { createOrigam, createIcons } from ''origam''
