INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('6c156b2e-abd3-4522-9457-df9cfd95b151', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'e5c1c6d4-7a45-4273-90eb-b81c17fb8b25', '', 'Custom threshold with callback', '<script setup lang="ts">
import { useIntersectionObserver } from ''origam''

const { intersectionRef, isIntersecting } = useIntersectionObserver(
  (entries) => {
    console.log(''intersection entries'', entries)
  },
  { threshold: 0.5, rootMargin: ''0px 0px -100px 0px'' }
)
</script>

<template>
  <section :ref="intersectionRef">
    50% visible triggers the callback
  </section>
</template>', 'vue', 1, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('d265bcb4-c61b-47b7-a6ed-6413ecffc3c0', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '12629cd1-60f3-441b-8d8d-db0dcf54dde9', '', 'Normalise a string item list', '<script setup lang="ts">
import { useItems } from ''origam''

const { items } = useItems({
  items: [''Apple'', ''Banana'', ''Cherry''],
  itemTitle: (v: string) => v,
  itemValue: (v: string) => v,
  returnObject: false
})
// items.value → [{ title: ''Apple'', value: ''Apple'', raw: ''Apple'', ... }, ...]
</script>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('e0c22e95-51a0-4b3c-9bb3-2fd77b52c1cb', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '12629cd1-60f3-441b-8d8d-db0dcf54dde9', '', 'Round-trip with transformIn / transformOut', '<script setup lang="ts">
import { ref } from ''vue''
import { useItems } from ''origam''

const modelValue = ref([''banana''])
const { items, transformIn, transformOut } = useItems({
  items: [
    { id: ''apple'', label: ''Apple'' },
    { id: ''banana'', label: ''Banana'' }
  ],
  itemTitle: ''label'',
  itemValue: ''id'',
  returnObject: false
})

// Convert model → internal selection
const selected = transformIn(modelValue.value)
// Convert internal selection → model
const out = transformOut(selected)
</script>', 'vue', 1, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('bf6ed421-6c2b-425e-b162-b085a22a9128', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'a9a5f7d5-513f-40b3-bed8-d14d5d0fb1ed', '', 'Read the main content rectangle', '<script setup lang="ts">
