</template>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('c5f8e378-8e97-41b2-a3da-ce6b46745f03', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'a9a5f7d5-513f-40b3-bed8-d14d5d0fb1ed', '', 'Inspect a registered layout item', '<script setup lang="ts">
