INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('ad6e5b15-4502-4c70-96ec-15466445f766', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '451177b5-4a9d-4676-8c14-4a5c76643193', '', 'Lazy-mount an overlay', '<script setup lang="ts">
import { shallowRef } from ''vue''
import { useLazy } from ''origam''

const isOpen = shallowRef(false)
const { hasContent, onAfterLeave } = useLazy({ eager: false }, isOpen)
</script>

<template>
  <Transition @after-leave="onAfterLeave">
    <div v-if="isOpen">
      <template v-if="hasContent">
        <!-- Expensive content only mounted once opened -->
      </template>
    </div>
  </Transition>
</template>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('1a5345f1-fa67-4b75-ad3e-d8506afce649', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '451177b5-4a9d-4676-8c14-4a5c76643193', '', 'Eager rendering (always in DOM)', '<script setup lang="ts">
import { shallowRef } from ''vue''
import { useLazy } from ''origam''

const isOpen = shallowRef(false)
// eager:true → hasContent is always true, content never removed
const { hasContent } = useLazy({ eager: true }, isOpen)
</script>', 'vue', 1, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('0778d0cc-e261-4c3a-99af-a6f0a094c471', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '36b94d7a-245c-4f1e-9200-097543355c9e', '', 'Read list context in a custom item', '<script setup lang="ts">
