</script>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('62a8d72b-8557-4fb7-9dc8-85547ea0a0ee', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '36b94d7a-245c-4f1e-9200-097543355c9e', '', 'Create a list context (useCreateList)', '<script setup lang="ts">
