INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('2ee0e89e-945d-466c-b0f8-35e43d775080', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '74f4211e-799e-4052-86d1-bfdbf66498e1', '', 'Indeterminate circular loader', '<script setup lang="ts">
