INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('1d79d6ed-47ba-45aa-aa80-3d8d5a78d85c', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '74f4211e-799e-4052-86d1-bfdbf66498e1', '', 'Determinate line loader', '<script setup lang="ts">
