INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('ab666d3e-d735-4e8a-9b7e-8df0aefe4a7d', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'a33071b8-f62b-43fb-ba4a-0430459c5eaa', '', 'Read the active locale in a component', '<script setup lang="ts">
