INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('57f9a0f8-ccb6-4e40-8dc6-13715754b3ad', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'a33071b8-f62b-43fb-ba4a-0430459c5eaa', '', 'Switch locale at runtime', '<script setup lang="ts">
