INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('4cc1cb6b-07cf-41ac-90a0-7ab501c365e2', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'a33071b8-f62b-43fb-ba4a-0430459c5eaa', '', 'Override locale for a component subtree (provideLocale)', '<script setup lang="ts">
