INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('e3b7bf10-bf8d-4691-b5ac-152ddfb766ee', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '767957bc-81c2-4d58-8f35-fd0f7831f34d', '', 'Position a badge at top-end', '<script setup lang="ts">
