INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('9d0772ee-4efb-40a3-9236-ba5f4affa159', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'a52f2c99-6c0c-4c20-85aa-15a1dc08aa9f', '', 'Using the spacing scale', '<!-- Scale step — emits utility class .origam--m-4 -->
