INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('26dfd66f-530e-4afd-b569-50d1a9093d75', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '2900d48a-b3b4-4357-911c-58428cab3d18', '', 'Phone number mask', '<script setup lang="ts">
import { ref } from ''vue''
import { useMask } from ''origam''

const raw = ref('''')
const { masked, unmasked, isValid, complete, setRaw } = useMask(raw, ''(###) ###-####'')
</script>

<template>
  <input
    :value="masked"
    placeholder="(555) 123-4567"
    @input="setRaw(($event.target as HTMLInputElement).value)"
  />
  <p v-if="!isValid && complete === false">Keep typing…</p>
  <p v-else-if="isValid">Valid: {{ unmasked }}</p>
</template>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('22e21316-4dcc-4998-88b2-923995616be0', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '2900d48a-b3b4-4357-911c-58428cab3d18', '', 'Date mask with reactive model', '<script setup lang="ts">
