</script>', 'vue', 1, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('ade291f1-3d8a-4972-8e4a-2529e7aa16dc', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'c9eef7a9-69d8-4375-9606-e3f05681ff3f', '', 'Basic masonry grid', '<script setup lang="ts">
import { ref } from ''vue''
import { useMasonry } from ''origam''

const items = ref([/* ... */])
const { containerRef, setItem, layout } = useMasonry({
  columnsRef: ref(3),
  gapRef: ref(16)
})
</script>

<template>
  <div
    :ref="containerRef"
    :style="{ position: ''relative'', height: layout.containerHeight + ''px'' }"
  >
    <div
      v-for="(item, i) in items"
      :key="item.id"
      :ref="(el) => setItem(i, el as HTMLElement)"
      :style="{
        position: ''absolute'',
        left: layout.items[i]?.left + ''px'',
        top: layout.items[i]?.top + ''px'',
        width: layout.items[i]?.width + ''px''
      }"
    >
      {{ item.content }}
    </div>
  </div>
</template>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('be14ea82-8ab6-4eb5-9460-619983ce2d9b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'c9eef7a9-69d8-4375-9606-e3f05681ff3f', '', 'Responsive breakpoints', '<script setup lang="ts">
import { ref } from ''vue''
import { useMasonry } from ''origam''

const { containerRef, setItem, layout, relayout } = useMasonry({
  columnsRef: ref(1),
  gapRef: ref(12),
  breakpointsRef: ref({ 600: 2, 900: 3, 1200: 4 }),
  alignRef: ref(''center'')
})
</script>', 'vue', 1, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('dabb48af-cda8-4185-a5e9-dbfb82a5c4df', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '8b479edf-6066-4dfd-8ec8-152b95d2573a', '', 'Custom video player UI', '<script setup lang="ts">
import { useMediaPlayer } from ''origam''
import { ref } from ''vue''

const mediaRef = ref<HTMLVideoElement | null>(null)
const { state, methods } = useMediaPlayer({ mediaRef, muted: true })
</script>

<template>
  <video ref="mediaRef" src="/demo.mp4" />
  <div class="controls">
    <button @click="methods.toggle()">
      {{ state.playing.value ? ''Pause'' : ''Play'' }}
    </button>
    <input
      type="range"
      :max="state.duration.value"
      :value="state.currentTime.value"
      @input="(e) => methods.seek(Number((e.target as HTMLInputElement).value))"
    />
    <button @click="methods.toggleMute()">
      {{ state.muted.value ? ''Unmute'' : ''Mute'' }}
    </button>
  </div>
</template>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('f7a8452c-67bc-4093-88c2-c512f450dd73', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'e224a697-010f-4b83-be54-5fdf84dcbf91', 'consts.detail.blockquote_langs.example', 'Iterating available languages', 'import { BLOCKQUOTE_LANGS } from ''origam''

for (const lang of BLOCKQUOTE_LANGS) {
  console.log(lang) // ''auto'', ''fr'', ''en'', ''es'', ''de''
}', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('d47f5664-192e-43cf-a453-5b6184450047', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '5f45b5a7-5e2f-44da-b22a-37539dd06aa4', '', 'Field with hint and error message', '<script setup lang="ts">
import { ref } from ''vue''
import { useMessage } from ''origam''

const props = defineProps<{
  hint?: string
  errorMessages?: string | string[]
  messages?: string | string[]
}>()

const validationMessages = ref<string[]>([])
const { hasMessages, messages } = useMessage(props, validationMessages)
</script>

<template>
  <div class="field">
    <input type="text" />
    <div v-if="hasMessages" class="field__messages">
      <span v-for="msg in [messages].flat()" :key="msg">{{ msg }}</span>
    </div>
  </div>
</template>', 'vue', 0, false, NULL);
