INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('5e1b6925-e22e-4df0-8e0a-313c294441b2', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '6bd4501c-85c7-4b68-af9a-9038d9c2a197', '', 'Server-side data with reactive options', '<script setup lang="ts">
import { ref, watch } from ''vue''

const options = ref({ page: 1, itemsPerPage: 10, sortBy: [], groupBy: [], search: undefined })
const items = ref([])

watch(options, async (o) => {
  const { data } = await fetch(`/api/items?page=${o.page}&limit=${o.itemsPerPage}`)
    .then(r => r.json())
  items.value = data
}, { deep: true, immediate: true })
</script>

<template>
  <origam-data-table
    :headers="headers"
    :items="items"
    v-model:options="options"
  />
</template>', 'vue', 1, false, NULL);
