INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('a3b13917-73d6-4e06-b77f-acb8768a56f6', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'e0e8b08e-af5b-4748-a685-ba8eb7c84083', '', 'Manual parallax layer (custom wrapper)', '<script setup lang="ts">
import { useParallaxTransform } from ''origam''
import { PARALLAX_ELEMENT_TYPE } from ''origam/enums''
import { ref, computed } from ''vue''

const props = {
    type: PARALLAX_ELEMENT_TYPE.TRANSLATE,
    strength: 20
}

const { transformStyles } = useParallaxTransform(props)

const mouse = ref({ x: 0, y: 0 })
const layerStyle = computed(() => ({
    transform: transformStyles(mouse.value.x, mouse.value.y)
}))
</script>

<template>
  <div :style="layerStyle">
    <slot />
  </div>
</template>', 'vue', 0, false, NULL);
