INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('4afcd9a1-5169-4b35-a4f0-7ab18c2efbc9', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '12db64f9-a257-4c72-bd5d-1ae97459173d', '', 'Custom canvas rendering using modules', '<script setup lang="ts">
import { ref, watchEffect } from ''vue''
import { useQrCode } from ''origam''

const canvas = ref<HTMLCanvasElement>()
const { modules } = useQrCode(''https://example.com'')

watchEffect(() => {
  const ctx = canvas.value?.getContext(''2d'')
  if (!ctx) return
  const grid = modules.value
  const cell = 4
  ctx.clearRect(0, 0, canvas.value!.width, canvas.value!.height)
  grid.forEach((row, r) => row.forEach((dark, c) => {
    ctx.fillStyle = dark ? ''#000'' : ''#fff''
    ctx.fillRect(c * cell, r * cell, cell, cell)
  }))
})
</script>

<template>
  <canvas ref="canvas" :width="modules.length * 4" :height="modules.length * 4" />
</template>', 'vue', 2, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('2cf0bad5-5c44-44a9-bf8b-acba2a652070', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '86e61d4d-b341-4969-ba15-ce113280d734', '', 'Collect refs from a v-for list', '<script setup lang="ts">
import { useRefs } from ''origam''

const { refs: itemRefs, updateRef } = useRefs<HTMLLIElement>()

function focusItem(i: number) {
  itemRefs.value[i]?.focus()
}
</script>

<template>
  <ul>
    <li
      v-for="(item, i) in items"
      :key="item.id"
      :ref="(el) => updateRef(el, i)"
      tabindex="0"
    >
      {{ item.label }}
    </li>
  </ul>
</template>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('e05ad583-83f0-4c38-9936-0cd38c35011a', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '86e61d4d-b341-4969-ba15-ce113280d734', '', 'Refs of child Origam components', '<script setup lang="ts">
import { useRefs } from ''origam''
import type { TOrigamBtn } from ''origam''

const { refs: btnRefs, updateRef } = useRefs<TOrigamBtn>()

function blurAll() {
  btnRefs.value.forEach(btn => btn?.blur())
}
</script>

<template>
  <origam-btn
    v-for="(action, i) in actions"
    :key="action.id"
    :ref="(el) => updateRef(el, i)"
    @click="action.handler"
  >
    {{ action.label }}
  </origam-btn>
</template>', 'vue', 1, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('6cefa917-70f2-48ba-bd79-14ee53e02153', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '62d4637a-3d83-4362-9615-7a879b4d2594', '', 'Track element dimensions reactively', '<script setup lang="ts">
import { computed } from ''vue''
import { useResizeObserver } from ''origam''

const { resizeRef, contentRect } = useResizeObserver()

const isWide = computed(() => (contentRect.value?.width ?? 0) > 600)
</script>

<template>
  <div :ref="resizeRef" :class="{ ''layout--wide'': isWide }">
    <slot />
  </div>
</template>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('8b416142-e47d-4aea-a650-277548d77980', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '62d4637a-3d83-4362-9615-7a879b4d2594', '', 'Custom callback + border-box', '<script setup lang="ts">
