INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('6d6b640d-fb13-4f72-b5a2-3e474012aff0', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '712889b5-a8e5-4625-8594-ecb3abeb9e88', '', 'Radius presets', '<!-- Modern utility rung -->
