INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('3102ae26-ec1d-4d95-9434-d77de39be3d1', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'f2aef4b9-594a-4579-a113-3915f22132a3', '', 'Origam button as router-link', '<!-- Origam components resolve links via useLink internally -->
