INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('b1769941-b3e7-4b39-b1a4-a78e95110d1b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'f2aef4b9-594a-4579-a113-3915f22132a3', '', 'Back button guard (Dialog)', '<script setup lang="ts">
import { useRouter as useVueRouter } from ''vue-router''
import { useBackButton } from ''origam''

const router = useVueRouter()
const isOpen = defineModel<boolean>()

useBackButton(router, (next) => {
  if (isOpen.value) {
    isOpen.value = false
    next(false)
  } else {
    next()
  }
})
</script>', 'vue', 2, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('246890d0-fa94-45cb-aa80-d0e34ee6f69e', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '8ebdd7e0-ce55-48be-ac8f-acd7d4b2994a', '', 'Apply scope to a teleported overlay', '<script setup lang="ts">
import { useScopeId } from ''origam''

const { scopeId } = useScopeId()
</script>

<template>
  <Teleport to="body">
    <!-- Scoped CSS rules from this SFC now match the overlay -->
    <div v-bind="scopeId" class="my-overlay">
      <slot />
    </div>
  </Teleport>
</template>

<style scoped>
.my-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0 0 0 / 0.4);
}
</style>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('37259fef-d678-4b71-8bc6-d5e57167a07f', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '8ebdd7e0-ce55-48be-ac8f-acd7d4b2994a', '', 'Spread on a programmatic createElement call', '<script setup lang="ts">
