INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('2c4292c3-4144-4110-af73-b85bc2e80ef8', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'fcaadf2a-ffb8-4869-b25c-e2c20b82e10b', '', 'Custom scroll ratio indicator', '<script setup lang="ts">
