INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('9a6d04c1-dd20-40fb-a953-d53ac5759424', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '5e18b077-3b2e-448e-8a74-ef79449760a2', '', 'Row checkbox cell using useSelection', '<script setup lang="ts">
