INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('5d38373a-58b7-415d-a7f2-12456bdac507', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '5e18b077-3b2e-448e-8a74-ef79449760a2', '', 'Select-all header checkbox', '<script setup lang="ts">
