INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('54781fd0-ac94-492b-8973-6d4979ff8e66', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '721b2521-3874-47a8-9726-466bb0645f51', '', 'Navigation item that auto-selects on route match', '<script setup lang="ts">
import { useSelectLink } from ''origam''
import { useLink } from ''vue-router''

const props = defineProps<{ to: string }>()

// Provided by the parent group (e.g. OrigamNavList)
const select = inject(ORIGAM_GROUP_ITEM_KEY)?.select

const link = useLink({ to: props.to })
useSelectLink(link, select)
</script>

<template>
  <origam-btn :to="to" :class="{ active: link.isActive.value }">
    <slot />
  </origam-btn>
</template>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('88b1181b-bf4b-450b-9e86-1f0a2af58c3b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'ecd3d09e-26c4-4f3b-abdb-148fef248eff', '', 'Basic bottom sheet with swipe gesture', '<script setup lang="ts">
import { ref, computed } from ''vue''
import { useSheetSwipe, DEFAULT_SHEET_SNAP_POINTS } from ''origam''

const el = ref<HTMLElement>()
const handle = ref<HTMLElement>()

const { currentSnap, dragOffset, isDragging, snapTo, dismiss, currentSnapHeight } =
  useSheetSwipe({
    el,
    handle,
    snapPoints: ref(DEFAULT_SHEET_SNAP_POINTS),
    defaultSnap: ref(''half''),
    persistent: ref(false),
    disabled: ref(false),
  })

const sheetStyle = computed(() => ({
  height: `${currentSnapHeight.value + dragOffset.value}px`,
  transition: isDragging.value ? ''none'' : ''height 0.3s ease'',
}))
</script>

<template>
  <div ref="el" class="sheet" :style="sheetStyle">
    <div ref="handle" class="sheet__handle" />
    <div class="sheet__content">
      <origam-btn @click="snapTo(''full'')">Expand</origam-btn>
      <origam-btn @click="dismiss">Dismiss</origam-btn>
    </div>
  </div>
</template>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('1a5c6c61-8c15-42b6-ba52-d6f9c3b5a191', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '09ef672a-2ea0-4193-8e92-78d5447885dc', '', 'Named size presets', '<origam-btn size="x-small">XS</origam-btn>
