<origam-avatar size="64" icon="mdi-account" />', 'vue', 1, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('b386fb8a-f2ce-45e8-94d7-3c3bd001c974', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'd77aec13-6f47-47a9-8f6f-b66794e52dce', '', 'Snap a user-typed value to the step grid', '<script setup lang="ts">
import { useSteps } from ''origam''

const props = defineProps<{
  min?: number | string
  max?: number | string
  step?: number | string
}>()

const { min, max, decimals, roundValue } = useSteps(props)

function onInputChange(raw: string) {
  const snapped = roundValue(raw)
  console.log(`Snapped ${raw} → ${snapped} (decimals: ${decimals.value})`)
}
</script>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('57aaea34-ddd5-4dda-961a-d23854907729', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '4e5c1732-1d74-4502-a26c-21af0d3c3fd3', '', 'Auto-dismiss snackbar with countdown progress bar', '<script setup lang="ts">
import { ref, onMounted, computed } from ''vue''
import { useCountdown } from ''origam''

const progressEl = ref<HTMLElement>()
const DURATION = 5000

const { time, start, clear, reset } = useCountdown(DURATION)

const progressPct = computed(() => (time.value / DURATION) * 100)

onMounted(() => start(progressEl.value))
</script>

<template>
  <div
    class="snackbar"
    @mouseenter="clear"
    @mouseleave="start"
  >
    <slot />
    <div
      ref="progressEl"
      class="snackbar__progress"
      :style="{ width: progressPct + ''%'' }"
    />
  </div>
</template>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('98f78e06-eacb-4164-8e9a-3cc60e7dd56b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'c949db76-da62-4964-933c-23de2d89534a', '', 'Push a success notification from any component', '<script setup lang="ts">
