INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('67e584d4-405b-45be-ad02-e8b3457d5bd9', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '1aa29c21-5d0f-4a20-8502-24b962c1b27b', 'consts.detail.scroll_strategies.example', 'Listing all valid scroll strategy keys', 'import { SCROLL_STRATEGIES } from ''origam''

