INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('cef05fea-cdd4-4fe6-a00e-cc65e1db0481', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'c949db76-da62-4964-933c-23de2d89534a', '', 'Named stack with bounded capacity', '<!-- app.vue — register the rendering component once -->
