INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('3e5d8e55-9aa0-4150-8e6e-9b7135357550', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '5e7dac18-cad1-4cbc-b156-be59a6ee436b', '', 'Sortable data table header cell', '<script setup lang="ts">
