INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('c52d6c56-245a-47cc-9e29-cd42373efc97', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '5e7dac18-cad1-4cbc-b156-be59a6ee436b', '', 'Sorted items computed ref', '<script setup lang="ts">
