INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('b6bc7157-8ae7-42ac-87d8-36daea74a3c7', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '2c5c2a3e-215c-4dc0-8aa0-e8ad4ae01ab1', '', 'Gate DOM-dependent logic on isBooted', '<script setup lang="ts">
