INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('03438aa6-88d8-43e7-a57b-224ec4546357', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '9b00f479-5a57-4961-b431-ab90c7de8c11', '', 'Overlay component using useStack', '<script setup lang="ts">
import { toRef, readonly } from ''vue''
import { useStack } from ''origam''

const props = defineProps<{ modelValue: boolean; zIndex?: number | string }>()

const isActive = readonly(toRef(props, ''modelValue''))
const zIndex = readonly(toRef(props, ''zIndex''))

const { globalTop, localTop, stackStyles } = useStack(isActive, zIndex, false)
</script>

<template>
  <Teleport to="body">
    <div v-if="modelValue" class="overlay" :style="stackStyles">
      <slot />
    </div>
  </Teleport>
</template>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('8dfb9bb8-326f-40b0-a3a5-2285a7bcd6b1', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'ab7bd698-18b3-4891-b4bb-bdbdc1da0341', '', 'Card with hover elevation + bg swap', '<script setup lang="ts">
import { useHover, useStateEffect } from ''origam''

const props = defineProps<{
  color?: string
  bgColor?: string
  hover?: boolean | object
  elevation?: string | number
}>()

const { isHover, hoverState, onMouseenter, onMouseleave } = useHover(props)

const {
  colorClasses, colorStyles,
  elevationClasses, elevationStyles,
} = useStateEffect(props, isHover)
</script>

<template>
  <div
    :class="[colorClasses, elevationClasses]"
    :style="[colorStyles, elevationStyles]"
    @mouseenter="onMouseenter"
    @mouseleave="onMouseleave"
  >
    <slot />
  </div>
</template>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('fcd5d022-2b2d-4bd8-93f4-a61e775efa5d', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'ab7bd698-18b3-4891-b4bb-bdbdc1da0341', '', 'Active nav item with full state override', '<!-- Nav item selected = active; unselected = resting state -->
