INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('f9c59ca5-0133-4684-9378-c6662d8e5c05', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'db0e56c4-c4d4-482d-b2fa-85a117d81784', '', 'Sticky navigation drawer', '<script setup lang="ts">
