INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('7f7afb99-71f2-43da-a386-35776eb1a383', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'ca656eb3-6a92-4225-bc58-89e727734a5b', '', 'Per-instance scoped keyframes', '<script setup lang="ts">
