INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('51e25269-068b-41fa-a678-9a991f85588c', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '6db9d2af-63bf-4b07-847d-d8ba3c654146', '', 'Overlay component with configurable teleport target', '<script setup lang="ts">
