INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('c049cb6b-9abc-4dbf-9945-e5b588feb376', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'f8820940-2048-40d6-a8bb-a58f3eb67b6f', '', 'Minimal rich textarea with toolbar', '<script setup lang="ts">
import { ref } from ''vue''
import { useTextareaRich } from ''origam''
import { TEXTAREA_TOOLBAR_COMMAND } from ''origam/enums''

const model = ref(''<p>Hello</p>'')

const { hostRef, active, format, onInput, onKeydown, onPaste } = useTextareaRich({
  value: () => model.value,
  onUpdate: (html) => { model.value = html },
  onFormat: (cmd, val) => {
    if (cmd === TEXTAREA_TOOLBAR_COMMAND.LINK) {
      // open link popover…
    }
  },
  disabled: () => false,
})
</script>

<template>
  <div>
    <origam-btn :active="active.bold" @click="format(TEXTAREA_TOOLBAR_COMMAND.BOLD)">B</origam-btn>
    <origam-btn :active="active.italic" @click="format(TEXTAREA_TOOLBAR_COMMAND.ITALIC)">I</origam-btn>
    <div
      ref="hostRef"
      contenteditable
      @input="onInput"
      @keydown="onKeydown"
      @paste="onPaste"
    />
  </div>
</template>', 'vue', 0, false, NULL);
