INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('acfa726a-b6f4-4d4b-9108-5db1ead217a9', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '606ac208-5c21-4f6e-af0c-88c05234e0e8', '', 'Throttle a scroll handler to 16 ms', '<script setup lang="ts">
import { onMounted, onBeforeUnmount } from ''vue''
import { useThrottleFn } from ''origam''

function handleScroll() {
  // expensive layout read
  console.log(window.scrollY)
}

const throttled = useThrottleFn(handleScroll, 16)

onMounted(() => window.addEventListener(''scroll'', throttled, { passive: true }))
onBeforeUnmount(() => window.removeEventListener(''scroll'', throttled))
</script>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('6a40c121-38f0-4a21-a3b0-2539b5fc697d', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '606ac208-5c21-4f6e-af0c-88c05234e0e8', '', 'Throttle a search-as-you-type input', '<script setup lang="ts">
import { useThrottleFn } from ''origam''

const search = useThrottleFn((query: string) => {
  // fire API call at most once per 300 ms
  fetchResults(query)
}, 300)
</script>

<template>
  <origam-text-field @input="(e) => search(e.target.value)" />
</template>', 'vue', 1, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('550eb586-ec40-4023-bbac-70fdd76513ff', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'f569a1aa-f303-4a13-a506-34f4bf7efb0c', '', 'Run a watcher only while a panel is open', '<script setup lang="ts">
import { useToggleScope } from ''origam''
import { ref, watch } from ''vue''

const isOpen = ref(false)
const data = ref<string[]>([])

useToggleScope(() => isOpen.value, () => {
    watch(data, (val) => {
        console.log(''Panel is open, data changed:'', val)
    })
})
</script>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('193707a9-79c9-4759-8248-52dacb490e7c', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'f569a1aa-f303-4a13-a506-34f4bf7efb0c', '', 'Reset the scope when a sub-condition changes', '<script setup lang="ts">
import { useToggleScope } from ''origam''
import { ref, watch } from ''vue''

const enabled = ref(false)
const mode = ref(''fast'')

useToggleScope(() => enabled.value, (reset) => {
    watch(mode, () => {
        // Re-initialise the scope whenever mode changes
        reset()
    })
})
</script>', 'vue', 1, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('a449a891-58d4-4482-aa8b-32077660b291', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '1eeb9995-78a8-40ad-a733-e7ba6a118f33', '', 'Swipeable navigation drawer', '<script setup lang="ts">
import { useTouch } from ''origam''
import { ref } from ''vue''

const isActive = ref(false)
const isTemporary = ref(true)
const width = ref(256)
const touchless = ref(false)
const position = ref(''left'')

const { isDragging, dragProgress, dragStyles } = useTouch({
    isActive,
    isTemporary,
    width,
    touchless,
    position
})
</script>

<template>
  <nav
    :style="dragStyles"
    :class="{ ''nav--dragging'': isDragging }"
    class="nav-drawer"
  >
    <slot />
  </nav>
</template>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('7ec81673-be12-435d-9520-65d11537592e', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'f6aa8a3d-1081-493b-a771-aec0739632f4', '', 'Fade transition wrapper', '<script setup lang="ts">
