INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('dbae5adc-9654-48c5-848a-63f8b1f8b8d1', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '47a2efb6-8407-42fd-966a-ad85fcf321f6', '', 'Custom field with validation', '<script setup lang="ts">
