INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('3a027f92-d377-48b3-b8ec-86b03f0ef0a3', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '239e5a06-d770-4963-9422-cbece2765eb4', '', 'Component with variant prop', '<script setup lang="ts">
