INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('6a973ac2-73b8-4ff7-b4ef-1f4222352046', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '239e5a06-d770-4963-9422-cbece2765eb4', '', 'Passing a raw ref', '<script setup lang="ts">
