INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('c6f4fd14-5f7a-46c7-916d-cb9d8947eb55', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '72672983-694a-4ce4-ab7d-67f6ea06f828', '', 'Fling detection in a custom swipeable', '<script setup lang="ts">
import { useVelocity } from ''origam''

const { addMovement, endTouch, getVelocity } = useVelocity()

function onTouchstart(e: TouchEvent) {
    endTouch(e)
    addMovement(e)
}

function onTouchmove(e: TouchEvent) {
    addMovement(e)
}

function onTouchend(e: TouchEvent) {
    addMovement(e)
    const vel = getVelocity(e.changedTouches[0].identifier)
    if (Math.abs(vel.x) > 400) {
        console.log(''Fling detected:'', vel.direction)
    }
}
</script>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('ce0f352d-963a-455d-8030-2f7936cb7c4e', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '4c8f63d7-8094-49d8-adf1-dd6eedcb08bf', '', 'Custom video player with fullscreen and PIP', '<script setup lang="ts">
