    </button>
    <button @click="methods.togglePip()">
      {{ state.pip.value ? ''Exit PiP'' : ''Picture-in-picture'' }}
    </button>
  </div>
</template>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('2eca4af7-7e48-409f-97c6-9f0f8a9ca04a', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '4c8f63d7-8094-49d8-adf1-dd6eedcb08bf', '', 'Using OrigamVideo (recommended)', '<template>
