INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('f72c3919-956d-4bb8-842e-a0886a4a296c', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'b0e0d69d-8af2-43b7-876e-cd323d52a6d0', '', 'Virtual list with 10 000 rows', '<script setup lang="ts">
import { useVirtual } from ''origam''
import { ref } from ''vue''

const items = ref(Array.from({ length: 10_000 }, (_, i) => ({ id: i, label: `Item ${i}` })))

const {
    containerRef,
    markerRef,
    computedItems,
    paddingTop,
    paddingBottom,
    handleScroll,
    handleScrollend,
    handleItemResize,
    scrollToIndex
} = useVirtual({ itemHeight: 48, height: ''600px'' }, items)
</script>

<template>
  <div
    ref="containerRef"
    style="height: 600px; overflow-y: auto;"
    @scroll="handleScroll"
    @scrollend="handleScrollend"
  >
    <div ref="markerRef" />
    <div :style="{ paddingTop: paddingTop + ''px'', paddingBottom: paddingBottom + ''px'' }">
      <div
        v-for="item in computedItems"
        :key="item.raw.id"
        style="height: 48px;"
      >
        {{ item.raw.label }}
      </div>
    </div>
  </div>
</template>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('f463cf84-0aea-4c82-9dc3-be4b015982cb', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '126c4321-432d-48da-a2a7-b5a2d3b8a8ff', '', 'Boolean toggle with v-model', '<script setup lang="ts">
import { useVModel } from ''origam''

const props = defineProps<{
    modelValue?: boolean
}>()

const isOpen = useVModel(props, ''modelValue'', false)
</script>

<template>
  <button @click="isOpen = !isOpen">
    {{ isOpen ? ''Close'' : ''Open'' }}
  </button>
</template>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('218868d2-4ad3-461d-b8fa-3a65d3189fa7', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '126c4321-432d-48da-a2a7-b5a2d3b8a8ff', '', 'String prop with value transform', '<script setup lang="ts">
import { useVModel } from ''origam''

const props = defineProps<{
    modelValue?: string
}>()

// Store internally as uppercase, emit as-is
const model = useVModel(
    props,
    ''modelValue'',
    '''',
    (v) => v?.toUpperCase() ?? '''',
    (v) => v
)
</script>', 'vue', 1, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('0720abfc-3459-43a0-9416-ab2d3b48184b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '6168c1a1-5c18-4d9b-9da3-7ab219d7707a', '', 'Text watermark on a document container', '<script setup lang="ts">
import { useWatermark } from ''origam''
import { onMounted, onBeforeUnmount, ref } from ''vue''

const containerRef = ref<HTMLElement | null>(null)

const { install, uninstall } = useWatermark({
    text: ''CONFIDENTIAL'',
    opacity: 0.08,
    angle: -30,
    gap: 120,
    color: ''#000000''
})

onMounted(() => {
    if (containerRef.value) install(containerRef.value)
})

onBeforeUnmount(() => {
    uninstall()
})
</script>

<template>
  <div ref="containerRef" style="position: relative;">
    <slot />
  </div>
</template>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('4b8c2685-ee2f-4c2a-813b-ac01aa054279', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '6168c1a1-5c18-4d9b-9da3-7ab219d7707a', '', 'Reactive options + patternUrl binding', '<script setup lang="ts">
import { useWatermark } from ''origam''
import { ref } from ''vue''

const opacity = ref(0.1)
const { patternUrl } = useWatermark(() => ({
    text: ''DRAFT'',
    opacity: opacity.value,
    angle: -45
}))
</script>

<template>
  <div :style="{ backgroundImage: patternUrl, backgroundRepeat: ''repeat'' }">
    Content
  </div>
</template>', 'vue', 1, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('0b45e8e4-b981-452c-ba75-f31a37d0503c', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'd4fb6b98-27e4-4bca-ab8b-9a5d2ab5cfe3', '', 'Waveform thumbnail for a playlist track', '<script setup lang="ts">
import { useWaveform } from ''origam''
import { ref } from ''vue''

const src = ref(''/tracks/song.mp3'')
const { peaks, isComputing, error } = useWaveform(src, { bins: 80 })
</script>

<template>
  <div v-if="isComputing" class="skeleton" />
  <div v-else-if="error" class="error">Failed to load waveform</div>
  <svg v-else viewBox="0 0 80 32" width="160" height="32">
    <rect
      v-for="(peak, i) in peaks"
      :key="i"
      :x="i * 2"
      y="0"
      width="1"
      :height="peak * 32"
    />
  </svg>
</template>', 'vue', 0, false, NULL);
