INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('648710a8-20d8-40f6-8f74-71a85928a2cf', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'cd3ef169-d678-44f5-8dce-2add65792053', 'consts.detail.color_mappers.example', 'Parsing a CSS color string', 'import { COLOR_MAPPERS, CSS_COLOR_REGEX } from ''origam''

function parseColor(raw: string) {
  const m = CSS_COLOR_REGEX.exec(raw)
  if (!m) return null
  const fn = m.groups!.fn as keyof typeof COLOR_MAPPERS
  const vals = m.groups!.values.split('','').map(Number)
  return COLOR_MAPPERS[fn]?.(...(vals as [number, number, number, number?]))
}', 'typescript', 0, false, NULL);
