INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('c723db2b-fa34-40ff-8d26-f8ce8da350fc', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '721ccb49-be03-4e26-a609-b000b4b798e1', 'consts.detail.lo_con_offset.example', 'APCA low-contrast offset in context', 'import { LO_CON_THRESH, LO_CON_OFFSET } from ''origam''

// When the absolute APCA contrast is below LO_CON_THRESH,
// the result is adjusted by LO_CON_OFFSET to avoid clamping.
const adjustedContrast = Math.abs(apca) < LO_CON_THRESH
  ? 0
  : apca - Math.sign(apca) * LO_CON_OFFSET', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('2f83f16e-04df-4be1-bfda-5b092996dfa6', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'bfcd6bfc-9771-425a-b2d7-9c68420a5743', 'consts.detail.lo_con_thresh.example', 'APCA low-contrast threshold in context', 'import { LO_CON_THRESH, LO_CON_OFFSET } from ''origam''

// Absolute APCA contrast below LO_CON_THRESH is clamped to 0.
const clamp = (apca: number) =>
  Math.abs(apca) < LO_CON_THRESH ? 0 : apca - Math.sign(apca) * LO_CON_OFFSET', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('aca27082-6bda-42b3-a1f4-65412c7633b6', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '562e2eb3-d468-4189-ae04-c6ccf376a2a0', 'consts.detail.magic_radius.example', 'Computing the SVG circle circumference', 'import { MAGIC_RADIUS } from ''origam''

// CIRCUMFERENCE is exported alongside MAGIC_RADIUS
const CIRCUMFERENCE = 2 * Math.PI * MAGIC_RADIUS // ≈ 125.66

// strokeDashoffset drives the progress arc
