INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('87b6d60d-4821-48a9-a75a-26972b2d9379', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'fbd96ab8-ebec-436c-8925-d6096dcf1daa', 'consts.detail.main_trc.example', 'sRGB linearisation with MAIN_TRC', 'import { MAIN_TRC } from ''origam''

// Convert an sRGB 0–255 channel to a linear light value
const linearise = (channel: number) => {
  const c = channel / 255
  return c <= 0.04045
    ? c / 12.92
    : ((c + 0.055) / 1.055) ** MAIN_TRC
}', 'typescript', 0, false, NULL);
