INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('aaf6577a-3d8e-43e7-ad87-a159786815da', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '443ca265-bf5f-4cd0-825d-f4ef8aa841ee', 'consts.detail.number_format_lru_capacity.example', 'The LRU cache capping in useNumberFormat', 'import { NUMBER_FORMAT_LRU_CAPACITY } from ''origam''

// Internal LRU implementation (simplified):
const cache = new Map<string, Intl.NumberFormat>()

function getFormatter(key: string, options: Intl.NumberFormatOptions) {
  if (!cache.has(key)) {
    if (cache.size >= NUMBER_FORMAT_LRU_CAPACITY) {
      // evict the oldest entry
      cache.delete(cache.keys().next().value)
    }
    cache.set(key, new Intl.NumberFormat(key, options))
  }
  return cache.get(key)!
}', 'typescript', 0, false, NULL);
