INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('ca9562ee-e1e9-4422-a54c-5d9be92396a7', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '5b4e753f-358b-413b-87c6-78a4cbc1bfad', 'consts.detail.srgb_forward_matrix.example', 'Applying the XYZ→sRGB matrix (internal use)', 'import { SRGB_FORWARD_MATRIX, SRGB_FORWARD_TRANSFORM } from ''origam''

// Convert XYZ [X, Y, Z] to linear sRGB
