const r = SRGB_FORWARD_TRANSFORM(linearR)', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('d3452050-2197-4e18-86fc-bb72f5f84e60', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '5fd414be-047c-44ee-bbd0-c6599a106448', 'consts.detail.srgb_forward_transform.example', 'Converting a linear channel value to sRGB', 'import { SRGB_FORWARD_TRANSFORM } from ''origam''

