const linearR = 0.5
const encodedR = SRGB_FORWARD_TRANSFORM(linearR) // ~0.7354', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('903cd442-3ac0-407e-a4ae-013cdab1e453', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '5d10c602-47c3-4970-882d-f3585d0972db', 'consts.detail.srgb_reverse_matrix.example', 'Applying the sRGB→XYZ matrix (internal use)', 'import { SRGB_REVERSE_MATRIX, SRGB_REVERSE_TRANSFORM } from ''origam''

