INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('3147f4c4-f334-4cbc-8174-dcb236e1fc9f', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '4f9c0671-cbf0-4786-90af-342bd024fa30', 'consts.detail.srgb_reverse_transform.example', 'Decoding an sRGB channel value to linear', 'import { SRGB_REVERSE_TRANSFORM } from ''origam''

