INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('c7e59146-5261-4abc-b950-b4e615e1bf77', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '5b43f804-830a-48fb-81f6-cbf8d0cf7e92', 'directives.click_outside.example_basic_title', 'Basic usage', '<script setup lang="ts">
import { ref } from ''vue''

const isOpen = ref(true)
const close = () => { isOpen.value = false }
</script>

