INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('3d5cd3f4-a9e3-46fe-b9d3-52a7b6872dac', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '5b43f804-830a-48fb-81f6-cbf8d0cf7e92', 'directives.click_outside.example_options_title', 'With options (guard + include)', '<script setup lang="ts">
import { ref } from ''vue''

const isOpen = ref(false)
const triggerRef = ref<HTMLElement | null>(null)

const onClickOutside = () => { isOpen.value = false }
</script>

<template>
  <div
    v-click-outside="{
      handler: onClickOutside,
      closeConditional: () => isOpen,
      include: () => triggerRef.value ? [triggerRef.value] : []
    }"
  >
    Panel content
  </div>
</template>', 'vue', 1, false, NULL);
