INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('c52c340e-d815-4ca6-be03-e6b889f03bd4', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '22646d93-a34e-4079-896b-1d8f203dd95f', 'directives.contrast.example_optout_title', 'Per-element opt-out', '<template>
