INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('4f4ee260-f46d-416b-9753-1f30a45a5668', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'b4d3815a-c911-4ac0-b13f-6c76387bf095', 'directives.hover.example_class_title', 'Class toggle on hover', '<template>
