INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('e8d7cab7-f90b-405e-9199-4aac832610f9', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'b4d3815a-c911-4ac0-b13f-6c76387bf095', 'directives.hover.example_callback_title', 'Callback mode', '<script setup lang="ts">
import { ref } from ''vue''

const isHovered = ref(false)
const onHover = (hovered: boolean) => { isHovered.value = hovered }
</script>

<template>
  <div v-hover.callback="onHover">
    {{ isHovered ? ''Hovered!'' : ''Hover me'' }}
  </div>
</template>', 'vue', 1, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('303db644-ac13-4fa7-a71e-2c65899371e3', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '6750eb13-563c-4356-9e62-267b9a158199', 'directives.intersect.example_basic_title', 'Animate on enter (once)', '<script setup lang="ts">
import { ref } from ''vue''

const visible = ref(false)

const onEnter = (isIntersecting: boolean) => {
  if (isIntersecting) visible.value = true
}
</script>

<template>
  <div
    v-intersect.once="onEnter"
    :class="{ ''fade-in'': visible }"
  >
