INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('995af687-9474-41c0-8746-0f10d4b3249b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '6750eb13-563c-4356-9e62-267b9a158199', 'directives.intersect.example_options_title', 'With threshold option', '<script setup lang="ts">
const onHalfVisible = (isIntersecting: boolean) => {
  console.log(''50% visible:'', isIntersecting)
}
</script>

<template>
  <div
    v-intersect="{
      handler: onHalfVisible,
      options: { threshold: 0.5 }
    }"
  >
    Fires when 50% of me is in view.
  </div>
</template>', 'vue', 1, false, NULL);
