INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('c1cae2ae-debe-49b9-ae9e-faf0b2f8eb3f', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'fd6e7015-cf65-4c44-98c4-2b35de0cebb0', 'directives.touch.example_swipe_title', 'Swipe left / right', '<script setup lang="ts">
