INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('b42ca6da-53a7-49f6-8ab6-f31de01d6c52', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'fd6e7015-cf65-4c44-98c4-2b35de0cebb0', 'directives.touch.example_lifecycle_title', 'Raw touch lifecycle', '<script setup lang="ts">
import type { ITouchData } from ''origam''

const onStart = (e: ITouchData) => console.log(''start'', e)
const onEnd   = (e: ITouchData) => console.log(''end'',   e)
</script>

<template>
  <div
    v-touch="{
      start: onStart,
      end:   onEnd,
      options: { passive: true }
    }"
  >
    Touch me
  </div>
</template>', 'vue', 1, false, NULL);
