INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('5b9b0e1d-b946-4576-ab15-c5fc0079f15e', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '8b245f8d-66b7-4e2d-a5cf-58178cfc5bef', 'interfaces.detail.i_chart_box_plot_box.example', 'Accessing IChartBoxPlotBox in the #tooltip slot', '<OrigamChartBoxPlot :series="series">
