INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('f9c3f231-b827-44d0-b755-6dac1809b41d', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'ef28e33b-db31-4024-8f4a-b08729d7b04d', 'interfaces.detail.i_chart_box_plot_datum.example', 'Pre-aggregated box plot data', 'import type { IChartBoxPlotDatum } from ''origam''

