INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('3c383edd-d5ed-466f-b3b7-111b5e09f792', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '574f311f-11fc-4e4b-ac22-192f6a6c14d5', 'interfaces.detail.i_chart_box_plot_raw_datum.example', 'Passing raw sample arrays — let the component compute quartiles', 'import type { IChartBoxPlotRawDatum } from ''origam''

const data: IChartBoxPlotRawDatum[] = [
    {
        category: ''Server A'',
        samples: [120, 135, 142, 150, 155, 160, 210, 300],
        color: ''primary'',
    },
    {
        category: ''Server B'',
        samples: [80, 90, 95, 100, 102, 108, 115],
    },
