INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('034e48a3-d300-479f-a8d6-8f4dd1963613', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'd57a156e-fb48-4101-b1cb-2b6675df5719', 'interfaces.detail.i_chart_box_plot_slots.example', 'Custom tooltip slot on a box-plot chart', '<OrigamChartBoxPlot :series="series" :categories="cats">
