INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('6d31ec4a-82d7-44ef-b874-16ce0679ffb7', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'd8c7ea88-7289-4999-820a-73253ceab907', 'interfaces.detail.i_chart_bullet_bullet.example', 'Reading the bullet descriptor in a custom tooltip slot', '<OrigamChartBullet :series="series">
