INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('2be2de59-b918-4c04-ab42-c6f5411dbd2d', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '61865ad1-1e15-463e-b411-31561298801a', 'interfaces.detail.i_chart_bullet_datum.example', 'Providing bullet data with three qualitative ranges', 'import type { IChartBulletDatum } from ''origam''

