INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('2dec9a1e-2170-4ef2-b333-d3a3e04e4094', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '2e4be118-71f6-4626-80bf-f4b1992b4b2d', 'interfaces.detail.i_chart_bullet_slots.example', 'Custom tooltip showing value vs target in a bullet chart', '<OrigamChartBullet :series="kpiSeries">
