</OrigamChartBullet>', 'vue', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('c6ef138f-eced-4aa2-af42-66ccf8861567', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '9dbbb236-90e0-4106-9fd1-03fe10e20eae', 'interfaces.detail.i_chart_candlestick_candle.example', 'Reading candle data in a custom tooltip slot', '<OrigamChartCandlestick :series="ohlcSeries">
