INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('9d43737d-fc77-4d2d-be95-50e77206b94c', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '4245b4b8-0c00-4209-aa91-d172620335cd', 'interfaces.detail.i_chart_drilldown_frame.example', 'Internal frame shape — read-only reference for composable consumers', '// IChartDrilldownFrame is an internal type used by the chart engine.
