INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('801b487b-0539-4010-91f8-d3bd0adb6704', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '790f7de2-dfb6-499c-9cef-0b8a5b720806', 'interfaces.detail.i_chart_gauge_geometry.example', 'Consuming geometry in a custom gauge slot', '// IChartGaugeGeometry is returned by useChartGauge — accessed via the gauge-value slot
