INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('9e2ceaf0-6b35-42a9-b453-36e0f1cfaccc', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '70639d5a-6715-4790-beeb-9b17e72f2d74', 'interfaces.detail.i_chart_word_cloud_word.example', 'Extending IChartWordCloudDatum for layout', 'import type { IChartWordCloudWord } from ''origam''

// After geometry placement each word exposes full SVG positioning:
function renderWord(w: IChartWordCloudWord) {
    return `<text
        x="${w.x}" y="${w.y}"
        font-size="${w.fontSize}"
        fill="${w.color}"
        transform="rotate(${w.angle})">${w.text}</text>`
}', 'typescript', 0, false, NULL);
