INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('2ac42939-614d-4649-8fae-01386447c0ac', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'afd00eb9-9d38-4486-8654-c1a087f7870f', 'interfaces.detail.i_data_table_select_strategy.example', 'Custom page-only select strategy', 'import type { IDataTableSelectStrategy } from ''origam''

const pageStrategy: IDataTableSelectStrategy = {
    showSelectAll: true,
    allSelected: ({ currentPage }) => currentPage,
    select: ({ items, value, selected }) => {
        const next = new Set(selected)
        for (const item of items) value ? next.add(item.value) : next.delete(item.value)
        return next
    },
    selectAll: ({ value, currentPage, selected }) => {
        const next = new Set(selected)
        for (const item of currentPage) value ? next.add(item.value) : next.delete(item.value)
        return next
    },
}', 'typescript', 0, false, NULL);
