INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('06ced211-9fbe-4255-a3d7-6cd03527a6ac', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '8c99c825-2a42-41c6-b493-8d6b229865a5', 'interfaces.detail.i_h_t_m_l_expand_element.example', 'Internal usage in the expand transition enter hook', 'import type { IHTMLExpandElement } from ''origam''

