INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('60033397-ed2b-4bf1-bc8b-c1d12e7eab7c', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '55a82bc1-b023-4f04-bb27-f0ca13762580', 'interfaces.detail.i_intersect_directive_binding.example', 'Using the typed binding in the v-intersect directive hook', 'import type { IIntersectDirectiveBinding } from ''origam''

const vIntersect = {
    mounted(el: HTMLElement, binding: IIntersectDirectiveBinding) {
        const handler = typeof binding.value === ''function''
            ? binding.value
            : binding.value?.handler
        const options = typeof binding.value === ''object''
            ? binding.value?.options
            : undefined
    }
}', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('22185dcd-408e-46c1-9f6a-8590bcc38d29', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'b5f91500-82cf-47e3-984c-7ae36a6eab20', 'interfaces.detail.i_intersect_html_element.example', 'Casting an element to IIntersectHtmlElement for cleanup', 'import type { IIntersectHtmlElement } from ''origam''

function teardown(el: HTMLElement) {
    const observed = el as IIntersectHtmlElement
    if (observed._observe) {
        Object.keys(observed._observe).forEach(key => {
            observed._observe![key]?.observer?.disconnect()
        })
        delete observed._observe
    }
}', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('e2e80302-6286-40a5-843c-f12aca9ec2b7', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '94bd946c-43d2-4070-ac06-f878ee14bb78', 'interfaces.detail.i_intersect_html_element_observe.example', 'Iterating the observe map to disconnect all observers', 'import type { IIntersectHtmlElementObserve } from ''origam''

function disconnectAll(obs: IIntersectHtmlElementObserve) {
    Object.values(obs).forEach((entry) => {
        (entry as { observer: IntersectionObserver }).observer?.disconnect()
    })
}', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('eb58de3a-10fa-400d-99a7-6989941b3a12', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '64b30516-224a-4cf7-90dc-fa35f3a82fcf', 'interfaces.detail.i_intersection_observer_init.example', 'Passing options to OrigamLazy', '<OrigamLazy :options="{ root: null, rootMargin: ''0px'', threshold: 0.5 }">
