INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('0eaf5319-f5c3-4a23-bcfd-5ecd3fbdfa35', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '9444d52a-9d31-4ba6-9034-4f9617f9ee13', 'interfaces.detail.i_menu_provide.example', 'Injecting the menu context in a nested child', 'import { inject } from ''vue''
