INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('9e849386-631b-46dd-95a7-6cb3bcf3642a', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'e2179fb2-72a6-466a-95c6-0da465c70d3e', 'interfaces.detail.i_ripple_element_dataset.example', 'Reading dataset flags from a ripple wave element', 'import type { IRippleElement, IRippleElementDataset } from ''origam''

function getRippleAge(el: IRippleElement): number {
    const dataset: IRippleElementDataset | undefined = el.dataset
    const activated = dataset?.activated
    return activated ? Date.now() - new Date(activated).getTime() : 0
}', 'typescript', 0, false, NULL);
