INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('1b2f5912-3eeb-4403-b1dc-8784729cbc93', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'e7f101b6-c10d-46da-bfd4-6330a18b3fe7', 'interfaces.detail.i_scroll_strategy_data.example', 'Writing a custom TScrollStrategyFn', 'import type { IScrollStrategyData } from ''origam''

function closeOnScroll(data: IScrollStrategyData, props: any, scope: any) {
    // Close the overlay as soon as the user scrolls
