INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('379566f8-3690-4bb3-98da-7624a656fe32', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '0497f33d-e845-4b1f-883d-8b56d840832c', 'interfaces.detail.i_snackbar_group_item.example', 'Accessing the current stack items', 'import { useSnackbarGroup } from ''origam''
