INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('ce7eb389-5800-4d00-aefb-a4efe65cdc8e', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '8d89a512-12ed-4958-999f-061403feebf3', 'interfaces.detail.i_snackbar_group_item_action.example', 'Notify with an undo action', 'import { useSnackbarGroup } from ''origam''

