INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('125add14-4ee0-482a-aabb-47f4351d775e', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'd2bbd5e1-efa8-459c-b19e-7126d1a535ea', 'interfaces.detail.i_use_chart_options.example', 'Passing options to useChart', 'import { useChart } from ''origam''
