INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('157f0371-12bc-4a47-9e7c-a045b55f72e5', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'a314f5e0-5b9f-45b7-9591-46dab4520e18', 'interfaces.detail.i_watermark_props.example', 'Wrapping confidential content with OrigamWatermark', '<OrigamWatermark
