INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('050a7280-e108-4881-adc3-494156863a0b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '6f3eb8c5-c1a3-45b1-b99a-e2ed0619dcf0', 'interfaces.detail.i_watermark_slots.example', 'Wrapping protected content', '<OrigamWatermark text="CONFIDENTIAL" :opacity="0.12">
