INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('f7cdc67f-7476-4ff9-9101-b95edaaf592a', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '470b4067-6071-4546-b282-801fe4bb364f', 'interfaces.detail.i_window_emits.example', 'Listening to slide changes via v-model', '<OrigamWindow v-model="activeSlide" @update:model-value="onSlideChange">
