INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('9aadf91d-d70d-4480-8429-e9aa31fc0d26', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'e16bd249-78e8-4dbb-be00-e625f3b6052b', 'interfaces.detail.i_window_item_props.example', 'Custom per-item transitions', '<OrigamWindow v-model="active">
