INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('d390b0c7-8e1c-4b8d-833e-8ebfd16972ec', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '4da31272-c65f-4605-9b1a-b1c57d3c9c0d', 'interfaces.detail.i_window_props.example', 'Basic keyboard-navigable carousel', '<OrigamWindow v-model="slide" :show-arrows="true" continuous>
