INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('baabd553-9634-4aaa-84f7-c15f2c59952a', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'e0af0edb-6a73-4db0-bdf6-b5c503b03601', 'interfaces.detail.i_window_provide.example', 'Consuming the provided context in a custom WindowItem', 'import { inject } from ''vue''
