INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('a6c607cf-1988-44e4-a2ad-501cb99e1b4e', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '9fc025ae-ae82-468a-af52-dc614b3cfd29', 'utils.detail.add_days.example_basic', 'Add and subtract days', 'import { addDays } from ''origam''

