INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('ae855b92-9d6b-427f-a947-747e111b2dbb', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '01532b28-a552-4701-a2d7-d450caa6076d', 'utils.detail.add_hours.example_basic', 'Add hours to a date', 'import { addHours } from ''origam''

