INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('22ddeb61-8fd6-4ee4-87fa-49acd33cf2dd', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '1ed700ba-bb15-4e56-890c-51751b158c4c', 'utils.detail.add_minutes.example_basic', 'Add minutes to a date', 'import { addMinutes } from ''origam''

