INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('6b0a4344-af8b-4089-9429-6496950984f3', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '96617a56-55cb-4387-8877-5592f2d9ea93', 'utils.detail.add_months.example_basic', 'Advance a calendar month', 'import { addMonths } from ''origam''

