INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('2785e424-3f77-4f8d-95cd-0544222da9da', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '69afd2c4-4254-4a84-a78a-681e42aaf752', 'utils.detail.add_weeks.example_basic', 'Add and subtract weeks', 'import { addWeeks } from ''origam''

