INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('bbb1994d-4502-4fd1-961a-ef0567738aea', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'ac82aed0-b087-482a-a88f-ec3744336cc4', 'utils.detail.add_window_listener.example_basic', 'Listen to resize with automatic cleanup', 'import { addWindowListener } from ''origam''
import { onUnmounted } from ''vue''

const cleanupFns: Array<() => void> = []
const remove = addWindowListener(''resize'', () => console.log(''resized''), cleanupFns)

// manual teardown
remove()

// or auto-teardown via onUnmounted
onUnmounted(() => cleanupFns.forEach(fn => fn()))', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('f63521e0-0b88-4030-bfe0-a0dda5366da4', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'e0bc96a6-0904-4ef1-8911-415dc7e429cd', 'utils.detail.anchor_to_point.example_basic', 'Convert a top-center anchor to a point', 'import { anchorToPoint } from ''origam''

const box = { x: 100, y: 50, width: 200, height: 40 }
const anchor = { side: ''top'', align: ''center'' }
anchorToPoint(anchor, box)
// → { x: 200, y: 50 }  (center-top in viewport space)', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('a19bba61-c083-40e7-8a5f-48664fe8a750', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '1c7ac227-7d48-4c33-9dd6-2b85e025296e', 'utils.detail.animate.example_basic', 'Fade-in an element', 'import { animate } from ''origam''

const el = document.querySelector(''.my-card'')!
