INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('222c0256-f462-4eff-9420-53f73b8de444', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'd0797bec-f4ae-4f25-a9ae-84a449558c73', 'utils.detail.apc_acontrast.example_basic', 'Black text on white background', 'import { APCAcontrast } from ''origam''

