INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('1b996975-fb51-4baf-ae8c-a2c77ebaa852', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '86e944d0-7b19-4c21-8745-4a3eedb3c769', 'utils.detail.apply_mask.example_phone', 'Phone number mask', 'import { applyMask } from ''origam''

