INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('545f93be-ff93-4200-941c-ba63de0d715f', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'e186ed75-52af-4cce-9d38-bd9922cc73b8', 'utils.detail.apply_theme.example_basic', 'Inject a brand theme at runtime', 'import { applyTheme } from ''origam''

