INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('0efba3f2-1f7e-462d-995e-526c5c734ddb', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '0d5982d3-2e5f-4682-b0db-3b0e16ca7550', 'utils.detail.apply_themes.example_basic', 'Inject multiple themes at once', 'import { applyThemes } from ''origam''

