INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('5f773ca5-e276-4221-ae45-2d1a80ef2d48', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'c862ad2a-ff9d-4ba4-8faa-8febf2b60fde', 'utils.detail.arc_path.example_basic', 'Full-circle donut slice', 'import { arcPath } from ''origam''

