INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('31d0027e-6b03-4dd3-adec-4994be60c715', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'f78502d4-b8ad-497d-a04b-66604b2edab0', 'utils.detail.area_path.example_basic', 'Monotone area path', 'import { areaPath } from ''origam''

