INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('be38b691-d000-4c85-8c81-23f35e136305', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '5bd10676-3ecf-466f-8ae2-95a1dcb946b5', 'utils.detail.attached_root.example_basic', 'Check if an element is in the document', 'import { attachedRoot } from ''origam''

