INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('f45610f8-39e4-48f7-83b4-a8bc7d250294', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '736c9cfa-4686-4e2a-85c2-102e3410b72c', 'utils.detail.binary_closest.example_basic', 'Find the closest cumulative offset', 'import { binaryClosest } from ''origam''

// Cumulative item heights: [0, 40, 80, 120, 160]
const offsets = [0, 40, 80, 120, 160]
binaryClosest(offsets, 90)  // → 2 (80 ≤ 90)
binaryClosest(offsets, 40)  // → 1
binaryClosest(offsets, 200) // → 4 (last index)', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('048889b8-3461-480a-b4f8-8f3d12245419', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'ab92b7de-dfbd-416e-b347-6cc4292e3795', 'utils.detail.bind_props.example_basic', 'Apply attributes and listeners to a custom element', 'import { bindProps } from ''origam''

const el = document.querySelector(''.my-widget'')!
bindProps(el, {
    ''data-active'': ''true'',
    ''aria-label'': ''Close'',
    onClick: () => console.log(''clicked''),
})

// Remove the attribute later
bindProps(el, { ''data-active'': null })', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('3f6e21df-ab50-42b4-9c78-840ad758f563', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '4f6527d6-4940-4748-b403-9937531b8369', 'utils.detail.bind_scroll.example_basic', 'Track scroll position in a composable', 'import { bindScroll } from ''origam''
import { effectScope, ref } from ''vue''

const scrollY = ref(0)
const scope = effectScope()

scope.run(() => {
    bindScroll(document.querySelector(''.panel'') as HTMLElement, (e) => {
        scrollY.value = (e.target as HTMLElement).scrollTop
    })
})

// Cleanup is handled by scope.stop()
scope.stop()', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('04f5ce42-6c31-4f0d-bd26-616a03fd2ade', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'fa0a1558-0e6a-4911-b16d-b5d46399f2d7', 'utils.detail.block_scroll_strategy.example_basic', 'Use inside an overlay composable', 'import { blockScrollStrategy } from ''origam''
import { effectScope } from ''vue''

// Used internally by useScrollStrategy when scrollStrategy === ''block''
const scope = effectScope()
scope.run(() => {
    blockScrollStrategy(overlayData, { contained: false })
})
// Scroll is blocked while scope is alive
scope.stop() // → scroll restored', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('7afc21d6-34e7-45cf-9841-d7b0daa34abe', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '2a6187e3-5d6f-4bb0-aca5-0a14f22d44cf', 'utils.detail.bracket_dash_array.example_basic', 'Map border-style to SVG stroke attributes', 'import { bracketDashArray } from ''origam''

bracketDashArray(''dashed'')   // → { dasharray: ''8 5'' }
bracketDashArray(''dotted'')   // → { dasharray: ''1 5'', linecap: ''round'' }
bracketDashArray(''solid'')    // → {}
bracketDashArray(null)       // → {}', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('d39a95f7-08f5-43f8-83c7-5d0129ed360b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'e9c6eb96-9f0a-4e7b-a75c-e2547e2c6322', 'utils.detail.get_minutes.example_basic', 'Extract minutes from a date', 'import { getMinutes } from ''origam''

