INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('005edf1f-6d95-4077-8ad0-d374f4940d48', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'a1fc9535-6406-4b69-a2c2-95efa36972b1', 'utils.detail.bracket_surface_vars.example_basic', 'Build CSS variables for a bracket match surface', 'import { bracketSurfaceVars } from ''origam''

