// }', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('a1fbadc2-fe4c-4fe9-8b06-0715de363e09', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'bcc4aff8-24a2-4143-ad2b-a15e39d6b7f7', 'utils.detail.build_disabled_predicate.example_array', 'Disable specific dates from an array', 'import { buildDisabledPredicate } from ''origam''

const isDisabled = buildDisabledPredicate([
    new Date(''2024-12-25''),
    ''2024-12-31'',
])

