isDisabled(new Date(''2024-12-24'')) // → false', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('27b33a24-0ebc-40b9-a186-5221e65a473b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'bcc4aff8-24a2-4143-ad2b-a15e39d6b7f7', 'utils.detail.build_disabled_predicate.example_fn', 'Pass a custom predicate directly', 'import { buildDisabledPredicate } from ''origam''

