INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('6d4135fa-8fe0-465d-a6c2-3ae354a89354', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'e0346884-97e0-43ca-aee9-251c7a8f7d04', 'utils.detail.build_month_matrix.example_basic', 'Generate a January 2024 grid (Monday start)', 'import { buildMonthMatrix } from ''origam''

