INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('63043f04-a824-43f3-b2e9-aaa8313d456e', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '716a50e2-75d2-4b28-bb9c-e1dd3e6f458b', 'utils.detail.calculate.example_basic', 'Calculate ripple geometry from a click', 'import { calculate } from ''origam''
// Typically called internally by the v-ripple directive:
el.addEventListener(''mousedown'', (e) => {
    const { radius, scale, centerX, centerY } = calculate(e, el)
    el.style.setProperty(''--ripple-radius'', `${radius}px`)
    el.style.setProperty(''--ripple-center-x'', centerX)
    el.style.setProperty(''--ripple-center-y'', centerY)
})', 'typescript', 0, false, NULL);
