INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('8415a634-cb80-4394-b3d7-5bb2e0c96f20', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '023150a9-abaa-4760-b9b0-a9301ba478ff', 'utils.detail.calculate_impulse_velocity.example_basic', 'Compute fling velocity from touch samples', 'import { calculateImpulseVelocity } from ''origam''

