INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('f26ae305-5077-492a-8a91-93a0917dab31', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'ddb501ab-fa24-4fb7-8564-a15b1901376f', 'utils.detail.cyclic_movement.example_basic', 'Used internally by OrigamParallaxElement', 'import { cyclicMovement } from ''origam''

