INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('eaa79502-8e48-4d14-b4f0-8610e5b96183', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '297b35bb-221b-4cd3-8825-d523444b58ad', 'utils.detail.debounce.example_basic', 'Debounce a search handler', 'import { debounce } from ''origam''

