INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('11bc7983-5455-4dc3-ab25-993af2b6b328', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '3fc723ae-817a-470d-9d55-e46a516e74f6', 'utils.detail.deep_equal.example_basic', 'Comparing objects and dates', 'import { deepEqual } from ''origam''

