INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('8fab8dac-d400-4947-a32c-7d202502093b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '3e0f7335-74d8-45b7-91d7-390fbcb12b13', 'utils.detail.default_filter.example_basic', 'Substring match', 'import { defaultFilter } from ''origam''

