INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('41d921f3-c1bf-4eca-978d-5b5bbcd1a672', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '7e2d84cd-8052-46a8-8c1e-93e283d8c526', 'utils.detail.defer.example_basic', 'Delayed execution with cancel', 'import { defer } from ''origam''

