INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('dc1f3512-1c0b-4cc9-a987-a6562000f8f6', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '42d1e8c4-1781-4587-9e7f-7bf11304d142', 'utils.detail.destruct_computed.example_basic', 'Destructure a computed object reactively', 'import { destructComputed } from ''origam''
import { computed, ref } from ''vue''

const count = ref(0)
const { doubled, label } = destructComputed(() => ({
    doubled: count.value * 2,
    label: `value is ${count.value}`,
}))

console.log(doubled.value) // 0
