INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('0043113b-6deb-48d5-9b20-38fe0a018b6a', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '64430106-489e-4e00-a5e7-e99c6332d069', 'utils.detail.end_of_week.example_basic', 'Last day of the week per locale', 'import { endOfWeek } from ''origam''

