INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('6143d068-3429-4a57-afe4-0db0a36c4c00', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '95e23bf5-f267-4ad4-a086-9278c436ef95', 'utils.detail.end_of_week_fixed.example_basic', 'Week ending on Saturday (Sunday-first)', 'import { endOfWeekFixed } from ''origam''

