INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('d3835f10-38cf-4609-bb6f-2a7b0ba4938b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '3ed05b8a-acb8-4390-b439-620e84fda484', 'utils.detail.expand_recurrence.example_basic', 'Weekly recurrence over a month', 'import { expandRecurrence } from ''origam''

const event = {
    id: ''1'',
    title: ''Stand-up'',
    start: ''2024-06-03T09:00:00'',
    end:   ''2024-06-03T09:15:00'',
    rrule: ''FREQ=WEEKLY;BYDAY=MO,WE,FR'',
}

const range = { start: new Date(''2024-06-01''), end: new Date(''2024-06-30'') }
const occurrences = expandRecurrence(event, range)
// → array of cloned events for every Mon, Wed, Fri in June', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('5671bc21-6c2b-49b0-883b-8a679dff3a82', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '718b90a8-c12b-4be0-b0c0-3f86d840f3aa', 'utils.detail.extract_color.example_basic', 'Extract to hex vs RGB object', 'import { extractColor } from ''origam''

