INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('686f0948-040b-49f8-a8d2-db3d95aea313', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'a1d2813e-e8db-4507-a846-22046805bb04', 'utils.detail.extract_keys.example_basic', 'Collect column keys from nested headers', 'import { extractKeys } from ''origam''

