INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('8f7d2214-5f30-4126-af12-7570496e31f2', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'de5d9e0c-4665-4625-87aa-f94dd98d29c9', 'utils.detail.extract_leaves.example_basic', 'Flatten grouped headers to leaf columns', 'import { extractLeaves } from ''origam''

