INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('4c62a1be-65f5-4542-a8fe-b27d0bb1d269', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'bd8ebb6d-b0a6-49d2-aac8-2d6bd1fb5549', 'utils.detail.filter_input_attrs.example_basic', 'Split attrs between root and input', 'import { filterInputAttrs } from ''origam''

