INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('5ac586ea-10a8-4bcb-b28b-b6ef08457e66', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '3630eb68-68da-4f86-b235-4a70f64fdcc6', 'utils.detail.filter_items.example_basic', 'Filter a list by query', 'import { filterItems } from ''origam''

