INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('5a843522-b1a5-402c-a460-826e08a63820', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '21ddd332-6914-4f04-90ec-6cef476203b4', 'utils.detail.find_children_with_provide.example_basic', 'Locate children by injection key', 'import { findChildrenWithProvide } from ''origam''
