INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('8043d9bb-befc-4c04-8d3f-311bb999b1e6', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '65403d6d-7b14-4f00-a6ec-4155e96ce437', 'utils.detail.flatten_fragments.example_basic', 'Flatten default slot VNodes', 'import { flattenFragments } from ''origam''
