INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('45a17135-7ded-4583-8557-4e971fdb526c', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '45e287cb-10ed-4bd8-9048-619e673a887a', 'utils.detail.flatten_items.example_basic', 'Flatten with one open group', 'import { flattenItems } from ''origam''

