INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('2c0c2d0b-b604-4684-b705-2b9e3ae1fdcf', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'afdd1622-32c9-4960-8822-5a7a9fd1d9f6', 'utils.detail.group_items.example_basic', 'Single-level grouping', 'import { groupItems } from ''origam''

const rows = [
  { raw: { country: ''FR'', name: ''Alice'' }, id: ''1'' },
  { raw: { country: ''DE'', name: ''Bob''   }, id: ''2'' },
  { raw: { country: ''FR'', name: ''Carol'' }, id: ''3'' },
]

groupItems(rows, [''country''])
// → [
//   { id: ''root_country_FR'', key: ''country'', value: ''FR'', items: [Alice, Carol], depth: 0 },
//   { id: ''root_country_DE'', key: ''country'', value: ''DE'', items: [Bob],          depth: 0 },
// ]', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('08dd626c-c9fd-4430-abe0-aaf8a6b515f9', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'a00bfb86-2612-41df-9669-f0ef7be9cbc8', 'utils.detail.group_items_by_property.example_basic', 'Partition rows by a field', 'import { groupItemsByProperty } from ''origam''

const rows = [
  { raw: { status: ''active'' }, id: ''1'' },
  { raw: { status: ''idle''   }, id: ''2'' },
  { raw: { status: ''active'' }, id: ''3'' },
]

const map = groupItemsByProperty(rows, ''status'')
map.get(''active'')  // → [row1, row3]
map.get(''idle'')    // → [row2]', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('eaebed33-45d0-43a1-b78a-9f27bfda4b90', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '1e61fee9-1052-4396-90d3-9d2d1f3d28a4', 'utils.detail.handle_gesture.example_basic', 'Detect a left swipe', 'import { handleGesture } from ''origam''

