INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('538d88ba-0547-4b28-998f-cca796fc8521', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '3e33468b-aae6-4f1f-bf28-303597452101', 'utils.detail.is_touch_event.example_basic', 'Detecting touch to set ripple origin', 'import { isTouchEvent, isKeyboardEvent } from ''origam''

function getRippleOrigin(e: TRippleEvent) {
    if (isTouchEvent(e)) {
        return { x: e.touches[0].clientX, y: e.touches[0].clientY }
    }
    if (isKeyboardEvent(e)) {
        return null // centred ripple
    }
    return { x: (e as MouseEvent).clientX, y: (e as MouseEvent).clientY }
}', 'typescript', 0, false, NULL);
