INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('b8986a4a-0dab-400d-9e6d-0300fa75bb98', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '49dcbaa6-4571-4937-af69-75f054ebd437', 'utils.detail.is_utility_intent.example_basic', 'Checking whether an intent has a utility class', 'import { isUtilityIntent } from ''origam''

