INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('11cb4415-0772-40c1-8767-cb6b37a593a4', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '2f0fc672-147b-44c3-9d2c-5b2ae4fb217c', 'utils.detail.is_within_range.example_basic', 'Range inclusion check', 'import { isWithinRange } from ''origam''

