INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('eda73b59-5849-43d4-bb74-b9d18f93fe8e', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '8a705845-43fa-4043-8087-18a8f9ee16fd', 'utils.detail.oops.example_exhaustive', 'Exhaustiveness guard in a switch', 'import { oops } from ''origam''

type Direction = ''up'' | ''down'' | ''left'' | ''right''

function move(dir: Direction): void {
  switch (dir) {
    case ''up'':    return doUp()
    case ''down'':  return doDown()
    case ''left'':  return doLeft()
    case ''right'': return doRight()
    default:      oops() // TypeScript error if a branch is missing
  }
}', 'typescript', 0, false, NULL);
