INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('8991f4ec-0187-4ac4-994d-d1d08dbc56b5', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'd6fcf2b4-23c5-45a6-b814-4f2bcec5ca85', 'utils.detail.parse_display_options.example_basic', 'Resolve display options', 'import { parseDisplayOptions } from ''origam''

