INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('0dcdbb75-1303-4f01-b7c5-eaa640d8c21c', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '812c2f94-c648-4b1e-8714-357a2bdff212', 'utils.detail.parse_fixed_columns.example_basic', 'Mark the last fixed column', 'import { parseFixedColumns } from ''origam''

