INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('ac3dc4d4-190a-43ef-8e9d-92a22f4abdd9', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '8b5c6281-a09f-4f9d-a215-658b3b1571b0', 'utils.detail.parse_gradient.example_basic', 'Resolve named colors in a gradient', 'import { parseGradient } from ''origam''

