INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('2ebe83be-2d48-476e-bdb4-e2e447076fed', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '319ead6f-4461-42de-9b54-14eba391b3c8', 'utils.detail.parse_header_items.example_basic', 'Build multi-level header rows', 'import { parseHeaderItems } from ''origam''

