INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('687df689-a2b1-4d63-bf5e-73fef9d79c11', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '1eed8acc-c86f-4a44-abca-4d3d32cd45a3', 'utils.detail.parse_hex.example_basic', 'Normalise hex color strings', 'import { parseHex } from ''origam''

