INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('e30a823e-07da-4b53-868a-2634880f25d4', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '4b93b7c4-e01a-4de2-856c-24c7ff3cc6fc', 'utils.detail.parse_highlight_lines.example_basic', 'Parse highlight ranges', 'import { parseHighlightLines } from ''origam''

