INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('0d126873-4c05-4cfb-bf83-f3a0c48b17ce', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'bcbf9de2-6327-4d04-a9c9-f776c24fb7b2', 'utils.detail.parse_iso.example_basic', 'Parse an ISO date string', 'import { parseISO } from ''origam''

