INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('51411899-f174-43fc-8c3e-516cf7b098ae', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'd2d50d31-b188-49d4-aaa6-c8137e45e28c', 'utils.detail.parse_local_date.example_basic', 'Parse a date without timezone shift', 'import { parseLocalDate } from ''origam''

