INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('8d6050ae-1626-482e-bc4f-6c3fb28ebb82', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'e34280f9-e91c-4220-82a7-52650d8b2206', 'utils.detail.parse_pattern.example_basic', 'Compile a phone number mask', 'import { parsePattern } from ''origam''

