//   { kind: ''digit'',   char: ''#'', consumer: true  },
//   { kind: ''digit'',   char: ''#'', consumer: true  },
//   { kind: ''literal'', char: '')'', consumer: false },
//   ...
// ]', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('11917012-6805-4b9c-8afb-a1e7d1885627', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '410d312b-1b1c-4f58-80e5-9e8a86a6adeb', 'utils.detail.parse_r_rule.example_basic', 'Parse a weekly recurrence rule', 'import { parseRRule } from ''origam''

parseRRule(''RRULE:FREQ=WEEKLY;BYDAY=MO,WE;COUNT=10'')
// → {
//   freq: ''WEEKLY'',
//   interval: 1,
//   count: 10,
//   until: null,
//   byDay: [1, 3]   // Monday=1, Wednesday=3
// }

parseRRule(''FREQ=YEARLY'')  // → null (unsupported FREQ)', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('fbb31dba-562e-425c-90d9-276c237e3aee', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'c0642528-b9c5-4d81-b8e6-2f8639656d7b', 'utils.detail.path_length.example_basic', 'Measure a simple two-segment path', 'import { pathLength } from ''origam''

pathLength([[0, 0], [3, 4]])        // → 5   (3-4-5 triangle)
pathLength([[0, 0], [1, 0], [1, 1]]) // → 2
pathLength([[0, 0]])                 // → 0', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('a467c7ea-ad06-4512-bd25-ca8d420847b1', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '171bcda7-b687-42b5-93ec-b014e3eec7f8', 'utils.detail.pick.example_basic', 'Extract known keys from an object', 'import { pick } from ''origam''

const props = { color: ''primary'', size: ''md'', label: ''Submit'' }

pick(props, [''color'', ''size''])
// → { color: ''primary'', size: ''md'' }

pick(props, [''color'', ''nonExistent''])
// → { color: ''primary'' }  (nonExistent is silently skipped)', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('ba97ee07-42ed-4bf8-b56f-6e901a30a85b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'e1befc28-63fb-4d7a-91f4-3b1eddc70495', 'utils.detail.pick_with_rest.example_basic', 'Split component props from inherited attrs', 'import { pickWithRest } from ''origam''

const attrs = { class: ''foo'', id: ''bar'', ''aria-label'': ''close'', color: ''primary'' }

const [componentProps, htmlAttrs] = pickWithRest(attrs, [''color'', /^aria-/])
// componentProps → { color: ''primary'', ''aria-label'': ''close'' }
// htmlAttrs      → { class: ''foo'', id: ''bar'' }', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('b9726bba-13d9-4b93-825b-f90ff5811b96', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '2610b359-0d7a-4e94-8a86-8914cbc2ba02', 'utils.detail.pixel_ceil.example_basic', 'Ceil to physical pixel (2x display)', 'import { pixelCeil } from ''origam''

// devicePixelRatio = 2
pixelCeil(10.1)   // → 10.5  (next 0.5-px boundary)
pixelCeil(10.5)   // → 10.5
pixelCeil(10.6)   // → 11', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('2a744ef5-cbda-4d8e-9d13-b4771e0d201e', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '09f8a4a0-ce8b-4102-9331-361b4081110a', 'utils.detail.pixel_round.example_basic', 'Round to physical pixel (2x display)', 'import { pixelRound } from ''origam''

// devicePixelRatio = 2
pixelRound(10.1)   // → 10    (rounds down to 0.5-px grid)
pixelRound(10.3)   // → 10.5  (rounds up)
pixelRound(10.75)  // → 11', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('1040d509-e81f-4314-91c3-248de7debb15', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '8736a9ca-0077-4898-a17b-89b1451c588a', 'utils.detail.polar_to_cartesian.example_basic', 'Position a label at the top of a circle', 'import { polarToCartesian } from ''origam''

