polarToCartesian(100, 100, 50, Math.PI / 2)
// → [150, 100]  (3 o''clock)', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('8330a08d-94e4-40f0-a94a-7eb650d41df6', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'd0647325-8fa4-4661-9230-54bd1ac00db8', 'utils.detail.polygon_path.example_basic', 'Build a closed triangle path', 'import { polygonPath } from ''origam''

