INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('c74c06ae-31d6-48c4-a318-d5eb4f657cca', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '374f4f2b-19c0-4b39-a737-49ce7e7b7814', 'utils.detail.polygon_to_svg_path.example_basic', 'Project a geographic polygon', 'import { polygonToSvgPath } from ''origam''

