INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('3549f7ca-0160-46e7-a0b2-864d93e2a974', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '0cfcb1ac-9997-4eb2-95d8-0d5a093c245f', 'utils.detail.priority_queue.example_basic', 'Sort items by priority', 'import { priorityQueue } from ''origam''

