INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('75c0e91e-6d69-4a82-893e-f5f091ab087b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '22088b2b-ceef-437d-9b27-26f580f9388a', 'utils.detail.raw_bg_expr_with_state.example_basic', 'Generate hover and active colour expressions', 'import { rawBgExprWithState } from ''origam''

