INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('51871c2c-6b24-4b2a-a2ff-c6b506bb564b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '365fe243-a035-4773-b8d3-beee76faa456', 'utils.detail.ref_element.example_basic', 'Resolve an element from a component ref', 'import { refElement } from ''origam''
