INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('fd5cf886-4c18-48d9-a53a-483f45f2624c', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '2d9acf14-9381-4bf3-a6a7-125f7515568b', 'utils.detail.reposition_scroll_strategy.example_basic', 'Attach to an overlay via the scrollStrategy prop', '<!-- In an OrigamMenu or OrigamTooltip consumer -->
