INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('3d5fbae9-55b3-418b-a9de-903237ec1529', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '85755bf6-2616-494a-a14a-712d7b207cac', 'utils.detail.resolve_mask_config.example_basic', 'Resolve built-in key and raw pattern', 'import { resolveMaskConfig } from ''origam''

