INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('e6dbf049-9802-4997-922c-eb96a2661515', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '89c7ff29-6662-493f-80b3-a86281f0c85e', 'utils.detail.resolve_qr_color.example_basic', 'Resolve foreground and background colours', 'import { resolveQrColor } from ''origam''

resolveQrColor(''primary'', ''foreground'', ''#000000'')
