// → ''#000000''', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('d1276f57-fd2f-4ca6-a809-e7f9e382a03d', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'e6502582-08a3-4edf-b334-915b8e233ef0', 'utils.detail.resolve_qr_corner_radius.example_basic', 'Resolve various rounded values to module units', 'import { resolveQrCornerRadius } from ''origam''

