INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('8a5841e0-d235-452b-902d-4dbe12eaa5c8', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'c2919319-bbbd-457a-b6e8-ca2ff9340e9f', 'utils.detail.resolve_theme_vars.example_basic', 'Flatten a theme object to CSS vars', 'import { resolveThemeVars } from ''origam''

