INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('59f7eca1-5bdc-4b86-b0f7-3d9411220fb8', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '067fb589-f633-44c2-8cd0-7b67996266fa', 'utils.detail.resolve_unref.example_basic', 'Unwrap a ref and a getter function', 'import { resolveUnref } from ''origam''
