INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('98018036-28ce-47d8-bf85-f5e516c57c58', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '895ae5a5-0255-42af-9d3c-07d1162728f3', 'utils.detail.ripple_show.example_basic', 'Attach to a mousedown listener', 'import { rippleShow, rippleHide } from ''origam''

