INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('edc67e42-e94a-48ce-ae94-9d242daa84fb', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '8c13fe97-1dd5-4b0c-97ae-a5f88c278101', 'utils.detail.ripple_stop.example_basic', 'Prevent ripple bubbling from a child element', 'import { rippleStop } from ''origam''

