INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('01913c58-15fe-495e-a3c3-6381ef416f10', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'bf341d50-c0ea-49ca-b43a-61e23e6c104a', 'utils.detail.ripple_transform.example_basic', 'Scale a ripple element', 'import { rippleTransform } from ''origam''

