INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('cc2d48ec-1e79-4851-a603-fcf300dae80e', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '9423c391-4377-4cc2-9972-63943683baea', 'utils.detail.split_key_sequence.example_basic', 'Parse a chord sequence', 'import { splitKeySequence } from ''origam''

