INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('3c8dfa02-7a23-4426-80a7-1b84b3b3ed72', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '250239ff-07df-493c-b3b3-2d15d15ac3d6', 'utils.detail.start_of_week.example_basic', 'Find Monday from any day (fr-FR locale)', 'import { startOfWeek } from ''origam''

