INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('ebb80a67-2802-4690-ab51-eecae3e11844', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'd94013a9-1084-45be-b4fa-107e977871f1', 'utils.detail.stepped_path.example_basic', 'Draw a stepped chart line', 'import { steppedPath } from ''origam''

const d = steppedPath([[0, 10], [50, 30], [100, 10]])
// → ''M0,10 L50,10 L50,30 L100,30 L100,10''

// <path :d="d" fill="none" stroke="currentColor" />', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('bc5b79fd-8773-4960-b9ae-b8aeaa9020f3', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'd9614109-90de-4891-bf47-167c26211d47', 'utils.detail.stepped_path_length.example_basic', 'Drive a stroke-dasharray animation', 'import { steppedPathLength } from ''origam''

const points = [[0, 0], [50, 0], [50, 100], [100, 100]] as const
const len = steppedPathLength(points)
// → 200  (50 + 100 + 50)

// Use as SVG pathLength so dasharray matches
// <path pathLength={len} stroke-dasharray={len} ...>', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('8ad24006-5c02-4382-b2f1-862aaead52a1', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'cc9039f1-4bc2-40be-adc3-5009e9003b30', 'utils.detail.strip_alpha.example_basic', 'Stripping alpha from an HSV colour', 'import { stripAlpha } from ''origam''

const hsva = { h: 210, s: 0.8, v: 0.9, a: 0.5 }

stripAlpha(hsva, true)   // → { h: 210, s: 0.8, v: 0.9 }
stripAlpha(hsva, false)  // → { h: 210, s: 0.8, v: 0.9, a: 0.5 }', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('c1f2e786-6686-44fe-9980-f99c1a0f1f4b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'ad741a27-4c8f-4c7a-9fd8-daa6e96ff7b6', 'utils.detail.template_ref.example_basic', 'Attach a template ref and read its element', 'import { templateRef } from ''origam''

const rootEl = templateRef()

// In template: <div :ref="rootEl">
// In script:
console.log(rootEl.el)    // HTMLDivElement | null
console.log(rootEl.value) // same ref target', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('794070ad-1061-4ac2-90ef-ba680ecf9477', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '73323553-4499-415b-9940-d7ff9f94d54d', 'utils.detail.theme_selector.example_basic', 'Selector for various theme configurations', 'import { themeSelector } from ''origam''

themeSelector({ name: '''', mode: ''auto'' })
// → '':root''

themeSelector({ name: ''brand-x'', mode: ''auto'' })
// → ''[data-theme="brand-x"]''

themeSelector({ name: ''brand-x'', mode: ''dark'' })
// → ''[data-theme="brand-x"][data-mode="dark"]''', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('5fca5758-dd48-4fdd-91a0-95c947721036', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '64c368cc-1cf9-4a89-aa3f-0e7c63506138', 'utils.detail.theme_to_css.example_basic', 'Produce a CSS rule for a named theme', 'import { themeToCss } from ''origam''

const css = themeToCss({
  name: ''brand-x'',
  mode: ''auto'',
  cssVars: {
    ''--origam-color__action--primary---bg'': ''#0057ff'',
    ''--origam-color__action--primary---fg'': ''#ffffff'',
  },
})
// → ''[data-theme="brand-x"] {\n  --origam-color__action--primary---bg: #0057ff;\n  …\n}\n''', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('54ebb1a4-2d47-4a65-aeb2-1e9ac74ed71a', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'fe79fd43-13cd-40d5-9a80-5abf7f3e1e19', 'utils.detail.theme_vars_to_vars.example_basic', 'Flatten a partial token bucket', 'import { themeVarsToVars } from ''origam''

const flat = themeVarsToVars({
  color: {
    ''action-primary-bg'': ''#0057ff'',
    ''action-primary-fg'': ''#ffffff'',
  },
})
// → {
//   ''--origam-color---action-primary-bg'': ''#0057ff'',
//   ''--origam-color---action-primary-fg'': ''#ffffff'',
// }', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('2b42faa0-60c3-4d35-bc75-a40c4afbc23f', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'f00abddb-5a3d-4fb6-9db8-317b929d833b', 'utils.detail.to_date.example_basic', 'Coercing various input types', 'import { toDate } from ''origam''

toDate(''2024-06-01'')       // → Date(2024-06-01)
toDate(1717200000000)      // → Date(…epoch…)
toDate(new Date())         // → cloned Date
toDate(null)               // → null
toDate(''not-a-date'')       // → null', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('a1f67c0b-0f51-46e9-a999-2957c0f0bc5c', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '9e4588ca-a2c4-4af5-840c-e9a6bdd7f014', 'utils.detail.to_hex.example_basic', 'Convert integer channels to hex digits', 'import { toHex } from ''origam''

toHex(0)    // → ''00''
toHex(10)   // → ''0A''
toHex(255)  // → ''FF''
toHex(16.7) // → ''11'' (rounds to 17)', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('20d7d9b0-60e5-4e50-95b8-499e6a257ce3', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '72003636-606b-42d1-9dfa-899e8ed197c0', 'utils.detail.to_iso.example_basic', 'Format a date with the default adapter', 'import { toISO, useDateAdapter } from ''origam''

const { adapter } = useDateAdapter()
toISO(adapter, new Date(''2024-06-01''))
// → ''2024-06-01''', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('131e73b0-0322-4e0a-bb0c-9f535f0364e8', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '0d738eea-86f3-4b53-aa6c-c4c1fd0ed7a3', 'utils.detail.to_kebab_case.example_basic', 'Convert different case conventions', 'import { toKebabCase } from ''origam''

toKebabCase(''camelCase'')   // → ''camel-case''
toKebabCase(''PascalCase'')  // → ''-pascal-case''
toKebabCase(''myProp123'')   // → ''my-prop123''
toKebabCase()              // → ''''', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('3d83b66a-db65-4a53-a892-04a613fe373e', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '29596a8b-7b70-4ccb-acab-29ab95073534', 'utils.detail.token_foreground_for_intent.example_basic', 'Colour inline text by intent', 'import { tokenForegroundForIntent } from ''origam''

tokenForegroundForIntent(''primary'')
// → ''var(--origam-color__action--primary---fgSubtle)''

tokenForegroundForIntent(''danger'')
// → ''var(--origam-color__feedback--danger---fgSubtle)''

tokenForegroundForIntent(''neutral'')
// → ''var(--origam-color__action--secondary---fg)''', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('362803ae-292f-4994-8680-6793f1c4a760', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '5ff56fbf-5db7-4dcf-89dd-4502a18d5a10', 'utils.detail.token_intent_states.example_basic', 'Guard a path segment', 'import { TOKEN_INTENT_STATES } from ''origam''

TOKEN_INTENT_STATES.has(''primary'') // → true
TOKEN_INTENT_STATES.has(''overlay'') // → false', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('6679b112-34ac-424d-93a2-e797a666a97f', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'e161f914-9b38-4674-9f25-66f0d70e733f', 'utils.detail.token_path_to_css_var.example_basic', 'Resolve component and semantic token paths', 'import { tokenPathToCssVar } from ''origam''

tokenPathToCssVar([''btn'', ''primary'', ''background-color''], true)
// → ''--origam-btn--primary---background-color''

tokenPathToCssVar([''color'', ''neutral'', ''500''], false)
// → ''--origam-color__neutral---500''', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('8fd8c34f-adc5-4984-9887-c837c9f1dc7c', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '5d6a7f77-e25a-4e17-bdcc-1b0e59e9845b', 'utils.detail.token_path_to_css_var_name.example_basic', 'Encode component token paths with state and BEM child', 'import { tokenPathToCssVarName } from ''origam''

// Component token — simple property
tokenPathToCssVarName([''btn'', ''background-color''], true)
// → ''origam-btn---background-color''

// Component token — state variant
tokenPathToCssVarName([''btn'', ''primary'', ''background-color''], true)
// → ''origam-btn--primary---background-color''

// Semantic token (2-level)
tokenPathToCssVarName([''color'', ''primary''], false)
// → ''origam-color---primary''', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('0e0d6d3a-7f8a-4f4b-afb4-84d83bf8735d', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '29fcd008-2cc4-43a8-98cd-e5b9b991e657', 'utils.detail.token_styles_for_intent.example_basic', 'Apply intent surface styles', 'import { tokenStylesForIntent } from ''origam''

tokenStylesForIntent(''primary'')
// → { ''background-color'': ''var(--origam-color__action--primary---bg)'',
//      color: ''var(--origam-color__action--primary---fg)'' }

tokenStylesForIntent(''danger'', ''hover'')
// → { ''background-color'': ''var(--origam-color__feedback--danger--hover---bg)'',
//      color: ''var(--origam-color__feedback--danger--hover---fg)'' }', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('5598f2e2-d801-482e-b234-fc182d85fedc', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '407140bb-7c11-49c5-b17b-fb4fabac776d', 'utils.detail.touchend.example_basic', 'Detect a left swipe with touchend', 'import { touchstart, touchend } from ''origam''

const wrapper = {
  touchstartX: 0, touchstartY: 0,
  touchendX: 0,   touchendY: 0,
  touchmoveX: 0,  touchmoveY: 0,
  offsetX: 0,     offsetY: 0,
  left: () => console.log(''swiped left''),
}

el.addEventListener(''touchstart'', e => touchstart(e, wrapper))
el.addEventListener(''touchend'',   e => touchend(e, wrapper))', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('678c960e-1cbd-49b3-b2c7-7b7e7f826383', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '6a276bef-c4c7-4b92-8f3e-f2a68908675b', 'utils.detail.touchmove.example_basic', 'Track pointer position during a drag', 'import { touchstart, touchmove, touchend } from ''origam''

const wrapper = {
  touchstartX: 0, touchstartY: 0,
  touchendX: 0,   touchendY: 0,
  touchmoveX: 0,  touchmoveY: 0,
  offsetX: 0,     offsetY: 0,
  move: (w) => console.log(''dx:'', w.touchmoveX - w.touchstartX),
}

el.addEventListener(''touchstart'', e => touchstart(e, wrapper))
el.addEventListener(''touchmove'',  e => touchmove(e, wrapper))
el.addEventListener(''touchend'',   e => touchend(e, wrapper))', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('f850913b-022f-4dcd-8488-c77dba852d30', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '0f03590b-06f0-466c-a549-a2bbf6291bd1', 'utils.detail.touchstart.example_basic', 'Pair with touchend to detect a swipe', 'import { touchstart, touchend } from ''origam''

const wrapper = {
  touchstartX: 0, touchstartY: 0,
  touchendX: 0,   touchendY: 0,
  touchmoveX: 0,  touchmoveY: 0,
  offsetX: 0,     offsetY: 0,
  left: () => console.log(''swiped left''),
}

el.addEventListener(''touchstart'', e => touchstart(e, wrapper))
el.addEventListener(''touchend'',   e => touchend(e, wrapper))', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('9f4743b0-9230-4a17-82c7-929751867133', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'adabbb25-55e6-4eb5-bed3-819991d8ae12', 'utils.detail.transform_data_table_item.example_basic', 'Normalise a single table row', 'import { transformDataTableItem } from ''origam''

const item = { id: 1, name: ''Alice'', role: ''admin'' }
const columns = [
  { key: ''name'', value: ''name'' },
  { key: ''role'', value: ''role'' },
]

const row = transformDataTableItem(
  { itemValue: ''id'', itemSelectable: undefined, returnObject: false },
  item,
  0,
  columns
)
// row.value → 1
// row.columns → { name: ''Alice'', role: ''admin'' }', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('c349bd1a-50ac-4399-acd4-08b9012a564a', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'd7e757c9-c9e2-40db-b959-183bb6d498e4', 'utils.detail.transform_data_table_items.example_basic', 'Normalise all rows of a table', 'import { transformDataTableItems } from ''origam''

const rows = transformDataTableItems(
  { itemValue: ''id'', itemSelectable: undefined, returnObject: false },
  [
    { id: 1, name: ''Alice'' },
    { id: 2, name: ''Bob'' },
  ],
  [{ key: ''name'', value: ''name'' }]
)
// rows[0].value → 1
// rows[0].columns → { name: ''Alice'' }', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('b96fafbf-fd3b-4ce8-bb5a-aa0353795b58', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'a892bb45-1197-40e5-9303-ba07c40fc329', 'utils.detail.transform_list_item.example_basic', 'Normalise a plain object item', 'import { transformListItem } from ''origam''

const item = transformListItem(
  { itemTitle: ''label'', itemValue: ''id'', itemChildren: ''children'', itemProps: false },
  { id: 42, label: ''Settings'', children: [] }
)
// item.title  → ''Settings''
// item.value  → 42
// item.children → []', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('7a6b779f-bdb9-4442-9694-b543320ee106', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '3b5c1ab5-73d9-4167-8e62-19c4aefc3126', 'utils.detail.transform_list_items.example_basic', 'Build a OrigamList-ready item array', 'import { transformListItems } from ''origam''

const items = transformListItems(
  { itemTitle: ''name'', itemValue: ''id'', itemChildren: ''children'', itemProps: false },
  [
    { id: 1, name: ''Home'' },
    { id: 2, name: ''Settings'' },
  ]
)
// items[0].title → ''Home''
// items[0].value → 1', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('e72bbc80-14a4-4eff-9896-61ff7f62d32d', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '8973e317-2468-48f5-82c1-379039ad87f7', 'utils.detail.try_on_mounted.example_basic', 'Safe use inside and outside a component', 'import { tryOnMounted } from ''origam''

// Inside a composable used in <script setup>:
// → registers with onMounted normally
tryOnMounted(() => console.log(''mounted''))

// Inside a utility called in a test or SSR context
// (no current Vue instance):
// → executes synchronously right away
tryOnMounted(() => console.log(''no instance, runs now''))

// Deferred in the nextTick when outside a component:
tryOnMounted(() => console.log(''next tick''), false)', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('cc14dcb1-2b16-4ec3-bfc7-67d6a0390d10', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '8f3e230d-48a5-40ea-af19-1690570d5c28', 'utils.detail.try_on_scope_dispose.example_basic', 'Cleanup inside and outside a scope', 'import { tryOnScopeDispose } from ''origam''

// Inside a component / composable — registered normally
const registered = tryOnScopeDispose(() => {
    clearInterval(timer)
})
// registered → true

// Outside any Vue scope — silently skipped
const skipped = tryOnScopeDispose(() => clearInterval(timer))
// skipped → false', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('2b748b67-ec2e-4ac7-b23b-9ee71555a369', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'f0b26340-e7d3-4e81-b1b3-b7e45d200712', 'utils.detail.unbind_props.example_basic', 'Teardown in a custom directive', 'import { bindProps, unbindProps } from ''origam''

const props = { onClick: handleClick, ''aria-label'': ''Close'' }

// Mount phase
bindProps(el, props)

// Unmount phase — removes listener and attribute
unbindProps(el, props)', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('eec43ae7-edd9-4121-9598-b4eb3c08b530', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'e15378e3-a66b-4215-9c48-b3e1fb761f8e', 'utils.detail.unmask_value.example_basic', 'Strip mask from a phone number', 'import { unmaskValue } from ''origam''

unmaskValue(''(12) 3456-7890'', ''(##) ####-####'')
// → ''1234567890''

unmaskValue(''12/31/2024'', ''##/##/####'')
// → ''12312024''', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('a29f0d21-f6cc-45db-8e3b-e2474ab026ae', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '5d9f6734-b97c-4d02-8ea2-c8b84eb7dd86', 'utils.detail.unmount_intersect.example_basic', 'Directive teardown', 'import { unmountIntersect } from ''origam''

// Inside a custom directive using v-intersect internals
const myDirective = {
    unmounted(el, binding) {
        unmountIntersect(el, binding)
    },
}', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('af4e5844-bd5f-4532-be95-77623ada0479', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '6cd9af72-162d-495f-8ec6-e603b8e874ea', 'utils.detail.unref_element.example_basic', 'Access the DOM node from a template ref', 'import { ref, onMounted } from ''vue''
import { unrefElement } from ''origam''

const btnRef = ref(null)

onMounted(() => {
    const el = unrefElement(btnRef)
    // el → HTMLButtonElement
    el?.focus()
})', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('f413cfc6-9d5f-4f79-aa10-5a37c49f07bd', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '991ac9e7-aedc-4dd0-a2bd-7aa032c63afc', 'utils.detail.update_hover.example_basic', 'Directive updated hook', 'import { updateHover } from ''origam''

const vHover = {
    updated(el, binding) {
        const wasEnabled = el._hover?.enabled ?? false
        updateHover(el, binding, wasEnabled, ''my-component'')
    },
}', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('727710fb-c88f-4a3d-b0d1-8f48f9fda3ed', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '33bb42d0-003f-4625-9635-a6e1c93a2131', 'utils.detail.update_ripple.example_basic', 'Directive updated hook', 'import { updateRipple } from ''origam''

const vRipple = {
    updated(el, binding) {
        const wasEnabled = el._ripple?.enabled ?? false
        updateRipple(el, binding, wasEnabled)
    },
}', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('e740f3fd-84b7-40a9-b522-c50cad29887c', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'f65672ea-8f38-4b01-955c-215a54cde7a2', 'utils.detail.use_provided.example_basic', 'Locale prop with provided fallback', 'import { useProvided } from ''origam''

// In a component that accepts an optional locale prop:
const props = defineProps<{ locale?: string }>()
const { locale: injectedLocale } = useLocale()

const locale = useProvided(props, ''locale'', injectedLocale)
// locale.value → props.locale if defined, else injectedLocale.value', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('c8fb4317-b6da-4718-a5f0-772b050e9eae', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '7f3ff052-92ca-47e0-8468-99e600e68b1f', 'utils.detail.validate_pattern.example_basic', 'Named and custom validators', 'import { validatePattern } from ''origam''

validatePattern(''1234567890'', ''numeric'')  // → true
validatePattern(''abc123'', ''numeric'')      // → false

// Custom validator
validatePattern(''hello'', (s) => s.length >= 3)  // → true', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('089bc66e-7e3f-47a7-b24e-0bf22c04cdcb', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'c3021626-ebe3-4e58-8d26-de282fbfdfe2', 'utils.detail.viewport_to_element.example_basic', 'Translate a click position into element space', 'import { viewportToElement } from ''origam''

el.addEventListener(''click'', (e) => {
    const box = el.getBoundingClientRect()
    const local = viewportToElement(
        { x: e.clientX, y: e.clientY },
        box
    )
    // local.x / local.y → position relative to el''s top-left corner
})', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('ab8cd631-42fb-45bc-8b1f-d2ca0215ac3c', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'fbaa14d2-0da6-4561-98b7-3c5fefd20f71', 'utils.detail.warn_legacy_color.example_basic', 'Emit once per unique kind+value', 'import { warnLegacyColor } from ''origam''

// Triggers a console.warn on first call for this pair:
warnLegacyColor(''bgColor'', ''#ff0080'')

// Silent on second call — already warned:
warnLegacyColor(''bgColor'', ''#ff0080'')', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('2eacc491-7d18-424a-b47b-e5a24ab19fce', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '5d948947-ff7c-429e-9d7e-44fe2ad82fdc', 'utils.detail.wrap_in_array.example_basic', 'Scalar, array and null inputs', 'import { wrapInArray } from ''origam''

wrapInArray(''primary'')          // → [''primary'']
wrapInArray([''a'', ''b''])         // → [''a'', ''b'']
wrapInArray(null)               // → []
wrapInArray(undefined)          // → []', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('f0cc0464-8914-412b-ac12-2a18f27d60bc', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '98af1311-e784-4b15-9b31-8ec565cc0eff', 'utils.detail.xyzto_lab.example_basic', 'XYZ to Lab', 'import { XyztoLab, RgbtoXyz } from ''origam''

XyztoLab(RgbtoXyz({ r: 255, g: 255, b: 255 }))
// → [100, 0, 0]  (white in L*a*b*)', 'typescript', 0, false, NULL);
INSERT INTO public.doc_example (id, created_at, updated_at, entry_id, title_key, title_fallback, code, lang, "position", edited_by_user, editorial_locked_at) VALUES ('4c1d3ad7-5772-44af-b0af-edf012ce4bb0', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '74198fb0-4d67-4e05-a1e5-6589a5e75a85', 'utils.detail.xyz_to_rgb.example_basic', 'XYZ back to sRGB', 'import { XyzToRgb, RgbtoXyz } from ''origam''

const original = { r: 100, g: 150, b: 200 }
const roundTrip = XyzToRgb(RgbtoXyz(original))
// → { r: 100, g: 150, b: 200 }', 'typescript', 0, false, NULL);


