INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('981042bd-e87d-4fc0-adde-3b474ab43e28', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '64f43b9d-c41e-419b-8592-337aecb337cc', 'props', 'IActivatorProps', true, NULL, '', 'Props controlling how the overlay is triggered. Includes activator selector/element, open-on strategy (click, hover, focus, context-menu), close-on-content-click, delay settings inherited from IDelayProps, and an optional target override.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('30e1932e-4639-48ba-918d-31ed31f3b54b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '64f43b9d-c41e-419b-8592-337aecb337cc', 'isActive', 'Ref<boolean>', true, NULL, '', 'Reactive flag representing the open/closed state of the overlay. useActivator reads and writes this ref to toggle the overlay on user interaction.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c14d4cb0-969b-4f66-8134-42ae55935278', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '64f43b9d-c41e-419b-8592-337aecb337cc', 'isTop', 'Ref<boolean>', true, NULL, '', 'Reactive flag set by the overlay stack manager. When true, this overlay is the topmost one; when it becomes false while hover/focus-triggered, the composable auto-closes the overlay.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9e8148ee-d96b-45c8-b77d-09a6117d28a9', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '7a11802d-9786-4adb-a342-6ffdf9d3a8d9', 'props', 'IActiveProps & Record<string, any>', true, NULL, '', 'Component props. Reads `props[prop]` (default: `props.active`).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('471cf0da-8eb9-49ee-85aa-0559eb2ada00', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '7a11802d-9786-4adb-a342-6ffdf9d3a8d9', 'prop', 'string', false, '''active''', '', 'The prop key to read for the active value. Use "modelValue" for components with a v-model binding.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a204723a-232f-4530-b4b0-538a517fefab', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '7a11802d-9786-4adb-a342-6ffdf9d3a8d9', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name prefix for the `{name}--active` class.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2db3c159-453f-4bf5-a1e2-6255fcd75318', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '91a6bf47-da70-4191-90c6-a851fe513c72', 'props', 'IAdjacentProps', true, NULL, '', 'Props carrying prependIcon, appendIcon, prependAvatar, and appendAvatar values. The composable reads these to determine whether the outer prepend/append regions should render.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('deed0356-2dec-4ce2-9bb4-4981c4ab4332', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '91a6bf47-da70-4191-90c6-a851fe513c72', 'prependIcon', 'Ref | ComputedRef', false, NULL, '', 'Optional reactive icon override for the prepend slot. When provided, takes precedence over props.prependIcon, enabling status-aware icon swapping without prop mutation.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ab99b763-ffb7-4d43-856a-ffd85e485505', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '91a6bf47-da70-4191-90c6-a851fe513c72', 'appendIcon', 'Ref | ComputedRef', false, NULL, '', 'Optional reactive icon override for the append slot. Same semantics as prependIcon but for the trailing position.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('39d7972d-d984-474d-85e6-a594d4d0f94c', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '2e5cd49a-cb4a-4ef0-ac53-bd071c9e278d', 'props', '{ aspectRatio?: string | number }', true, NULL, '', 'Object carrying an optional aspectRatio value. Accepts a numeric ratio (1.777 for 16:9), a division expression string ("16/9"), or is left undefined to use window.innerWidth / window.innerHeight as the ratio.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3accda6b-ef32-4f00-a19f-308521bc813e', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '5fb99ab4-60be-436d-bf84-d8ca40472305', 'props', 'IUseAudioProps', true, NULL, '', 'Props object with audio (URL of the audio source) and playAudio (boolean flag). When playAudio changes to true the composable calls onPlay(); when it changes to false it calls onStop(). When audio changes, wasPlayed and isPlaying are reset.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c9beb818-11d3-4002-9a9f-665f6676972c', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '40bdc8fb-4914-4107-999f-03b23f0b34fd', 'options', 'IUseOrigamAudioPlayerOptions', false, '{}', '', 'Optional configuration. Accepts `audioRef` (bring your own ref), `autoplay`, `muted`, `loop`, and `preload`. All fields are optional.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4dab3e17-656d-493e-aaaf-7abd374e6344', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '25889cc4-16cd-4452-82bf-cd3c4bbc58a0', 'props', 'T | Ref<TColor>', true, NULL, '', 'Either the component props object (paired with `name`) or a plain Ref<TColor>.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('492a7ee7-f775-443a-a156-732f973190d7', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '25889cc4-16cd-4452-82bf-cd3c4bbc58a0', 'name', 'K', false, NULL, '', 'The key to read from the props object. Typically "bgColor". Omit when passing a plain Ref.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('77af2c43-d67c-4e40-9eec-1acc693d938c', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'ed26f58b-3514-4fb6-890e-7393114695dd', 'props', 'IBorderProps | Ref<...>', true, NULL, '', 'Either the component props object (reads border, borderColor, borderStyle) or a plain Ref for the border shorthand only.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b675d6cf-1381-488a-ba0b-d521e1d2ac49', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'ed26f58b-3514-4fb6-890e-7393114695dd', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name prefix for the `{name}--border` class.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('fcd38fba-9ec3-4e55-953e-b169ea4d7f74', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'b7cd987d-51ee-44c4-9ba8-b882456dcfac', 'options', 'IUseCalendarOptions', true, NULL, '', 'Configuration thunks. All fields are getter functions so the composable reacts to reactive sources without re-instantiation. Includes events, view, currentDate, firstDayOfWeek, slotDuration, dayStartHour, dayEndHour, and optional minDate/maxDate/locale.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('dca7e1d8-2166-4dae-a6ae-2ed311924d8d', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'b7cd987d-51ee-44c4-9ba8-b882456dcfac', 'setView', '(view: TCalendarView) => void', false, NULL, '', 'Optional callback invoked by the returned setView proxy. Bind to a v-model:view setter to keep the parent state in sync when the calendar switches views.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('06eda5e3-9a21-4548-b9e6-22afe1f7098d', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'b7cd987d-51ee-44c4-9ba8-b882456dcfac', 'setCurrentDate', '(date: Date) => void', false, NULL, '', 'Optional callback invoked by navigate(). Bind to a v-model:currentDate setter. If omitted, navigation calls have no effect on the parent state.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2af5e96d-a65d-40f0-a8f9-96fceb4cac06', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '89b1262b-658a-438f-911f-20080950a593', 'options', 'IUseChartOptions', true, NULL, '', 'Configuration object with getter thunks for type, series, categories, stacked, stacking, donutHoleSize, colorScheme, smoothing, yMin, yMax, width, height, padding, and optional hiddenLabels and secondaryYAxis. All values are () => T functions so the composable reacts to any reactive source.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('47f321ea-4837-490e-8bbc-1be5d0828cbe', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'a00adb4c-b546-4b85-b215-6e2df2e90d98', 'options', 'IUseChartGaugeOptions', true, NULL, '', 'Configuration thunks. Required: value, min, max, width, height, padding. Optional: thickness (arc ring width, default 18px), startAngle (radians, default -3π/4), endAngle (radians, default 3π/4). All values are () => T getters so the composable reacts to reactive sources.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('611cf6b2-6858-4998-b6dd-5ef7aa3881cf', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '47f371d1-009f-41cd-81e2-3c3c5ec2de2d', 'options.dataLength', '() => number', true, NULL, '', 'Reactive getter returning the total number of categories or data points. Must always return a value >= 1.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d5cfbae0-03c3-46c7-be69-c84be46c1e5a', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'cbebd0b8-17f7-4246-8b58-665a028ac73a', 'options', 'IUseClipboardOptions', false, NULL, '', 'Optional configuration object. Currently only feedbackDuration is supported.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('cddaaf52-cfa1-4f46-84d2-a5ad1ece3233', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'cbebd0b8-17f7-4246-8b58-665a028ac73a', 'options.feedbackDuration', 'number', false, '2000', '', 'Duration in milliseconds the copied ref stays true after a successful write before auto-resetting.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5cc61adf-9c93-4697-b835-a5124b38913b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '944a393a-abe7-469a-b261-1965876f11f7', 'colors', 'ComputedRef<{ background?: TColor; text?: TColor }>', true, NULL, '', 'A computed ref wrapping both the background and text color values. Either key may be omitted.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('830046e2-aa66-48e6-8b5f-57cbea00b9fd', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '63da2f09-e5bf-4c85-b763-f5e4b20e8b65', 'props', 'IColorProps & IBgColorProps', true, NULL, '', 'Component props containing color, bgColor, hoverColor, hoverBgColor, activeColor, activeBgColor.', 0, false, NULL, NULL);
