INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1755db46-bcfa-45a7-aac3-ce9b428c003e', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '74f4211e-799e-4052-86d1-bfdbf66498e1', 'name', 'string', false, NULL, '', 'Kebab-case component name used to build the ${name}--loading BEM modifier class. Defaults to the current component name via getCurrentInstanceName().', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8ca8fd4a-da56-4d31-a316-29a570bac96e', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '767957bc-81c2-4d58-8f35-fd0f7831f34d', 'props', 'ILocationProps', true, NULL, '', 'Component props extending ILocationProps. The location key accepts a TAnchor string ("top", "bottom start", "right center", etc.).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('84d61269-335d-4bad-9f3e-251ca3351481', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '767957bc-81c2-4d58-8f35-fd0f7831f34d', 'opposite', 'boolean', false, 'false', '', 'When true, positions the element on the opposite side (e.g. "top" becomes bottom: calc(100% - Npx)). Used for tooltip anchoring to a host.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8aa293e4-86e2-4d4c-b8d0-713889a89659', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '767957bc-81c2-4d58-8f35-fd0f7831f34d', 'offset', '(side: string) => number', false, NULL, '', 'Optional function returning a pixel offset for a given side string. Allows per-side inset adjustments without altering the anchor semantics.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8cab5952-32e0-4f01-a5d9-3762736a2db1', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'a52f2c99-6c0c-4c20-85aa-15a1dc08aa9f', 'props', 'IMarginProps', true, NULL, '', 'Component props extending IMarginProps. Reads the `margin` shorthand.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('cb36cb5b-e7bf-4d6b-9e11-d90b554647d5', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'a52f2c99-6c0c-4c20-85aa-15a1dc08aa9f', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name prefix used for the `--marged` class. Defaults to the current Vue instance name.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f493f2fe-7d95-4d8a-9d5f-be22ed0c3f29', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '2900d48a-b3b4-4357-911c-58428cab3d18', 'modelValue', 'MaybeRef<string | null | undefined>', true, NULL, '', 'The raw input value to format. Accepts a plain string or a reactive ref. When it changes the mask is reapplied.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e7b418a7-088c-4512-a693-7c7e7f7c5c8b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '2900d48a-b3b4-4357-911c-58428cab3d18', 'mask', 'MaybeRef<TMask | undefined>', true, NULL, '', 'Mask spec — a pattern string (e.g. "##/##/####"), a named preset, or a custom config object. When it changes the current value is reformatted.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0d76091b-e308-43fb-af63-d0eefcd34d6a', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'c9eef7a9-69d8-4375-9606-e3f05681ff3f', 'columnsRef', 'Ref<number>', true, NULL, '', 'Default column count. Used when no breakpoint in breakpointsRef matches the container width.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1adb099a-b254-42f2-9d1b-1aa878cfd630', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'c9eef7a9-69d8-4375-9606-e3f05681ff3f', 'gapRef', 'Ref<number>', true, NULL, '', 'Gap between items in pixels (both axes). The component resolves token/string gaps to a number before passing it here.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('773fd5ab-f2d3-4903-aefb-13cc3b1bcb78', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'c9eef7a9-69d8-4375-9606-e3f05681ff3f', 'breakpointsRef', 'Ref<TMasonryColumnBreakpoints | undefined>', false, NULL, '', 'Optional map of container-width breakpoints to column counts (e.g. { 600: 2, 900: 3 }). The largest key that is less than or equal to the container width wins.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('07e8facb-6afd-4fff-9b3e-8584c225313f', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'c9eef7a9-69d8-4375-9606-e3f05681ff3f', 'alignRef', 'Ref<TMasonryAlign>', false, '''top''', '', 'Vertical alignment of items within a column. ''top'' packs items to the top; ''center'' distributes unused space above and below each column''s content.', 3, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d66a7609-c925-4062-a2ac-0be1e8d19031', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '8b479edf-6066-4dfd-8ec8-152b95d2573a', 'options', 'IUseMediaPlayerOptions', false, '{}', '', 'Accepts `mediaRef` (bring your own ref), `autoplay`, `muted`, `loop`, `preload`. All optional. When `autoplay` is true but the OS prefers-reduced-motion setting is active, a console warning is emitted and autoplay is suppressed.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('101f7f70-d125-45fd-9c21-b794a7c4ef42', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '5f45b5a7-5e2f-44da-b22a-37539dd06aa4', 'props', '{ messages?: string | string[]; errorMessages?: string | string[]; hint?: string }', true, NULL, '', 'Field props containing the message sources: `messages` (info), `errorMessages` (validation errors), and `hint` (helper text).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('cc4d438a-685a-41f7-be07-2b5ada7905ab', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '5f45b5a7-5e2f-44da-b22a-37539dd06aa4', 'otherMessages', 'Ref<Array<any>> | ComputedRef<Array<any>>', false, 'ref([])', '', 'External messages array injected by a parent form or validation layer (e.g. from useValidation). Takes precedence over hint when non-empty.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d0810fe4-3316-4af7-9d01-c22f7934f49a', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '7da871b1-e44d-400d-be2c-35b6a345f89c', 'props', 'INestedProps', true, NULL, '', 'Props including `opened` (initial open set), `selected` (initial selection map), `selectStrategy` (string or custom object), `openStrategy` (string or custom object), and `mandatory`.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('391dc491-86f1-41e7-a306-b61d2358652d', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'd25216da-e904-447d-8bf5-84684f71c31d', 'options', 'MaybeRefOrGetter<IUseNumberFormatOptions>', false, '{}', '', 'Formatting options: locale (string | string[] | "auto"), format ("decimal" | "currency" | "percent" | "unit" | "compact" | "scientific" | "engineering"), currency, unit, notation, minimumFractionDigits, maximumFractionDigits, useGrouping, signDisplay, and more. Accepts a plain object, a ref, or a getter.', 0, false, NULL, NULL);
