INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f0045be1-d8c1-49d7-8d97-4894ff5e9230', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'e0e8b08e-af5b-4748-a685-ba8eb7c84083', 'props', 'IParallaxElementProps', true, NULL, '', 'Props of a parallax layer element. Reads `type` (PARALLAX_ELEMENT_TYPE enum), `strength` (movement intensity, default 10), and `axis` (AXIS enum, used for rotate type to constrain movement to a single axis).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0ba364e0-7fd2-45db-95cf-6ff7903befb5', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '72ef1cbc-e775-41be-8666-033f5ddad91b', 'value', 'string | null | undefined', true, NULL, '', 'The password string to evaluate. Null and undefined are treated as empty (score 0, level "weak").', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e55ebe00-cc7d-412c-8149-fb0e1cda67f0', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '8312c368-090f-4b59-a7a8-67691215e21a', 'props', 'IPositionProps', true, NULL, '', 'Props containing `position` (CSS position keyword), `top`, `bottom`, `left`, `right` (CSS length values or token references).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d48ba265-b4be-40cf-b06d-e29d204ed0c5', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '8312c368-090f-4b59-a7a8-67691215e21a', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name prefix used to build the BEM modifier class, e.g. "origam-btn" → "origam-btn--fixed".', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('cd04033c-9540-4904-88c9-2cb89c1e60f2', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'c02878b2-f2f2-4de1-b663-b942048edd93', 'props', 'IProgressTypeProps', true, NULL, '', 'Props shared by OrigamProgressLinear and OrigamProgressCircular: modelValue, max, thickness, indeterminate, striped, active, absolute, plus padding and margin props.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3fadab31-be5f-4ae5-9245-299af6a4bf93', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '7763798d-b769-4c30-b5b3-c5bd0469761d', 'props', 'T extends Record<string, any>', true, NULL, '', 'The component interface (or a plain object with the same keys) that defines the allowed prop surface. Only keys present here will be picked by filterProps.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e665592f-afd7-4672-9096-a9554cd35fa8', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '12db64f9-a257-4c72-bd5d-1ae97459173d', 'value', 'MaybeRefOrGetter<string>', true, NULL, '', 'The payload to encode: URL, text, vCard, etc. Accepts a plain string, a ref, or a getter function. Reactive — the SVG rebuilds whenever value changes.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('fddd8198-203f-4376-8e03-1de17fab90b2', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '12db64f9-a257-4c72-bd5d-1ae97459173d', 'options', 'MaybeRefOrGetter<IUseQrCodeOptions>', false, '{}', '', 'Encoding and rendering options: errorCorrectionLevel ("L" | "M" | "Q" | "H"), foreground, background, margin (module units), cornerRadius (per <rect>), and logo ({ src, size, padding, background }).', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a348d249-81b1-44c1-8bec-d683c3d01685', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '62d4637a-3d83-4362-9615-7a879b4d2594', 'callback', 'ResizeObserverCallback', false, NULL, '', 'Optional raw ResizeObserver callback. Receives the full entries array and the observer instance. Called on every resize event before contentRect is updated.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e0e893a8-aea1-4a97-a524-b568c542caa0', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '62d4637a-3d83-4362-9615-7a879b4d2594', 'box', '''content'' | ''border''', false, '''content''', '', 'Which box model dimension to capture. "content" uses entries[0].contentRect; "border" calls getBoundingClientRect() on the element for border-box dimensions including padding and border.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('85ba5f31-351a-4fd3-9f36-33871e839043', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '712889b5-a8e5-4625-8594-ecb3abeb9e88', 'props', 'IRoundedProps | Ref<boolean | number | string | TRounded | null | undefined>', true, NULL, '', 'Either the component props object or a plain Ref. Reads the `rounded` value.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('59768875-9eb4-4ce3-bfa9-d86552e48638', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '712889b5-a8e5-4625-8594-ecb3abeb9e88', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name prefix for the `{name}--rounded-*` legacy classes.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a8e7048f-af85-469d-adf5-787b38986202', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'f2aef4b9-594a-4579-a113-3915f22132a3', 'props (useLink)', 'ILinkProps & ITagProps', true, NULL, '', 'Props containing `href` (external link), `to` (vue-router location), `tag` (root element override), and `exact` (exact-active matching).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e1ba8678-8310-417f-b625-eb1035cef2e5', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'f2aef4b9-594a-4579-a113-3915f22132a3', 'attrs (useLink)', 'SetupContext[''attrs'']', true, NULL, '', 'The component attrs used to detect a click listener, which makes a non-link element behave as clickable.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('385ea8c3-b60b-452d-a3c7-173854263f52', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'f2aef4b9-594a-4579-a113-3915f22132a3', 'router (useBackButton)', 'Router | undefined', true, NULL, '', 'The Router instance. When undefined (no vue-router), only the popstate listener is registered.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5d806400-112b-4035-8429-4b535cf3a1e7', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'f2aef4b9-594a-4579-a113-3915f22132a3', 'cb (useBackButton)', '(next: NavigationGuardNext) => void', true, NULL, '', 'Guard callback called when a popstate (back) event is detected. Must call next() to allow navigation or next(false) to cancel.', 3, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0c6b6a0b-d361-4d5d-a834-58595a48d33a', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'fcaadf2a-ffb8-4869-b25c-e2c20b82e10b', 'props', 'IScrollProps', true, NULL, '', 'Props containing `scrollTarget` (CSS selector string for a custom scroll container, defaults to window) and `scrollThreshold` (pixel distance that must be crossed before scroll events activate).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b6b0a3c4-0983-4136-baa7-a18d1e03ec3a', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'fcaadf2a-ffb8-4869-b25c-e2c20b82e10b', 'args', 'IScrollArguments', false, NULL, '', 'Optional arguments bag. `canScroll: Ref<boolean>` — when provided, scroll events are ignored while canScroll is false (used by layouts that conditionally enable scrolling).', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2357992d-1fb3-4d9a-ae07-7fabd9ba2b7e', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '721b2521-3874-47a8-9726-466bb0645f51', 'link', 'IUseLink', true, NULL, '', 'The link object returned by useRouter/useLink. Exposes isLink (whether an href/to prop is present) and isActive (whether the current route matches the link target). Watched by the composable to trigger selection.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d13af64e-3b7a-4b0c-a91f-1c2349e9e8ad', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '721b2521-3874-47a8-9726-466bb0645f51', 'select', '(value: boolean, e?: Event) => void', false, NULL, '', 'The group selection callback injected by useGroup. When the link becomes active, this is called with value=true on the next tick. When undefined, the composable becomes a no-op.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('cf82803d-0e67-4466-aadc-2c19b3c3cd91', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'ecd3d09e-26c4-4f3b-abdb-148fef248eff', 'options', 'ISheetSwipeOptions', true, NULL, '', 'Configuration object. Includes el (sheet root element ref), handle (drag handle element ref), snapPoints (reactive array of TSheetSnapPoint), defaultSnap (initial snap id), disabled (Ref<boolean> to suspend gesture), and persistent (Ref<boolean> to block the closed snap).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1d6adc41-f3a1-4f9b-a2a9-6c058b880e32', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '09ef672a-2ea0-4193-8e92-78d5447885dc', 'props', 'ISizeProps', true, NULL, '', 'Component props extending ISizeProps. Reads the `size` value.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f5fd133c-6e74-416c-b641-06d202797897', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '09ef672a-2ea0-4193-8e92-78d5447885dc', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name prefix for the `{name}--size-{value}` class.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c06d9895-211f-430b-b5ae-d4d1e6cae0bc', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'd77aec13-6f47-47a9-8f6f-b66794e52dce', 'props', 'ISliderFieldProps', true, NULL, '', 'Component props. Reads min (default 0), max (default 100), and step (default 0 = no stepping). All three accept string or number — they are parsed with parseFloat internally.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('86a188b1-1e56-4f09-854f-184fee189fe2', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '4e5c1732-1d74-4502-a26c-21af0d3c3fd3', 'milliseconds', 'number', true, NULL, '', 'Total countdown duration in milliseconds. This is the initial value of time and the value it resets to on reset().', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('533dc304-7109-4d46-94d3-c9526a97e23d', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'c949db76-da62-4964-933c-23de2d89534a', 'options', 'IUseSnackbarGroupOptions', false, NULL, '', 'Optional configuration. id (string) namespaces the stack so multiple independent stacks can coexist on the same page (default: SNACKBAR_GROUP_DEFAULT_ID). max (number) caps the stack size with FIFO eviction. defaultDuration (ms) is the fallback auto-dismiss delay for items that omit their own (default: 5000 ms).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a7e61b54-c5ec-4889-9fb9-4ec5eaaa3b67', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '9b00f479-5a57-4961-b431-ab90c7de8c11', 'isActive', 'Readonly<Ref<boolean>>', true, NULL, '', 'Reactive open/closed state. When it flips to true, useStack registers the component in the global stack and computes a new z-index. When false, the entry is removed and z-index is released.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8002d531-a88c-4845-8345-cae67e8fd737', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '9b00f479-5a57-4961-b431-ab90c7de8c11', 'zIndex', 'Readonly<Ref<string | number>>', true, NULL, '', 'Base z-index to start from when no other overlays are open. Typically comes from the component props (e.g. zIndex="200").', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('78b0af4b-5169-460c-83b9-158fc60c937c', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '9b00f479-5a57-4961-b431-ab90c7de8c11', 'disableGlobalStack', 'boolean', true, NULL, '', 'When true, skips registration in GLOBAL_STACK. Use for overlays that manage their own z-index independently (e.g. nested teleport roots) and should not compete with the global stacking order.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4ec399d8-794b-4261-8c70-8549bb633fa2', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'ab7bd698-18b3-4891-b4bb-bdbdc1da0341', 'props', 'TStateEffectProps', true, NULL, '', 'Component props implementing all eight axes: IColorProps & IBgColorProps & IBorderProps & IRoundedProps & IElevationProps & IPaddingProps & IMarginProps & { gap? }. Also reads props.status when present to force the matching semantic intent (overrides color/bgColor).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('79743de4-1e4d-4dbf-b84e-fbd048e17a0a', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'ab7bd698-18b3-4891-b4bb-bdbdc1da0341', 'isHover', 'Ref<boolean> | ComputedRef<boolean>', false, 'ref(false)', '', 'Reactive hover state from useHover. When true, the composable applies the override values from hoverState for each axis.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('753d2928-be9e-4f15-81fc-37f0310c84d3', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'ab7bd698-18b3-4891-b4bb-bdbdc1da0341', 'isActive', 'Ref<boolean> | ComputedRef<boolean>', false, 'ref(false)', '', 'Reactive active/selected state from useActive. When true (and isHover is false), override values from activeState are applied. Hover takes priority when both are engaged simultaneously.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1474343c-74c1-4dd4-87ba-5e7cec9d8ef4', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'ab7bd698-18b3-4891-b4bb-bdbdc1da0341', 'hoverState', 'ComputedRef<IHoverState | undefined>', false, 'computed(() => undefined)', '', 'State config object from useHover. Contains per-axis override values (color, bgColor, border, rounded, elevation, padding, margin, gap) to apply while hovered.', 3, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b72f3e15-a219-4ac8-82c3-d046a7904ad0', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'ab7bd698-18b3-4891-b4bb-bdbdc1da0341', 'activeState', 'ComputedRef<IActiveState | undefined>', false, 'computed(() => undefined)', '', 'State config object from useActive. Same shape as IHoverState — per-axis overrides applied while the item is selected/active.', 4, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('18fa5941-c911-44ca-aad9-6deb42296bf7', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'ab7bd698-18b3-4891-b4bb-bdbdc1da0341', 'isDisabled', 'Ref<boolean> | ComputedRef<boolean>', false, 'ref(false)', '', 'When true, colorClasses is emptied (utility classes suppressed) so the disabled opacity veil is not overridden by a tokenised background.', 5, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('945ef9fc-e92a-4377-a923-b6fa56b2e3a6', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'ab7bd698-18b3-4891-b4bb-bdbdc1da0341', 'flat', 'Ref<boolean> | ComputedRef<boolean>', false, 'ref(false)', '', 'When true, elevationClasses and elevationStyles resolve to empty. Bridges the flat prop of Btn / Card without requiring a separate useElevation call.', 6, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d27641c9-c657-4e42-a881-b557aa4864e3', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '9388b289-2ca5-45b8-bffc-e500f47c9074', 'props', 'IStatusProps & IAdjacentProps', true, NULL, '', 'Component props. Reads status (TStatus: success | info | warning | error), statusIconPosition (prepend | append | both | replace), prependIcon, appendIcon, and icon. When status is set and statusIconPosition is replace, the status icon overwrites props.icon; when prepend/append/both, it fills the matching slot only if no explicit icon prop was passed.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('184351e3-1217-46ac-a3ba-322707c2d7d5', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '9388b289-2ca5-45b8-bffc-e500f47c9074', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name used to build the BEM modifier class `{name}--{status}` (e.g. origam-alert--success). Defaults to the current Vue instance name.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5106de6d-0bca-4752-a6bb-8b92444c4abd', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'db0e56c4-c4d4-482d-b2fa-85a117d81784', 'options', 'ISticky', true, NULL, '', 'Configuration object containing rootEl (template ref to the sticky element), isSticky (Ref<boolean> — feature toggle; when false the scroll listener is removed), and layoutItemStyles (ComputedRef of the layout item styles, providing the top offset imposed by the app-bar).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3a6c144e-df6f-4980-ae14-3a940526b68a', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'ca656eb3-6a92-4225-bc58-89e727734a5b', 'styles', 'ComputedRef', true, NULL, '', 'A ComputedRef returning a CSS value array or object. Accepts the same formats as Vue :style bindings (array of objects, strings, or mixed). useStyle normalises this to a flat `#id { prop: value; … }` string and feeds it to useStyleTag.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3beb937d-510e-45ee-b650-463caa381a04', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'ca656eb3-6a92-4225-bc58-89e727734a5b', 'uniq', 'string', false, NULL, '', 'Optional fixed element id. When omitted, a unique id is generated from the component name and a counter (e.g. origam-card-3). Provide a fixed id when multiple instances must share the same <style> tag (e.g. global animation keyframes).', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('04dbf862-a31f-4efb-80de-9f07ea605199', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'ca656eb3-6a92-4225-bc58-89e727734a5b', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name prefix for the generated id. Defaults to the current Vue instance name.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('dd8d40fe-12ba-433b-a211-3dd26759144e', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '6db9d2af-63bf-4b07-847d-d8ba3c654146', 'target', 'Ref<boolean | string | Element>', true, NULL, '', 'Reactive teleport destination. true → returns undefined (Vue Teleport disabled, renders in-place). false → document.body. A CSS selector string → querySelector result. An Element → used directly. Returns undefined and warns if a string selector yields no match.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('915129b9-a8e3-4e9c-a6e9-c1f5d9a8c07c', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'f8820940-2048-40d6-a8bb-a58f3eb67b6f', 'options', 'IUseTextareaRichOptions', true, NULL, '', 'Configuration object. value: () => string — getter for the initial HTML content (bound to the parent v-model). onUpdate: (html: string) => void — called with sanitised HTML on every change. onFormat: (command, value?) => void — called after each format command (lets the host open a link popover on Cmd+K). disabled: () => boolean — suppresses all commands and keyboard shortcuts when true.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0c5bd85b-6a07-4d2e-824d-dafdeed5e6ae', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'b063f525-6237-41cf-a77a-6a4a4bb2530f', 'props', 'T | Ref<TColor>', true, NULL, '', 'Either the component props object (paired with `name`) or a plain Ref<TColor>.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6ca067e5-87a5-49c3-b537-7b3f7576cefc', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'b063f525-6237-41cf-a77a-6a4a4bb2530f', 'name', 'K', false, NULL, '', 'The key to read from the props object. Typically "color". Omit when passing a plain Ref.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d8c50c38-8046-4842-b2ed-81f4144e28fb', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '606ac208-5c21-4f6e-af0c-88c05234e0e8', 'fn', '(...args: T) => R', true, NULL, '', 'The function to throttle. Called immediately on the first invocation within each window. The return value is discarded — the wrapper always returns void.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1d313d0b-e6dc-4b9c-bed0-b5f0f37bf37b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '606ac208-5c21-4f6e-af0c-88c05234e0e8', 'wait', 'number', true, NULL, '', 'Throttle window in milliseconds. No call will execute within wait ms of the previous execution.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('cc46cd42-3713-4358-a5bd-83793126d4a7', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'f569a1aa-f303-4a13-a506-34f4bf7efb0c', 'source', 'WatchSource<boolean>', true, NULL, '', 'Reactive boolean source (ref, computed, or getter). When it evaluates to true the scope is started; when false the scope is stopped.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ca694aac-ff42-4d6a-8ba3-c2830e5b2e30', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'f569a1aa-f303-4a13-a506-34f4bf7efb0c', 'fn', '(reset: () => void) => void', true, NULL, '', 'Callback run inside the new effectScope. Receives a `reset()` function that can be called from inside the scope to stop the current scope and immediately restart it — useful for subscriptions that need to re-initialise when an inner condition changes.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('bbcbdaeb-2ce0-496f-ba81-ef00edde5d3c', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '1eeb9995-78a8-40ad-a733-e7ba6a118f33', 'isActive', 'Ref<boolean>', true, NULL, '', 'Whether the drawer is currently open. The composable writes to this ref when a fling gesture settles.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d4979831-5353-4b5f-9c73-2b80e3a63b0e', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '1eeb9995-78a8-40ad-a733-e7ba6a118f33', 'isTemporary', 'Ref<boolean>', true, NULL, '', 'When true the drawer is temporary (modal overlay). The touch zone logic also activates for touches anywhere inside the element body, not only at the edge.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('dfbe25e4-18e3-4214-95d7-cc9d0c1047f6', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '1eeb9995-78a8-40ad-a733-e7ba6a118f33', 'width', 'Ref<number>', true, NULL, '', 'Pixel width (or height for top/bottom positions) of the drawer. Used to compute drag progress as a fraction in [0, 1].', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4dfe375b-5246-467d-acd1-44241556e74a', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '1eeb9995-78a8-40ad-a733-e7ba6a118f33', 'touchless', 'Ref<boolean>', true, NULL, '', 'When true all touch handling is disabled. Lets the consumer disable swipe gestures without unmounting the composable.', 3, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b9eccd43-c886-4693-8660-eb8f54132816', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '1eeb9995-78a8-40ad-a733-e7ba6a118f33', 'position', 'Ref<''left'' | ''right'' | ''top'' | ''bottom''>', true, NULL, '', 'The edge from which the drawer slides in. Determines the touch zone, coordinate axis, and transform direction.', 4, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('756bb432-eefb-4dcb-b0fe-19a7a96bf2e6', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'f6aa8a3d-1081-493b-a771-aec0739632f4', 'props', 'ITransitionProps', true, NULL, '', 'Reads `name` (CSS transition class prefix), `disabled` (bypass the transition), `group` (use TransitionGroup), `mode` (in-out / out-in), `origin` (transform-origin set on beforeEnter), `leaveAbsolute` (position the leaving element absolutely), `hideOnLeave` (display:none on leave).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('75adf0b2-62c5-4bb6-b8b4-d76613a64f60', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '47a2efb6-8407-42fd-966a-ad85fcf321f6', 'props', 'IValidationProps', true, NULL, '', 'Props read: modelValue, validationValue, rules, error, errorMessages, maxErrors, disabled, readonly, focused, validateOn, name.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('108f303f-a71c-4a85-b91c-0866f9f481e1', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '47a2efb6-8407-42fd-966a-ad85fcf321f6', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name prefix for validation CSS class names (e.g. `origam-text-field--error`).', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6b32fa15-acdf-4722-83e6-804f4063b6c9', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '47a2efb6-8407-42fd-966a-ad85fcf321f6', 'id', 'MaybeRef<string | number>', false, 'getUid()', '', 'Unique field ID used to register with the parent form. Defaults to an auto-generated UID.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4805edb0-e5c6-452d-b81b-74defeaee315', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '239e5a06-d770-4963-9422-cbece2765eb4', 'props', 'IVariantProps | Ref<TVariant | TVariantInput | string | undefined>', true, NULL, '', 'Either the component props object (reads `props.variant`) or a bare reactive ref / computed to the variant string. The composable detects which form is passed via `isRef`.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('60b0bceb-94c5-47fc-8bf8-81c07d783082', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '239e5a06-d770-4963-9422-cbece2765eb4', 'name', 'string', false, 'getCurrentInstanceName()', '', 'The BEM block prefix. Defaults to the current component name (e.g. `origam-btn`). The class produced will be `{name}--variant-{variant}`.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('503ce9d8-35ed-49c1-a80c-4a6d33666a54', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '4c8f63d7-8094-49d8-adf1-dd6eedcb08bf', 'options', 'IUseVideoPlayerOptions', false, '{}', '', 'Accepts `videoRef` (bring your own typed ref), `autoplay`, `muted`, `loop`, `preload`. All optional. Autoplay is suppressed when prefers-reduced-motion is active.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9dde9dde-6ebe-471e-a895-5826735d5b0c', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'b0e0d69d-8af2-43b7-876e-cd323d52a6d0', 'props', 'IVirtualProps', true, NULL, '', 'Reads `itemHeight` (expected row height in px, used to estimate the initial window), `height` (container height as string / number), `scrollDuration` (ms, default 300), `scrollEasing` (easing name, default easeInOutCubic).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f8e4ac74-50ee-43ff-8137-4f54e19996b9', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'b0e0d69d-8af2-43b7-876e-cd323d52a6d0', 'items', 'Ref<readonly T[]>', true, NULL, '', 'The full dataset ref. The composable slices this array to produce `computedItems`. Changing the ref triggers an offset recalculation.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0b3ef439-e2aa-47c9-81dc-1891f43a4727', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '126c4321-432d-48da-a2a7-b5a2d3b8a8ff', 'props', 'Props', true, NULL, '', 'The component props object returned by defineProps. The composable reads `props[prop]` and inspects `vm.vnode.props` to detect whether the listener is wired.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('36f960c5-e1a8-47cd-82cd-725da924092e', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '126c4321-432d-48da-a2a7-b5a2d3b8a8ff', 'prop', 'Prop', true, NULL, '', 'The prop key to observe, e.g. `"modelValue"` for a standard v-model binding.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('20f8ce2b-9e52-4e16-9429-2133d793cb63', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '126c4321-432d-48da-a2a7-b5a2d3b8a8ff', 'defaultValue', 'Props[Prop]', false, NULL, '', 'Value used to initialise the internal ref when the prop is undefined on first render.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('cd90f4f4-eac7-4fe7-a748-9ff1ae07c908', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '126c4321-432d-48da-a2a7-b5a2d3b8a8ff', 'transformIn', '(value?: Props[Prop]) => Inner', false, 'identity', '', 'Optional transform applied to the external prop value before exposing it to the component. Useful for converting a string to a number, or normalising null / undefined.', 3, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('060fbb07-16b3-446b-8d01-aac752abfcb3', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '126c4321-432d-48da-a2a7-b5a2d3b8a8ff', 'transformOut', '(value: Inner) => Props[Prop]', false, 'identity', '', 'Optional inverse transform applied before emitting `update:prop`. Pairs with transformIn to keep the internal representation separate from the public API value.', 4, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ab651579-3b35-4a54-ad15-030505526cf6', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '6168c1a1-5c18-4d9b-9da3-7ab219d7707a', 'options', 'MaybeRefOrGetter<IUseWatermarkOptions>', false, '{}', '', 'Options bag (static object, reactive ref, or getter function). Reads: `text`, `image` (URL), `opacity` (default 0.15), `angle` (degrees, default -30), `gap` (tile spacing in px, default 100), `fontSize` (px, default 16), `fontFamily`, `color`, `fontWeight`, `pointerEvents` ("none" | "auto"), `zIndex`, `antiTamper` (enable MutationObserver re-injection). Passing a ref makes patternUrl update reactively when options change.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0f88c91c-3da2-4058-ae7a-73a9115b5ac5', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'd4fb6b98-27e4-4bca-ab8b-9a5d2ab5cfe3', 'srcRef', 'Ref<string | undefined | null>', true, NULL, '', 'Reactive reference to the audio file URL. The composable watches this ref and re-triggers computation whenever the value changes. null / undefined clears the peaks array.', 0, false, NULL, NULL);
