INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('16e94578-d7ff-471a-9655-252d389b3fae', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '57411518-86e8-460d-922a-8bfcdfc2d3c1', 'playbackRates', 'ReadonlyArray<number>', '', 'primitive', false, false, '[0.5, 0.75, 1, 1.25, 1.5, 2]', 'components.media_controller.props.playback_rates.description', 'Available playback rates exposed via the config cog menu. When the array has more than 1 entry, a "Playback speed" drill-down appears.', 4, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7ca8dd6e-887d-415b-ba55-a0201dbc0ef3', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '57411518-86e8-460d-922a-8bfcdfc2d3c1', 'allowRemotePlayback', 'boolean', '', 'primitive', false, false, 'false', 'components.media_controller.props.allow_remote_playback.description', 'Enable the Cast / AirPlay button (Remote Playback API). The button only appears when this flag is true AND state.remoteAvailable is true at runtime.', 5, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('94ef96d6-a664-4691-a688-227857eb9dfa', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'f85e96b2-abf5-441d-bd63-b988f1fae4f0', 'role', 'string', '', 'primitive', false, false, 'undefined', 'components.otp_input_field.props.role.description', 'ARIA role applied to the root element.', 11, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a1952252-3314-4a6e-a501-4d864f223a13', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '57411518-86e8-460d-922a-8bfcdfc2d3c1', 'downloadable', 'boolean', '', 'primitive', false, false, 'false', 'components.media_controller.props.downloadable.description', 'Adds a "Download" row to the config cog menu when true. Requires downloadUrl to be set.', 6, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8c162132-0997-4d7f-abe4-9fe2c8e868b9', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '57411518-86e8-460d-922a-8bfcdfc2d3c1', 'downloadUrl', 'string | null', '', 'primitive', false, false, 'null', 'components.media_controller.props.download_url.description', 'URL surfaced to the consumer when the Download menu item is clicked. Supports same-origin, data: and blob: URLs natively; cross-origin URLs are routed through a fetch → blob pipeline.', 7, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('91f6f4b7-977f-4d82-b9d6-0a3c35e4fba1', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '57411518-86e8-460d-922a-8bfcdfc2d3c1', 'downloadFilename', 'string', '', 'primitive', false, false, 'undefined', 'components.media_controller.props.download_filename.description', 'Suggested filename for the downloaded file (<a download="…"> attribute).', 8, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('66878fb8-da41-481a-9b93-a61e1bd3c3fe', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '57411518-86e8-460d-922a-8bfcdfc2d3c1', 'qualityOptions', 'ReadonlyArray<TQualityOption>', '', 'primitive', false, false, '[]', 'components.media_controller.props.quality_options.description', 'Optional list of quality variants. When ≥ 2 entries are present, a "Quality" drill-down appears in the config menu. Each entry is { quality: string; label: string }.', 9, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('34142e1f-2ce2-43e2-90ab-93c62b6c1205', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '57411518-86e8-460d-922a-8bfcdfc2d3c1', 'currentQuality', 'string | null', '', 'primitive', false, false, 'null', 'components.media_controller.props.current_quality.description', 'Currently-active quality identifier displayed as the appendText in the Quality menu row.', 10, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('29933ac6-50ba-4f15-9db3-14b0bf7b3d95', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '57411518-86e8-460d-922a-8bfcdfc2d3c1', 'showPrevious', 'boolean', '', 'primitive', false, false, 'false', 'components.media_controller.props.show_previous.description', 'Show the "previous track" transport button. The parent listens to the previous emit and decides the action (skip back 10s or jump to the previous playlist track).', 11, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9d27227a-09cc-456c-a2f3-e73efe31e9d4', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '57411518-86e8-460d-922a-8bfcdfc2d3c1', 'showNext', 'boolean', '', 'primitive', false, false, 'false', 'components.media_controller.props.show_next.description', 'Show the "next track" transport button. The parent owns the action.', 12, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b1735952-0427-4dbd-a07a-74e9f78515cd', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '57411518-86e8-460d-922a-8bfcdfc2d3c1', 'showLoop', 'boolean', '', 'primitive', false, false, 'false', 'components.media_controller.props.show_loop.description', 'Show the tri-state loop button (none → all → one → none). Supports v-model:loopMode.', 13, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('99082356-9bfb-4911-b4f5-81a11517175f', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '57411518-86e8-460d-922a-8bfcdfc2d3c1', 'showShuffle', 'boolean', '', 'primitive', false, false, 'false', 'components.media_controller.props.show_shuffle.description', 'Show the shuffle toggle button. Supports v-model:shuffle.', 14, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('78314a49-7099-4b17-b0a8-3d96faebfbb2', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '57411518-86e8-460d-922a-8bfcdfc2d3c1', 'loopMode', 'TAudioLoopMode', '', 'primitive', false, false, '''none''', 'components.media_controller.props.loop_mode.description', 'Current loop mode: "none" | "all" | "one". The Controller cycles on click and emits update:loopMode; the parent applies its playlist or <audio loop> policy.', 15, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0859f664-dbcb-4cca-8044-a045177ae68b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '57411518-86e8-460d-922a-8bfcdfc2d3c1', 'shuffle', 'boolean', '', 'primitive', false, false, 'false', 'components.media_controller.props.shuffle.description', 'Current shuffle state. The Controller toggles on click and emits update:shuffle; the parent switches its next-track resolution.', 16, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('acc918c2-4965-40c1-882b-c27fe1e6136d', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'a57a7a08-2f97-4715-bfbc-b3fdbe48d368', 'modelValue', 'number', '', 'primitive', false, true, '—', 'components.media_scrubber.props.model_value.description', 'Current value between min and max. Supports v-model. The component never mutates this directly — every change surfaces via update:modelValue.', 0, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('76d35fa9-7af5-4a9a-9615-cf77cd5e0d00', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'a57a7a08-2f97-4715-bfbc-b3fdbe48d368', 'max', 'number', '', 'primitive', false, true, '—', 'components.media_scrubber.props.max.description', 'Upper bound of the value range. Required to compute the thumb position. Passing 0 or any value <= min freezes the scrubber at the start.', 1, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3c15e4d5-2bec-48de-9380-4803b1e4336b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'a57a7a08-2f97-4715-bfbc-b3fdbe48d368', 'min', 'number', '', 'primitive', false, false, '0', 'components.media_scrubber.props.min.description', 'Lower bound of the value range.', 2, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d6e84c63-221d-4c73-814f-53ea39cf97b3', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'a57a7a08-2f97-4715-bfbc-b3fdbe48d368', 'step', 'number', '', 'primitive', false, false, '0', 'components.media_scrubber.props.step.description', 'Discrete step. 0 (default) means continuous — pointer events emit the raw float; positive values snap each emission to the nearest multiple.', 3, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('82110819-6502-4cd7-8dce-5e644810c9ab', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'a57a7a08-2f97-4715-bfbc-b3fdbe48d368', 'buffered', 'number', '', 'primitive', false, false, 'undefined', 'components.media_scrubber.props.buffered.description', 'Optional buffered position (end of the browser''s media buffer). Renders the __buffer bar from min up to buffered. Pass undefined to hide the bar entirely.', 4, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('218398b8-ff13-4c63-b18c-64150e894a88', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'a57a7a08-2f97-4715-bfbc-b3fdbe48d368', 'orientation', 'TMediaScrubberOrientation', '', 'primitive', false, false, '''horizontal''', 'components.media_scrubber.props.orientation.description', 'Layout axis. horizontal = YouTube timeline shape; vertical = volume / level meter shape (top of track = max, bottom = min).', 5, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e0bf1aaf-f2cf-4d55-bf0f-d3122287dd7b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'a57a7a08-2f97-4715-bfbc-b3fdbe48d368', 'disabled', 'boolean', '', 'primitive', false, false, 'false', 'components.media_scrubber.props.disabled.description', 'Disables pointer + keyboard interaction. The element drops out of the tab order (tabindex="-1") and pointer events become no-ops.', 6, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8ccd2a70-909e-4127-bb7c-d91598ea4f3c', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'a57a7a08-2f97-4715-bfbc-b3fdbe48d368', 'showThumbOnHoverOnly', 'boolean', '', 'primitive', false, false, 'false', 'components.media_scrubber.props.show_thumb_on_hover_only.description', 'Hides the thumb at rest and reveals it on hover / focus / drag — the YouTube pattern. When false, the thumb is always visible.', 7, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('38f16100-c290-4d2f-8cb2-1c3a9ad764d9', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'a57a7a08-2f97-4715-bfbc-b3fdbe48d368', 'showHoverTooltip', 'boolean', '', 'primitive', false, false, 'false', 'components.media_scrubber.props.show_hover_tooltip.description', 'Shows a tooltip above the cursor (horizontal only) reflecting the hovered value. Content can be overridden via the #tooltip slot.', 8, false, NULL, NULL);
