INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('648fc03a-6f98-46c3-91da-ad8d6f394f07', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'a57a7a08-2f97-4715-bfbc-b3fdbe48d368', 'ariaLabel', 'string', '', 'primitive', false, true, '—', 'components.media_scrubber.props.aria_label.description', 'Required accessibility label read by screen readers when the scrubber gains focus. Always pass a translated string here.', 10, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('590126ba-09b1-41df-8d30-e0f675fa444c', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'a57a7a08-2f97-4715-bfbc-b3fdbe48d368', 'ariaValueText', 'string', '', 'primitive', false, false, 'undefined', 'components.media_scrubber.props.aria_value_text.description', 'Optional human-readable representation of the current value (e.g. "1:23" for a timestamp, "45 %" for a volume level). Mapped to aria-valuetext.', 11, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a57f53a6-a8d1-4713-bac3-9ec3e55d406c', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'a57a7a08-2f97-4715-bfbc-b3fdbe48d368', 'color', 'TColor', 'color', 'type', false, false, 'undefined', 'components.media_scrubber.props.color.description', 'Intent or custom color applied to the track background via useBackgroundColor. Utility class emitted for tokenised values; inline style for custom colors.', 12, false, NULL, NULL);
