INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('36efc882-65f0-4f6a-976d-378f3a7ea56a', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:01:01.3203+00', '4de51029-19c0-4432-aaf1-9288b4c238eb', 'disabled', 'boolean', NULL, NULL, true, NULL, 'false', NULL, 'Disables pointer + keyboard interaction. The element drops out of the tab order and pointer events become no-ops.', 6, false, NULL, NULL);
