INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a744ff9c-caf9-4386-9a68-00bb8f0800f8', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:01:01.3203+00', '592b046d-5add-41d3-838c-683b63ec9805', 'format', 'TNumberFormatFormat', NULL, NULL, true, NULL, NULL, NULL, 'High-level format dialect — see `TNumberFormatFormat`.', 1, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('06b6855e-016b-408b-aabe-f350b9030970', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:01:01.3203+00', '592b046d-5add-41d3-838c-683b63ec9805', 'locale', 'TNumberFormatLocale', NULL, NULL, true, NULL, NULL, NULL, 'BCP-47 locale tag (or array, for fallback chains). The literal
