INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('67f535c9-7b22-4757-88af-3c88c1c7b952', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:01:01.3203+00', '592b046d-5add-41d3-838c-683b63ec9805', 'currencyDisplay', 'TNumberFormatCurrencyDisplay', NULL, NULL, true, NULL, NULL, NULL, 'Currency-symbol rendering — `''symbol''` (`$`), `''narrowSymbol''`
