INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('024d6cc7-948b-4347-a524-eb4fca206ab4', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:01:01.3203+00', '592b046d-5add-41d3-838c-683b63ec9805', 'unit', 'string', NULL, NULL, true, NULL, NULL, NULL, 'Sanctioned unit identifier (e.g. `''kilometer-per-hour''`,
