INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d31969a6-60d2-4ac0-a821-e06cfd455255', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:01:01.3203+00', '592b046d-5add-41d3-838c-683b63ec9805', 'notation', 'TNumberFormatNotation', NULL, NULL, true, NULL, NULL, NULL, 'Raw `notation` override. Auto-set to `''compact''` when `format ===
