INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('06820783-1e04-4867-87ca-f21f1c9b4677', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:01:01.3203+00', '71688db5-47ca-48a8-b5f9-9210724f8c51', 'perPage', 'number | string', NULL, NULL, true, NULL, NULL, NULL, 'Number of items rendered on a single page. Used together with
