INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('cec64a8f-91ee-45bf-9360-0b08476172db', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:01:01.3203+00', '6eaf0bc1-8e30-41dc-8bcb-3da13b734469', 'speed', 'number', NULL, NULL, true, NULL, NULL, NULL, 'Parallax speed multiplier for this layer.
 - `0`   → fixed (no movement, sticks to host)
 - `0.5` → half the scroll speed (background — far)
 - `1`   → moves with the scroll (neutral)
 - `>1`  → faster than the scroll (foreground — near)

Negative values reverse the direction.', 0, false, NULL, NULL);
