INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6df7286c-e14a-4a5c-8c0b-08beeeb40df6', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:01:01.3203+00', '9fdf3a03-997b-4535-8d74-deb2dfdd62fc', 'easing', 'TParallaxEasing | string', NULL, NULL, true, NULL, NULL, NULL, 'Easing curve. Accepts a TParallaxEasing keyword (linear | ease-out | spring) or any raw CSS timing-function string.', 1, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('05d0dbca-d0b7-4ae5-9c07-f58815db9bc5', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:01:01.3203+00', '9fdf3a03-997b-4535-8d74-deb2dfdd62fc', 'perspective', 'number', NULL, NULL, true, NULL, NULL, NULL, 'CSS perspective depth (px) applied to the parallax container for 3D transform effects.', 2, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4fa0b8c6-086f-4780-9e9c-d41b70711d8b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:01:01.3203+00', '9fdf3a03-997b-4535-8d74-deb2dfdd62fc', 'event', 'TParallaxEvent', NULL, NULL, true, NULL, NULL, NULL, 'Event type that drives the parallax — scroll, move (mouse), or similar. Controls which input is read.', 3, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9018de7a-f735-48d1-9087-d59914085173', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:01:01.3203+00', '9fdf3a03-997b-4535-8d74-deb2dfdd62fc', 'active', 'boolean', NULL, NULL, true, NULL, NULL, NULL, 'Freezes the mouse-driven mode when false. Distinct from `disabled` which stops all effects.', 4, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('97593e6e-5f47-41cc-832c-ceee73ffe655', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:01:01.3203+00', '9fdf3a03-997b-4535-8d74-deb2dfdd62fc', 'duration', 'number', NULL, NULL, true, NULL, NULL, NULL, 'Transition duration (ms) for the parallax interpolation. Replaces the deprecated `animationDuration`.', 5, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6a3114d6-a28f-4e25-b11c-9f06b6930d57', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:01:01.3203+00', '9fdf3a03-997b-4535-8d74-deb2dfdd62fc', 'direction', 'TParallaxDirection', NULL, NULL, true, NULL, NULL, NULL, 'Direction of the parallax effect — "vertical" (translateY), "horizontal" (translateX), or "both" (2D on mouse move).', 6, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1ee7c7ca-c2f9-4664-8abf-1308b1c41ea6', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:01:01.3203+00', '9fdf3a03-997b-4535-8d74-deb2dfdd62fc', 'speed', 'number', NULL, NULL, true, NULL, NULL, NULL, 'Global speed multiplier in single-layer mode. Default 0.5. Equivalent to wrapping slot in a single layer with this speed.', 7, false, NULL, NULL);
