INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1354df24-670c-40cd-a663-787cc7804f23', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:01:01.3203+00', '9fdf3a03-997b-4535-8d74-deb2dfdd62fc', 'threshold', 'number', NULL, NULL, true, NULL, NULL, NULL, 'Proportion (0→1) of host visible in viewport before the effect activates. 0 = starts immediately at viewport edge, 0.3 = waits until 30% visible.', 9, false, NULL, NULL);
