INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('53531f82-eb8c-4a3c-b739-e352e669cbbd', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:01:01.3203+00', 'b329b73e-1615-4e9c-bea7-11aa07387aa3', 'label', 'string', NULL, NULL, true, NULL, NULL, NULL, 'Accessible aria-label for the progress bar. Defaults to "Loading" when omitted.', 7, false, NULL, NULL);
