INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f36828cf-742c-4df4-aa7a-6916aa853eb2', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:01:01.3203+00', 'b5d36afa-0a16-4c80-b2af-c4a0fb9d94c8', 'value', 'string', NULL, NULL, false, NULL, NULL, NULL, 'Text or URL encoded into the QR matrix. UTF-8 is supported via the underlying qrcode-generator Byte mode.', 0, false, NULL, NULL);
