INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('78af14a2-346c-4287-9bc5-e1270d599127', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:01:01.3203+00', 'b5d36afa-0a16-4c80-b2af-c4a0fb9d94c8', 'qrCodeProps', 'IQrCodeOptions', NULL, NULL, true, NULL, NULL, NULL, 'Per-matrix overrides (color, bgColor, rounded) applied to the SVG internals, not the wrapper.', 2, false, NULL, NULL);
