INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('75582c7a-fedc-4aec-8b54-19c45ccd5461', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:01:01.3203+00', 'ba4087bd-e03c-4e5d-bfab-6ad0abe7edd9', 'name', 'string', NULL, NULL, true, NULL, NULL, NULL, 'Brand name. When set, the injected variables are scoped to
`[data-theme="<name>"]` instead of `:root`, so the theme activates only
when `data-theme` matches (set it via `useTheme().setTheme(name)`).', 0, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('058a22c6-9b77-4f76-a17b-bff4dfcd7735', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:01:01.3203+00', 'ba4087bd-e03c-4e5d-bfab-6ad0abe7edd9', 'mode', 'TMode', NULL, NULL, true, NULL, NULL, NULL, 'Color mode this variable block applies to. When set alongside `name`,
the selector becomes `[data-theme="<name>"][data-mode="<mode>"]`. When
set without `name`, it becomes `[data-mode="<mode>"]`.', 1, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c737968c-2e69-4203-bf4f-3b5ed243600a', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:01:01.3203+00', 'ba4087bd-e03c-4e5d-bfab-6ad0abe7edd9', 'label', 'string', NULL, NULL, true, NULL, NULL, NULL, 'Human-readable brand label for UI (e.g. a theme switcher). Falls back to
`name` when absent. Surfaced through `useInstalledThemes()`.', 2, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d8d7ac47-6a6b-43a4-90fa-11e248a6035f', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:01:01.3203+00', 'ba4087bd-e03c-4e5d-bfab-6ad0abe7edd9', 'description', 'string', NULL, NULL, true, NULL, NULL, NULL, 'Short brand description for UI (e.g. a switcher subtitle). Surfaced
through `useInstalledThemes()`.', 3, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b584d9ce-0115-43e8-9c5f-c6d50221b9c1', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:01:01.3203+00', 'ba4087bd-e03c-4e5d-bfab-6ad0abe7edd9', 'swatch', 'string', NULL, NULL, true, NULL, NULL, NULL, 'CSS background value for a brand swatch preview (a solid color or a
`linear-gradient(...)`). Surfaced through `useInstalledThemes()` so a
switcher can render a preview without a hard-coded metadata map.', 4, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('20dcef98-f5b9-4015-b2cf-9c3d32e10376', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:01:01.3203+00', 'ba4087bd-e03c-4e5d-bfab-6ad0abe7edd9', 'vars', 'IThemeVars', NULL, NULL, true, NULL, NULL, NULL, 'THE token-configuration bucket — the normal way to author a theme''s
design tokens. Nested JSON keyed by token GROUP; each group''s tree
resolves to its `--origam-*` namespace via the shared naming grammar
(see `IThemeVars`):
  - `color`   → `--origam-color-*`   (`color.surface.default`, `color.action.primary.bg`, …)
  - `rounded` → `--origam-radius-*`  (`rounded.md`, `rounded.lg`, …)
  - `border`  → `--origam-border-*`  (`border.width.thin`, …)
  - `typo`    → `--origam-font-*`    (`typo.family.sans`, `typo.size.md`, …)
  - `shadow`  → `--origam-shadow-*`  (`shadow.md`, …)
  - `spacing` → `--origam-space-*`   (`spacing.4`, …)
  - `motion`  → `--origam-motion-*`  (`motion.duration.fast`, …)

A color leaf accepts any CSS color OR a gradient (no dedicated gradient group).', 5, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d2331dc2-d03d-446d-9b79-9896c8dbe6bc', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:01:01.3203+00', 'ba4087bd-e03c-4e5d-bfab-6ad0abe7edd9', 'cssVars', 'TThemeVars', NULL, NULL, true, NULL, NULL, NULL, 'ESCAPE HATCH — pre-resolved raw `--origam-*` custom-property map. Keys
with or without the leading `--` are accepted. Use ONLY for a raw var
that has no group slot in `vars`. Wins over `vars` on key collision.

  cssVars: { ''--origam-some-unmapped-var'': ''...'' }', 6, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9df470d9-fa3f-46c3-900c-55f76ce03ad3', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:01:01.3203+00', 'ba4087bd-e03c-4e5d-bfab-6ad0abe7edd9', 'components', 'IDefault', NULL, NULL, true, NULL, NULL, NULL, NULL, 7, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3b45e4ee-5e7d-4a2c-aac7-982bec0e8bc8', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:01:01.3203+00', '03ffbd40-a64b-4848-85cf-d4590c7a3901', 'side', '''start'' | ''end'' | ''alternating''', NULL, NULL, false, NULL, NULL, NULL, 'Layout side for item content: left of the dot (start), right of the dot (end), or alternating.', 0, false, NULL, NULL);
