INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3bb1e42e-0470-4678-bb83-3d0df3d4c9f5', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '64f43b9d-c41e-419b-8592-337aecb337cc', 'activatorEl', 'Ref<HTMLElement | undefined>', '', 'The resolved activator DOM element. Updated on each user interaction event so the overlay can position itself relative to the correct element.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('30e222d7-5ea2-43a7-809a-dd03bd7e9daf', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '64f43b9d-c41e-419b-8592-337aecb337cc', 'activatorRef', 'Ref<HTMLElement | undefined>', '', 'Template ref for a statically rendered activator child. Assign to the activator element via v-bind to let the composable resolve it automatically on mount.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1fb2ac19-00ec-4c32-bfc0-1a2b98abc0e2', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '64f43b9d-c41e-419b-8592-337aecb337cc', 'target', 'ComputedRef<HTMLElement | [x: number, y: number] | undefined>', '', 'Resolved positioning target. Returns cursor coordinates when target="cursor" is set, the element bound to targetRef when provided, or falls back to the activatorEl.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b42523e2-06eb-4862-9730-5134c81704f0', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '64f43b9d-c41e-419b-8592-337aecb337cc', 'targetEl', 'ComputedRef<HTMLElement | undefined>', '', 'Target as a plain HTMLElement (undefined when target is a coordinate pair). Useful for anchor-positioning calculations that require an element.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('fb2aa288-613d-463c-bfef-601f4292db48', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '64f43b9d-c41e-419b-8592-337aecb337cc', 'targetRef', 'Ref<HTMLElement | undefined>', '', 'Template ref for an explicit positioning target element, independent from the activator element.', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0865abc7-ab34-4089-9269-a7b3fa4d2ec6', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '64f43b9d-c41e-419b-8592-337aecb337cc', 'activatorEvents', 'ComputedRef<Partial<Record<string, EventListener>>>', '', 'Event listeners to spread on the activator element via v-bind. Only includes listeners relevant to the active open strategy (onClick, onMouseenter/leave, onFocus/Blur, onContextmenu).', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6075b93e-38a5-4979-a436-d0261eac761b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '64f43b9d-c41e-419b-8592-337aecb337cc', 'contentEvents', 'ComputedRef<Record<string, EventListener>>', '', 'Event listeners to spread on the overlay content panel. Handles hover-sustain (keep open while cursor is inside the content), focus-in/out relay, and closeOnContentClick.', 6, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('21e79d31-2088-410b-8819-6be1007ec1f7', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '64f43b9d-c41e-419b-8592-337aecb337cc', 'scrimEvents', 'ComputedRef<Record<string, EventListener>>', '', 'Event listeners for the backdrop scrim element. Sustains hover-open when the cursor moves from the activator to the scrim before reaching the content.', 7, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('bd418b9b-6023-4489-a1b7-6e7bb72f7848', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '7a11802d-9786-4adb-a342-6ffdf9d3a8d9', 'isActive', 'ComputedRef<boolean>', '', 'Derived active state. True when forced, when the boolean prop is true, or when the internal toggle is on.', 0, false, NULL, NULL);
