INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ccdc67d5-a800-4913-b381-2b2d5a7e5026', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '5e18b077-3b2e-448e-8a74-ef79449760a2', 'allSelected', 'ComputedRef<boolean>', '', 'True when all eligible items (non-disabled) are selected according to the active strategy.', 6, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5bbf6e2b-f802-498f-bfeb-f4e64e96ed0c', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '5e18b077-3b2e-448e-8a74-ef79449760a2', 'showSelectAll', 'ComputedRef<boolean>', '', 'Whether the select-all checkbox should be visible. Always false for the single select strategy.', 7, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3e8ec0b2-a391-41d2-94f6-22665d186635', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'ecd3d09e-26c4-4f3b-abdb-148fef248eff', 'currentSnap', 'Ref<TSheetSnapId>', '', 'The id of the currently active snap point. Writable — programmatically call snapTo() or assign directly. Kept in sync with options.defaultSnap via a watcher.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('51750459-afe0-488e-85fd-2ffbf282e4f8', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'ecd3d09e-26c4-4f3b-abdb-148fef248eff', 'dragOffset', 'ShallowRef<number>', '', 'Live pixel offset from the baseline snap height during an active drag. Positive = sheet growing (finger moving up). Resets to 0 on pointer release. Bind to a CSS translateY to achieve 1:1 finger tracking.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7d619bf0-77f8-4b01-866e-7dafb231b2ea', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'ecd3d09e-26c4-4f3b-abdb-148fef248eff', 'isDragging', 'ShallowRef<boolean>', '', 'True while a pointer is captured by the handle. Use it to suppress the sheet transition (transition: none) so the user sees immediate 1:1 tracking instead of the animated snap.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('acf377bc-d585-413e-aeec-a981df63136d', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'ecd3d09e-26c4-4f3b-abdb-148fef248eff', 'snapTo', '(id: TSheetSnapId) => void', '', 'Programmatically move to a named snap point. Respects the persistent constraint (cannot snap to closed when persistent=true). Resets dragOffset to 0.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4aaf7d90-7afe-497b-a595-32c881e69b3d', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'ecd3d09e-26c4-4f3b-abdb-148fef248eff', 'dismiss', '() => void', '', 'Convenience wrapper for snapTo("closed"). Blocked when persistent=true (falls back to the lowest non-zero snap).', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2a760598-ff6c-4273-85d5-96860c92aa1b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'ecd3d09e-26c4-4f3b-abdb-148fef248eff', 'currentSnapHeight', 'ComputedRef<number>', '', 'Resolved pixel height of the current snap point. SSR-safe (returns 0 when window is absent). Used to compute the sheet height style: currentSnapHeight + dragOffset.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2d0cb48e-c81e-4cf5-9708-9ce1c6418649', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '09ef672a-2ea0-4193-8e92-78d5447885dc', 'sizeClasses', 'ComputedRef<string[]>', '', 'Component-local BEM modifier class (e.g. "origam-btn--size-small") plus the typographic utility class (e.g. "origam--text-sm") bridging the legacy to modern taxonomy.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('62cda288-87c1-4ac3-a300-e69886bffa7e', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '09ef672a-2ea0-4193-8e92-78d5447885dc', 'sizeStyles', 'ComputedRef<string[]>', '', 'Inline width and height declarations for custom numeric or CSS-length sizes (when the value is not a named preset).', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9157db72-6ee0-4f41-aa0a-0cd1da5a2341', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'd77aec13-6f47-47a9-8f6f-b66794e52dce', 'min', 'ComputedRef<number>', '', 'Parsed minimum value. Defaults to 0 when props.min is undefined or null.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f280b35e-56eb-447c-9a86-3f5d6aa190db', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'd77aec13-6f47-47a9-8f6f-b66794e52dce', 'max', 'ComputedRef<number>', '', 'Parsed maximum value. Defaults to 100 when props.max is undefined or null.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('46e73537-0fb4-430f-b34e-1837d1d40b31', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'd77aec13-6f47-47a9-8f6f-b66794e52dce', 'step', 'ComputedRef<number>', '', 'Parsed step value. 0 means no stepping (any value between min and max is valid). Positive values define the snap grid.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6c03147c-2770-4b6f-8dc4-d5a0ce2d4ade', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'd77aec13-6f47-47a9-8f6f-b66794e52dce', 'decimals', 'ComputedRef<number>', '', 'Number of decimal places to preserve in roundValue output. Derived from max(getDecimals(step), getDecimals(min)) to match the precision implied by the step grid.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6f0580ba-85a6-40e4-ba1e-a4705dcf1069', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'd77aec13-6f47-47a9-8f6f-b66794e52dce', 'roundValue', '(value: string | number) => number', '', 'Snap a raw value to the nearest valid step, clamped to [min, max]. Handles the min-offset edge case so that a step=5 min=3 grid snaps to 3, 8, 13, … rather than 0, 5, 10, ….', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('31e9c1d0-1b14-476b-8c55-2b18e2d3ca05', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '4e5c1732-1d74-4502-a26c-21af0d3c3fd3', 'time', 'ShallowRef<number>', '', 'Remaining milliseconds. Starts at the initial milliseconds value, decrements on each tick, and bottoms out at 0. Bind to a progress bar width to visualise the countdown.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('fd97883f-4ef4-4bb2-b8b3-f3e79e18abf7', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '4e5c1732-1d74-4502-a26c-21af0d3c3fd3', 'clear', '() => void', '', 'Stops the interval without resetting time. Use to pause the countdown (e.g. while the user is hovering the snackbar).', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4186d78e-5e10-4673-92fa-2402ee27377d', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '4e5c1732-1d74-4502-a26c-21af0d3c3fd3', 'reset', '() => void', '', 'Clears the interval and resets time to the initial milliseconds value on the next tick. Use when the snackbar content changes and the countdown should restart.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e2178764-169f-496c-ad40-4012457d9559', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '4e5c1732-1d74-4502-a26c-21af0d3c3fd3', 'start', '(el?: HTMLElement) => void', '', 'Start (or resume) the countdown. Reads the CSS transitionDuration of el to synchronise tick frequency with the progress bar animation. Falls back to 200 ms when no element is provided or no transition is set. Clears any existing interval before starting.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9c14a06e-84f9-44cd-aa1d-feaefed0a933', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'c949db76-da62-4964-933c-23de2d89534a', 'items', 'Readonly<Ref<ReadonlyArray<ISnackbarGroupItem>>>', '', 'Reactive read-only snapshot of the current stack. Mutate only through notify / dismiss / dismissAll — direct writes are blocked at the TypeScript level.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('163c36b3-5887-4a38-9cfc-41844239e246', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'c949db76-da62-4964-933c-23de2d89534a', 'notify', '(opts: ISnackbarGroupItemOptions) => string', '', 'Push a new item onto the stack. Accepts ISnackbarGroupItemOptions (message, variant, icon, duration, onDismiss callback…). Returns the generated item id so the caller can dismiss it early.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('05daaaaa-0e23-41d0-8c9c-16a4d8936d88', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'c949db76-da62-4964-933c-23de2d89534a', 'dismiss', '(itemId: string) => void', '', 'Remove the item with the given id from the stack, cancel its auto-dismiss timer, and invoke its onDismiss callback if any.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('52c5b53d-3607-4bc0-a541-5aa62e2a378d', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'c949db76-da62-4964-933c-23de2d89534a', 'dismissAll', '() => void', '', 'Dismiss every item in the stack in one call. Iterates a snapshot of the ids so mid-loop mutations are safe.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8f9711d7-335d-4ba7-95b0-6cb39cbd072f', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '5e7dac18-cad1-4cbc-b156-be59a6ee436b', 'sortBy', 'Ref<Array<IDataTableSortItem>>', '', 'Reactive array of active sort descriptors, each with a key (column key) and an order (asc | desc). Driven by useVModel against the host table props.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0590e6ea-57d9-4e4b-918e-a698618ab0a0', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '5e7dac18-cad1-4cbc-b156-be59a6ee436b', 'toggleSort', '(column: IInternalDataTableHeader) => void', '', 'Cycle the sort state for a column: none → asc → desc → none (or asc when mustSort=true). Respects multiSort — when false, replaces the entire sortBy array with a single entry.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a2575785-1500-4c45-ac16-68827199fc32', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '5e7dac18-cad1-4cbc-b156-be59a6ee436b', 'isSorted', '(column: IInternalDataTableHeader) => boolean', '', 'Returns true when the column has an active sort entry in sortBy. Used by header cells to show the sort icon.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1fdc0772-1a35-4725-8cd1-5414d17247c2', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '2c5c2a3e-215c-4dc0-8aa0-e8ad4ae01ab1', 'ssrBootStyles', 'ComputedRef<CSSProperties | []>', '', 'An object `{ transition: "none !important" }` when the component has not yet booted, or an empty array after the first animation frame. Spread onto the root element via :style to suppress hydration-flash transitions.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2425c458-e59a-453f-a95b-0ad93b8fff35', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '2c5c2a3e-215c-4dc0-8aa0-e8ad4ae01ab1', 'isBooted', 'Readonly<ShallowRef<boolean>>', '', 'False on the server and during the first rAF after mount, true thereafter. Useful as a guard before running DOM-dependent logic that assumes the component is fully hydrated.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6176fd2e-a9e5-465d-8cc6-a7623508d13c', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'd0797bec-f4ae-4f25-a9ae-84a449558c73', NULL, 'number', 'utils.detail.apc_acontrast.returns', 'Signed APCA contrast value. Absolute value >= 45 is the recommended minimum for body text.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('263c3431-3097-4fc8-9d1d-e51e0e743ec6', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '9b00f479-5a57-4961-b431-ab90c7de8c11', 'globalTop', 'Readonly<ShallowRef<boolean>>', '', 'True when this component is the last entry in GLOBAL_STACK (topmost overlay on the page). Updated asynchronously via setTimeout to avoid synchronous circular reads during stack registration.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a8d246ea-fa98-45dd-a0ad-a7cdbbcd9247', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '9b00f479-5a57-4961-b431-ab90c7de8c11', 'localTop', 'ComputedRef<boolean>', '', 'True when this overlay has no active child overlays (nothing opened on top of it within its own sub-tree). Used to decide whether clicks on the backdrop should close this overlay.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('cdd43efd-6f8b-433d-9183-c65774b4842e', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '9b00f479-5a57-4961-b431-ab90c7de8c11', 'stackStyles', 'ComputedRef<{ zIndex: number }>', '', 'Style object containing the computed zIndex. Spread onto the overlay root element so it automatically rises above the previous topmost overlay.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c2e5391a-9cc4-475a-bbd9-b6d400e91bc1', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'ab7bd698-18b3-4891-b4bb-bdbdc1da0341', 'colorClasses / colorStyles', 'ComputedRef<string[]>', '', 'Tokenised intent values emit a utility class (origam--bg-primary); custom CSS colors emit an inline style. Both are empty when disabled/hover/active is true (state-inline path takes over).', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('72c3c2a7-dfba-48c1-9fb9-0cd70e350d8e', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'ab7bd698-18b3-4891-b4bb-bdbdc1da0341', 'borderClasses / borderStyles', 'ComputedRef<string[]>', '', 'Delegated to useBorder with a reactive proxy that swaps to hoverState/activeState.border when the state is engaged.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f00f3d46-d9c2-42e0-adb7-a0f13fc711e0', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'ab7bd698-18b3-4891-b4bb-bdbdc1da0341', 'roundedClasses / roundedStyles', 'ComputedRef<string[]>', '', 'Delegated to useRounded. State-aware: applies hoverState/activeState.rounded when engaged.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ac7a4299-40bb-455c-98b9-339362eac00a', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'ab7bd698-18b3-4891-b4bb-bdbdc1da0341', 'elevationClasses / elevationStyles', 'ComputedRef<string[]>', '', 'Delegated to useElevation. Cleared when flat=true. State-aware via the pickEffective resolver.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('61739ae5-cd03-474b-bf66-81a35ad476aa', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'ab7bd698-18b3-4891-b4bb-bdbdc1da0341', 'paddingClasses / paddingStyles', 'ComputedRef<string[]>', '', 'Delegated to usePadding via a reactive getter proxy to preserve dependency tracking across state swaps.', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6348b91e-8c96-4a52-b8be-1a0a9c56f788', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'ab7bd698-18b3-4891-b4bb-bdbdc1da0341', 'marginClasses / marginStyles', 'ComputedRef<string[]>', '', 'Delegated to useMargin via a reactive getter proxy.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('bdcf0416-2ebd-4134-ae20-4710fdcce7c3', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'ab7bd698-18b3-4891-b4bb-bdbdc1da0341', 'gapClasses / gapStyles', 'ComputedRef<string[]>', '', 'Gap has no dedicated composable. Emits an inline style (gap: Npx or gap: <value>) when a gap override is present. gapClasses is always empty.', 6, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('57385c96-7696-4087-a374-44dbf7896f26', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '9388b289-2ca5-45b8-bffc-e500f47c9074', 'icon', 'ComputedRef<string | undefined>', '', 'Resolved center/replace icon. Returns the status icon when statusIconPosition="replace" and no explicit props.icon was provided, otherwise passes through props.icon.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3af73cb2-d5e7-4f9a-abda-c6c24185059f', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '9388b289-2ca5-45b8-bffc-e500f47c9074', 'prependIcon', 'ComputedRef<string | undefined>', '', 'Resolved prepend-slot icon. Injects the status icon when statusIconPosition is prepend or both and props.prependIcon is unset.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('353e0df2-3557-414d-9895-80cc14353dcb', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '9388b289-2ca5-45b8-bffc-e500f47c9074', 'appendIcon', 'ComputedRef<string | undefined>', '', 'Resolved append-slot icon. Injects the status icon when statusIconPosition is append or both and props.appendIcon is unset.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ea62461a-6072-45fb-8a0d-dbbc9aaf0bd7', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '9388b289-2ca5-45b8-bffc-e500f47c9074', 'statusClasses', 'ComputedRef<string[]>', '', 'Array containing `{name}--{status}` when a status is set, empty otherwise. Bind to the root element for SCSS state selectors.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('cbd58ddc-d7e5-432a-a751-abee5df251cd', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '9388b289-2ca5-45b8-bffc-e500f47c9074', 'statusIntent', 'ComputedRef<TColor | undefined>', '', 'The resolved TColor intent for the current status (success→success, info→info, warning→warning, error→danger). Undefined when no status is set. Consumed by useStateEffect to force the semantic surface color.', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1be869e6-1472-428b-9ebd-0cf760a9fd7e', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'db0e56c4-c4d4-482d-b2fa-85a117d81784', 'isStuck', 'ShallowRef<boolean | "top" | "bottom">', '', 'Current stuck state. "top" = anchored at the top of the viewport (sidebar shorter than viewport or scrolled to top), "bottom" = anchored at the bottom edge, true = stuck mid-page (sidebar taller than viewport, user scrolled past the top edge), false = not sticky (isSticky prop is false).', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5029cda9-178c-4738-bc50-aafb4780ae61', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'db0e56c4-c4d4-482d-b2fa-85a117d81784', 'stickyStyles', 'ComputedRef<Array<CSSProperties | undefined>>', '', 'Two-element style array to spread on the element. The first resets top/bottom/height when isSticky is enabled. The second applies the computed positional offset: the layoutItem top when not yet stuck, or the scrolled stuckPosition when stuck mid-page or at the bottom.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('45e37cd2-f108-419c-94d6-b6a68509d244', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'ca656eb3-6a92-4225-bc58-89e727734a5b', 'id', 'ComputedRef<string>', '', 'The element id used as the CSS scope selector (#id). Apply this id to the root element of the component so the injected styles target only this instance.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9ca21287-bd79-4fb6-8c0e-195d06691f4f', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'ca656eb3-6a92-4225-bc58-89e727734a5b', 'css', 'ShallowRef<string>', '', 'The current generated CSS string. Reactive — updates whenever the styles ComputedRef changes.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4ce256d8-8946-4b7e-b0f0-94058526c261', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'ca656eb3-6a92-4225-bc58-89e727734a5b', 'load / unload', '() => void', '', 'Manually control style tag injection. Normally called automatically on mount / scope dispose. Call load() to re-inject after an explicit unload().', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('14f0a258-b38f-4d1e-9a6e-1ba54df55abf', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'ca656eb3-6a92-4225-bc58-89e727734a5b', 'isLoaded', 'Readonly<ShallowRef<boolean>>', '', 'True when the <style> tag is currently present in document.head.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3f015de7-0054-4f4b-bfad-0b69cd18989b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '6db9d2af-63bf-4b07-847d-d8ba3c654146', 'teleportTarget', 'ComputedRef<Element | undefined>', '', 'The resolved .origam-overlay-container element inside the target, or undefined when teleport is disabled (target=true) or the app is running on the server (SSR). Pass directly to <Teleport :to="teleportTarget">.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b76417aa-8de0-4081-b347-41f9b664aa2a', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'f8820940-2048-40d6-a8bb-a58f3eb67b6f', 'hostRef', 'Ref<HTMLElement | undefined>', '', 'Template ref to assign to the contenteditable element. The composable uses it to read and write innerHTML, attach the selectionchange listener, and focus the element before applying a format command.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('36dd1300-88aa-40fa-b4f2-6b316794f06b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'f8820940-2048-40d6-a8bb-a58f3eb67b6f', 'active', 'ITextareaRichActiveState', '', 'Reactive object tracking the formatting state at the current caret position. Properties: bold, italic, underline, code, link (booleans), listBullet, listOrdered (booleans), heading (0 | 1 | 2 | 3). Bind to toolbar button :active props.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8e000047-3c2e-40cd-bc45-6820114bb79a', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'f8820940-2048-40d6-a8bb-a58f3eb67b6f', 'format', '(command: TTextareaToolbarCommand, value?: string) => void', '', 'Apply a formatting command. Delegates to document.execCommand for bold, italic, underline, lists, and headings. Handles link creation (value = URL) and inline code toggling (insertHTML). Calls onFormat and onUpdate after every change.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('69daafe4-a55b-439d-9358-b9a148fbe6db', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'f8820940-2048-40d6-a8bb-a58f3eb67b6f', 'isFormatActive', '(command: TTextareaToolbarCommand) => boolean', '', 'Returns whether the given command is active at the current caret position. Reads from the reactive active object — a convenience wrapper for toolbar binding.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('03ae9372-6aaf-45b7-b9b5-fb7919c762ca', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'f8820940-2048-40d6-a8bb-a58f3eb67b6f', 'setValue', '(html: string) => void', '', 'Imperatively update the contenteditable innerHTML with sanitised HTML. No-ops when hostRef is unset or when the content is already identical (avoids cursor jump).', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('817e72c9-0e8b-45d1-8923-36418acf55a2', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'f8820940-2048-40d6-a8bb-a58f3eb67b6f', 'onInput / onKeydown / onPaste', '(event) => void', '', 'Event handlers to bind on the host element. onInput emits sanitised HTML. onKeydown intercepts Cmd/Ctrl+B/I/U/E/K and Cmd+Shift+7/8 for list shortcuts. onPaste strips HTML to sanitised form (or escapes plain text) before inserting.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('981cfab3-c6c4-4cc1-98e7-666008096226', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'b063f525-6237-41cf-a77a-6a4a4bb2530f', 'textColorClasses', 'ComputedRef<string[]>', '', 'Utility class names (e.g. ["origam--color-primary"]) to bind via :class.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e45a3128-d847-4a9d-9024-d99cbbc6147b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'b063f525-6237-41cf-a77a-6a4a4bb2530f', 'textColorStyles', 'ComputedRef<string[]>', '', 'Inline CSS declarations (e.g. ["color: #6d28d9"]) to bind via :style. For gradients, includes background-image + background-clip: text.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('959f2594-23a6-4fb1-afb3-83449b759750', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'c09141c1-9b1e-4e51-88e4-0e5c141774d8', 'theme', 'Readonly<Ref<TTheme>>', '', 'The current brand theme value: ''auto'' | ''light'' | ''dark'' | string (custom brand). Read-only reactive ref.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('47696c58-ba93-401d-990f-139c436ba9a3', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'c09141c1-9b1e-4e51-88e4-0e5c141774d8', 'resolved', 'Readonly<ComputedRef<TThemeResolved>>', '', 'Effective theme after resolving ''auto'' against prefers-color-scheme. Always ''light'' or ''dark''.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('da102b72-4756-4986-befc-79f6a508102d', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'c09141c1-9b1e-4e51-88e4-0e5c141774d8', 'setTheme', '(next: TTheme) => void', '', 'Sets the brand theme, applies data-theme to <html> and persists to localStorage.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('75d225b7-0e8e-4233-b555-a7e0974eca24', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'c09141c1-9b1e-4e51-88e4-0e5c141774d8', 'toggle', '() => void', '', 'Convenience: flips the brand light ↔ dark. Treats ''auto'' as light.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6c231734-133e-4c1a-b4b2-331d8804448e', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'c09141c1-9b1e-4e51-88e4-0e5c141774d8', 'mode', 'Readonly<Ref<TMode>>', '', 'The current color mode: ''auto'' | ''light'' | ''dark''. Read-only reactive ref.', 4, false, NULL, NULL);
