INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d6e30fc8-394c-415a-85a8-583a7a499dd9', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'c09141c1-9b1e-4e51-88e4-0e5c141774d8', 'setMode', '(next: TMode) => void', '', 'Sets the color mode, applies data-mode to <html> and persists to localStorage.', 6, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1bb9d3a8-ceba-468a-8eda-78be0fbef9b4', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'c09141c1-9b1e-4e51-88e4-0e5c141774d8', 'toggleMode', '() => void', '', 'Flips the color mode light ↔ dark. Treats ''auto'' as the current system preference.', 7, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8728aa80-ccf9-4479-b5bd-914d27576f7d', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '606ac208-5c21-4f6e-af0c-88c05234e0e8', '(...args: T) => void', '(...args: T) => void', '', 'The throttled wrapper function. Call it as you would the original fn — excess calls within the wait window are dropped without side effects.', 0, false, NULL, NULL);
