INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9e0127ce-19dd-4b1d-9ccc-3e16cbb8d58c', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '47a2efb6-8407-42fd-966a-ad85fcf321f6', 'isPristine', 'ShallowRef<boolean>', '', 'True until the first validation run that is not silent. Reset by resetValidation().', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('86b5a8fd-cc67-4965-a2d3-06319ba649d5', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '47a2efb6-8407-42fd-966a-ad85fcf321f6', 'isValid', 'ComputedRef<boolean | undefined>', '', 'False when there are errors, undefined while pristine with a lazy strategy, true otherwise.', 5, false, NULL, NULL);
