INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0790aaa7-aa79-4c13-8880-40d4e8d88bff', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '47a2efb6-8407-42fd-966a-ad85fcf321f6', 'reset', '() => Promise<void>', '', 'Clear the model value (set to null), then run resetValidation.', 7, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8ffe39d9-a960-470e-90a7-b4ba7adf93d4', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '47a2efb6-8407-42fd-966a-ad85fcf321f6', 'resetValidation', '() => Promise<void>', '', 'Mark as pristine and clear internal error messages without changing the value.', 8, false, NULL, NULL);
