INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e64e881a-2b3e-4ab6-9fee-ce6d46068ce9', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '47a2efb6-8407-42fd-966a-ad85fcf321f6', 'validationClasses', 'ComputedRef<Record<string, boolean>>', '', 'Computed class map with `--error`, `--dirty`, `--disabled`, `--readonly` modifier classes.', 10, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d74b08b2-3b41-43e5-b62e-2c4e24694be9', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '239e5a06-d770-4963-9422-cbece2765eb4', 'variantClasses', 'ComputedRef<string[]>', '', 'Array containing `{name}--variant-{variant}` when a variant is set, empty array otherwise. Bind to the component root via `:class`.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6f0a7104-3ce6-45b4-afe7-de74bf5871a7', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '72672983-694a-4ce4-ab7d-67f6ea06f828', 'addMovement', '(e: TouchEvent) => void', '', 'Record a touchstart or touchmove event sample. Each touch point is tracked independently. Call this on every touchmove to build a time-stamped sample history.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('22ae81b5-5c52-4562-91e6-1b4cef2bc6e9', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '72672983-694a-4ce4-ab7d-67f6ea06f828', 'endTouch', '(e: TouchEvent) => void', '', 'Clear the circular buffer for all changed touches. Call at touchstart before starting a new gesture to discard leftover samples from a previous interaction.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1d0ef8f0-baea-40d1-86d9-a029881c4b74', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '72672983-694a-4ce4-ab7d-67f6ea06f828', 'getVelocity', '(id: number) => { x: number; y: number; direction: string }', '', 'Compute the velocity vector for the given touch identifier from the recent sample history. Returns px/ms values for x and y axes and the dominant direction string. Throws if no samples are found for the id.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2d4b2e83-d47c-4476-a061-2933b9d419df', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '4c8f63d7-8094-49d8-adf1-dd6eedcb08bf', 'videoRef', 'Ref<HTMLVideoElement | null>', '', 'Template ref to bind to the `<video>` element. Reused from `options.videoRef` when provided.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5cf6e10d-27a2-472b-9140-e2c06c406a63', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '4c8f63d7-8094-49d8-adf1-dd6eedcb08bf', 'state', 'IVideoPlayerState', '', 'All IMediaPlayerState fields (playing, paused, currentTime, duration, buffered, volume, muted, ready, loading, error, playbackRate, remoteAvailable, remoteState) plus `fullscreen: Ref<boolean>` and `pip: Ref<boolean>`.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('eb6a4b8e-5a42-42f5-af93-a11ac1173cd5', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '4c8f63d7-8094-49d8-adf1-dd6eedcb08bf', 'methods', 'IVideoPlayerMethods', '', 'All IMediaPlayerMethods (play, pause, toggle, seek, setVolume, toggleMute, load, skipBackward, skipForward, setPlaybackRate, requestRemotePlayback, stopRemotePlayback) plus `enterFullscreen`, `exitFullscreen`, `toggleFullscreen`, `requestPip`, `exitPip`, `togglePip`.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ff3dfc7c-a68c-4cc5-b15d-122a190fd8f8', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'b0e0d69d-8af2-43b7-876e-cd323d52a6d0', 'containerRef', 'Ref<HTMLElement | undefined>', '', 'Assign to the scrollable container element. The composable reads `scrollTop` from it and listens to `handleScroll` / `handleScrollend`.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a85bd453-e7bb-4372-9c39-0cd90ef79c57', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'b0e0d69d-8af2-43b7-876e-cd323d52a6d0', 'markerRef', 'Ref<HTMLElement | undefined>', '', 'Assign to a zero-height element at the top of the list content area. Its `offsetTop` is used to compute an offset if there is padding or a header above the virtual list.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5b9295c2-cc45-4831-9ad2-9b8ecd5b3b76', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'b0e0d69d-8af2-43b7-876e-cd323d52a6d0', 'computedItems', 'ComputedRef<Array<{ raw: T; index: number }>>', '', 'The slice of items currently in the render window. Each entry carries the original `raw` item and its absolute `index` in the full list.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('303118cb-5cfa-4afe-bfa1-bb359887c781', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'b0e0d69d-8af2-43b7-876e-cd323d52a6d0', 'paddingTop', 'ShallowRef<number>', '', 'Pixel padding to add above the first rendered item to preserve the scroll height.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e61c1b6a-d4a5-489b-88f7-74a67214c985', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'b0e0d69d-8af2-43b7-876e-cd323d52a6d0', 'paddingBottom', 'ShallowRef<number>', '', 'Pixel padding to add below the last rendered item to preserve the scroll height.', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c32cf856-ef6b-44dc-b8a4-6948e7e0cf8f', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'b0e0d69d-8af2-43b7-876e-cd323d52a6d0', 'scrollToIndex', '(index: number, options?: Partial<IGoToOptions>) => void', '', 'Programmatically scroll the container to a specific item index. Defers the scroll if the list has not yet measured (first render not complete). Pass `{ duration: 0 }` for instant scroll.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6df883b3-e2dc-4eaa-afcc-00086b44cafa', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'b0e0d69d-8af2-43b7-876e-cd323d52a6d0', 'handleScroll', '() => void', '', 'Bind to the `scroll` event of the container element. Computes scroll velocity and triggers visible-items recalculation.', 6, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('be9099ac-9c9c-4305-84b4-cebb6bccb8d7', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'b0e0d69d-8af2-43b7-876e-cd323d52a6d0', 'handleScrollend', '() => void', '', 'Bind to the `scrollend` event. Resets scroll velocity and recalculates the visible window.', 7, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b273aa8d-67d1-454c-a900-736f03315522', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'b0e0d69d-8af2-43b7-876e-cd323d52a6d0', 'handleItemResize', '(index: number, height: number) => void', '', 'Call when a rendered item changes its measured height. Updates the size cache and triggers an offset recalculation. Wire via a ResizeObserver on each rendered row.', 8, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d2e05c75-cb77-4187-85ff-0a980886ddc0', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '126c4321-432d-48da-a2a7-b5a2d3b8a8ff', '(model)', 'Ref<TInnerVal<Inner>> & { readonly externalValue: Props[Prop] }', '', 'A writable computed ref. Reading it returns the current value (controlled or internal). Writing it updates the internal ref and emits `update:prop`. The `externalValue` accessor returns the raw prop value without transformIn applied.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f18e5515-a5a2-4243-953b-d9fde9e8eac3', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '6168c1a1-5c18-4d9b-9da3-7ab219d7707a', 'patternUrl', 'ComputedRef<string>', '', 'CSS `url("data:image/svg+xml,…")` string. Bind to `background-image` on any container element, or pass to `install()`. Recomputes reactively when options change.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3eaa8edf-c961-43c5-886e-9363e99cb718', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '6168c1a1-5c18-4d9b-9da3-7ab219d7707a', 'install', '(target?: HTMLElement) => HTMLElement | null', '', 'Inject a full-cover `<div>` layer with `position: absolute; inset: 0` and the pattern as background-image into `target` (defaults to document.body). Sets `position: relative` on the target if it is `static`. Returns the created layer element, or null during SSR.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b7d45690-3229-4485-aaff-ea593ececb93', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '6168c1a1-5c18-4d9b-9da3-7ab219d7707a', 'uninstall', '() => void', '', 'Remove the injected layer and disconnect the MutationObserver if active. Called automatically on scope dispose.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6ad65ac9-f0f3-4403-acd8-49bef7da9fa5', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'd4fb6b98-27e4-4bca-ab8b-9a5d2ab5cfe3', 'peaks', 'Ref<Array<number>>', '', 'Array of `bins` values in [0, 1], where 1 is the loudest bucket in the track. Empty while computing or on error.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('577ad54d-1702-4c91-b7b9-54c3281aa30f', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'd4fb6b98-27e4-4bca-ab8b-9a5d2ab5cfe3', 'isComputing', 'Ref<boolean>', '', 'True while the fetch + decode round-trip is in progress. Use to render a skeleton or loading indicator.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6e89142f-a28e-4092-abb1-50f95100a734', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'd4fb6b98-27e4-4bca-ab8b-9a5d2ab5cfe3', 'error', 'Ref<Error | null>', '', 'Captures fetch errors (non-2xx response), decode errors (corrupt / unsupported audio), and OfflineAudioContext unavailability. null when no error.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('24911100-d827-4c79-a0ff-e7de8d49af19', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'd4fb6b98-27e4-4bca-ab8b-9a5d2ab5cfe3', 'compute', '() => Promise<void>', '', 'Manually trigger a recomputation. Normally not needed — the composable re-runs automatically when srcRef changes. Useful for retry-on-error flows.', 3, false, NULL, NULL);
