INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e8012726-a984-4168-bfc0-e41d1656d01c', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'e57439b9-a761-4fca-b345-236bed3adafc', 'sm', 'types.detail.empty_state_size.sm', 'Compact — smaller icon, reduced font sizes, tighter padding. Suitable for inline empty zones inside dense containers such as sidebars or data tables.', 0, false, NULL, NULL);
