INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3ea34251-af62-435f-982f-0e979b5801f9', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '08e9010f-800c-4274-878d-b6b90531ac44', 'null', 'types.detail.file.null', 'No file is currently selected, or the selection has been cleared.', 2, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b2e7b938-aeb9-4b38-81bb-bbde6357886d', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'f58debb7-ecf3-4561-b773-643789074420', 'list', 'types.detail.file_field_display.list', 'Default. Renders each selected file as a card in a vertical stack below the field. Suitable when filenames and per-file actions (remove, download, progress) need to be visible.', 0, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('40766386-c338-42cb-aca4-6e8b8b20ac64', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'f58debb7-ecf3-4561-b773-643789074420', 'chips', 'types.detail.file_field_display.chips', 'Renders each selected file as a closable <OrigamChip> inline inside the field. Compact mode — best for forms where many files can be selected but vertical space is limited.', 1, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c4d0cc0d-72d7-420f-a2ab-db26bd1c7ece', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'f58debb7-ecf3-4561-b773-643789074420', 'counter', 'types.detail.file_field_display.counter', 'Shows a single "N files selected" line with an <OrigamCounter>. Most compact mode — use when the file names are irrelevant to the user after selection.', 2, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b5f825e5-86a0-4b8e-8675-6b6abfcd051c', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '283bceba-264e-4d90-9ef5-098563d79ccf', 'false', 'types.detail.file_size.false', 'File sizes are not displayed. This is the default behaviour when the showSize prop is omitted.', 0, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2def5631-eaad-4718-b2ea-6eda7fad3cb5', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '283bceba-264e-4d90-9ef5-098563d79ccf', 'true', 'types.detail.file_size.true', 'File sizes are displayed using the SI divisor (1 000) — KB, MB, GB.', 1, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8d3f2988-c028-4822-bd4e-d7688d662382', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '283bceba-264e-4d90-9ef5-098563d79ccf', '1000', 'types.detail.file_size.1000', 'Explicit SI (decimal) units: 1 KB = 1 000 bytes, 1 MB = 1 000 000 bytes. Matches the marketing convention used by most storage providers.', 2, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('28876bfa-3eab-468b-96ea-42eb6e132b90', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '283bceba-264e-4d90-9ef5-098563d79ccf', '1024', 'types.detail.file_size.1024', 'Binary / IEC units: 1 KiB = 1 024 bytes, 1 MiB = 1 048 576 bytes. Traditional computing convention; more accurate for OS-reported file sizes.', 3, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1493910d-ca2c-4e5d-a0b4-1ef1a5442360', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '644455ec-e703-4b3a-8e03-1943d1ed69c4', 'row', 'types.detail.flex_direction.row', 'Default. Items are laid out horizontally, left to right (in LTR contexts).', 0, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ff6b9534-5510-4abc-b8ff-5e6d2737fd56', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '644455ec-e703-4b3a-8e03-1943d1ed69c4', 'column', 'types.detail.flex_direction.column', 'Items are stacked vertically, top to bottom.', 1, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('db75c031-1ea0-409a-8232-66c438f3b8ce', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '644455ec-e703-4b3a-8e03-1943d1ed69c4', 'row-reverse', 'types.detail.flex_direction.row_reverse', 'Items flow horizontally in reverse — right to left in LTR contexts.', 2, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7e6bd8dd-e490-47f9-8be3-5e79e24b6468', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '644455ec-e703-4b3a-8e03-1943d1ed69c4', 'column-reverse', 'types.detail.flex_direction.column_reverse', 'Items are stacked vertically in reverse — bottom to top.', 3, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a14962df-07bb-4acb-99d5-5299e62fe613', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '46731064-681c-4e8c-9868-3d67b7767d6a', 'row', 'types.detail.grid_auto_flow.row', 'Items fill each row in turn, adding new rows as needed (default browser behaviour).', 0, false, NULL, NULL);
