INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f45c491e-7f28-429e-9580-68f11eeb2d39', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '46731064-681c-4e8c-9868-3d67b7767d6a', 'row dense', 'types.detail.grid_auto_flow.row_dense', 'Row-first flow with a backfill pass — smaller items are placed in earlier gaps, improving visual density at the cost of DOM order.', 2, false, NULL, NULL);
