INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3e8a8b15-067e-4522-b641-17823c9d4c1a', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'd039493e-4e04-4796-87c7-2230fdb06ea5', 'dark', 'types.detail.theme.dark', 'Legacy alias kept for backwards compatibility. As of the two-axis model, prefer setting mode="dark" on OrigamThemeProvider.', 2, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c7b0ad8d-0f12-4dcb-a440-93eba1b84a95', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'd039493e-4e04-4796-87c7-2230fdb06ea5', '(custom string)', 'types.detail.theme.custom', 'Any other string is treated as a custom brand theme (e.g. "sobre", "brand-a"). The matching CSS token file must be loaded by the consumer.', 3, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5bcbd76a-e929-4f05-8dcb-da399fccfa65', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '2091a0aa-d5f2-4777-8dea-93a6119a9ed9', 'vertical', 'types.detail.timeline_orientation.vertical', 'Events are stacked from top to bottom along the Y axis. Default orientation.', 0, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('36fc8a29-d1d5-4579-a88e-38d2d545a42b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '2091a0aa-d5f2-4777-8dea-93a6119a9ed9', 'horizontal', 'types.detail.timeline_orientation.horizontal', 'Events are laid out left to right along the X axis. Useful for timelines that span calendar periods or process steps.', 1, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a01e7933-1ad7-4ac6-82c7-f8efc4752a5d', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '6b7130b7-b49a-467b-b81f-0db8204c2c6d', 'in-out', 'types.detail.transition.in_out', 'The new element transitions IN first, then the leaving element transitions OUT. Useful when content should appear before the old content disappears.', 0, false, NULL, NULL);
