INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('88ee579e-0f45-4ce3-b4fb-13b8071b9e12', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '6b7130b7-b49a-467b-b81f-0db8204c2c6d', 'default', 'types.detail.transition.default', 'Enter and leave transitions run simultaneously. Matches Vue''s native <Transition> default behaviour.', 2, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7d3e961c-011b-4794-88f7-d1d9c76d73f9', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'b5cba7af-d62a-48a8-8134-57866fe8156d', 'in-out', 'types.detail.transition_mode.in_out', 'New element transitions in first, then old element transitions out.', 0, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e46c4bf0-c184-4116-b788-97dceb3e62f1', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', 'b5cba7af-d62a-48a8-8134-57866fe8156d', 'out-in', 'types.detail.transition_mode.out_in', 'Old element transitions out first, then new element transitions in.', 1, false, NULL, NULL);
