INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ec2a9506-f9e7-4472-b506-bf5e36b0d49b', '2026-07-09 20:00:42.251498+00', '2026-07-09 20:00:42.251498+00', '2e1b559d-a61c-4fef-a178-4d1314ccc68a', 'native', 'types.detail.video_controls.native', 'The <video> element receives the native controls attribute and the browser paints its own toolbar. Useful for AirPlay on Safari or inside Tauri shells that talk to native players.', 1, false, NULL, NULL);
